  const db = requireSyncDb(env);
  const row = version
    ? await db.prepare("SELECT * FROM business_goals WHERE goal_id = ? AND version = ?")
      .bind(clean(goalId), num(version))
      .first()
    : await db.prepare("SELECT * FROM business_goals WHERE goal_id = ? ORDER BY version DESC LIMIT 1")
      .bind(clean(goalId))
      .first();
  return normalizeGoalRow(row);
