async function activeGoalForWeek(env, weekStart = "") {
  const db = syncDb(env);
  if (!db) return null;
  if (!clean(weekStart)) {
    const active = await db
      .prepare("SELECT * FROM business_goals WHERE status = 'active' ORDER BY updated_at DESC LIMIT 1")
      .first();
    return normalizeGoalRow(active);
  }
  const rows = await db
    .prepare("SELECT * FROM business_goals WHERE status IN ('active', 'archived') ORDER BY CASE status WHEN 'active' THEN 0 ELSE 1 END, updated_at DESC LIMIT 25")
    .all();
  const goals = (rows.results || []).map(normalizeGoalRow).filter(Boolean);
  const selected = clean(weekStart);
  return goals.find((goal) => {
    if (!selected) return true;
    if (goal.active_from_week && selected < goal.active_from_week) return false;
    if (goal.active_to_week && selected > goal.active_to_week) return false;
    return true;
  }) || null;
}

