async function claimWeeklyRun(env, { weekStart, triggerType }) {
  const db = requireSyncDb(env);
  const now = new Date().toISOString();
  const boundaries = weekBoundaries(weekStart, DEFAULT_TIMEZONE);
  const runId = crypto.randomUUID();
  const runKey = makeWeeklyRunKey(weekStart);

  await db
    .prepare(
      `INSERT OR IGNORE INTO weekly_sync_runs
       (run_id, run_key, week_start, week_end, trigger_type, status, current_step,
         started_at, updated_at, retry_count, step_attempt, next_retry_at, last_provider_error,
         ga4_status, meta_status, shopify_status, report_status, rows_written_json, is_complete)
       VALUES (?, ?, ?, ?, ?, 'queued', 'queued', ?, ?, 0, 0, '', '',
         'pending', 'pending', 'pending', 'pending', '{}', 0)`
    )
    .bind(runId, runKey, weekStart, boundaries.week_end, triggerType, now, now)
    .run();

  const run = await getRunByWeek(env, weekStart);
  if (!run) throw new Error(`Unable to claim run for ${weekStart}.`);

  if (run.is_complete) {
    return { run, should_start: false, reason: "The selected reporting week is already complete." };
  }

  if (run.run_id !== runId && ["queued", "running"].includes(run.status)) {
    const workflowStatus = await workflowStatusForRun(env, run);
    if (workflowRunIsActive(workflowStatus)) {
      return { run, should_start: false, reason: "A run for this reporting week is already queued or running." };
    }

    if (triggerType === "manual") {
      const retried = await retryRun(env, run.run_id, { force: true });
      return {
        run: retried,
        should_start: true,
        reason: workflowRunIsMissing(workflowStatus)
          ? "Stored Workflow instance was missing; the run will be recreated."
          : "Stored Workflow instance was not active; the run will be retried safely."
      };
    }

    return {
      run,
      should_start: false,
      reason: workflowRunIsMissing(workflowStatus)
        ? "Stored Workflow instance is missing; use /sync-week or /sync-retry to recreate it."
        : "Stored Workflow instance is not active; use /sync-week or /sync-retry to restart it."
    };
  }

  if (run.run_id !== runId && triggerType === "cron") {
    return { run, should_start: false, reason: "A prior incomplete run exists; use /sync-retry to restart it deliberately." };
  }

  if (run.run_id !== runId && triggerType === "manual") {
    const retried = await retryRun(env, run.run_id);
    return { run: retried, should_start: true, reason: "Existing incomplete run will be retried safely." };
  }

  await db
    .prepare(
      `UPDATE weekly_sync_runs
       SET status = 'queued', trigger_type = ?, updated_at = ?, error_message = '', partial_reason = ''
       WHERE run_id = ?`
    )
    .bind(triggerType, now, run.run_id)
    .run();

  return { run: await getRunById(env, run.run_id), should_start: true, reason: "Run claimed." };
}

async function updateRunState(env, runId, patch = {}) {
  const db = requireSyncDb(env);
  const existing = await getRunById(env, runId);
  if (!existing) throw new Error(`Run ${runId} was not found.`);

  const updated = {
    status: patch.status ?? existing.status,
    workflow_instance_id: patch.workflow_instance_id ?? existing.workflow_instance_id,
    current_step: patch.current_step ?? existing.current_step,
    updated_at: patch.updated_at ?? new Date().toISOString(),
    finished_at: patch.finished_at ?? existing.finished_at,
    step_attempt: patch.step_attempt ?? existing.step_attempt,
    next_retry_at: patch.next_retry_at ?? existing.next_retry_at,
    last_provider_error: patch.last_provider_error ?? existing.last_provider_error,
    error_message: patch.error_message ?? existing.error_message,
    ga4_status: patch.ga4_status ?? existing.ga4_status,
    meta_status: patch.meta_status ?? existing.meta_status,
    shopify_status: patch.shopify_status ?? existing.shopify_status,
    report_status: patch.report_status ?? existing.report_status,
    rows_written_json: patch.rows_written_json
      ? serializeRowsWritten(patch.rows_written_json)
      : serializeRowsWritten(existing.rows_written),
    is_complete: patch.is_complete == null ? (existing.is_complete ? 1 : 0) : (patch.is_complete ? 1 : 0),
    partial_reason: patch.partial_reason ?? existing.partial_reason
  };

  await db
    .prepare(
      `UPDATE weekly_sync_runs
       SET status = ?, workflow_instance_id = ?, current_step = ?, updated_at = ?, finished_at = ?, error_message = ?,
           step_attempt = ?, next_retry_at = ?, last_provider_error = ?,
           ga4_status = ?, meta_status = ?, shopify_status = ?, report_status = ?,
           rows_written_json = ?, is_complete = ?, partial_reason = ?
       WHERE run_id = ?`
    )
    .bind(
      updated.status,
      updated.workflow_instance_id,
      updated.current_step,
      updated.updated_at,
      updated.finished_at,
      updated.error_message,
      updated.step_attempt,
      updated.next_retry_at,
      updated.last_provider_error,
      updated.ga4_status,
      updated.meta_status,
      updated.shopify_status,
      updated.report_status,
      updated.rows_written_json,
      updated.is_complete,
      updated.partial_reason,
      runId
    )
    .run();

  return getRunById(env, runId);
}

async function retryRun(env, runId, options = {}) {
  const db = requireSyncDb(env);
  const run = await getRunById(env, runId);
  if (!run) throw new Error(`Run ${runId} was not found.`);
  if (run.is_complete || run.status === "complete") {
    throw new Error("Completed weekly sync runs cannot be retried.");
  }
  if (["queued", "running"].includes(run.status) && !options.force) {
    throw new Error("This weekly sync run is already queued or running.");
  }

  const now = new Date().toISOString();
  await db
    .prepare(
      `UPDATE weekly_sync_runs
       SET status = 'queued', current_step = 'queued', updated_at = ?, finished_at = '',
           retry_count = retry_count + 1, step_attempt = 0, next_retry_at = '',
           last_provider_error = '', error_message = '', partial_reason = '',
           rows_written_json = '{}', is_complete = 0
       WHERE run_id = ?`
    )
    .bind(now, run.run_id)
    .run();

  return getRunById(env, run.run_id);
}

// ── P1.16 true drop-relative weeks ───────────────────────────────────────────
//
// That is correct for suppression and reporting, but it is still a calendar
// approximation: five of the seven 2026 drops land mid-week, so their calendar
// against W0 315 for that reason alone.
//
// True drop-relative weeks anchor on the drop itself: W0 = drop_date..+6, so a
// Tuesday drop's W1 begins the following Tuesday. Every drop then has a full
// seven days of drop traffic in W0 regardless of weekday, which makes ALL past
// drops comparable at W0 rather than only the two Sunday ones.
//
// The calendar week stays the fact grain — the sync cadence, assertCompletedWeek
// and the Monday review all depend on it. This is an additional layer.
async function fetchDailySalesSeries(shop, token, since, until) {
  const table = await shopifyQL(
    shop,
    token,
    `FROM sales SHOW orders, gross_sales, net_sales, sales_reversals
     TIMESERIES day SINCE ${since} UNTIL ${until}
     ${shopifyQLExclusionClause()}`
  );

  const byDay = new Map();
  for (const row of shopifyQLRows(table)) {
    const day = clean(row.day).slice(0, 10);
    if (!day) continue;
    byDay.set(day, {
      orders: num(row.orders),
      gross_sales: num(row.gross_sales),
      net_sales: num(row.net_sales),
      // ShopifyQL returns reversals negative; store magnitude, as everywhere.
      sales_reversals: reversalMagnitude(row.sales_reversals)
    });
  }
  return byDay;
}

function buildDropRelativeWeeks(byDay, drops, asOf, maxWeeks = 8) {
  const rows = [];
  const asOfMs = dateOnlyToUtcMs(clean(asOf));

  for (const drop of drops || []) {
    const dropDate = clean(drop.drop_date);
    if (!dropDate) continue;

    const dropMs = dateOnlyToUtcMs(dropDate);
    const floor = metricOrBlank(drop.floor_orders);

    // Stop at the next drop: once a new drop lands, later windows are no longer
    // measuring this drop's decay.
    const nextDrop = (drops || [])
      .map((d) => clean(d.drop_date))
      .filter((d) => d && d > dropDate)
      .sort()[0];
    const nextDropMs = nextDrop ? dateOnlyToUtcMs(nextDrop) : Infinity;

    for (let i = 0; i < maxWeeks; i++) {
      const startMs = dropMs + i * 7 * DAY_MS;
      const endMs = startMs + 6 * DAY_MS;
      if (startMs >= nextDropMs) break;
      if (startMs > asOfMs) break;

      let orders = 0, gross = 0, net = 0, reversals = 0, daysPresent = 0;

      for (let d = 0; d < 7; d++) {
        const day = formatDateOnlyFromUtcMs(startMs + d * DAY_MS);
        const rec = byDay.get(day);
        if (!rec) continue;
        daysPresent += 1;
        orders += rec.orders;
        gross += rec.gross_sales;
        net += rec.net_sales;
        reversals += rec.sales_reversals;
      }

      // A window truncated by the next drop or by today is reported with its
      // day count, never silently averaged up to a full week.
      const complete = endMs <= asOfMs && endMs < nextDropMs && daysPresent === 7;

      rows.push({
        drop_id: clean(drop.drop_id),
        drop_date: dropDate,
        drop_weekday: clean(drop.drop_weekday),
        drop_week_index: i,
        drop_week_label: i === 0 ? "W0" : `W+${i}`,
        window_start: formatDateOnlyFromUtcMs(startMs),
        window_end: formatDateOnlyFromUtcMs(endMs),
        days_in_window: daysPresent,
        is_complete_window: complete ? "TRUE" : "FALSE",
        orders,
        gross_sales: r2(gross),
        net_sales: r2(net),
        sales_reversals: r2(reversals),
        // Blank rather than zero when the drop has no observed floor.
        drop_lift: floor === "" || floor === 0 ? "" : r4(orders / floor)
      });
    }
  }

  return rows;
}

// ── Surface API (§7) ─────────────────────────────────────────────────────────
//
// One scoped payload per surface, shaped for the question that surface answers.
// The UI is built against THIS contract, not against tab structure, so the D1
// migration (P2.1) later replaces the implementation without touching the UI.
//
// Non-negotiable across every surface: no number travels without its basis and
// its settledness. A figure measured over full cost coverage and one estimated
// over 92% must never render identically, and a week compared at 7-day
// attribution age must never look like a settled one.
function metricWithBasis(value, { basis = "", settled = null, note = "" } = {}) {
  return {
    value: metricOrBlank(value),
    basis,
    // null means settledness does not apply to this metric.
    settled,
    note
  };
}

function buildDailyOpsSurface(tabData, config) {
  const weekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly)
    .filter((r) => clean(r.week_start))
    .sort((a, b) => clean(b.week_start).localeCompare(clean(a.week_start)));

  const latest = weekly[0] || {};
  const prior = weekly.slice(1, 5);
  const avgOrders = prior.length
    ? r2(prior.reduce((a, r) => a + num(r.orders), 0) / prior.length)
    : "";

  const syncMeta = objectsFromTab(tabData, "SyncMeta", HEADERS.SyncMeta);
  const lastBySource = {};
  for (const row of syncMeta) {
    const endpoint = clean(row.endpoint);
    if (!endpoint) continue;
    const existing = lastBySource[endpoint];
    if (!existing || clean(row.finished_at) > clean(existing.finished_at)) {
      lastBySource[endpoint] = row;
    }
  }

  // The failure this project exists to prevent: a dead Meta token halted the
  // Shopify sync for six weeks and nobody noticed. Sync health is first.
  //
  // But "last status per endpoint" alone cries wolf. On 2026-09-08 the live
  // payload carried two `error` rows — a Meta token failure from 08-29 and a GA4
  // grid-limit failure from 09-04 — while MetaWeekly and GA4Weekly BOTH held data
  // for the latest week. Both had been fixed; the error was simply the last row
  // that endpoint ever wrote. A banner reading "2 syncs failing" on that state is
  // exactly the false alarm this dashboard is supposed to abolish, and it trains
  // the reader to ignore the banner that matters.
  //
  // So an error is reconciled against whether the source's data actually arrived
  // for the latest week. Present => `stale_error` (worth fixing, not on fire).
  // Absent => `failing`.
  const latestWeekKey = clean(latest.week_start);
  const sourceHasLatestWeek = (tab) => {
    if (!tab) return null;
    return objectsFromTab(tabData, tab, HEADERS[tab])
      .some((r) => clean(r.week_start) === latestWeekKey);
  };
  // Endpoint names are not a controlled vocabulary — they include
  // "/sync-shopify-all", "workflow:meta", "/sync-ga4-week" and "scheduled" — so
  // the source is matched by substring and "unknown" is left unresolved rather
  // than guessed.
  const tabForEndpoint = (endpoint) => {
    const e = clean(endpoint).toLowerCase();
    if (e.includes("meta")) return "MetaWeekly";
    if (e.includes("ga4")) return "GA4Weekly";
    if (e.includes("shopify")) return "ShopifyWeekly";
    return "";
  };

  const syncHealth = Object.entries(lastBySource).map(([endpoint, row]) => {
    const status = clean(row.status);
    const tab = tabForEndpoint(endpoint);
    const dataPresent = sourceHasLatestWeek(tab);
    let alert = status === "success" ? "ok" : "failing";
    if (status !== "success" && dataPresent === true) alert = "stale_error";
    if (status !== "success" && dataPresent === null) alert = "unresolved";
    return {
      endpoint,
      status,
      alert,
      source_tab: tab,
      data_present_for_latest_week: dataPresent,
      finished_at: clean(row.finished_at),
      week_start: clean(row.week_start),
      error: clean(row.error_message).slice(0, 200)
    };
  });

  const onFire = syncHealth.filter((r) => r.alert === "failing").length;
  const staleErrors = syncHealth.filter((r) => r.alert === "stale_error").length;

  const skus = objectsFromTab(tabData, "ShopifySkuWeekly", HEADERS.ShopifySkuWeekly)
    .filter((r) => clean(r.week_start) === clean(latest.week_start));

  // One list, not two.
  //
  // The first render of this page had "selling but out of stock" and "low days of
  // cover" side by side. Seen rendered, they were the same list twice: an out of
  // stock SKU has zero days of cover by definition, so every row in the second
  // table was already in the first. Worse, the second table printed
  // `product_title` without the variant, so three sizes of CHARIOT WHITE TEE read
  // as three identical rows.
  //
  // Ordered by the revenue the SKU actually produced this week, because that is
  // what stops if it stays unavailable — not by units, which over-ranks cheap
  // items, and not by days of cover, which puts every zero in an arbitrary order.
  const RESTOCK_COVER_DAYS = 14;
  const restock = skus
    .filter((r) => {
      if (num(r.units_sold) <= 0) return false;
      if (clean(r.is_oos) === "TRUE") return true;
      const cover = metricOrBlank(r.days_of_cover_7d);
      return cover !== "" && num(cover) <= RESTOCK_COVER_DAYS;
    })
    .map((r) => ({
      sku: clean(r.sku),
      product_title: clean(r.product_title),
      variant_title: clean(r.variant_title),
      units_sold: num(r.units_sold),
      net_sales: metricOrBlank(r.net_sales),
      days_of_cover: metricOrBlank(r.days_of_cover_7d),
      out_of_stock: clean(r.is_oos) === "TRUE"
    }))
    .sort((a, b) => num(b.net_sales) - num(a.net_sales));

  const restockSummary = {
    skus: restock.length,
    out_of_stock: restock.filter((r) => r.out_of_stock).length,
    units: restock.reduce((a, r) => a + r.units_sold, 0),
    // Revenue these SKUs produced this week. It is what stops if they stay
    // unavailable — deliberately not called a "loss", because nothing has been
    // lost yet and some of it substitutes to other sizes.
    weekly_net_sales: r2(restock.reduce((a, r) => a + num(r.net_sales), 0)),
    cover_days_threshold: RESTOCK_COVER_DAYS
  };

  return {
    question: "Is anything on fire?",
    cadence: "daily",
    timezone: config?.timezone || DEFAULT_TIMEZONE,
    latest_week: clean(latest.week_start),
    orders_latest_week: metricOrBlank(latest.orders),
    orders_prior_4w_avg: avgOrders,
    sync_health: syncHealth,
    sync_alert: {
      // The one number the banner should key off. `stale_errors` is deliberately
      // separate: it is a maintenance item, not an emergency.
      failing: onFire,
      stale_errors: staleErrors,
      verdict: onFire > 0
        ? "on_fire"
        : (staleErrors > 0 ? "healthy_with_stale_errors" : "healthy"),
      note: onFire > 0
        ? "A source has an error AND no data for the latest week."
        : (staleErrors > 0
          ? "Errors on record, but every source has data for the latest week — these are last-known failures that have since been fixed. Worth clearing, not worth waking up for."
          : "")
    },
    delivery: {
      not_delivered_rate: metricWithBasis(latest.not_delivered_rate, {
        basis: "courier_events",
        settled: clean(latest.delivery_settled).toUpperCase() === "TRUE",
        note: "Rate over resolved orders only."
      }),
      carrier_reporting_rate: metricOrBlank(latest.carrier_reporting_rate),
      pending_orders: metricOrBlank(latest.delivery_pending_orders)
    },
    restock: restock.slice(0, 15),
    restock_summary: restockSummary
  };
}

// P1.27 drop-relative comparison.
//
// This is the comparison the business model section of CLAUDE.md says is the
// only honest one. Revenue is drop-driven: every post-drop week looks like a
// collapse against the calendar week before it, and week-over-week has produced
// a false alarm on every one of them. The question is never "is this week down
// on last week" — it always is — but "is W+2 of THIS drop worse than W+2 of the
// six drops before it."
//
// Two things make a naive version of this lie:
//
//    Comparing absolute orders at an index therefore measures how big the drop
//    was, not how fast it decayed. So every point also carries its share of its
//    OWN W0 (`share_of_w0`), and the verdict is read off that shape, not the
//    absolute level. Both are returned; only one is used to judge.
// 2. A partial window has fewer days in it and reads as a collapse that never
//    happened. Incomplete windows are plotted but never enter peer statistics.
//
// P1.4) contaminates any cohort overlapping it. Rather than invent a boolean
// threshold, each point carries the mean discount rate of the ShopifyWeekly
// weeks its window overlaps, so the contamination is a number the reader sees
// rather than a judgement this function made for them.
function buildDropComparison(tabData, shopify, config) {
  const dropId = clean(shopify.drop_id);
  const weekIndex = metricOrBlank(shopify.drop_week_index);
  const rows = objectsFromTab(tabData, "DropWeekly", HEADERS.DropWeekly)
    .filter((r) => clean(r.drop_id) && metricOrBlank(r.drop_week_index) !== "");

  if (!dropId || weekIndex === "") {
    return { available: false, reason: "This week is not mapped to a drop.", cohorts: [] };
  }
  if (!rows.length) {
    return { available: false, reason: "DropWeekly has not been built yet.", cohorts: [] };
  }

  const weekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly)
    .filter((r) => clean(r.week_start));

  // Mean discount rate over the ShopifyWeekly weeks a drop window overlaps.
  const discountOverWindow = (start, end) => {
    const s = clean(start);
    const e = clean(end);
    if (!s || !e) return "";
    const rates = weekly
      .filter((w) => clean(w.week_start) <= e && clean(w.week_end) >= s)
      .map((w) => metricOrBlank(w.discount_rate))
      .filter((v) => v !== "");
    if (!rates.length) return "";
    return r4(rates.reduce((a, b) => a + num(b), 0) / rates.length);
  };

  const discountPeriods = parseDiscountPeriods(config?.discountPeriods);

  const byDrop = new Map();
  for (const row of rows) {
    const id = clean(row.drop_id);
    if (!byDrop.has(id)) byDrop.set(id, []);
    byDrop.get(id).push(row);
  }

  const cohorts = [...byDrop.entries()]
    .map(([id, list]) => {
      const sorted = list.slice().sort((a, b) => num(a.drop_week_index) - num(b.drop_week_index));
      const w0 = sorted.find((r) => num(r.drop_week_index) === 0);
      const w0Orders = w0 ? metricOrBlank(w0.orders) : "";
      return {
        drop_id: id,
        drop_date: clean(sorted[0].drop_date),
        is_current: id === dropId,
        w0_orders: w0Orders,
        points: sorted.map((r) => {
          const orders = metricOrBlank(r.orders);
          return {
            i: num(r.drop_week_index),
            label: clean(r.drop_week_label),
            orders,
            net_sales: metricOrBlank(r.net_sales),
            // Blank, not 1, when W0 is unknown: a fabricated ratio here would
            // put a false curve on the chart, which is worse than a gap.
            share_of_w0: orders !== "" && num(w0Orders) > 0 ? r4(num(orders) / num(w0Orders)) : "",
            complete: clean(r.is_complete_window).toUpperCase() === "TRUE",
            discount_rate: discountOverWindow(r.window_start, r.window_end),
            // P1.4. Whether this window ran under a sitewide campaign.
            campaign_period: overlapsDiscountPeriod(r.window_start, r.window_end, discountPeriods)
          };
        })
      };
    })
    .sort((a, b) => clean(a.drop_date).localeCompare(clean(b.drop_date)));

  const current = cohorts.find((c) => c.is_current) || null;
  const mine = current ? current.points.find((p) => p.i === num(weekIndex)) : null;

  const peerPoints = cohorts
    .filter((c) => !c.is_current)
    .map((c) => c.points.find((p) => p.i === num(weekIndex)))
    .filter((p) => p && p.complete && p.share_of_w0 !== "");

  const peerShares = peerPoints.map((p) => num(p.share_of_w0));
  const peerMedian = medianNumeric(peerShares);

  // P1.4. A verdict is only like-for-like if this week and its peers were under
  // the same promotional conditions. From the winter drop onward they will not
  // be: every prior drop launched into the sitewide discount and the winter one
  // launches after it. Saying "decaying faster than any prior drop" without that
  // caveat would blame the drop for the discount ending.
  const peersOnDiscount = peerPoints.filter((p) => p.campaign_period === true).length;
  const peersOffDiscount = peerPoints.filter((p) => p.campaign_period === false).length;

  let verdict = "";
  let comparable = false;
  if (mine && mine.complete && mine.share_of_w0 !== "" && peerShares.length >= 2 && peerMedian !== "") {
    comparable = true;
    const lo = Math.min(...peerShares);
    const hi = Math.max(...peerShares);
    const v = num(mine.share_of_w0);
    if (v < lo) verdict = "steeper_than_any_prior_drop";
    else if (v > hi) verdict = "shallower_than_any_prior_drop";
    else verdict = "within_prior_range";
  }

  return {
    available: true,
    drop_id: dropId,
    drop_week_index: weekIndex,
    drop_week_label: clean(shopify.drop_week_label),
    cohorts,
    // How many drops ever ran a complete week at each index. This is what makes
    // an empty comparison legible: at W+5 there are structurally zero peers and
    // there always will be, whereas W+1 and W+2 are richly covered.
    peers_by_index: (() => {
      const counts = {};
      for (const c of cohorts) {
        for (const pt of c.points) {
          if (!pt.complete || c.is_current) continue;
          counts[pt.i] = (counts[pt.i] || 0) + 1;
        }
      }
      return counts;
    })(),
    peer: {
      n: peerShares.length,
      // Stated even when the verdict stands, because the reader has to be able to
      // discount it themselves.
      peers_on_campaign: peersOnDiscount,
      peers_off_campaign: peersOffDiscount,
      campaign_mismatch: (() => {
        if (!mine || mine.campaign_period === null) return null;
        const known = peersOnDiscount + peersOffDiscount;
        if (!known) return null;
        const agreeing = mine.campaign_period ? peersOnDiscount : peersOffDiscount;
        return agreeing / known < CAMPAIGN_AGREEMENT_FLOOR;
      })(),
      campaign_mismatch_note: (() => {
        if (!mine || mine.campaign_period === null) return "";
        const known = peersOnDiscount + peersOffDiscount;
        if (!known) return "";
        const agreeing = mine.campaign_period ? peersOnDiscount : peersOffDiscount;
        if (agreeing / known >= CAMPAIGN_AGREEMENT_FLOOR) return "";
        return mine.campaign_period
          ? `This week ran under a sitewide discount and ${peersOffDiscount} of ${peersOnDiscount + peersOffDiscount} comparable peers did not. It is flattered relative to them.`
          : `This week ran with no sitewide discount while ${peersOnDiscount} of ${peersOnDiscount + peersOffDiscount} comparable peers did. It is penalised relative to them, and a steeper reading here may be the discount ending rather than the drop underperforming.`;
      })(),
      comparable,
      verdict,
      // Decay shape, which is what the verdict is read off.
      this_share_of_w0: mine ? mine.share_of_w0 : "",
      median_share_of_w0: peerMedian === "" ? "" : r4(peerMedian),
      min_share_of_w0: peerShares.length ? r4(Math.min(...peerShares)) : "",
      max_share_of_w0: peerShares.length ? r4(Math.max(...peerShares)) : "",
      // Absolute level, reported but deliberately NOT used to judge.
      this_orders: mine ? mine.orders : "",
      median_orders: medianNumeric(peerPoints.map((p) => num(p.orders))),
      not_comparable_reason: comparable
        ? ""
        : (!mine ? "This drop has no row at that index yet."
          : !mine.complete ? "This week's window is still open — it will read low until the week completes."
          : peerShares.length < 2 ? `${peerShares.length === 0 ? "No" : "Only one"} earlier drop ran a complete week at this position, because drops land every 3–5 weeks and the next one restarts the clock.`
          : "Decay shape is unavailable because W0 orders are unknown.")
    },
    discount_window_note: "A sitewide ~20% discount ran approx 2026-06-29 → 2026-09-20. Cohorts overlapping it carry a raised discount rate; compare shape, not level, across that boundary."
  };
}

// Does the threshold behind the funnel diagnosis describe THIS store?
//
// The weekly funnel diagnosis branches on a fixed site-level ATC floor
// (GA4_LOW_ATC_RATE). A fixed floor is only meaningful if the shop it is applied
// to can actually reach it — otherwise the same conclusion prints every week and
// stops carrying information.
//
// Checked against 17 live weeks on 2026-09-08: median site-level ATC 8.71%, floor
// cleared in 11 of 17 weeks. So the floor IS calibrated for this store, and the
// the diagnosis stood up. An earlier reading of this code assumed the floor was
// miscalibrated because CLAUDE.md records a ~3.3% ATC; that figure belongs to the
// PRODUCT-level view_to_cart_rate of Landmine #4, a different metric entirely.
//
// This function changes no diagnosis. It reports whether the floor that fired is
// defensible against the store's own distribution, so the surface can mark a
// conclusion it cannot stand behind instead of presenting it as fact.
function diagnosisTrust(tabData, ga4Row) {
  const rates = objectsFromTab(tabData, "GA4Weekly", HEADERS.GA4Weekly)
    .map((r) => metricOrBlank(r.atc_rate))
    .filter((v) => v !== "" && num(v) > 0)
    .map(num);

  const observedMedian = medianNumeric(rates);
  // The SAME constant the funnel diagnosis branches on. Referencing
  // DIAGNOSIS_THRESHOLDS here would judge one metric's conclusion against a
  // different metric's threshold, which agreed only by coincidence.
  const threshold = GA4_LOW_ATC_RATE;
  const weekRate = metricOrBlank(ga4Row?.atc_rate);

  if (observedMedian === "" || weekRate === "") {
    return { trusted: null, reason: "Not enough GA4 history to judge the threshold.", threshold, observed_median: observedMedian, week_rate: weekRate, weeks: rates.length };
  }

  // The threshold is indefensible when the store has essentially never met it.
  const everMet = rates.filter((v) => v >= threshold).length;
  const aboveOwnMedian = num(weekRate) >= num(observedMedian);

  const trusted = !(everMet === 0 && aboveOwnMedian);

  return {
    trusted,
    threshold,
    observed_median: r4(observedMedian),
    week_rate: weekRate,
    weeks: rates.length,
    weeks_meeting_threshold: everMet,
    reason: trusted
      ? ""
      : `The "weak add-to-cart" conclusion comes from a fixed floor of ${r2(threshold * 100)}%, which this store has not met in any of the last ${rates.length} weeks, while this week's ${r2(num(weekRate) * 100)}% is at or above its own median of ${r2(num(observedMedian) * 100)}%. The floor is describing a different business, not this one. Treat the funnel conclusion as unproven until it is derived from this store's own distribution.`
  };
}

// Why did orders move? — the join from outcome back to driver.
//
// CLAUDE.md is emphatic that week-over-week is a false-alarm generator here, and
// it is right: as a VERDICT on performance it is noise, because revenue is
// drop-driven. That verdict stays with the drop-relative comparison.
//
// This is a different use. Once the drop-relative view has said whether a move
// matters, the next question is what produced it, and for that the previous week
// is the correct reference — spend, impressions and clicks are calendar-driven,
// not drop-driven. The distinction is enforced by what this function returns: an
// explanation and never a judgement. Nothing here says "good" or "bad".
//
// 85% on W+4 (129 -> 238), which the surface was about to call "the week's most
// interesting fact, not explained by the drop cycle". True, and useless: spend
// rise was bought at flat efficiency, which is a completely different thing to
// tell the reader.
function explainOrderChange(tabData, weekStart) {
  const weekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly)
    .filter((r) => clean(r.week_start))
    .sort((a, b) => clean(a.week_start).localeCompare(clean(b.week_start)));
  const reports = objectsFromTab(tabData, "ReportWeekly", HEADERS.ReportWeekly);

  const at = weekly.findIndex((r) => clean(r.week_start) === weekStart);
  if (at < 1) return { available: false, reason: "No prior week to compare against." };

  const now = weekly[at];
  const prior = weekly[at - 1];
  const priorWeek = clean(prior.week_start);
  const rNow = reports.find((r) => clean(r.week_start) === weekStart) || {};
  const rPrior = reports.find((r) => clean(r.week_start) === priorWeek) || {};

  // Blank in, blank out. A missing spend must not become a zero that turns a
  // flat week into "infinite efficiency gain".
  const pair = (a, b) => {
    const A = metricOrBlank(a), B = metricOrBlank(b);
    if (A === "" || B === "" || num(B) === 0) return { now: A, prior: B, pct: "" };
    return { now: A, prior: B, pct: r4((num(A) - num(B)) / num(B)) };
  };

  const orders = pair(now.orders, prior.orders);
  const spend = pair(rNow.meta_spend, rPrior.meta_spend);
  const aov = pair(now.aov, prior.aov);
  const cpo = (orders.now !== "" && spend.now !== "" && num(orders.now) > 0 && num(orders.prior) > 0)
    ? pair(num(spend.now) / num(orders.now), num(spend.prior) / num(orders.prior))
    : { now: "", prior: "", pct: "" };

  let verdict = "";
  let sentence = "";
  const MOVE = 0.10;      // below this, treat as flat
  const EFFICIENCY = 0.15; // cost-per-order drift that still counts as "held"

  if (orders.pct !== "" && Math.abs(num(orders.pct)) < MOVE) {
    verdict = "flat";
    sentence = "Orders held roughly level with last week.";
  } else if (orders.pct !== "" && spend.pct !== "") {
    const up = num(orders.pct) > 0;
    const spendMoved = Math.abs(num(spend.pct)) >= MOVE;
    const sameDirection = spendMoved && (num(spend.pct) > 0) === up;
    const efficiencyHeld = cpo.pct !== "" && Math.abs(num(cpo.pct)) < EFFICIENCY;

    if (sameDirection && efficiencyHeld) {
      verdict = up ? "bought" : "spend_cut";
      sentence = up
        ? `Orders rose ${r2(num(orders.pct) * 100)}% and spend rose ${r2(num(spend.pct) * 100)}%, with cost per order flat at ${r2(num(cpo.now))}. This is bought volume at unchanged efficiency, not a change in demand.`
        : `Orders fell ${r2(Math.abs(num(orders.pct)) * 100)}% and spend fell ${r2(Math.abs(num(spend.pct)) * 100)}%, with cost per order flat. The market did not move; the budget did.`;
    } else if (sameDirection && !efficiencyHeld) {
      verdict = "bought_at_worse_rate";
      sentence = `Orders moved ${r2(num(orders.pct) * 100)}% and spend ${r2(num(spend.pct) * 100)}%, but cost per order moved ${r2(num(cpo.pct) * 100)}% to ${r2(num(cpo.now))}. The change was paid for, and the price changed.`;
    } else if (!spendMoved) {
      verdict = up ? "demand" : "demand_loss";
      sentence = up
        ? `Orders rose ${r2(num(orders.pct) * 100)}% on essentially unchanged spend. This one is not bought.`
        : `Orders fell ${r2(Math.abs(num(orders.pct)) * 100)}% on essentially unchanged spend — demand, not budget.`;
    } else {
      verdict = "diverging";
      sentence = `Orders moved ${r2(num(orders.pct) * 100)}% while spend moved ${r2(num(spend.pct) * 100)}% in the opposite direction.`;
    }
  } else {
    verdict = "unknown";
    sentence = "Spend or order history is missing for one of the two weeks.";
  }

  // Worth saying alongside any volume story: more orders at a lower basket is not
  // the same win as more orders at the same basket.
  const aovNote = (aov.pct !== "" && Math.abs(num(aov.pct)) >= MOVE)
    ? `Average order value ${num(aov.pct) > 0 ? "rose" : "fell"} ${r2(Math.abs(num(aov.pct)) * 100)}% to ${r2(num(aov.now))}.`
    : "";

  return {
    available: true,
    prior_week: priorWeek,
    orders, spend, aov,
    cost_per_order: cpo,
    verdict,
    sentence,
    aov_note: aovNote,
    // Guards against this being read as a performance verdict.
    scope: "Explains what moved the number. Whether the level is good is the drop-relative question, not this one."
  };
}

// Admin: "make the data right".
//
// Deliberately NOT a settings screen. Every row is a defect in the data with the
// thing it costs stated next to it, because the only reason to open this page is
// to decide what is worth fixing. A gap with no stated payoff is a chore; a gap
// that says "this is what turns margin from an estimate into a measurement" is a
// decision.
function buildAdminSurface(tabData, config) {
  const weekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly)
    .filter((r) => clean(r.week_start))
    .sort((a, b) => clean(b.week_start).localeCompare(clean(a.week_start)));
  const latest = weekly[0] || {};
  const week = clean(latest.week_start);

  // ── 1. COGS gaps. The single highest-value fix: margin is an ESTIMATE until
  //      every selling SKU has a unit cost, and an estimate that "leans
  //      optimistic" is the worst kind of number to run a business on.
  const skus = objectsFromTab(tabData, "ShopifySkuWeekly", HEADERS.ShopifySkuWeekly)
    .filter((r) => clean(r.week_start) === week);

  const missingCost = skus
    .filter((r) => num(r.units_sold) > 0 && metricOrBlank(r.unit_cost) === "")
    .map((r) => ({
      sku: clean(r.sku),
      product_title: clean(r.product_title),
      units_sold: num(r.units_sold)
    }))
    .sort((a, b) => b.units_sold - a.units_sold);

  // Distinct products, because the founder fills a cost per product, not per
  // size variant — reporting 14 rows for 3 products makes the job look bigger
  // than it is.
  const missingProducts = [...new Set(missingCost.map((r) => r.product_title).filter(Boolean))];

  const cogs = {
    coverage_rate: metricOrBlank(latest.cogs_coverage_rate),
    margin_basis: clean(latest.margin_basis) || "unavailable",
    missing_rows: missingCost.length,
    missing_products: missingProducts,
    missing_units: missingCost.reduce((a, r) => a + r.units_sold, 0),
    top_gaps: missingCost.slice(0, 12),
    unlocks: clean(latest.margin_basis) === "measured"
      ? ""
      : "Filling these turns contribution margin from an estimate into a measurement. The estimate prices uncovered units at the covered average, which leans optimistic — the real number is very likely lower."
  };

  // ── 2. Attribution capture. Answers "are the ad URL parameters actually
  //      working", which is otherwise invisible until a CAC number looks wrong.
  const attribution = {
    health: clean(latest.attribution_health) || "unknown",
    unattributed_share: metricOrBlank(latest.unattributed_share),
    attributed_orders: metricOrBlank(latest.attributed_orders),
    orders: metricOrBlank(latest.orders),
    unlocks: "Delivered CAC and wasted-ad-spend are only as good as this. Unattributed orders are silently excluded from every per-campaign figure."
  };

  // ── 3. Errors worth clearing. Same reconciliation the daily surface uses: an
  //      error whose source has since delivered data is maintenance, not an
  //      emergency, and it belongs here rather than on the alert page.
  const syncMeta = objectsFromTab(tabData, "SyncMeta", HEADERS.SyncMeta);
  const lastBySource = {};
  for (const row of syncMeta) {
    const endpoint = clean(row.endpoint);
    if (!endpoint) continue;
    const existing = lastBySource[endpoint];
    if (!existing || clean(row.finished_at) > clean(existing.finished_at)) lastBySource[endpoint] = row;
  }
  const staleErrors = Object.entries(lastBySource)
    .filter(([, row]) => clean(row.status) !== "success")
    .map(([endpoint, row]) => ({
      endpoint,
      finished_at: clean(row.finished_at),
      week_start: clean(row.week_start),
      error: clean(row.error_message).slice(0, 240)
    }));

  // ── 4. Warehouse size. Landmine #5: every read pulls all of this into memory,
  //      and a grid limit has already broken a sync once. Row counts are free —
  //      the data is already here — and make the growth visible before it bites.
  //      The grid CEILING is deliberately not guessed: it varies per tab and
  //      reading it would cost a Sheets call this surface does not make.
  const warehouse = Object.keys(HEADERS)
    .map((tab) => {
      const rows = tabData?.[tab]?.values;
      return { tab, rows: Array.isArray(rows) ? Math.max(0, rows.length - 1) : "", columns: HEADERS[tab].length };
    })
    .filter((t) => t.rows !== "")
    .sort((a, b) => b.rows - a.rows);

  const totalRows = warehouse.reduce((a, t) => a + t.rows, 0);

  return {
    question: "What is stopping the numbers from being true?",
    cadence: "as needed",
    week,
    // Ordered by what it unlocks, not by how easy it is.
    cogs,
    attribution,
    stale_errors: staleErrors,
    warehouse: {
      tabs: warehouse,
      total_rows: totalRows,
      note: "Every report read pulls all of this into memory (Landmine #5). Row counts are exact; grid ceilings are not read here because that would cost a Sheets call."
    },
    timezone: config?.timezone || DEFAULT_TIMEZONE
  };
}

// Live attribution check — the same day, not the next sync.
//
// Attribution capture is the one thing in this pipeline that is NOT retroactive:
// a click id not captured today cannot be reconstructed by any dashboard, ever.
// So the feedback loop on "did my change work" has to be same-day, and every
// other number here is weekly by design. On 2026-09-09 the founder set the Meta
// URL parameters, and the earliest the weekly surfaces could have shown it was
// the following Saturday's cron — five days of flying blind on the one change
// that cannot be redone.
//
// This reads recent orders straight from Shopify and reports what capture is
// actually doing right now.
//
// Deliberately NOT a metric. It reads an incomplete, ragged window of the most
// recent N orders, so it must never be compared against a weekly figure — the
// populations are different. It answers one question: is capture working, and
// what is stopping the ad-level join.
const LIVE_ATTRIBUTION_ORDERS = 60;

async function fetchRecentOrdersForAttribution(shop, token, limit) {
  const query = `
    query RecentAttribution($first: Int!) {
      orders(first: $first, sortKey: CREATED_AT, reverse: true) {
        nodes {
          name
          createdAt
          customAttributes { key value }
        }
      }
    }
  `;
  const data = await shopifyGraphQL(shop, token, query, { first: limit });
  return data?.orders?.nodes || [];
}

function buildLiveAttributionSurface(orders, knownAds) {
  const rows = [];
  const counts = { exact: 0, ad_id: 0, platform_click: 0, campaign: 0, unattributed: 0 };
  const byPlatform = {};
  // Values that arrived in utm_content but are not a known ad id. These are the
  // actionable list: each one is an ad whose own URL parameters override the
  // account default, and orders from it can never join to an ad.
  const nonAdContent = {};

  for (const order of orders) {
    const resolved = resolveOrderAttribution(order, knownAds);
    counts[resolved.confidence] += 1;

    const attrs = orderAttributionAttributes(order);
    const content = clean(attrs[ATTRIBUTION_KEYS.content]);
    const platform = clean(attrs[ATTRIBUTION_KEYS.platform]).toLowerCase();

    if (resolved.confidence !== "unattributed") {
      byPlatform[platform || "unknown"] = (byPlatform[platform || "unknown"] || 0) + 1;
    }
    // A content value that did not resolve to an ad id is either an ad-level
    // override or an organic link. Either way it is why the join failed.
    if (content && !resolved.ad_id) {
      nonAdContent[content] = (nonAdContent[content] || 0) + 1;
    }

    rows.push({
      order: clean(order.name),
      created_at: clean(order.createdAt),
      platform: platform || "",
      content,
      campaign: clean(attrs[ATTRIBUTION_KEYS.campaign]),
      confidence: resolved.confidence,
      ad_id: resolved.ad_id
    });
  }

  const total = orders.length;
  const captured = total - counts.unattributed;
  const adJoinable = counts.exact + counts.ad_id;

  return {
    question: "Is attribution capture working right now?",
    cadence: "on demand",
    // Said twice, deliberately, because the number looks like a metric.
    scope: `The most recent ${total} orders, whenever they happened. This is a spot check over a ragged window — never compare it against a weekly figure.`,
    orders_checked: total,
    captured,
    captured_rate: total ? r4(captured / total) : "",
    ad_joinable: adJoinable,
    ad_joinable_rate: total ? r4(adJoinable / total) : "",
    by_confidence: counts,
    by_platform: byPlatform,
    // Sorted by how many orders each blocked, so the most expensive fix is first.
    blocking_ad_join: Object.entries(nonAdContent)
      .map(([value, orders_affected]) => ({ value, orders_affected }))
      .sort((a, b) => b.orders_affected - a.orders_affected)
      .slice(0, 12),
    recent: rows.slice(0, 15),
    verdict: total === 0
      ? "no_orders"
      : captured === 0
        ? "not_capturing"
        : adJoinable === 0
          ? "capturing_but_no_ad_join"
          : adJoinable === captured
            ? "fully_joined"
            : "partially_joined"
  };
}

// Per-ad performance, on demand, over a rolling window.
//
// The weekly surfaces answer "which ad" only after a completed week has synced.
// This answers it now, from a date-bounded window, so a spend decision does not
// have to wait five days.
//
// The window is a DATE RANGE, not "the last N orders". Spend and orders have to
// be drawn from the same period or the ratio between them is meaningless — the
// two-populations trap that has already produced three wrong numbers in this
// project.
//
// THE CENTRAL CAVEAT, and the reason this is honest rather than merely fast:
//
//   Spend is COMPLETE. Every EGP Meta charged is in the numerator.
//   Orders are PARTIAL. Only orders whose utm_content resolves to a known ad id
//   can be joined, and live capture sits near 35%.
//
// A complete numerator over an undercounted denominator makes cost-per-order read
// HIGH. So the figure is an upper bound: true CAC is at or below it, never above.
// That is a genuinely useful statement — "this ad costs at most X per order" —
// and it is stated as a bound rather than dressed up as a measurement.
//
// Equally: an ad with spend and zero attributed orders has NOT been proven to
// have sold nothing. It may simply be under-captured. Those are reported in their
// own bucket and never as failures.
const AD_PERF_DEFAULT_DAYS = 7;
const AD_PERF_MAX_DAYS = 30;

// `formatDateOnlyFromUtcMs` deliberately returns a UTC date and is used where UTC
// is what is wanted. Meta reads `since`/`until` in the ad account's own timezone,
// so pairing it with a UTC date names the wrong day whenever the two disagree —
// Cairo is UTC+2/+3, so any moment after 21:00 UTC is already tomorrow there.
function dateOnlyInTimezone(ms, timezone) {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone || DEFAULT_TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(new Date(ms));
  const get = (type) => parts.find((p) => p.type === type)?.value || "";
  return `${get("year")}-${get("month")}-${get("day")}`;
}

function buildAdPerformanceLive(orders, insightRows, knownAds, window) {
  const spendByAd = new Map();
  for (const row of insightRows || []) {
    const adId = clean(row.ad_id);
    if (!adId) continue;
    spendByAd.set(adId, {
      ad_id: adId,
      ad_name: clean(row.ad_name),
      campaign_name: clean(row.campaign_name),
      adset_name: clean(row.adset_name),
      spend: num(row.spend),
      impressions: num(row.impressions),
      link_clicks: num(row.inline_link_clicks)
    });
  }

  const byAd = new Map();
  let ordersTotal = 0;
  let ordersJoined = 0;
  let revenueJoined = 0;

  for (const order of orders || []) {
    // Cancelled orders are excluded from both sides: counting an order that came
    // back as an acquisition would flatter every ad that produced one.
    if (clean(order.cancelledAt)) continue;
    ordersTotal += 1;

    const resolved = resolveOrderAttribution(order, knownAds);
    if (!resolved.ad_id) continue;

    ordersJoined += 1;
    const revenue = num(money(order.currentTotalPriceSet));
    revenueJoined += revenue;

    const current = byAd.get(resolved.ad_id) || { orders: 0, revenue: 0 };
    current.orders += 1;
    current.revenue += revenue;
    byAd.set(resolved.ad_id, current);
  }

  const ads = [...spendByAd.values()].map((ad) => {
    const joined = byAd.get(ad.ad_id) || { orders: 0, revenue: 0 };
    return {
      ...ad,
      attributed_orders: joined.orders,
      attributed_revenue: r2(joined.revenue),
      // Named for what it is. Not "CAC" — that word implies a measurement.
      max_cost_per_attributed_order: joined.orders > 0 ? r2(ad.spend / joined.orders) : "",
      min_attributed_roas: ad.spend > 0 && joined.orders > 0 ? r2(joined.revenue / ad.spend) : ""
    };
  }).sort((a, b) => b.spend - a.spend);

  const spendTotal = r2(ads.reduce((a, x) => a + x.spend, 0));
  const silent = ads.filter((a) => a.spend > 0 && a.attributed_orders === 0);
  const joinRate = ordersTotal ? r4(ordersJoined / ordersTotal) : "";

  return {
    question: "Which ad is buying orders, right now?",
    cadence: "on demand",
    window,
    coverage: {
      orders_in_window: ordersTotal,
      orders_joined_to_an_ad: ordersJoined,
      join_rate: joinRate,
      note: "Spend is complete; orders are not. Only orders whose utm_content resolves to a known ad id can be joined, so every per-ad order count is a FLOOR and every cost-per-order is a CEILING."
    },
    spend_total: spendTotal,
    attributed_revenue_total: r2(revenueJoined),
    // Spend that bought no order we can see. Deliberately not called wasted.
    unjoined_spend: {
      ads: silent.length,
      spend: r2(silent.reduce((a, x) => a + x.spend, 0)),
      note: "These ads spent and no order joined to them. That is not proof they sold nothing — at the current join rate it is the expected outcome for a small spender."
    },
    ads,
    caveats: [
      "Ordered, not delivered: parcels from this window are still in flight, so nothing here is net of RTO.",
      "Not net of reversals: an order counted today can still be cancelled.",
      "Rolling window, not a completed week — never compare these figures against the weekly surfaces."
    ]
  };
}

// P1.47 contribution waterfall — what is actually left.
//
// Until now the first card on the weekly page said "contribution margin" and
// EGP per four weeks — and it ignored ad spend, which is the largest variable
// cost in the business. A number called contribution that omits the two biggest
// variable costs is not a contribution figure.
//
// THE DOUBLE-COUNT THIS AVOIDS. ShopifyQL `net_sales` is already gross_sales less
// `discount_rate`. So discounts and reversals are NOT subtracted again here —
// doing so would deduct them twice and is precisely the trap this codebase has
// already fallen into three times with two-basis arithmetic.
//
// `reversal_wasted_ad_spend` is likewise NOT a line. It is a slice of ad spend,
// not an additional cost; subtracting both would double-count it. It stays a
// diagnostic.
//
// EVERY MISSING TERM IS A COST, so the bottom line is an UPPER bound. That is
// stated on the result rather than left for the reader to work out.
function buildContributionWaterfall(shopify, report) {
  const netSales = metricOrBlank(shopify.net_sales);
  const marginBasis = clean(shopify.margin_basis) || "unavailable";
  const margin = marginBasis === "measured"
    ? metricOrBlank(shopify.gross_margin)
    : metricOrBlank(shopify.gross_margin_estimated);

  // COGS is implied rather than stored: margin is net_sales less cost of sold,
  // so the cost is the difference. Blank in, blank out.
  const cogs = (netSales !== "" && margin !== "") ? r2(num(netSales) - num(margin)) : "";
  const freight = metricOrBlank(shopify.freight_total_cost);
  const adSpend = metricOrBlank(report.meta_spend);
  const codFee = metricOrBlank(shopify.cod_fee);

  const steps = [];
  let running = netSales === "" ? "" : num(netSales);

  const cost = (key, label, amount, opts) => {
    const included = amount !== "" && running !== "";
    if (included) running = r2(running - num(amount));
    steps.push({
      key,
      label,
      amount: amount === "" ? "" : r2(-num(amount)),
      running: included ? running : "",
      included,
      basis: opts.basis || "",
      note: opts.note || "",
      missing_reason: included ? "" : (opts.missing_reason || "Not measured for this week.")
    });
  };

  steps.push({
    key: "net_sales",
    label: "Net sales",
    amount: netSales,
    running: netSales,
    included: netSales !== "",
    basis: "shopifyql_as_booked",
    note: "Already net of discounts and reversals. Neither is deducted again below.",
    missing_reason: ""
  });

  cost("cogs", "Cost of goods", cogs, {
    basis: marginBasis,
    note: marginBasis === "estimated"
      ? `Estimated: COGS covers ${r2(num(shopify.cogs_coverage_rate) * 100)}% of units, the rest priced at the covered average. Leans optimistic, so the real cost is higher.`
      : ""
  });

  cost("freight", "Freight, both legs", freight, {
    basis: clean(shopify.freight_basis) || "unknown",
    note: "Outbound on every shipped order plus a return leg on every RTO, at the founder's rate card.",
    missing_reason: "Freight lands from the first sync after 2026-09-10."
  });

  cost("cod_fee", "COD collection fee", codFee, {
    basis: clean(shopify.cod_fee_basis) || "not_set",
    note: clean(shopify.cod_fee_basis) === "assumed_2pct_unconfirmed"
      ? `Assumed ${r2(num(shopify.cod_fee_rate) * 100)}% of collected value — NOT confirmed with ShipBlu. Charged only on delivered orders, since a returned parcel collects nothing.`
      : "Charged only on delivered orders, since a returned parcel collects nothing.",
    missing_reason: "Lands from the first sync after 2026-09-10."
  });

  const beforeMarketing = running;
  steps.push({
    key: "before_marketing",
    label: "Contribution before marketing",
    amount: "",
    running: beforeMarketing,
    included: beforeMarketing !== "",
    basis: "subtotal",
    note: "",
    missing_reason: ""
  });

  cost("ad_spend", "Ad spend", adSpend, {
    basis: clean(report.paid_spend_basis) || "unknown",
    note: clean(report.paid_spend_note) ||
      "The whole of paid, not just the wasted share — wasted ad spend is a slice of this, not an extra cost."
  });

  const excluded = steps
    .filter((step) => !step.included && step.key !== "before_marketing")
    .map((step) => ({ term: step.label, reason: step.missing_reason }));

  // TikTok spend is missing from ad_spend itself rather than from a step, so it
  // has to be named separately or it disappears from the completeness picture.
  if (clean(report.paid_spend_basis) === "meta_only_incomplete") {
    excluded.push({
      term: "Non-Meta ad spend",
      reason: "Orders came from a platform with no spend source, so ad spend above is understated."
    });
  }

  return {
    steps,
    bottom_line: running,
    bottom_line_rate: (running !== "" && netSales !== "" && num(netSales) !== 0)
      ? r4(num(running) / num(netSales))
      : "",
    excluded,
    // Every excluded term is a COST, so the true figure can only be lower.
    is_upper_bound: excluded.length > 0,
    bound_note: excluded.length
      ? "Every term still missing is a cost, so what is actually left is at or below this figure — never above."
      : ""
  };
}

function buildWeeklyReviewSurface(tabData, weekStart, config) {
  const shopify = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly)
    .find((r) => clean(r.week_start) === weekStart) || {};
  const report = objectsFromTab(tabData, "ReportWeekly", HEADERS.ReportWeekly)
    .find((r) => clean(r.week_start) === weekStart) || {};
  const meta = objectsFromTab(tabData, "MetaWeekly", HEADERS.MetaWeekly)
    .find((r) => clean(r.week_start) === weekStart) || {};
  const ga4 = objectsFromTab(tabData, "GA4Weekly", HEADERS.GA4Weekly)
    .find((r) => clean(r.week_start) === weekStart) || {};

  const attributionSettled = clean(shopify.attribution_settled).toUpperCase() === "TRUE";
  const deliverySettled = clean(shopify.delivery_settled).toUpperCase() === "TRUE";
  const marginBasis = clean(shopify.margin_basis) || "unavailable";

  const freshness = weekFreshnessFromTabs(tabData, weekStart);

  return {
    question: "What happened, and what do I change?",
    cadence: "weekly",

    // §7: drop position and attribution age are HEADER material, always stated.
    header: {
      week_start: weekStart,
      week_end: clean(shopify.week_end),
      drop_label: clean(shopify.drop_week_label),
      drop_id: clean(shopify.drop_id),
      days_since_drop: metricOrBlank(shopify.days_since_drop),
      attribution_age_days: metricOrBlank(shopify.attribution_age_days),
      attribution_settled: attributionSettled,
      delivery_settled: deliverySettled,
      freshness: freshness.freshness,
      stale_sources: freshness.stale_sources,
      // A single sentence the surface can render verbatim rather than making the
      // reader assemble the caveats themselves.
      provisional_note: attributionSettled && deliverySettled
        ? ""
        : `Provisional: ${!attributionSettled ? `reversals still settling (age ${metricOrBlank(shopify.attribution_age_days)}d)` : ""}${!attributionSettled && !deliverySettled ? "; " : ""}${!deliverySettled ? `${metricOrBlank(shopify.delivery_pending_orders)} parcels still in transit` : ""}.`
    },

    // The five leadership numbers. Margin leads, MER supports (§7).
    leadership: {
      contribution_margin: metricWithBasis(
        marginBasis === "measured" ? shopify.gross_margin : shopify.gross_margin_estimated,
        {
          basis: marginBasis,
          settled: marginBasis === "measured",
          note: marginBasis === "estimated"
            ? `Estimated: COGS covers ${r2(num(shopify.cogs_coverage_rate) * 100)}% of units; the rest priced at the covered average. Leans optimistic.`
            : ""
        }
      ),
      net_sales: metricWithBasis(shopify.net_sales, { basis: "shopifyql_as_booked", settled: true }),
      net_sales_attributed: metricWithBasis(shopify.net_sales_attributed, {
        basis: "order_week_attributed",
        settled: attributionSettled,
        note: attributionSettled ? "" : "Reads high: this week's own reversals have not all landed."
      }),
      orders: metricWithBasis(shopify.orders, { basis: "shopifyql", settled: true }),
      delivered_cac: metricWithBasis(report.delivered_cac_estimated, {
        // Two bases apply to this number and both must be stated: which orders
        // are in the denominator, and whether the spend in the numerator covers
        // every paid channel.
        basis: `${clean(report.delivered_orders_basis) || "unknown"} · ${clean(report.paid_spend_basis) || "unknown"}`,
        settled: deliverySettled,
        note: `Spend divided by orders that actually stuck, not all orders. ${clean(report.paid_spend_note)}`.trim()
      }),
      mer: metricWithBasis(report.mer, {
        basis: clean(report.paid_spend_basis) || "unknown",
        settled: attributionSettled,
        note: clean(report.paid_spend_note)
      })
    },

    // Driver tree, top of funnel down (§7).
    drivers: {
      impressions: metricOrBlank(meta.impressions),
      link_clicks: metricOrBlank(meta.link_clicks),
      ctr_link: metricOrBlank(meta.ctr_link),
      cpc_link: metricOrBlank(meta.cpc_link),
      landing_page_views: metricOrBlank(meta.landing_page_views),
      // Paid clicks that never became a landing-page view: spend lost before the
      // site was seen. Populated since the replay and never looked at (§11.5).
      lpv_rate_from_link_click: metricOrBlank(meta.lpv_rate_from_link_click),
      sessions: metricOrBlank(ga4.sessions),
      add_to_cart_rate: metricOrBlank(ga4.atc_rate),
      checkout_completion_rate: metricOrBlank(ga4.checkout_completion_rate),
      shopify_cvr: metricOrBlank(report.ga4_shopify_cvr),
      aov: metricOrBlank(shopify.aov),
      click_to_order: num(meta.link_clicks) > 0 ? r4(num(shopify.orders) / num(meta.link_clicks)) : ""
    },

    // Where the money actually goes.
    leakage: {
      discounts: metricOrBlank(shopify.discounts),
      discount_rate: metricOrBlank(shopify.discount_rate),
      sales_reversals: metricWithBasis(shopify.sales_reversals, {
        basis: "booked_in_week",
        settled: true,
        note: "Booked on the cancel date; 90% belong to an earlier order week."
      }),
      not_delivered_rate: metricWithBasis(shopify.not_delivered_rate, {
        basis: "courier_events",
        settled: deliverySettled,
        note: `Carrier reporting coverage ${r2(num(shopify.carrier_reporting_rate) * 100)}%.`
      }),
      wasted_ad_spend: metricWithBasis(report.reversal_wasted_ad_spend, {
        basis: clean(report.reversal_share_basis) || "unknown",
        settled: attributionSettled,
        note: "Ad spend consumed by orders that came back."
      }),
      // resell; the two freight legs do not.
      rto_freight: metricWithBasis(shopify.freight_return_cost, {
        basis: clean(shopify.freight_basis) || "unknown",
        settled: clean(shopify.delivery_settled).toUpperCase() === "TRUE",
        note: `Return legs at the founder's rate card, over ${metricOrBlank(shopify.freight_priced_orders)} priced orders. Excludes any COD collection fee, which is not configured.`
      }),
      freight_total: metricWithBasis(shopify.freight_total_cost, {
        basis: clean(shopify.freight_basis) || "unknown",
        settled: clean(shopify.delivery_settled).toUpperCase() === "TRUE",
        note: "Outbound plus return legs. Not deducted from contribution margin above — that figure is still net sales less COGS only."
      }),
      rto_goods_cycled: metricWithBasis(shopify.reversed_unit_cost, {
        basis: "goods_value_cycled_not_lost",
        settled: null,
        note: "Goods return to inventory and resell. NOT a margin deduction."
      })
    },

    // P1.47. What is actually left, once every measured cost is taken out.
    contribution: buildContributionWaterfall(shopify, report),

    // P1.14. Which products come back, on the same courier basis as the weekly
    // cheap tee costs less than 18% on a jacket, and the decision is about money.
    rto_by_sku: objectsFromTab(tabData, "ShopifySkuWeekly", HEADERS.ShopifySkuWeekly)
      .filter((r) => clean(r.week_start) === weekStart && metricOrBlank(r.rto_rate_units) !== "")
      .map((r) => ({
        sku: clean(r.sku),
        product_title: clean(r.product_title),
        variant_title: clean(r.variant_title),
        units_shipped: metricOrBlank(r.units_shipped),
        units_not_delivered: metricOrBlank(r.units_not_delivered),
        rto_rate_units: metricOrBlank(r.rto_rate_units),
        revenue_not_delivered: metricOrBlank(r.rto_revenue_not_delivered)
      }))
      .sort((a, b) => num(b.revenue_not_delivered) - num(a.revenue_not_delivered))
      .slice(0, 12),

    // The only comparison the business model permits as a VERDICT (P1.27).
    drop_comparison: buildDropComparison(tabData, shopify, config),

    // Week-over-week used only to EXPLAIN the move, never to judge it (P1.31).
    change_attribution: explainOrderChange(tabData, weekStart),

    diagnosis: {
      main_problem: clean(report.shopify_main_problem_trigger),
      funnel_problem: clean(report.ga4_main_funnel_problem),
      meta_problem: clean(report.meta_main_problem),
      final: clean(report.final_diagnosis),
      post_drop_decay_suppressed: clean(report.post_drop_decay_suppressed) === "TRUE",
      trust: diagnosisTrust(tabData, ga4)
    }
  };
}

// ── P1.24 courier delivery truth ─────────────────────────────────────────────
//
// ShipBlu writes its full delivery lifecycle into Shopify as fulfillment events.
// No courier API integration is required — verified 2026-09-05 against live
// orders showing IN_TRANSIT / OUT_FOR_DELIVERY / ATTEMPTED_DELIVERY / DELIVERED
// / FAILURE with timestamps.
//
// This matters more than a cost feed would. Until now the pipeline learned about
// an RTO only when the inventory handler manually cancelled the order, in
// batches days later — the root cause of the cross-week attribution problem
// behind P1.9, P1.18 and P1.22. The courier event carries the truth on the day
// it happened.
//
// Statuses observed live. Anything unrecognised is counted as `unknown` rather
// than being forced into a bucket.
// NOT_DELIVERED is the displayStatus an RTO parcel ends on, and omitting it sent
// bucket totals reconciled perfectly, which is exactly why the gap was easy to
// miss: nothing was lost, it was misfiled.
const DELIVERY_TERMINAL_SUCCESS = new Set(["DELIVERED"]);
const DELIVERY_TERMINAL_FAILURE = new Set([
  "NOT_DELIVERED", "FAILURE", "CANCELED", "CANCELLED"
]);
// FULFILLED means a fulfillment exists but the courier has reported nothing yet.
const DELIVERY_IN_FLIGHT = new Set([
  "FULFILLED", "LABEL_PRINTED", "LABEL_PURCHASED", "READY_FOR_PICKUP",
  "PICKED_UP", "CONFIRMED", "IN_TRANSIT", "OUT_FOR_DELIVERY", "ATTEMPTED_DELIVERY"
]);

function orderDeliveryOutcome(order) {
  const fulfillments = order?.fulfillments || [];
  if (!fulfillments.length) {
    return { outcome: "unfulfilled", attempts: 0, delivered_at: "", in_transit_at: "", days_to_outcome: "" };
  }

  // The per-event stream was dropped: including it pushed the orders query to a
  // cost of 1028 against Shopify's 1000 limit. displayStatus carries the same
  // outcome, and deliveredAt / inTransitAt carry the timing. What is lost is the
  // ATTEMPTED_DELIVERY count, which is a leading RTO indicator worth recovering
  // later on a narrower query (P1.25) rather than by shrinking the page size and
  // paying for more round trips on every sync.
  let attempts = 0;
  let deliveredAt = "";
  let inTransitAt = "";
  let latestStatus = "";
  const latestAt = "";

  const carrierSet = new Set();

  for (const f of fulfillments) {
    if (clean(f?.deliveredAt)) deliveredAt = clean(f.deliveredAt);
    if (clean(f?.inTransitAt)) inTransitAt = clean(f.inTransitAt);
    for (const t of f?.trackingInfo || []) {
      const c = clean(t?.company);
      if (c) carrierSet.add(c);
    }

    const display = clean(f?.displayStatus).toUpperCase();
    if (!display) continue;

    // A parcel currently sitting in ATTEMPTED_DELIVERY has had at least one
    // failed attempt, even without the event history.
    if (display === "ATTEMPTED_DELIVERY") attempts = Math.max(attempts, 1);

    // Prefer a terminal status over an in-flight one across multiple
    // fulfillments; otherwise take the first non-empty.
    if (
      !latestStatus ||
      DELIVERY_TERMINAL_SUCCESS.has(display) ||
      DELIVERY_TERMINAL_FAILURE.has(display)
    ) {
      latestStatus = display;
    }
  }

  let outcome = "pending";
  if (DELIVERY_TERMINAL_SUCCESS.has(latestStatus)) outcome = "delivered";
  else if (DELIVERY_TERMINAL_FAILURE.has(latestStatus)) outcome = "not_delivered";
  else if (DELIVERY_IN_FLIGHT.has(latestStatus)) outcome = "pending";
  else if (latestStatus) outcome = "unknown";

  // Dispatch to terminal outcome, in days. Blank unless both ends are known.
  const startMs = inTransitAt ? Date.parse(inTransitAt) : NaN;
  const endMs = deliveredAt ? Date.parse(deliveredAt) : (outcome === "not_delivered" && latestAt ? Date.parse(latestAt) : NaN);
  const daysToOutcome =
    Number.isFinite(startMs) && Number.isFinite(endMs) && endMs >= startMs
      ? r2((endMs - startMs) / DAY_MS)
      : "";

  // P1.10, measured rather than inferred — but ONLY where the carrier reports.
  //
  // Not every parcel ships via ShipBlu. Week 2026-07-19 went out on DHL Express,
  // which writes no delivery events, so those fulfillments carry displayStatus
  // FULFILLED and a null inTransitAt. Treating a null inTransitAt as
  // "pre-dispatch" made that week read 0/18 post/pre — 0% post-dispatch —
  // against 100% everywhere ShipBlu is used. Absence of carrier reporting is not
  // evidence the parcel never moved.
  //
  // So the phase is only asserted when the carrier actually reported movement.
  const carrierReported = Boolean(inTransitAt) || Boolean(deliveredAt) ||
    DELIVERY_TERMINAL_FAILURE.has(latestStatus) ||
    latestStatus === "OUT_FOR_DELIVERY" || latestStatus === "ATTEMPTED_DELIVERY" ||
    latestStatus === "IN_TRANSIT";

  const carriers = [...carrierSet].sort().join("|");

  let dispatchPhase = "";
  if (outcome === "not_delivered") {
    if (inTransitAt) dispatchPhase = "post_dispatch";
    else if (carrierReported) dispatchPhase = "post_dispatch_unconfirmed";
    else dispatchPhase = "unknown_no_carrier_data";
  }

  return {
    outcome,
    attempts,
    delivered_at: deliveredAt,
    in_transit_at: inTransitAt,
    latest_status: latestStatus,
    days_to_outcome: daysToOutcome,
    dispatch_phase: dispatchPhase,
    carrier: carriers,
    carrier_reported: carrierReported
  };
}

//
//   Cairo & Giza .......... 75
//   Alexandria & Delta .... 85
//   Rest of Egypt ......... 150
//
// TWO ASSUMPTIONS THE FOUNDER ASKED TO BE REMINDED OF, both surfaced on Admin
// rather than buried here:
//   1. A return leg is assumed to cost the SAME as an outbound leg. Couriers
//      often price RTO differently — sometimes a flat fee, sometimes a fraction.
//   2. The COD collection fee is assumed to be a PERCENTAGE, but no percentage
//      was given, so it is NOT computed. It stays blank rather than becoming a
//      fabricated zero, and every freight figure below therefore EXCLUDES it.
//      COD touches nearly every order, so it is very likely the larger cost.
//
// Keyed on `provinceCode`, not `province`. Codes are stable ISO-style values
// (C, GZ, ALX, DK); the display name is free text that arrives in Arabic, in
// English, and misspelled.
const FREIGHT_RATES = Object.freeze({ metro: 75, delta: 85, rest: 150 });

// COD collection fee. The founder confirmed the FORM is a percentage and asked to
// assume 2% while explicitly flagging that the rate is NOT confirmed. So it is
// applied, and every figure derived from it carries
// `cod_fee_basis: "assumed_2pct_unconfirmed"` — the number moves linearly with
// this, so a wrong rate is a wrong contribution figure by exactly the same ratio.
//
// Charged on what is COLLECTED, not on what is ordered. A parcel that comes back
// collects nothing, so an RTO pays no collection fee — it pays two freight legs
// instead. Applying it to all orders would overstate the cost by the RTO rate.
const COD_FEE_RATE_ASSUMED = 0.02;

// P1.4 sitewide campaign periods.
//
// explicit that any comparison spanning it is contaminated, and until now the
// pipeline only surfaced the raw discount rate per cohort and left the reader to
// notice.
//
// This matters far more from 2026-09-20 than it ever did before. Every prior drop
// in the comparison set launched INTO the discount. The winter drop launches
// after it ends. So the winter drop will be compared against six peers that were
// all discount-assisted, and it will look worse than it is for a reason that has
// nothing to do with the drop.
//
// Overridable from Config (`discount_periods`) so a future campaign is one cell,
// not a deploy.
const DEFAULT_DISCOUNT_PERIODS = "2026-06-29:2026-09-20";

// Share of comparable peers that must have run under the same promotional
// conditions for a verdict to be like-for-like. Not a majority rule: the winter
// drop's peers split 3-3, and a tie resolving to "comparable" is exactly the
// wrong answer on the one comparison this was built for.
const CAMPAIGN_AGREEMENT_FLOOR = 0.7;

function parseDiscountPeriods(configured) {
  const raw = clean(configured) || DEFAULT_DISCOUNT_PERIODS;
  return raw
    .split(",")
    .map((part) => clean(part).split(":"))
    .filter((pair) => pair.length === 2 && pair[0] && pair[1])
    .map(([start, end]) => ({ start: clean(start), end: clean(end) }));
}

// Date-only string comparison is correct here: both sides are YYYY-MM-DD, which
// sorts lexicographically, and no timezone maths is involved.
function overlapsDiscountPeriod(windowStart, windowEnd, periods) {
  const a = clean(windowStart);
  const b = clean(windowEnd);
  if (!a || !b) return null;
  return periods.some((period) => a <= period.end && b >= period.start);
}

// Anything absent is reported as unmapped, never bucketed into "rest" — guessing
// a zone silently inflates or deflates the cost with no way to notice.
const FREIGHT_ZONE_BY_PROVINCE_CODE = Object.freeze({
  C: "metro",     // Cairo
  GZ: "metro",    // Giza
  SU: "metro",    // Shopify's "6th of October". 75 EGP confirmed by the founder 2026-09-13.
  ALX: "delta",   // Alexandria
  BH: "delta",    // Beheira
  GH: "delta",    // Gharbia
  DK: "delta",    // Dakahlia
  KFS: "delta",   // Kafr el-Sheikh
  DT: "delta",    // Damietta
  SHR: "delta",   // Sharqia
  MNF: "delta",   // Monufia
  KB: "metro"     // Qalyubia. 75 EGP confirmed by the founder 2026-09-13 (was priced
                  // at the 85 Delta rate before that).
});

function orderFreightZone(order) {
  const code = clean(order?.shippingAddress?.provinceCode).toUpperCase();
  if (!code) return "";
  return FREIGHT_ZONE_BY_PROVINCE_CODE[code] || "";
}

// Outbound legs are charged on every order that actually shipped. Return legs are
// charged only on those the courier brought back — which P1.24 measures directly
// from courier events rather than inferring from cancellations.
//
// The 2026-09-04 filing was blocked on P1.9 and on an open question: can
// ShopifyQL group `sales_reversals` by variant SKU? That question is now moot.
// already identified without touching `sales_reversals` at all — and the line
// items are already in the orders payload. Same basis as the weekly RTO figure,
// zero new subrequests, and none of the two-basis risk the original spec feared.
//
// Deliberately NOT allocating freight to SKUs. Freight is billed per ORDER; a
// three-item order pays one round trip. Splitting that across lines needs an
// allocation rule nobody has chosen, and an invented rule would put a precise
// wrong number against each product. Units and revenue are attributable; the
// shipping cost is not.
const SKU_RTO_MIN_UNITS = 10;

function summarizeSkuDelivery(orders) {
  const bySku = new Map();

  const bump = (sku, field, amount) => {
    if (!sku) return;
    const row = bySku.get(sku) || { units_shipped: 0, units_not_delivered: 0, revenue_not_delivered: 0, orders_shipped: 0 };
    row[field] += amount;
    bySku.set(sku, row);
  };

  for (const order of orders || []) {
    const outcome = orderDeliveryOutcome(order);
    // Never dispatched: it was not shipped, so it cannot have come back.
    if (outcome.outcome === "unfulfilled") continue;
    // Still in flight or unreadable. Counting these as delivered would understate
    // every rate; counting them as returned would overstate it. They are excluded
    // from BOTH sides, which is why the denominator is resolved units only.
    if (outcome.outcome !== "delivered" && outcome.outcome !== "not_delivered") continue;

    const returned = outcome.outcome === "not_delivered";
    const seen = new Set();

    for (const edge of order?.lineItems?.edges || []) {
      const node = edge?.node || {};
      const sku = clean(node.sku);
      if (!sku) continue;
      // currentQuantity reflects removals; fall back to the ordered quantity.
      const qty = num(node.currentQuantity !== undefined && node.currentQuantity !== null ? node.currentQuantity : node.quantity);
      if (qty <= 0) continue;

      bump(sku, "units_shipped", qty);
      if (!seen.has(sku)) {
        bump(sku, "orders_shipped", 1);
        seen.add(sku);
      }
      if (returned) {
        bump(sku, "units_not_delivered", qty);
        bump(sku, "revenue_not_delivered", qty * num(money(node.originalUnitPriceSet)));
      }
    }
  }

  const out = {};
  for (const [sku, row] of bySku.entries()) {
    out[sku] = {
      ...row,
      revenue_not_delivered: r2(row.revenue_not_delivered),
      // A rate on a tiny denominator is noise wearing a percentage sign.
      rto_rate_units: row.units_shipped >= SKU_RTO_MIN_UNITS
        ? r4(row.units_not_delivered / row.units_shipped)
        : "",
      rto_basis: row.units_shipped >= SKU_RTO_MIN_UNITS
        ? "courier_events_resolved_units"
        : `below_${SKU_RTO_MIN_UNITS}_unit_floor`
    };
  }
  return out;
}

function summarizeFreight(orders, config) {
  let outboundCost = 0;
  let returnCost = 0;
  let collectedValue = 0;
  let shipped = 0;
  let returned = 0;
  let mapped = 0;
  const unmappedProvinces = {};
  // Bosta on 1 of 21 — a second carrier, priced here at ShipBlu's rates because
  // nothing else is known. Counted so the mispricing is visible rather than
  // silently folded into the total.
  const byCarrier = {};
  const byZone = { metro: 0, delta: 0, rest: 0 };

  for (const order of orders || []) {
    const outcome = orderDeliveryOutcome(order);
    // Never dispatched means no leg was billed either way.
    if (outcome.outcome === "unfulfilled") continue;
    shipped += 1;

    const zone = orderFreightZone(order);
    if (!zone) {
      const label = clean(order?.shippingAddress?.province) || clean(order?.shippingAddress?.provinceCode) || "(no address)";
      unmappedProvinces[label] = (unmappedProvinces[label] || 0) + 1;
      continue;
    }

    mapped += 1;
    byZone[zone] += 1;
    const carrier = clean(order?.fulfillments?.[0]?.trackingInfo?.[0]?.company) || "unknown";
    byCarrier[carrier] = (byCarrier[carrier] || 0) + 1;
    const rate = FREIGHT_RATES[zone];
    outboundCost += rate;

    if (outcome.outcome === "not_delivered") {
      returned += 1;
      // Assumption 1: return leg priced as outbound.
      returnCost += rate;
    } else if (outcome.outcome === "delivered") {
      // Only a delivered parcel hands over money, so only it incurs a
      // collection fee. In-flight orders are in neither bucket yet.
      collectedValue += num(money(order.currentTotalPriceSet));
    }
  }

  // Config can override the assumed rate the moment the real one is known,
  // without a deploy.
  const configured = metricOrBlank(config?.codFeeRate);
  const codRate = configured === "" ? COD_FEE_RATE_ASSUMED : num(configured);

  return {
    shipped_orders: shipped,
    priced_orders: mapped,
    returned_orders: returned,
    coverage_rate: shipped ? r4(mapped / shipped) : "",
    outbound_cost: r2(outboundCost),
    // The number that answers "what does RTO actually cost".
    return_cost: r2(returnCost),
    total_cost: r2(outboundCost + returnCost),
    orders_by_zone: byZone,
    orders_by_carrier: byCarrier,
    // Orders priced at the ShipBlu card that were not carried by ShipBlu.
    non_shipblu_orders: Object.entries(byCarrier)
      .filter(([carrier]) => !/shipblu/i.test(carrier))
      .reduce((a, [, n]) => a + n, 0),
    unmapped_provinces: Object.entries(unmappedProvinces)
      .map(([province, orders_affected]) => ({ province, orders_affected }))
      .sort((a, b) => b.orders_affected - a.orders_affected),
    basis: mapped === 0
      ? "no_priced_orders"
      : (mapped === shipped ? "founder_rate_card" : "founder_rate_card_partial"),
    cod_collected_value: r2(collectedValue),
    cod_fee_rate: codRate,
    cod_fee: r2(collectedValue * codRate),
    cod_fee_basis: configured === "" ? "assumed_2pct_unconfirmed" : "configured_rate",
    assumptions: [
      "A return leg is priced the same as an outbound leg — CONFIRM with ShipBlu.",
      "COD collection fee is applied at an ASSUMED 2% of collected value — the founder has not confirmed the real rate. Contribution moves linearly with it, so a wrong rate is wrong by the same ratio. CONFIRM with ShipBlu.",
      "The rate card is ShipBlu's, but not every parcel ships ShipBlu — see orders_by_carrier. Non-ShipBlu parcels are priced at ShipBlu rates because no other card exists. CONFIRM the other carrier's rates."
    ]
  };
}

function summarizeDelivery(orders) {
  const counts = { delivered: 0, not_delivered: 0, pending: 0, unfulfilled: 0, unknown: 0 };
  // Any status not in the three sets is recorded by name rather than silently
  // bucketed, so a new courier state shows up instead of quietly inflating
  // `unknown`.
  const unknownStatuses = {};
  let attempts = 0;
  let multiAttempt = 0;
  let postDispatchFailures = 0;
  let postDispatchUnconfirmed = 0;
  let noCarrierData = 0;
  let carrierReporting = 0;
  const carrierCounts = {};
  const durations = [];

  for (const order of orders || []) {
    const d = orderDeliveryOutcome(order);
    if (d.dispatch_phase === "post_dispatch") postDispatchFailures += 1;
    if (d.dispatch_phase === "post_dispatch_unconfirmed") postDispatchUnconfirmed += 1;
    if (d.dispatch_phase === "unknown_no_carrier_data") noCarrierData += 1;
    if (d.carrier) carrierCounts[d.carrier] = (carrierCounts[d.carrier] || 0) + 1;
    if (d.carrier_reported) carrierReporting += 1;
    counts[d.outcome] = (counts[d.outcome] || 0) + 1;
    if (d.outcome === "unknown" && d.latest_status) {
      unknownStatuses[d.latest_status] = (unknownStatuses[d.latest_status] || 0) + 1;
    }
    attempts += d.attempts;
    if (d.attempts > 1) multiAttempt += 1;
    if (d.days_to_outcome !== "") durations.push(d.days_to_outcome);
  }

  const total = (orders || []).length;
  const resolved = counts.delivered + counts.not_delivered;

  const median = (arr) => {
    if (!arr.length) return "";
    const a = [...arr].sort((x, y) => x - y);
    return a[Math.floor(a.length / 2)];
  };

  return {
    orders_total: total,
    delivered: counts.delivered,
    not_delivered: counts.not_delivered,
    pending: counts.pending,
    unfulfilled: counts.unfulfilled,
    unknown: counts.unknown,
    unknown_statuses: unknownStatuses,
    resolved_orders: resolved,
    // Rate over RESOLVED orders only. Dividing by all orders would understate
    // the failure rate for any recent week, where most parcels are still moving.
    not_delivered_rate: resolved ? r4(counts.not_delivered / resolved) : "",
    // inferred from fulfillment status at cancellation on one 34-order batch.
    post_dispatch_failures: postDispatchFailures,
    post_dispatch_unconfirmed: postDispatchUnconfirmed,
    failures_without_carrier_data: noCarrierData,
    // Share of failures CONFIRMED post-dispatch by a transit timestamp.
    //
    // Blank when nothing is confirmed, rather than 0. On the DHL Express weeks
    // every failure is "unconfirmed" — the carrier reports a failure but no
    // transit time — and reporting 0% there would assert those parcels never
    // shipped, which is the opposite of what is known. Blank says "cannot tell";
    // 0% would have said "all pre-dispatch".
    post_dispatch_share:
      postDispatchFailures > 0
        ? r4(postDispatchFailures / (postDispatchFailures + postDispatchUnconfirmed))
        : "",
    // Coverage: what share of orders ship on a carrier that reports at all.
    // Delivery metrics are only as good as this.
    carrier_reporting_rate: total ? r4(carrierReporting / total) : "",
    carriers: carrierCounts,
    delivery_attempts_total: attempts,
    multi_attempt_orders: multiAttempt,
    median_days_to_outcome: median(durations),
    // Parallel to attribution_settled: a week whose parcels are still in flight
    // cannot yet state its delivery outcome.
    delivery_settled: total > 0 && counts.pending === 0 && counts.unfulfilled === 0,
    resolved_share: total ? r4(resolved / total) : ""
  };
}

// ── Attribution capture (P1.17) ──────────────────────────────────────────────
//
// The theme snippet writes underscore-prefixed cart attributes, which Shopify
// carries into the order as note_attributes and the Admin API exposes as
// customAttributes. See attribution/README.md and
// coddiwomple-data-architecture.md §3.
//
// This reads them and reports capture health. It is deliberately built BEFORE
// the snippet is live: until then every order is unattributed, which is the
// correct reading and exactly what the health metric should say.
//
// Resolution order is strict, per §3, and stops at the first match:
//   1. click_id  present -> exact
//   2. utm_content matches a known ad id -> high confidence
//   3. utm_campaign only -> campaign level
//   4. nothing -> unattributed. NEVER silently assigned to last click.
const ATTRIBUTION_KEYS = {
  click_id: "_cw_click_id",
  platform: "_cw_platform",
  campaign: "_cw_campaign",
  content: "_cw_content",
  landing: "_cw_landing"
};

function orderAttributionAttributes(order) {
  const out = {};
  for (const attr of order?.customAttributes || []) {
    const key = clean(attr?.key);
    if (!key) continue;
    out[key] = clean(attr?.value);
  }
  return out;
}

// Known ad ids, scoped by platform.
//
// Today this set holds Meta ad ids only, so a bare `has(content)` is safe. The
// moment TikTok ad ids join it that stops being true: an order carrying
// `_cw_platform: meta` whose content id happens to match a TikTok ad would be
// joined to the wrong platform's ad and reported as `ad_id` — the highest
// confidence tier — while being simply wrong. Ad ids from different platforms
// share no namespace and nothing prevents a collision.
//
// Resolution rules, in order:
//   1. The order names its platform and we hold ads for it -> match within that
//      platform only.
//   2. The order names a platform we hold no ads for (TikTok today) -> we cannot
//      confirm which ad, so it falls to the campaign tier. Not a failure.
//   3. The order names no platform -> match across all platforms, but only if
//      the id appears in exactly ONE. An ambiguous id is downgraded rather than
//      guessed, because guessing here is indistinguishable from knowing.
//
// Accepts a bare Set for backward compatibility, treated as Meta's.
function knownAdLookup(knownAds) {
  if (!knownAds) return { find: () => "" };

  const byPlatform = knownAds instanceof Set
    ? new Map([["meta", knownAds]])
    : new Map(Object.entries(knownAds).map(([k, v]) => [clean(k).toLowerCase(), v]));

  return {
    find(adId, platform) {
      if (!adId) return "";
      const p = clean(platform).toLowerCase();
      if (p) {
        const set = byPlatform.get(p);
        // Rule 2: a platform we do not hold ads for cannot confirm an ad id.
        return set && set.has(adId) ? p : "";
      }
      const hits = [...byPlatform.entries()].filter(([, set]) => set && set.has(adId));
      // Rule 3: ambiguous means unknown.
      return hits.length === 1 ? hits[0][0] : "";
    }
  };
}

function resolveOrderAttribution(order, knownAds) {
  const attrs = orderAttributionAttributes(order);
  const clickId = clean(attrs[ATTRIBUTION_KEYS.click_id]);
  const content = clean(attrs[ATTRIBUTION_KEYS.content]);
  const campaign = clean(attrs[ATTRIBUTION_KEYS.campaign]);
  const statedPlatform = clean(attrs[ATTRIBUTION_KEYS.platform]);
  const lookup = knownAdLookup(knownAds);
  // The platform the ad id was actually FOUND under, which is authoritative over
  // the one the URL claimed.
  const matchedPlatform = lookup.find(content, statedPlatform);

  // A click id ALONE does not identify an ad. §3 reserves "exact" for a click id
  // matched in the platform's click export, which this pipeline does not have.
  // Meta appends fbclid automatically with no account configuration, so this
  // tier fires today, before any URL parameters are set — it proves the order
  // came from a Meta ad, not which one. Calling that "exact" would have
  // overstated what we know and let ad-level analysis run on it.
  if (clickId) {
    return {
      confidence: matchedPlatform ? "exact" : "platform_click",
      click_id: clickId,
      platform: matchedPlatform || statedPlatform,
      ad_id: matchedPlatform ? content : "",
      campaign,
      landing: clean(attrs[ATTRIBUTION_KEYS.landing])
    };
  }

  if (matchedPlatform) {
    return { confidence: "ad_id", click_id: "", platform: matchedPlatform, ad_id: content, campaign, landing: clean(attrs[ATTRIBUTION_KEYS.landing]) };
  }

  if (campaign) {
    return { confidence: "campaign", click_id: "", platform: statedPlatform, ad_id: "", campaign, landing: clean(attrs[ATTRIBUTION_KEYS.landing]) };
  }

  return { confidence: "unattributed", click_id: "", platform: "", ad_id: "", campaign: "", landing: "" };
}

// Health metric, per §3: an unattributed share above ~25% means capture is
// broken and every downstream attribution number is suspect. Before the snippet
// ships this reads 100% unattributed / "not_live", which is correct rather than
// alarming — the distinction matters, because "not installed" and "installed and
// failing" need different responses.
const ATTRIBUTION_UNATTRIBUTED_THRESHOLD = 0.25;

function summarizeAttributionCapture(orders, knownAds) {
  const counts = { exact: 0, ad_id: 0, platform_click: 0, campaign: 0, unattributed: 0 };
  // carry `_cw_platform: tiktok`, and the pipeline syncs Meta only — so every
  // figure that divides revenue by meta_spend has a denominator missing a whole
  // channel. The orders themselves are the cheapest possible detector of that,
  // and they answer it a full sync ahead of any TikTok integration.
  const byPlatform = {};
  let anySignal = false;

  for (const order of orders || []) {
    const resolved = resolveOrderAttribution(order, knownAds);
    counts[resolved.confidence] += 1;
    if (resolved.confidence !== "unattributed") {
      anySignal = true;
      // Unknown platform is its own bucket, never folded into meta.
      const platform = clean(resolved.platform).toLowerCase() || "unknown";
      byPlatform[platform] = (byPlatform[platform] || 0) + 1;
    }
  }

  const nonMetaAttributed = Object.entries(byPlatform)
    .filter(([platform]) => platform !== "meta")
    .reduce((a, [, n]) => a + n, 0);

  const total = (orders || []).length;

  // Two different questions, deliberately not merged:
  //   attributed        — capture fired at all (is the snippet working?)
  //   ad_attributed     — we know WHICH ad (can we do per-ad CAC and RTO?)
  // Reporting only the first would make a platform_click-only week look fully
  // solved while every per-ad analysis remained impossible.
  const attributed = counts.exact + counts.ad_id + counts.platform_click + counts.campaign;
  const adAttributed = counts.exact + counts.ad_id;
  const unattributedShare = total ? r4(counts.unattributed / total) : "";
  const adAttributedShare = total ? r4(adAttributed / total) : "";

  let health = "ok";
  if (!total) health = "no_orders";
  else if (!anySignal) health = "not_live";
  else if (unattributedShare !== "" && unattributedShare > ATTRIBUTION_UNATTRIBUTED_THRESHOLD) health = "degraded";

  return {
    orders_total: total,
    attributed_orders: attributed,
    ad_attributed_orders: adAttributed,
    unattributed_orders: counts.unattributed,
    unattributed_share: unattributedShare,
    ad_attributed_share: adAttributedShare,
    by_confidence: counts,
    by_platform: byPlatform,
    // Orders proven to come from a paid platform this pipeline does not sync.
    // Any figure dividing by meta_spend alone is understating its denominator by
    // whatever these cost.
    non_meta_attributed_orders: nonMetaAttributed,
    attributed_platforms: Object.keys(byPlatform).sort().join(","),
    threshold: ATTRIBUTION_UNATTRIBUTED_THRESHOLD,
    // ok | degraded | not_live | no_orders
    health,
    note:
      health === "not_live"
        ? "No order carries capture attributes. Expected until the theme snippet ships — see attribution/README.md. Not a failure."
        : adAttributed === 0 && attributed > 0
          ? "Capture is working but no order resolves to a specific ad: Meta appends fbclid automatically, while utm_content requires the ad-account URL parameters. Paid-vs-organic is answerable; per-ad CAC and per-ad RTO are not until those are set."
        : health === "degraded"
          ? `Unattributed share is above ${ATTRIBUTION_UNATTRIBUTED_THRESHOLD * 100}%. Capture is likely broken; treat every attribution number as suspect until fixed.`
          : ""
  };
}

// ── P1.2 drop dimension ──────────────────────────────────────────────────────
//
// days_since_drop is measured from the actual `drop_date`, NOT from the Sunday
// of the drop week. Anchoring to the week start would implicitly claim that a
// Monday drop's calendar week is "W0", when it is really six drop days plus one
// pre-drop day. Five of the seven 2026 drops land mid-week, and the artifact is
// visible: the May 14 (Thu) drop reads W+1 375 against W0 315 purely because W0
// held three drop days.
//
// Known limit: the fact rows are Sunday-Saturday, so a true drop-relative 7-day
// window for a mid-week drop straddles two rows. Full drop-relative windowing
// needs a daily series. It makes no difference for Sep 20 vs Jul 26 — both are
// Sunday drops, so the two frames coincide — and is only needed for the post-
// mortem comparison against Jun 29 / May 14.
async function loadDropCalendar(env) {
  const db = syncDb(env);
  if (!db) return [];

  try {
    const result = await db
      .prepare(
        `SELECT drop_id, drop_date, drop_week_start, drop_weekday, w0_is_partial,
                w0_orders, floor_orders, season, label
         FROM dim_drop ORDER BY drop_date ASC`
      )
      .all();
    return result?.results || [];
  } catch (_) {
    // The dimension is additive. A missing table must not fail a sync.
    return [];
  }
}

// The governing drop for a week is the latest drop that had started by the time
// the week ended. A drop landing mid-week governs that week.
function dropPositionForWeek(drops, boundaries) {
  const weekStart = clean(boundaries?.week_start);
  const weekEnd = clean(boundaries?.week_end);
  if (!weekStart || !weekEnd) return null;

  const governing = (drops || [])
    .filter((d) => clean(d.drop_date) && clean(d.drop_date) <= weekEnd)
    .sort((a, b) => clean(b.drop_date).localeCompare(clean(a.drop_date)))[0];

  if (!governing) return null;

  const dropMs = dateOnlyToUtcMs(clean(governing.drop_date));
  const daysSinceDrop = Math.round((dateOnlyToUtcMs(weekStart) - dropMs) / DAY_MS);

  // Drop-relative week index, measured from the week's END so that a calendar
  // week straddling a mid-week drop still lands in the right bucket.
  //
  // Measuring from week_start instead is wrong and was shipped briefly: for the
  // Jun 29 (Mon) drop, week 2026-07-05 reads days_since_drop = 6, which falls
  // outside a [7,28] day window — so W1, the steepest decay week, escaped
  // suppression. Five of the seven 2026 drops land mid-week, so that missed the
  // exact false alarm this rule exists to prevent on most of them.
  //
  // floor((week_end - drop_date) / 7) gives W0..W4 correctly for Sunday and
  // mid-week drops alike. Verified against Jul 26 (Sun) and Jun 29 (Mon).
  const daysSinceDropAtWeekEnd = Math.round((dateOnlyToUtcMs(weekEnd) - dropMs) / DAY_MS);
  const weekIndex = Math.floor(daysSinceDropAtWeekEnd / 7);

  // metricOrBlank, not num: num("") and num(null) both return 0, which would
  // turn "no observable floor" into a floor of zero.
  const floor = metricOrBlank(governing.floor_orders);

  return {
    drop_id: clean(governing.drop_id),
    drop_date: clean(governing.drop_date),
    drop_label: clean(governing.label),
    // Negative in the drop week when the week starts before the drop lands.
    days_since_drop: daysSinceDrop,
    days_since_drop_at_week_end: daysSinceDropAtWeekEnd,
    drop_week_index: weekIndex,
    drop_week_label: weekIndex === 0 ? "W0" : `W+${weekIndex}`,
    w0_is_partial: num(governing.w0_is_partial) === 1,
    floor_orders: floor === "" ? "" : floor
  };
}

// drop_lift = this week's orders ÷ the governing drop's observed floor.
// Blank, never zero, when the floor is unknown — most drops were cut short by
// the next one and have no observable floor.
function dropLift(position, orders) {
  if (!position) return "";
  // metricOrBlank throughout: num("") is 0, so using num here would report a
  // lift of 0 for a week with no order count rather than leaving it blank.
  const floor = metricOrBlank(position.floor_orders);
  if (floor === "" || floor === 0) return "";
  const value = metricOrBlank(orders);
  if (value === "") return "";
  return r4(value / floor);
}

// ── P1.12 week freshness ─────────────────────────────────────────────────────
//
// weekCompletenessFromTabs asks only "does this week have a row in each source
// tab?" It cannot see whether those rows agree with each other. That was an
// acceptable trade while rows were written seconds apart by the same sync, and
// stopped being acceptable the moment a metric definition changed under stored
// reversal semantics and a ReportWeekly row written under the new, with all four
// rows present and mutually inconsistent. Row presence reads "complete"; only
// synced_at coherence can see it.
//
// A stale week stays VIEWABLE. The point is to say so, not to hide it again —
// hiding correct-but-flagged data is the bug P1.13 just removed.
function weekFreshnessFromTabs(tabData, weekStart) {
  const syncedAtFor = (tab) => {
    const row = rowsForWeek(tabData, tab, weekStart)[0];
    return clean(row?.synced_at);
  };

  const reportSyncedAt = syncedAtFor("ReportWeekly");
  const sources = {
    ShopifyWeekly: syncedAtFor("ShopifyWeekly"),
    GA4Weekly: syncedAtFor("GA4Weekly"),
    MetaWeekly: syncedAtFor("MetaWeekly")
  };

  // Never guess, and never default to fresh: a blank timestamp anywhere means
  // the comparison cannot be made, which is "unknown", not "fresh".
  const blanks = Object.entries(sources)
    .filter(([, value]) => value === "")
    .map(([tab]) => tab);

  if (reportSyncedAt === "" || blanks.length) {
    return {
      freshness: "unknown",
      report_synced_at: reportSyncedAt,
      source_synced_at: sources,
      missing_synced_at: reportSyncedAt === "" ? ["ReportWeekly", ...blanks] : blanks,
      stale_sources: []
    };
  }

  const reportMs = Date.parse(reportSyncedAt);

  if (!Number.isFinite(reportMs)) {
    return {
      freshness: "unknown",
      report_synced_at: reportSyncedAt,
      source_synced_at: sources,
      missing_synced_at: ["ReportWeekly"],
      stale_sources: []
    };
  }

  // Stale when the report row predates a source row it was derived from.
  const staleSources = Object.entries(sources)
    .filter(([, value]) => {
      const ms = Date.parse(value);
      return Number.isFinite(ms) && ms > reportMs;
    })
    .map(([tab]) => tab);

  return {
    freshness: staleSources.length ? "stale" : "fresh",
    report_synced_at: reportSyncedAt,
    source_synced_at: sources,
    missing_synced_at: [],
    stale_sources: staleSources
  };
}

function weekCompletenessFromTabs(tabData, weekStart) {
  const sourceCounts = {
    ga4_weekly: rowsForWeek(tabData, "GA4Weekly", weekStart).length,
    meta_weekly: rowsForWeek(tabData, "MetaWeekly", weekStart).length,
    shopify_weekly: rowsForWeek(tabData, "ShopifyWeekly", weekStart).length,
    report_weekly: rowsForWeek(tabData, "ReportWeekly", weekStart).length,
    report_actions: rowsForWeek(tabData, "ReportActions", weekStart).length
  };

  const missingSources = Object.entries(sourceCounts)
    .filter(([key, count]) => key !== "report_actions" && count < 1)
    .map(([key]) => key);

  return {
    source_counts: sourceCounts,
    is_complete: missingSources.length === 0,
    missing_sources: missingSources
  };
}

async function verifyRowsForWeek(env, weekStart, tabNames) {
  const tabData = await readAllTabs(env);
  const rowCounts = Object.fromEntries(
    tabNames.map((tab) => [tab, rowsForWeek(tabData, tab, weekStart).length])
  );
  const missing = tabNames.filter((tab) => rowCounts[tab] < 1);
  if (missing.length) {
    throw new Error(`Missing expected rows for ${weekStart}: ${missing.join(", ")}.`);
  }
  return {
    week_start: weekStart,
    verified_tabs: [...tabNames],
    row_counts: rowCounts
  };
}

async function buildReportArtifacts(env, weekStart) {
  const tabData = await readAllTabs(env);
  const config = parseConfig(tabData.Config, env);
  assertCompletedWeek(weekStart, config.timezone);
  const boundaries = weekBoundaries(weekStart, config.timezone);
  const syncedAt = new Date().toISOString();

  const existingWeekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly);
  const existingProduct = objectsFromTab(tabData, "ShopifyProductWeekly", HEADERS.ShopifyProductWeekly);
  const existingSku = objectsFromTab(tabData, "ShopifySkuWeekly", HEADERS.ShopifySkuWeekly);
  const existingProdDiag = objectsFromTab(tabData, "ShopifyProductDiagnosis", HEADERS.ShopifyProductDiagnosis);
  const existingSkuDiag = objectsFromTab(tabData, "ShopifySkuDiagnosis", HEADERS.ShopifySkuDiagnosis);
  const existingGA4Weekly = objectsFromTab(tabData, "GA4Weekly", HEADERS.GA4Weekly);
  const existingGA4Product = objectsFromTab(tabData, "GA4ProductWeekly", HEADERS.GA4ProductWeekly);
  const existingMetaWeekly = objectsFromTab(tabData, "MetaWeekly", HEADERS.MetaWeekly);
  const existingMetaAd = objectsFromTab(tabData, "MetaAdWeekly", HEADERS.MetaAdWeekly);
  const existingReport = objectsFromTab(tabData, "ReportWeekly", HEADERS.ReportWeekly);
  const existingActions = objectsFromTab(tabData, "ReportActions", HEADERS.ReportActions);

  const weeklyRow = existingWeekly.find((r) => clean(r.week_start) === weekStart) || null;
  const ga4Row = existingGA4Weekly.find((r) => clean(r.week_start) === weekStart) || null;
  const metaRow = existingMetaWeekly.find((r) => clean(r.week_start) === weekStart) || null;

  if (!weeklyRow) throw new Error(`Cannot rebuild report: missing ShopifyWeekly row for ${weekStart}.`);
  if (!ga4Row) throw new Error(`Cannot rebuild report: missing GA4Weekly row for ${weekStart}.`);
  if (!metaRow) throw new Error(`Cannot rebuild report: missing MetaWeekly row for ${weekStart}.`);

  const productRows = existingProduct.filter((r) => clean(r.week_start) === weekStart);
  const skuRows = existingSku.filter((r) => clean(r.week_start) === weekStart);
  const productDiagnosis = existingProdDiag.filter((r) => clean(r.week_start) === weekStart);
  const skuDiagnosis = existingSkuDiag.filter((r) => clean(r.week_start) === weekStart);

  const reportRow = buildReportWeekly(
    boundaries,
    syncedAt,
    weeklyRow,
    ga4Row,
    metaRow,
    new Map(existingWeekly.map((r) => [clean(r.week_start), r])),
    new Map(existingGA4Weekly.map((r) => [clean(r.week_start), r])),
    new Map(existingReport.map((r) => [clean(r.week_start), r])),
    productDiagnosis,
    skuDiagnosis
  );

  const actionRows = buildActions({
    boundaries,
    syncedAt,
    reportRow,
    weeklyRow,
    ga4Row,
    metaRow,
    productRows,
    skuRows,
    productDiagnosis,
    skuDiagnosis,
    metaAdRows: existingMetaAd.filter((r) => clean(r.week_start) === weekStart),
    ga4ProductRows: existingGA4Product.filter((r) => clean(r.week_start) === weekStart)
  });

  const finalReport = upsertObjects(existingReport, [reportRow], (r) => clean(r.week_start));
  const finalActions = replaceObjectsForWeek(existingActions, weekStart, actionRows);

  return {
    finalReport,
    finalActions,
    report_actions_rows: actionRows.length,
    synced_at: syncedAt,
    tabData
  };
}

async function rebuildReportWeekly(env, weekStart) {
  const artifacts = await buildReportArtifacts(env, weekStart);

  const snapshot = await snapshotTabsBeforeRewrite(env, {
    source: "report_weekly",
    weekStart,
    runId: "",
    endpoint: "rebuildReportWeekly",
    tabData: artifacts.tabData,
    tabs: ["ReportWeekly"]
  });

  // ReportWeekly is upsertObjects([reportRow]) — always at least one data row,
  // so an empty result is a bug. allowEmpty stays false.
  const rewrite = await rewriteTabs(env, {
    source: "report_weekly",
    tabData: artifacts.tabData,
    tabsToRewrite: [
      {
        tab: "ReportWeekly",
        headers: HEADERS.ReportWeekly,
        objects: artifacts.finalReport,
        allowEmpty: false
      }
    ]
  });

  return {
    report_weekly_rows: 1,
    synced_at: artifacts.synced_at,
    snapshot,
    rewrite
  };
}

async function rebuildReportActions(env, weekStart) {
  const artifacts = await buildReportArtifacts(env, weekStart);

  const snapshot = await snapshotTabsBeforeRewrite(env, {
    source: "report_actions",
    weekStart,
    runId: "",
    endpoint: "rebuildReportActions",
    tabData: artifacts.tabData,
    tabs: ["ReportActions"]
  });

  // buildActions emits nothing unconditionally — all 17 addAction sites are
  // guarded — so a clean week legitimately produces zero actions. allowEmpty is
  // true: this must not turn a quiet week into a non-retryable failure and a
  const rewrite = await rewriteTabs(env, {
    source: "report_actions",
    tabData: artifacts.tabData,
    tabsToRewrite: [
      {
        tab: "ReportActions",
        headers: HEADERS.ReportActions,
        objects: artifacts.finalActions,
        allowEmpty: true
      }
    ]
  });

  return {
    report_actions_rows: artifacts.report_actions_rows,
    synced_at: artifacts.synced_at,
    snapshot,
    rewrite
  };
}

async function startWeeklySync(env, { weekStart, triggerType }) {
  const config = await getConfig(env);
  assertCompletedWeek(weekStart, config.timezone);
  const claim = await claimWeeklyRun(env, { weekStart, triggerType });
  if (!claim.should_start) return claim;

  const instance = await createWeeklyWorkflowInstance(env, claim.run);
  const run = await updateRunState(env, claim.run.run_id, {
    status: "queued",
    workflow_instance_id: instance.id
  });

  return {
    ...claim,
    run,
    workflow_instance_id: instance.id,
    workflow_status: instance.status ? await instance.status() : null
  };
}

function requireWeeklyWorkflow(env) {
  if (!env.WEEKLY_SYNC_WORKFLOW) {
    throw new Error("Missing Workflow binding WEEKLY_SYNC_WORKFLOW. Add the [[workflows]] binding before using automation.");
  }
  return env.WEEKLY_SYNC_WORKFLOW;
}

async function createWeeklyWorkflowInstance(env, run) {
  const workflow = requireWeeklyWorkflow(env);
  const instanceId = makeWeeklyWorkflowInstanceId(run);

  try {
    return await workflow.create({
      id: instanceId,
      params: {
        run_id: run.run_id,
        run_key: run.run_key,
        week_start: run.week_start,
        week_end: run.week_end,
        trigger_type: run.trigger_type
      }
    });
  } catch (err) {
    const existing = await workflow.get(instanceId);
    if (existing) return existing;
    throw err;
  }
}

async function workflowStatusForRun(env, run) {
  if (!run?.workflow_instance_id || !env.WEEKLY_SYNC_WORKFLOW) return null;
  try {
    const instance = await env.WEEKLY_SYNC_WORKFLOW.get(run.workflow_instance_id);
    return instance?.status ? await instance.status() : null;
  } catch (err) {
    const error = truncateOperationalError(err);
    return {
      status: error.includes("instance.not_found") || error.includes("Instance not found")
        ? "missing"
        : "unknown",
      error
    };
  }
}

function workflowRunIsMissing(status) {
  return clean(status?.status).toLowerCase() === "missing" ||
    clean(status?.error).toLowerCase().includes("instance.not_found") ||
    clean(status?.error).toLowerCase().includes("instance not found");
}

function workflowRunIsActive(status) {
  const value = clean(status?.status).toLowerCase();
  return ["queued", "running", "waiting", "paused"].includes(value);
}

function workflowStatusError(status) {
  return clean(
    status?.error?.message ||
    status?.rollback?.error?.message ||
    (typeof status?.error === "string" ? status.error : "")
  );
}

function runWithWorkflowStatus(run, workflowStatus) {
  if (!run) return null;
  const workflowState = clean(workflowStatus?.status).toLowerCase();
  if (!["errored", "terminated"].includes(workflowState)) return run;

  return {
    ...run,
    status: "failed",
    workflow_status: workflowState,
    error_message:
      workflowStatusError(workflowStatus) ||
      run.error_message ||
      `Cloudflare Workflow ${workflowState} without a provider error message.`,
    last_provider_error: workflowStatusError(workflowStatus) || run.last_provider_error,
    partial_reason: run.partial_reason || `Workflow ${workflowState} at ${run.current_step || "an unknown step"}.`
  };
}

async function stepFailure(env, runId, err, statusPatch = {}) {
  await updateRunState(env, runId, {
    status: "failed",
    finished_at: new Date().toISOString(),
    error_message: truncateOperationalError(err),
    last_provider_error: truncateOperationalError(err),
    is_complete: false,
    partial_reason: `Failed at ${statusPatch.current_step || "unknown"}.`,
    ...statusPatch
  });
  throwWorkflowError(err);
}

async function sourceAlreadyComplete(env, run, sourceStatus, verifyTabs) {
  const current = await getRunById(env, run.run_id);
  if (current?.[sourceStatus] !== "complete") return false;

  try {
    await verifyRowsForWeek(env, run.week_start, verifyTabs);
    return true;
  } catch (_) {
    return false;
  }
}

async function runGa4SyncStep(env, run) {
  if (await sourceAlreadyComplete(env, run, "ga4_status", ["GA4Weekly"])) {
    return { skipped: true, reason: "GA4 already complete and verified." };
  }

  await updateRunState(env, run.run_id, {
    status: "running",
    current_step: "ga4_sync",
    ga4_status: "running",
    step_attempt: 0,
    next_retry_at: ""
  });

  try {
    const result = await syncGA4Week(env, {
      week_start: run.week_start,
      endpoint: "workflow:ga4"
    });
    await updateRunState(env, run.run_id, {
      ga4_status: "complete",
      rows_written_json: {
        ...(await getRunById(env, run.run_id))?.rows_written,
        ga4: {
          weekly_rows: result.ga4_weekly_rows || 0,
          product_rows: result.ga4_product_rows || 0
        }
      }
    });
    return result;
  } catch (err) {
    return stepFailure(env, run.run_id, err, {
      current_step: "ga4_sync",
      ga4_status: "failed"
    });
  }
}

async function runMetaSyncStep(env, run) {
  if (await sourceAlreadyComplete(env, run, "meta_status", ["MetaWeekly"])) {
    return { skipped: true, reason: "Meta already complete and verified." };
  }

  await updateRunState(env, run.run_id, {
    status: "running",
    current_step: "meta_sync",
    meta_status: "running",
    step_attempt: 0,
    next_retry_at: ""
  });

  try {
    const result = await syncMetaWeek(env, {
      week_start: run.week_start,
      endpoint: "workflow:meta"
    });
    await updateRunState(env, run.run_id, {
      meta_status: "complete",
      rows_written_json: {
        ...(await getRunById(env, run.run_id))?.rows_written,
        meta: {
          weekly_rows: result.meta_weekly_rows || 0,
          campaign_rows: result.meta_campaign_rows || 0,
          ad_rows: result.meta_ad_rows || 0
        }
      }
    });
    return result;
  } catch (err) {
    return stepFailure(env, run.run_id, err, {
      current_step: "meta_sync",
      meta_status: "failed"
    });
  }
}

async function runShopifySyncStep(env, run) {
  if (await sourceAlreadyComplete(env, run, "shopify_status", ["ShopifyWeekly"])) {
    return { skipped: true, reason: "Shopify already complete and verified." };
  }

  await updateRunState(env, run.run_id, {
    status: "running",
    current_step: "shopify_sync",
    shopify_status: "running",
    step_attempt: 0,
    next_retry_at: ""
  });

  try {
    const result = await syncShopifyAll(env, {
      week_start: run.week_start,
      endpoint: "workflow:shopify"
    });
    await updateRunState(env, run.run_id, {
      shopify_status: "complete",
      rows_written_json: {
        ...(await getRunById(env, run.run_id))?.rows_written,
        shopify: {
          weekly_rows: result.shopify_weekly_rows || 0,
          product_rows: result.product_rows || 0,
          sku_rows: result.sku_rows || 0,
          inventory_snapshot_rows: result.inventory_snapshot_rows || 0,
          product_diagnosis_rows: result.product_diagnosis_rows || 0,
          sku_diagnosis_rows: result.sku_diagnosis_rows || 0
        }
      }
    });
    return result;
  } catch (err) {
    return stepFailure(env, run.run_id, err, {
      current_step: "shopify_sync",
      shopify_status: "failed"
    });
  }
}

async function runReportWeeklyStep(env, run) {
  await updateRunState(env, run.run_id, {
    status: "running",
    current_step: "report_weekly_rebuild",
    report_status: "running",
    step_attempt: 0,
    next_retry_at: ""
  });

  try {
    const result = await rebuildReportWeekly(env, run.week_start);
    await updateRunState(env, run.run_id, {
      rows_written_json: {
        ...(await getRunById(env, run.run_id))?.rows_written,
        report_weekly: result
      }
    });
    return result;
  } catch (err) {
    return stepFailure(env, run.run_id, err, {
      current_step: "report_weekly_rebuild",
      report_status: "failed"
    });
  }
}

async function runReportActionsStep(env, run) {
  await updateRunState(env, run.run_id, {
    status: "running",
    current_step: "report_actions_rebuild",
    report_status: "running",
    step_attempt: 0,
    next_retry_at: ""
  });

  try {
    const result = await rebuildReportActions(env, run.week_start);
    await updateRunState(env, run.run_id, {
      rows_written_json: {
        ...(await getRunById(env, run.run_id))?.rows_written,
        report_actions: result
      }
    });
    return result;
  } catch (err) {
    return stepFailure(env, run.run_id, err, {
      current_step: "report_actions_rebuild",
      report_status: "failed"
    });
  }
}

export class WeeklySyncWorkflow extends WorkflowEntrypoint {
  async run(event, step) {
    const params = event.payload || {};
    let run = await step.do(
      "Initialize/lock run",
      WORKFLOW_STEP_CONFIGS.initialize_lock,
      async () => {
        const current = await getRunById(this.env, params.run_id);
        if (!current) throw new NonRetryableError(`Run ${params.run_id} was not found.`);
        if (current.is_complete) return current;
        return updateRunState(this.env, current.run_id, {
          status: "running",
          current_step: "initialize_lock",
          workflow_instance_id: makeWeeklyWorkflowInstanceId(current),
          finished_at: "",
          error_message: "",
          last_provider_error: "",
          partial_reason: ""
        });
      }
    );

    if (run.is_complete) return run;

    await step.do("GA4 sync", WORKFLOW_STEP_CONFIGS.ga4_sync, async () => runGa4SyncStep(this.env, run));
    await step.do("GA4 verification", WORKFLOW_STEP_CONFIGS.ga4_verify, async () => {
      await updateRunState(this.env, run.run_id, { current_step: "ga4_verify" });
      try {
        return await verifyRowsForWeek(this.env, run.week_start, ["GA4Weekly"]);
      } catch (err) {
        return stepFailure(this.env, run.run_id, err, {
          current_step: "ga4_verify",
          ga4_status: "failed"
        });
      }
    });

    await step.do("Meta sync", WORKFLOW_STEP_CONFIGS.meta_sync, async () => runMetaSyncStep(this.env, run));
    await step.do("Meta verification", WORKFLOW_STEP_CONFIGS.meta_verify, async () => {
      await updateRunState(this.env, run.run_id, { current_step: "meta_verify" });
      try {
        return await verifyRowsForWeek(this.env, run.week_start, ["MetaWeekly"]);
      } catch (err) {
        return stepFailure(this.env, run.run_id, err, {
          current_step: "meta_verify",
          meta_status: "failed"
        });
      }
    });

    await step.do("Shopify sync", WORKFLOW_STEP_CONFIGS.shopify_sync, async () => runShopifySyncStep(this.env, run));
    await step.do("Shopify verification", WORKFLOW_STEP_CONFIGS.shopify_verify, async () => {
      await updateRunState(this.env, run.run_id, { current_step: "shopify_verify" });
      try {
        return await verifyRowsForWeek(this.env, run.week_start, ["ShopifyWeekly"]);
      } catch (err) {
        return stepFailure(this.env, run.run_id, err, {
          current_step: "shopify_verify",
          shopify_status: "failed"
        });
      }
    });

    await step.do("ReportWeekly rebuild", WORKFLOW_STEP_CONFIGS.report_weekly_rebuild, async () =>
      runReportWeeklyStep(this.env, run)
    );
    await step.do("ReportActions rebuild", WORKFLOW_STEP_CONFIGS.report_actions_rebuild, async () =>
      runReportActionsStep(this.env, run)
    );

    await step.do("Final completeness verification", WORKFLOW_STEP_CONFIGS.final_report_verify, async () => {
      await updateRunState(this.env, run.run_id, { current_step: "final_report_verify" });
      try {
        const verification = await verifyRowsForWeek(this.env, run.week_start, [
          "GA4Weekly",
          "MetaWeekly",
          "ShopifyWeekly",
          "ReportWeekly"
        ]);
        return {
          source_counts: {
            ga4_weekly: verification.row_counts.GA4Weekly,
            meta_weekly: verification.row_counts.MetaWeekly,
            shopify_weekly: verification.row_counts.ShopifyWeekly,
            report_weekly: verification.row_counts.ReportWeekly
          },
          is_complete: true,
          missing_sources: []
        };
      } catch (err) {
        return stepFailure(this.env, run.run_id, err, {
          current_step: "final_report_verify",
          report_status: "failed"
        });
      }
    });

    return step.do("Mark complete", WORKFLOW_STEP_CONFIGS.complete, async () =>
      updateRunState(this.env, run.run_id, {
        status: "complete",
        current_step: "complete",
        finished_at: new Date().toISOString(),
        report_status: "complete",
        is_complete: true,
        partial_reason: "",
        next_retry_at: "",
        last_provider_error: ""
      })
    );
  }
}

async function buildSyncStatus(env, selectedWeek = "") {
  const config = await getConfig(env);
  const weekStart = resolveWeekStartInput(selectedWeek, config);
  const latestRun = await getLatestRun(env);
  const selectedRun = weekStart ? await getRunByWeek(env, weekStart) : null;
  const latestWorkflowStatus = await workflowStatusForRun(env, latestRun);
  const selectedWorkflowStatus = await workflowStatusForRun(env, selectedRun);

  return {
    ok: true,
    selected_week: weekStart,
    latest_completed_week: latestCompletedSundayWeekStart(config.timezone),
    latest_run: runWithWorkflowStatus(latestRun, latestWorkflowStatus),
    selected_run: runWithWorkflowStatus(selectedRun, selectedWorkflowStatus),
    latest_workflow_status: latestWorkflowStatus,
    selected_workflow_status: selectedWorkflowStatus,
    step_plan: weeklySyncStepPlan(),
    workflow_retry_matrix: workflowRetryMatrix()
  };
}

async function buildReportWeeks(env) {
  const tabData = await readAllTabs(env);
  const config = parseConfig(tabData.Config, env);
  const reportRows = objectsFromTab(tabData, "ReportWeekly", HEADERS.ReportWeekly);
  const storedRuns = await listRecentRuns(env, 250);
  const runs = await Promise.all(storedRuns.map(async (run) => {
    if (!["queued", "running"].includes(clean(run.status).toLowerCase())) return run;
    const workflowStatus = await workflowStatusForRun(env, run);
    return runWithWorkflowStatus(run, workflowStatus);
  }));
  const weeks = new Map();

  function ensureWeek(weekStart) {
    const key = clean(weekStart);
    if (!key) return null;
    if (!weeks.has(key)) {
      weeks.set(key, {
        week_start: key,
        week_end: addDays(key, 6),
        completeness: "not_synced",
        is_complete: false,

        // Two independent questions, two fields. Neither is derived from the
        // other and nothing overwrites either.
        //   data_status — is the data for this week present in the tabs?
        //   run_status  — did the Workflow run for this week, and how did it end?
        // These were previously conflated in sync_status, which meant a week
        // replayed outside the Workflow read as unavailable even though its data
        // was complete and correct.
        data_status: "not_synced",
        run_status: "none",

        // P1.12: fresh | stale | unknown. Never defaults to fresh.
        freshness: "unknown",
        stale_sources: [],

        // DEPRECATED: alias of data_status, kept for one release so a Worker
        // deploy landing before the Pages deploy does not break the UI. Remove
        // once report-ui reads data_status. Not to be confused with
        // reportData.sync_status on /report-data, which is an object of genuine
        // run state and is unrelated to this field.
        sync_status: "not_synced",

        failed_step: "",
        error_message: "",
        updated_at: ""
      });
    }
    return weeks.get(key);
  }

  for (const row of reportRows) {
    const week = ensureWeek(row.week_start);
    if (!week) continue;
    const completeness = weekCompletenessFromTabs(tabData, week.week_start);
    week.report_status = clean(row.report_status || "Report row available");
    week.source_counts = completeness.source_counts;
    week.is_complete = completeness.is_complete;
    week.completeness = completeness.is_complete ? "complete" : "partial";
    week.missing_sources = completeness.missing_sources;

    // Data presence only. Run state never touches this.
    week.data_status = completeness.is_complete ? "complete" : "partial";
    week.sync_status = week.data_status;

    // each other? Shown as a badge, never a gate — a stale week stays selectable.
    const freshness = weekFreshnessFromTabs(tabData, week.week_start);
    week.freshness = freshness.freshness;
    week.stale_sources = freshness.stale_sources;
    week.report_synced_at = freshness.report_synced_at;
    week.missing_synced_at = freshness.missing_synced_at;
  }

  for (const run of runs) {
    const week = ensureWeek(run.week_start);
    if (!week) continue;
    week.run_id = run.run_id;

    // Run state only. This must never write to data_status or sync_status —
    // that overwrite is precisely what made replayed weeks unviewable.
    week.run_status = clean(run.status) || "none";

    week.failed_step = run.status === "failed" ? run.current_step : "";
    week.error_message = run.error_message;
    week.updated_at = run.updated_at;
    week.retry_count = run.retry_count;

    if (run.is_complete && week.is_complete) {
      week.completeness = "complete";
    } else if (run.status === "failed") {
      week.completeness = week.is_complete ? "complete" : "failed";
    } else if (["queued", "running"].includes(run.status)) {
      week.completeness = week.is_complete ? "complete" : "in_progress";
    }
  }

  const orderedWeeks = [...weeks.values()].sort((a, b) =>
    clean(b.week_start).localeCompare(clean(a.week_start))
  );
  const latestComplete = selectLatestCompleteReportWeek(orderedWeeks);

  return {
    ok: true,
    timezone: config.timezone,
    latest_completed_calendar_week: latestCompletedSundayWeekStart(config.timezone),
    latest_completed_available_week: latestComplete?.week_start || "",
    weeks: orderedWeeks
  };
}

// Availability is a question about data, not about whether the Workflow ran.
// A week replayed through the individual sync endpoints has complete, correct
// state hid seven weeks of good data behind an audit-trail detail.
//
// with each other. It becomes insufficient once a metric definition changes
// under already-stored rows.
function selectLatestCompleteReportWeek(weeks) {
  return (weeks || []).find((week) => week.is_complete && clean(week.data_status) === "complete") || null;
}

function sortByNumberDesc(rows, field) {
  return [...rows].sort((a, b) => num(b[field]) - num(a[field]));
}

function metricValueFromReportData(data, metric) {
  const scoreboard = data?.scoreboard || {};
  const revenue = data?.revenue?.weekly || {};
  const paid = data?.paid?.weekly || {};
  const returns = data?.returns || {};
  const map = {
    net_sales: scoreboard.net_sales?.current ?? revenue.net_sales,
    orders: scoreboard.orders?.current ?? revenue.orders,
    conversion_rate: scoreboard.conversion_rate?.current,
    mer: scoreboard.mer?.current,
    meta_roas: paid.roas,
    refund_rate: returns.refund_rate,
    item_return_rate: returns.item_return_rate,
    sell_through_rate: revenue.weekly_sell_through_rate,
    ending_inventory_units: revenue.ending_inventory_units
  };
  return metricOrBlank(map[metric]);
}

function goalDirection(goal) {
  if (["refund_rate", "item_return_rate"].includes(goal.primary_metric)) return "decrease";
  if (goal.target_type === "threshold" && /below|under|less|max/i.test(goal.original_text || "")) return "decrease";
  return "increase";
}

function calculateGoalProgress(goalSpec, reportData, weekStart = "") {
  const goal = sanitizeGoalObject(goalSpec || {});
  const current = metricValueFromReportData(reportData, goal.primary_metric);
  const baseline = goal.baseline_value !== "" ? goal.baseline_value : "";
  let target = goal.target_value;
  const warnings = [];
  const direction = goalDirection(goal);

  if (current === "") {
    warnings.push(`Current value for ${goal.primary_metric} is unavailable for ${weekStart || "the selected week"}.`);
  }

  if (goal.target_type === "percentage_growth") {
    if (baseline === "") warnings.push("Percentage-growth target needs a baseline value.");
    target = baseline === "" ? "" : baseline * (1 + num(goal.target_value));
  }

  if (goal.target_type === "directional") target = "";
  if (goal.target_type !== "directional" && target === "") {
    warnings.push("Target value is unavailable.");
  }

  let gap = "";
  let gap_pct = "";
  let status = "insufficient_data";
  if (current !== "" && target !== "") {
    gap = direction === "decrease" ? current - target : target - current;
    gap_pct = target ? gap / Math.abs(target) : "";
    const met = direction === "decrease" ? current <= target : current >= target;
    status = met ? "on_track" : "off_track";
  } else if (current !== "" && goal.target_type === "directional") {
    status = "directional";
  }

  return {
    week_start: weekStart,
    goal_id: goal.goal_id,
    goal_version: goal.version,
    name: goal.name,
    primary_metric: goal.primary_metric,
    target_type: goal.target_type,
    target_value: target === "" ? "" : r4(target),
    target_unit: goal.target_unit,
    current_value: current === "" ? "" : r4(current),
    baseline_value: baseline === "" ? "" : r4(baseline),
    gap: gap === "" ? "" : r4(gap),
    gap_pct: gap_pct === "" ? "" : r4(gap_pct),
    direction,
    deadline: goal.deadline,
    horizon_days: goal.horizon_days,
    status,
    warnings
  };
}

function evidenceObject(fields = {}) {
  return Object.fromEntries(
    Object.entries(fields).map(([key, value]) => [key, value === "" ? "" : value])
  );
}

function buildFunnelDiagnosis(reportData) {
  const weekly = reportData?.funnel?.weekly || {};
  const scoreboard = reportData?.scoreboard || {};
  const sessions = metricOrBlank(weekly.sessions);
  const productViewRate = metricOrBlank(weekly.product_view_rate);
  const atcRate = metricOrBlank(weekly.atc_rate);
  const checkoutStartRate = metricOrBlank(weekly.checkout_start_rate);
  const checkoutCompletionRate = metricOrBlank(weekly.checkout_completion_rate);
  const cvr = metricOrBlank(scoreboard.conversion_rate?.current);
  const warnings = [];
  const bottlenecks = [];

  if (sessions === "") warnings.push("GA4 sessions are missing.");
  if (sessions === 0) warnings.push("GA4 sessions are zero.");

  function add(label, score, evidence, threshold) {
    bottlenecks.push({ label, score: clamp(score), evidence, threshold });
  }

  if (productViewRate !== "") add("Product discovery", (0.3 - productViewRate) / 0.3 * 100, { product_view_rate: productViewRate }, "product_view_rate >= 0.30");
  if (atcRate !== "") add("Product-page conversion", (0.08 - atcRate) / 0.08 * 100, { atc_rate: atcRate }, "atc_rate >= 0.08");
  if (checkoutStartRate !== "") add("Cart-to-checkout progression", (0.35 - checkoutStartRate) / 0.35 * 100, { checkout_start_rate: checkoutStartRate }, "checkout_start_rate >= 0.35");
  if (checkoutCompletionRate !== "") add("Checkout completion", (0.35 - checkoutCompletionRate) / 0.35 * 100, { checkout_completion_rate: checkoutCompletionRate }, "checkout_completion_rate >= 0.35");

  const largest = bottlenecks.sort((a, b) => b.score - a.score)[0] || null;

  return {
    entity_type: "funnel",
    entity_id: "sitewide",
    entity_name: "Sitewide funnel",
    classification: largest && largest.score > 0 ? largest.label : "No major funnel bottleneck isolated",
    largest_bottleneck: largest && largest.score > 0 ? largest.label : "",
    evidence_fields: evidenceObject({
      sessions,
      product_view_rate: productViewRate,
      add_to_cart_rate: atcRate,
      checkout_start_rate: checkoutStartRate,
      checkout_completion_rate: checkoutCompletionRate,
      shopify_orders_per_ga4_session: cvr
    }),
    thresholds: {
      product_view_rate: 0.3,
      atc_rate: 0.08,
      checkout_start_rate: 0.35,
      checkout_completion_rate: 0.35
    },
    confidence: warnings.length ? 45 : largest && largest.score > 0 ? 78 : 65,
    missing_data_warnings: warnings,
    selected_week: reportData?.week?.week_start || "",
    comparison_period: "Current week; WoW and trailing-four-week comparison when ReportWeekly fields exist.",
    bottlenecks
  };
}

function normalizedProductKey(value) {
  return clean(value).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function aggregateFunnelProductRows(rows = []) {
  const products = new Map();
  for (const row of rows || []) {
    const key = normalizedProductKey(row.item_name) || clean(row.item_id).toLowerCase();
    if (!key) continue;
    if (!products.has(key)) {
      products.set(key, {
        week_start: clean(row.week_start),
        week_end: clean(row.week_end),
        item_id: clean(row.item_id),
        item_name: clean(row.item_name || "Unnamed product"),
        item_views: 0,
        add_to_carts: 0,
        begin_checkouts: 0,
        purchases: 0,
        item_revenue: 0
      });
    }
    const product = products.get(key);
    product.item_views += num(row.item_views);
    product.add_to_carts += num(row.add_to_carts);
    product.begin_checkouts += num(row.begin_checkouts);
    product.purchases += num(row.purchases);
    product.item_revenue += num(row.item_revenue);
  }
  return [...products.values()].map((product) => ({
    ...product,
    view_to_cart_rate: product.item_views ? r4(div(product.add_to_carts, product.item_views)) : "",
    cart_to_checkout_rate: product.add_to_carts ? r4(div(product.begin_checkouts, product.add_to_carts)) : "",
    checkout_to_purchase_rate: product.begin_checkouts ? r4(div(product.purchases, product.begin_checkouts)) : "",
    view_to_purchase_rate: product.item_views ? r4(div(product.purchases, product.item_views)) : ""
  }));
}

function percentile(sortedNumbers, pct) {
  const values = (sortedNumbers || []).filter((value) => Number.isFinite(Number(value))).map(Number).sort((a, b) => a - b);
  if (!values.length) return "";
  const index = Math.min(values.length - 1, Math.max(0, Math.ceil(values.length * pct) - 1));
  return values[index];
}

function medianNumeric(values = []) {
  const sorted = values.filter((value) => Number.isFinite(Number(value))).map(Number).sort((a, b) => a - b);
  if (!sorted.length) return "";
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function productSampleStats(productRows = [], funnelProductsByName = new Map()) {
  const netSalesValues = productRows.map((row) => num(row.net_sales)).filter((value) => value > 0);
  const unitsValues = productRows.map((row) => num(row.units_sold || row.net_units_sold)).filter((value) => value > 0);
  const velocityValues = productRows.map((row) => num(row.daily_velocity_7d)).filter((value) => value > 0);
  const conversionValues = productRows
    .map((row) => funnelProductsByName.get(normalizedProductKey(row.product_title)))
    .map((row) => metricOrBlank(row?.view_to_purchase_rate))
    .filter((value) => value !== "" && value > 0);
  // in from a different business, and it is applied to PRODUCT-level
  // view-to-cart, where this store runs nearer 3.3%. A goal the shop has never
  // reached fires on almost every product, so "demand-constrained" stopped
  // carrying information.
  //
  // The fix is to ask a question the data can answer: is this product worse than
  // this store's typical product? That is a relative judgement and it is stated
  // as one — the label is "below this store's median", not "below goal".
  const viewToCartValues = productRows
    .map((row) => funnelProductsByName.get(normalizedProductKey(row.product_title)))
    .map((row) => metricOrBlank(row?.view_to_cart_rate))
    .filter((value) => value !== "" && value > 0);

  const viewToCartMedian = medianNumeric(viewToCartValues);

  // Below this many products the median is noise, and a constant that is wrong
  // for the store still beats a median drawn from three items. Which one fired is
  // reported rather than left for the reader to infer.
  const MIN_SAMPLE = 5;
  const derived = viewToCartValues.length >= MIN_SAMPLE && viewToCartMedian !== "";

  return {
    net_sales_q75: percentile(netSalesValues, 0.75),
    units_q75: percentile(unitsValues, 0.75),
    velocity_q75: percentile(velocityValues, 0.75),
    conversion_median: medianNumeric(conversionValues),
    material_revenue_floor: Math.max(500, percentile(netSalesValues, 0.5) || 0),

    view_to_cart_median: viewToCartMedian,
    view_to_cart_sample: viewToCartValues.length,
    working_add_to_cart_rate: derived ? viewToCartMedian : DIAGNOSIS_THRESHOLDS.working_add_to_cart_rate,
    working_add_to_cart_rate_basis: derived ? "store_median" : "fallback_constant"
  };
}

// The add-to-cart bar a product is judged against. Derived from the store's own
// products when there are enough of them; otherwise the historical constant,
// which is wrong for this shop but is at least stable.
function workingAddToCartRate(stats) {
  const derived = metricOrBlank(stats?.working_add_to_cart_rate);
  return derived === "" ? DIAGNOSIS_THRESHOLDS.working_add_to_cart_rate : num(derived);
}

function productWinnerSignals(row, funnelRow = null, stats = {}) {
  const units = num(row.units_sold || row.net_units_sold);
  const orders = num(row.orders);
  const netSales = num(row.net_sales);
  const velocity = num(row.daily_velocity_7d);
  const current7d = num(row.current_7d_units);
  const viewToPurchase = metricOrBlank(funnelRow?.view_to_purchase_rate);
  const minimumWeeklySample =
    units >= DIAGNOSIS_THRESHOLDS.minimum_winner_units ||
    (orders >= DIAGNOSIS_THRESHOLDS.minimum_winner_orders && netSales >= num(stats.material_revenue_floor));
  const signals = [];
  if (stats.net_sales_q75 !== "" && netSales >= num(stats.net_sales_q75) && netSales > 0) signals.push("top_quartile_net_sales");
  if (stats.units_q75 !== "" && units >= num(stats.units_q75) && units > 0) signals.push("top_quartile_units");
  if (viewToPurchase !== "" && stats.conversion_median !== "" && viewToPurchase >= num(stats.conversion_median) && num(funnelRow?.item_views) >= DIAGNOSIS_THRESHOLDS.minimum_product_views) signals.push("above_median_product_conversion");
  if (velocity >= Math.max(DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity, num(stats.velocity_q75) || 0)) signals.push("strong_daily_velocity");
  if (current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units) signals.push("meaningful_rolling_units");
  return {
    minimum_weekly_sample: minimumWeeklySample,
    signal_count: signals.length,
    signals
  };
}

function classificationLogicGuide() {
  return {
    supply_constrained: {
      label: "Supply-constrained",
      logic: "Requires proven weekly demand plus low/zero stock, high OOS variant rate, or days of cover below threshold.",
      thresholds: {
        minimum_winner_units: DIAGNOSIS_THRESHOLDS.minimum_winner_units,
        minimum_winner_orders: DIAGNOSIS_THRESHOLDS.minimum_winner_orders,
        minimum_restock_daily_velocity: DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity,
        minimum_restock_units: DIAGNOSIS_THRESHOLDS.minimum_restock_units,
        low_days_cover: DIAGNOSIS_THRESHOLDS.low_days_cover,
        critical_days_cover: DIAGNOSIS_THRESHOLDS.critical_days_cover,
        stockout_oos_rate: DIAGNOSIS_THRESHOLDS.stockout_oos_rate
      }
    },
    demand_constrained: {
      label: "Demand/conversion-constrained",
      logic: "Requires enough product traffic, healthy stock/size availability, and a shortfall in add-to-cart, cart-to-checkout, or view-to-purchase.",
      thresholds: {
        minimum_funnel_diagnosis_views: DIAGNOSIS_THRESHOLDS.minimum_funnel_diagnosis_views,
        // Published as the constant because this block documents the RULE, not the
        // week's measured bar. The measured one travels with each classification.
        working_add_to_cart_rate_fallback: DIAGNOSIS_THRESHOLDS.working_add_to_cart_rate,
        working_cart_to_checkout_rate: DIAGNOSIS_THRESHOLDS.working_cart_to_checkout_rate,
        working_product_purchase_rate: DIAGNOSIS_THRESHOLDS.working_product_purchase_rate,
        healthy_stock_floor: DIAGNOSIS_THRESHOLDS.slow_inventory_units,
        minimum_days_cover: DIAGNOSIS_THRESHOLDS.low_days_cover,
        maximum_oos_variant_rate: DIAGNOSIS_THRESHOLDS.stockout_oos_rate
      }
    },
    slow_or_underexposed: {
      label: "Slow-moving / insufficient traffic",
      logic: "High stock with weak rolling unit movement is slow inventory; if views are below the experiment floor, the system labels weak exposure instead of inventing a demand constraint.",
      thresholds: {
        slow_inventory_units: DIAGNOSIS_THRESHOLDS.slow_inventory_units,
        slow_inventory_7d_units: DIAGNOSIS_THRESHOLDS.slow_inventory_7d_units,
        minimum_experiment_views: DIAGNOSIS_THRESHOLDS.minimum_experiment_views
      }
    },
    returns: {
      label: "Returns / product quality",
      logic: "Requires enough returned units and a return rate above the risk threshold; cause remains an investigation path, not a proved explanation.",
      thresholds: {
        minimum_return_units: DIAGNOSIS_THRESHOLDS.minimum_return_units,
        return_rate_risk: DIAGNOSIS_THRESHOLDS.return_rate_risk
      }
    },
    unavailable: {
      label: "Unavailable / no sellable stock",
      logic: "Zero-stock products and SKUs without enough proven demand for a restock conclusion are kept out of slow-moving and weak-sample buckets.",
      thresholds: {
        ending_inventory_units: 0,
        minimum_restock_units: DIAGNOSIS_THRESHOLDS.minimum_restock_units
      }
    }
  };
}

function variantStockSummary(variantRows = []) {
  const rows = (variantRows || [])
    .map((row) => ({
      variant_id: clean(row.variant_id || row.sku),
      variant_title: clean(row.variant_title || row.sku || "Variant"),
      stock: metricOrBlank(row.ending_inventory_units),
      units_sold: metricOrBlank(row.units_sold || row.net_units_sold),
      current_7d_units: metricOrBlank(row.current_7d_units),
      days_of_cover_7d: metricOrBlank(row.days_of_cover_7d),
      is_oos: clean(row.is_oos)
    }))
    .sort((a, b) => num(a.stock) - num(b.stock));
  return {
    variant_count: rows.length,
    total_variant_stock: rows.reduce((sum, row) => sum + (row.stock === "" ? 0 : num(row.stock)), 0),
    constrained_variants: rows.filter((row) => clean(row.is_oos).toUpperCase() === "TRUE" || row.stock === 0 || (row.days_of_cover_7d !== "" && row.days_of_cover_7d < DIAGNOSIS_THRESHOLDS.low_days_cover)).slice(0, 5),
    variants: rows.slice(0, 8)
  };
}

function productMoneyExplanation(classification, fields, currency = "EGP") {
  const unitValue = num(fields.units_sold) > 0 ? div(fields.net_sales, fields.units_sold) : "";
  if (/Supply-constrained/.test(classification) && unitValue !== "") {
    const shortfallUnits = Math.max(0, num(fields.units_sold) - num(fields.ending_inventory_units));
    const amount = r2(shortfallUnits * unitValue);
    if (amount > 0) {
      return {
        label: "EGP at risk next week",
        type: "revenue at risk",
        amount,
        currency,
        period: "next 7 days",
        formula: "max(0, selected-week units sold - current product stock) * selected-week product net sales per unit",
        inputs: {
          units_sold: fields.units_sold,
          ending_inventory_units: fields.ending_inventory_units,
          product_net_sales_per_unit: r2(unitValue)
        },
        confidence: fields.ending_inventory_units === "" ? "low" : "medium",
        assumptions: ["Assumes next-week demand is similar to the selected completed week.", "Uses product net sales per unit because margin is not supplied."],
        quantified_reason: "Proven demand and current stock imply a measurable next-week revenue cap."
      };
    }
  }
  if (classification === "Demand/conversion-constrained" && unitValue !== "" && fields.item_views !== "" && fields.view_to_purchase_rate !== "") {
    const current = Math.max(0, num(fields.view_to_purchase_rate));
    const target = Math.max(DIAGNOSIS_THRESHOLDS.healthy_product_conversion_rate, current * 1.15);
    const incrementalUnits = Math.max(0, num(fields.item_views) * (target - current));
    const amount = r2(incrementalUnits * unitValue);
    if (amount > 0) {
      return {
        label: "EGP upside next week",
        type: "revenue upside",
        amount,
        currency,
        period: "next 7 days",
        formula: "product views * max(healthy CVR floor, current CVR * 1.15 - current CVR) * selected-week product net sales per unit",
        inputs: {
          item_views: fields.item_views,
          current_view_to_purchase_rate: fields.view_to_purchase_rate,
          target_view_to_purchase_rate: r4(target),
          product_net_sales_per_unit: r2(unitValue)
        },
        confidence: "low",
        assumptions: ["Uses a conservative next-week conversion lift estimate; causality must be tested."],
        quantified_reason: "Traffic, stock, and product value are present, so upside can be estimated as a conversion-lift range."
      };
    }
  }
  return {
    label: "Unquantified",
    type: "not quantified",
    amount: "",
    currency,
    period: "next 7 days",
    formula: "No defensible next-week EGP calculation from the current row.",
    inputs: {},
    confidence: "low",
    unquantified_reason: "Current data lacks either product value, enough demand sample, or a positive estimated gap."
  };
}

function productClassificationExplanation(row, funnelRow, classification, fields, winner, warnings, variantRows = [], currency = "EGP", stats = {}) {
  const stock = metricOrBlank(fields.ending_inventory_units);
  const itemViews = metricOrBlank(fields.item_views);
  const viewToCart = metricOrBlank(fields.view_to_cart_rate);
  const cartToCheckout = metricOrBlank(fields.cart_to_checkout_rate);
  const viewToPurchase = metricOrBlank(fields.view_to_purchase_rate);
  const cover = metricOrBlank(fields.days_of_cover_7d);
  const returnRate = metricOrBlank(fields.return_rate_units);
  const variants = variantStockSummary(variantRows);
  const passed = [];
  const failed = [];
  const urgent = [];
  if (winner.minimum_weekly_sample) passed.push("minimum weekly sales/order sample");
  else failed.push("minimum weekly sales/order sample");
  if (winner.signal_count >= 2) passed.push(`${winner.signal_count} winner signals`);
  else failed.push("at least 2 winner signals");
  if (cover !== "" && cover < DIAGNOSIS_THRESHOLDS.low_days_cover) passed.push("days of cover below 14");
  if (cover !== "" && cover < DIAGNOSIS_THRESHOLDS.critical_days_cover) urgent.push("days of cover below 7");
  if (stock !== "" && stock <= 0) urgent.push("zero product stock");
  if (fields.oos_variant_rate !== "" && fields.oos_variant_rate >= DIAGNOSIS_THRESHOLDS.stockout_oos_rate) urgent.push("OOS variant rate above 50%");
  if (itemViews !== "" && itemViews >= DIAGNOSIS_THRESHOLDS.minimum_funnel_diagnosis_views) passed.push("product traffic sample above diagnosis floor");
  else if (itemViews !== "") failed.push("product traffic below diagnosis floor");
  // Says which bar was used. "Below goal" against a goal the store has never met
  // is the sentence that made this landmine invisible for months.
  const atcBar = workingAddToCartRate(stats);
  if (viewToCart !== "" && viewToCart < atcBar) {
    passed.push(
      clean(stats?.working_add_to_cart_rate_basis) === "store_median"
        ? `view-to-cart below this store's median (${r2(atcBar * 100)}%)`
        : `view-to-cart below the fallback goal (${r2(atcBar * 100)}%) — too few products to measure this store`
    );
  }
  if (cartToCheckout !== "" && cartToCheckout < DIAGNOSIS_THRESHOLDS.working_cart_to_checkout_rate) passed.push("cart-to-checkout below working goal");
  if (viewToPurchase !== "" && viewToPurchase < DIAGNOSIS_THRESHOLDS.working_product_purchase_rate) passed.push("view-to-purchase below working goal");
  if (returnRate !== "" && returnRate >= DIAGNOSIS_THRESHOLDS.return_rate_risk) passed.push("return rate above risk threshold");

  const whyNotSupply = /Demand|Slow-moving|insufficient traffic|Weak sample|Underexposed/.test(classification)
    ? "Not classified as supply-constrained because proven winner signals plus low-cover/OOS evidence were not both present."
    : "";
  const investigation = classification === "Demand/conversion-constrained"
    ? "Check PDP media, price, offer, fit/sizing clarity, traffic source match, and merchandising before changing stock decisions."
    : /Unavailable/.test(classification)
      ? "Keep this item out of slow-mover decisions until sellable stock returns; then collect qualified traffic before judging demand."
    : /Slow-moving|insufficient traffic|Weak sample/.test(classification)
      ? "First increase qualified exposure or collect more views; then reassess demand before discounting broadly."
      : /Return-risk/.test(classification)
        ? "Inspect return reasons, sizing/fit, imagery, QA, fulfillment, and expectation mismatch."
        : "Review product-level demand, stock cover, variant mix, and next-week availability.";

  return {
    label: classification,
    summary: `${classification}: ${clean(row.product_title || row.sku || row.variant_title || "entity")} was evaluated with sales, stock, variant cover, GA4 product views/ATC, returns, and rolling velocity.`,
    section_logic: classificationLogicGuide(),
    formula: "Winner sample + winner signals + stock/cover/OOS decide supply constraints; traffic + funnel shortfall + healthy stock decide demand constraints; zero stock without proven demand is unavailable; high stock + low rolling units decide slow inventory; returns override when material.",
    metrics_considered: ["units_sold", "orders", "net_sales", "ending_inventory_units", "variant stock", "days_of_cover_7d", "oos_variant_rate", "current_7d_units", "daily_velocity_7d", "item_views", "view_to_cart_rate", "cart_to_checkout_rate", "view_to_purchase_rate", "returned_items", "return_rate_units"],
    thresholds_used: DIAGNOSIS_THRESHOLDS,
    passed_thresholds: passed,
    failed_thresholds: failed,
    urgent_thresholds: urgent,
    why_not_stock_constrained: whyNotSupply,
    investigation_path: investigation,
    variant_stock: variants,
    money: productMoneyExplanation(classification, fields, currency),
    warnings
  };
}

function hasProvenCurrentDemand(fields = {}) {
  const units = num(fields.units_sold);
  const orders = num(fields.orders);
  const netSales = num(fields.net_sales);
  const velocity = num(fields.daily_velocity_7d);
  const current7d = num(fields.current_7d_units);
  return (
    units >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ||
    (orders >= DIAGNOSIS_THRESHOLDS.minimum_winner_orders && netSales > 0) ||
    velocity >= DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity ||
    current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units
  );
}

function classifyInventoryProduct(row, funnelRow = null, stats = {}, variantRows = [], currency = "EGP") {
  const units = num(row.units_sold || row.net_units_sold);
  const orders = num(row.orders);
  const netSales = num(row.net_sales);
  const stockMetric = metricOrBlank(row.ending_inventory_units);
  const stock = stockMetric === "" ? "" : num(stockMetric);
  const cover = metricOrBlank(row.days_of_cover_7d);
  const sellThrough = metricOrBlank(row.weekly_sell_through_rate);
  const oosRate = metricOrBlank(row.oos_variant_rate);
  const current7d = num(row.current_7d_units);
  const velocity = num(row.daily_velocity_7d);
  const itemViews = metricOrBlank(funnelRow?.item_views);
  const viewToCart = metricOrBlank(funnelRow?.view_to_cart_rate);
  const cartToCheckout = metricOrBlank(funnelRow?.cart_to_checkout_rate);
  const checkoutToPurchase = metricOrBlank(funnelRow?.checkout_to_purchase_rate);
  const viewToPurchase = metricOrBlank(funnelRow?.view_to_purchase_rate);
  const returned = num(row.returned_items);
  const returnRate = metricOrBlank(row.return_rate_units);
  const winner = productWinnerSignals(row, funnelRow, stats);
  const warnings = [];
  let classification = "Insufficient data";
  let confidence = 45;

  if (!clean(row.product_id)) warnings.push("Product ID missing; product joins use title only and are low-confidence.");
  if (!funnelRow) warnings.push("No reliable GA4 product row joined; funnel/product mapping is low-confidence or unavailable.");

  const provenCurrentDemand =
    units >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ||
    current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ||
    velocity >= DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity;
  const healthyStockForFunnel =
    stock !== "" &&
    stock >= DIAGNOSIS_THRESHOLDS.slow_inventory_units &&
    (velocity <= 0 || (cover !== "" && cover >= DIAGNOSIS_THRESHOLDS.low_days_cover)) &&
    (oosRate === "" || oosRate < DIAGNOSIS_THRESHOLDS.stockout_oos_rate);
  const atcBar = workingAddToCartRate(stats);
  const funnelShortfall =
    (viewToCart !== "" && viewToCart < atcBar) ||
    (cartToCheckout !== "" && cartToCheckout < DIAGNOSIS_THRESHOLDS.working_cart_to_checkout_rate) ||
    (viewToPurchase !== "" && viewToPurchase < DIAGNOSIS_THRESHOLDS.working_product_purchase_rate);

  if (stock !== "" && stock <= 0) {
    classification = provenCurrentDemand ? "Supply-constrained continuity risk" : "Unavailable / no sellable stock";
    confidence = provenCurrentDemand ? 78 : 88;
  } else if (winner.minimum_weekly_sample && winner.signal_count >= 2 && oosRate >= DIAGNOSIS_THRESHOLDS.stockout_oos_rate) {
    classification = "Supply-constrained winner";
    confidence = 86;
  } else if (winner.minimum_weekly_sample && winner.signal_count >= 2 && cover !== "" && cover < DIAGNOSIS_THRESHOLDS.low_days_cover && (velocity >= DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity || current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units)) {
    classification = cover < DIAGNOSIS_THRESHOLDS.critical_days_cover ? "Supply-constrained winner" : "Supply-constrained continuity risk";
    confidence = 82;
  } else if (itemViews >= DIAGNOSIS_THRESHOLDS.minimum_funnel_diagnosis_views && healthyStockForFunnel && funnelShortfall) {
    classification = "Demand/conversion-constrained";
    confidence = itemViews >= DIAGNOSIS_THRESHOLDS.minimum_experiment_views ? 78 : 66;
  } else if (viewToPurchase !== "" && viewToPurchase >= DIAGNOSIS_THRESHOLDS.healthy_product_conversion_rate && itemViews >= 20 && itemViews < DIAGNOSIS_THRESHOLDS.minimum_product_views && (current7d >= 3 || units >= 3)) {
    classification = "Underexposed promising product";
    confidence = warnings.length ? 55 : 70;
  } else if (winner.minimum_weekly_sample && winner.signal_count >= 2 && stock > 10 && sellThrough !== "" && sellThrough >= 0.08) {
    classification = "Healthy / monitor";
    confidence = 70;
  } else if (stock >= DIAGNOSIS_THRESHOLDS.slow_inventory_units && current7d <= DIAGNOSIS_THRESHOLDS.slow_inventory_7d_units) {
    classification = itemViews !== "" && itemViews < DIAGNOSIS_THRESHOLDS.minimum_experiment_views
      ? "Slow-moving / insufficient traffic"
      : units <= 0 ? "Dead or near-dead inventory" : "Slow-moving inventory";
    confidence = 72;
  } else if (units > 0 && units <= 2 && itemViews !== "" && itemViews < DIAGNOSIS_THRESHOLDS.minimum_experiment_views && stock > 5) {
    classification = "Low exposure - cannot diagnose demand constraint yet";
    confidence = warnings.length ? 38 : 48;
  } else if (units > 0 || itemViews > 0 || stock > 0) {
    classification = "Weak sample / reject";
    confidence = 42;
  }

  if (returned >= DIAGNOSIS_THRESHOLDS.minimum_return_units && returnRate !== "" && returnRate >= DIAGNOSIS_THRESHOLDS.return_rate_risk) {
    classification = "Return-risk product";
    confidence = Math.max(confidence, 76);
  }

  const fields = evidenceObject({
    units_sold: units,
    orders,
    net_sales: netSales,
    ending_inventory_units: stock,
    days_of_cover_7d: cover,
    weekly_sell_through_rate: sellThrough,
    oos_variant_rate: oosRate,
    current_7d_units: current7d,
    daily_velocity_7d: velocity,
    item_views: itemViews,
    view_to_cart_rate: viewToCart,
    cart_to_checkout_rate: cartToCheckout,
    checkout_to_purchase_rate: checkoutToPurchase,
    view_to_purchase_rate: viewToPurchase,
    returned_items: returned,
    return_rate_units: returnRate,
    winner_signal_count: winner.signal_count,
    winner_signals: winner.signals.join(", ")
  });

  return {
    entity_type: "product",
    entity_id: clean(row.product_id || row.product_title),
    entity_name: clean(row.product_title || "Unnamed product"),
    classification,
    evidence_fields: fields,
    classification_explanation: productClassificationExplanation(row, funnelRow, classification, fields, winner, warnings, variantRows, currency, stats),
    thresholds: DIAGNOSIS_THRESHOLDS,
    confidence,
    missing_data_warnings: warnings,
    selected_week: clean(row.week_start),
    comparison_period: "Selected week with current inventory snapshot and rolling velocity fields where available.",
    join_confidence: funnelRow && clean(row.product_id) ? "medium" : funnelRow ? "low" : "none"
  };
}

function classifySku(row) {
  const units = num(row.units_sold || row.net_units_sold);
  const stockMetric = metricOrBlank(row.ending_inventory_units);
  const stock = stockMetric === "" ? "" : num(stockMetric);
  const cover = metricOrBlank(row.days_of_cover_7d);
  const velocity = num(row.daily_velocity_7d);
  const current7d = num(row.current_7d_units);
  const returned = num(row.returned_items);
  const returnRate = metricOrBlank(row.return_rate_units);
  const isOos = clean(row.is_oos).toUpperCase() === "TRUE";
  const hasNoSellableStock = isOos || (stock !== "" && stock <= 0);
  const provenCurrentDemand =
    units >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ||
    current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ||
    velocity >= DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity;
  let classification = "Insufficient data";
  let confidence = 50;
  const warnings = [];
  if (!clean(row.variant_id || row.sku)) warnings.push("SKU/variant identifier missing.");

  if (hasNoSellableStock && provenCurrentDemand) {
    classification = "Supply-constrained winner";
    confidence = 90;
  } else if (hasNoSellableStock) {
    classification = "Unavailable / no sellable stock";
    confidence = 88;
  } else if ((units >= DIAGNOSIS_THRESHOLDS.minimum_restock_units || current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units || velocity >= DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity) && cover !== "" && cover < DIAGNOSIS_THRESHOLDS.low_days_cover) {
    classification = cover < DIAGNOSIS_THRESHOLDS.critical_days_cover ? "Supply-constrained winner" : "Supply-constrained continuity risk";
    confidence = 84;
  } else if (stock >= DIAGNOSIS_THRESHOLDS.slow_inventory_units && current7d <= DIAGNOSIS_THRESHOLDS.slow_inventory_7d_units) {
    classification = units <= 0 ? "Dead or near-dead inventory" : "Slow-moving inventory";
    confidence = 72;
  } else if (units > 0 || current7d > 0 || stock > 0) {
    classification = units >= DIAGNOSIS_THRESHOLDS.minimum_restock_units || current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ? "Healthy / monitor" : "Weak sample / reject";
    confidence = units >= DIAGNOSIS_THRESHOLDS.minimum_restock_units || current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ? 64 : 42;
  }
  if (returned >= DIAGNOSIS_THRESHOLDS.minimum_return_units && returnRate !== "" && returnRate >= DIAGNOSIS_THRESHOLDS.return_rate_risk) {
    classification = "Return-risk SKU";
    confidence = Math.max(confidence, 76);
  }

  return {
    entity_type: "sku",
    entity_id: clean(row.variant_id || row.sku),
    entity_name: clean(row.sku || row.variant_title || row.product_title),
    classification,
    evidence_fields: evidenceObject({
      units_sold: units,
      ending_inventory_units: stock,
      is_oos: clean(row.is_oos),
      days_of_cover_7d: cover,
      daily_velocity_7d: velocity,
      current_7d_units: current7d,
      returned_items: returned,
      return_rate_units: returnRate
    }),
    thresholds: DIAGNOSIS_THRESHOLDS,
    confidence,
    missing_data_warnings: warnings,
    selected_week: clean(row.week_start),
    comparison_period: "Selected week with current SKU inventory snapshot and rolling velocity fields where available.",
    join_confidence: "high"
  };
}

function diagnosisClassificationRank(row) {
  const classification = clean(row?.classification);
  if (/Supply-constrained/.test(classification)) return 0;
  if (/Return-risk/.test(classification)) return 1;
  if (/Demand\/conversion-constrained/.test(classification)) return 2;
  if (/Slow-moving|Dead or near-dead|Low exposure|Underexposed/.test(classification)) return 3;
  if (/Unavailable/.test(classification)) return 4;
  return 5;
}

function buildDeterministicDiagnosis(reportData) {
  const funnelProductsByName = new Map();
  for (const row of aggregateFunnelProductRows(reportData?.funnel?.products || [])) {
    const key = normalizedProductKey(row.item_name);
    if (key && !funnelProductsByName.has(key)) funnelProductsByName.set(key, row);
  }
  const stats = productSampleStats(reportData?.revenue?.products || [], funnelProductsByName);
  const skusByProductId = new Map();
  for (const sku of reportData?.inventory?.skus || []) {
    const key = clean(sku.product_id || sku.product_title);
    if (!key) continue;
    if (!skusByProductId.has(key)) skusByProductId.set(key, []);
    skusByProductId.get(key).push(sku);
  }

  const productDiagnostics = (reportData?.revenue?.products || [])
    .map((row) => classifyInventoryProduct(
      row,
      funnelProductsByName.get(normalizedProductKey(row.product_title)) || null,
      stats,
      skusByProductId.get(clean(row.product_id)) || skusByProductId.get(clean(row.product_title)) || [],
      reportData?.week?.currency || "EGP"
    ))
    .filter((d) => d.classification !== "Insufficient data")
    .sort((a, b) => diagnosisClassificationRank(a) - diagnosisClassificationRank(b) || b.confidence - a.confidence)
    .slice(0, 100);
  const skuDiagnostics = (reportData?.inventory?.skus || [])
    .map(classifySku)
    .filter((d) => d.classification !== "Insufficient data")
    .sort((a, b) => diagnosisClassificationRank(a) - diagnosisClassificationRank(b) || b.confidence - a.confidence)
    .slice(0, 100);

  return {
    week_start: reportData?.week?.week_start || "",
    funnel: buildFunnelDiagnosis(reportData),
    products: productDiagnostics,
    skus: skuDiagnostics,
    warnings: [
      "Inventory fields are current snapshot/rolling velocity signals unless the source row explicitly represents a week-end snapshot.",
      "Product-level GA4 joins use product names when product IDs are unavailable and are labeled low-confidence."
    ]
  };
}

function slugKey(value, fallback = "unknown") {
  const slug = clean(value).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return slug || fallback;
}

function evidenceRef(entityType, entityId, metric = "diagnosis") {
  return [slugKey(entityType, "entity"), slugKey(entityId, "sitewide"), slugKey(metric, "metric")].join(":");
}

function pushEvidence(evidence, ref, payload) {
  if (!ref) return;
  evidence.push({
    ref,
    week_start: clean(payload.week_start),
    entity_type: clean(payload.entity_type),
    entity_id: clean(payload.entity_id),
    entity_name: clean(payload.entity_name),
    metric: clean(payload.metric),
    value: payload.value === undefined ? "" : payload.value,
    source: clean(payload.source),
    fields: payload.fields || {}
  });
}

function evidenceIndexFromList(evidence = []) {
  return Object.fromEntries(evidence.map((item) => [item.ref, item]));
}

function metricBridgeItem(label, metric, current, previous, avg4, inverse = false) {
  const currentValue = metricOrBlank(current);
  const previousValue = metricOrBlank(previous);
  const avgValue = metricOrBlank(avg4);
  const delta = currentValue !== "" && previousValue !== "" ? currentValue - previousValue : "";
  const wowPct = currentValue !== "" && previousValue !== "" && previousValue !== 0 ? delta / Math.abs(previousValue) : "";
  const vsAvgPct = currentValue !== "" && avgValue !== "" && avgValue !== 0 ? (currentValue - avgValue) / Math.abs(avgValue) : "";
  const adjustedWow = wowPct === "" ? "" : wowPct * (inverse ? -1 : 1);
  return {
    label,
    metric,
    current: currentValue === "" ? "" : r4(currentValue),
    previous_week: previousValue === "" ? "" : r4(previousValue),
    four_week_average: avgValue === "" ? "" : r4(avgValue),
    absolute_change: delta === "" ? "" : r4(delta),
    wow_pct: wowPct === "" ? "" : r4(wowPct),
    vs_four_week_average_pct: vsAvgPct === "" ? "" : r4(vsAvgPct),
    direction: adjustedWow === "" ? "unknown" : adjustedWow > 0 ? "improved" : adjustedWow < 0 ? "worsened" : "flat",
    severity: adjustedWow === "" ? "unknown" : adjustedWow <= -0.10 ? "high" : adjustedWow < -0.03 ? "medium" : "low"
  };
}

function buildPerformanceBridge(reportData) {
  const scoreboard = reportData?.scoreboard || {};
  const shopify = reportData?.revenue?.weekly || {};
  const ga4 = reportData?.funnel?.weekly || {};
  const meta = reportData?.paid?.weekly || {};
  const currency = reportData?.week?.currency || clean(shopify.currency || meta.currency || "EGP");
  const netSales = metricBridgeItem("Net sales", "net_sales", scoreboard.net_sales?.current, scoreboard.net_sales?.previous_week, scoreboard.net_sales?.four_week_average);
  const orders = metricBridgeItem("Orders", "orders", scoreboard.orders?.current, scoreboard.orders?.previous_week, scoreboard.orders?.four_week_average);
  const cvr = metricBridgeItem("Shopify orders / GA4 sessions", "conversion_rate", scoreboard.conversion_rate?.current, scoreboard.conversion_rate?.previous_week, scoreboard.conversion_rate?.four_week_average);
  const aov = metricBridgeItem("Average order value", "aov", scoreboard.aov?.current, scoreboard.aov?.previous_week, scoreboard.aov?.four_week_average);
  const mer = metricBridgeItem("MER", "mer", scoreboard.mer?.current, scoreboard.mer?.previous_week, scoreboard.mer?.four_week_average);
  // Metric key stays "refund_rate": it is a stored goal key in D1 (GOALS
  // primary_metric) and renaming it would invalidate saved goals. The label and
  // the source column are corrected — the value is cancellations, not refunds.
  const refundRate = metricBridgeItem("Reversal rate (RTO)", "refund_rate", shopify.sales_reversal_rate ?? shopify.refund_rate, "", "", true);
  const drivers = [netSales, orders, cvr, aov, mer, refundRate];

  const sessions = metricOrBlank(ga4.sessions);
  const currentCvr = metricOrBlank(scoreboard.conversion_rate?.current);
  const targetCvr = Math.max(
    metricOrBlank(scoreboard.conversion_rate?.previous_week) === "" ? 0 : metricOrBlank(scoreboard.conversion_rate?.previous_week),
    metricOrBlank(scoreboard.conversion_rate?.four_week_average) === "" ? 0 : metricOrBlank(scoreboard.conversion_rate?.four_week_average)
  );
  const aovValue = metricOrBlank(scoreboard.aov?.current);
  const conversionRevenueAtRisk =
    sessions !== "" && currentCvr !== "" && targetCvr > currentCvr && aovValue !== ""
      ? r2((targetCvr - currentCvr) * sessions * aovValue)
      : "";
  const roas = metricOrBlank(meta.roas);
  const spend = metricOrBlank(meta.spend);
  const paidEfficiencyRisk =
    spend !== "" && roas !== "" && roas < 2
      ? r2(spend * (1 - Math.max(0, roas) / 2))
      : "";
  const refunds = metricOrBlank(shopify.refunds);
  const netSalesCurrent = metricOrBlank(scoreboard.net_sales?.current);
  const netSalesPrevious = metricOrBlank(scoreboard.net_sales?.previous_week);

  return {
    currency,
    driver_impacts: drivers,
    money_at_risk: {
      net_sales_delta:
        netSalesCurrent !== "" && netSalesPrevious !== ""
          ? {
              amount: r2(netSalesCurrent - netSalesPrevious),
              currency,
              formula: "current net sales - previous-week net sales",
              confidence: "high"
            }
          : null,
      conversion_gap_to_recent_baseline:
        conversionRevenueAtRisk === ""
          ? null
          : {
              amount: conversionRevenueAtRisk,
              currency,
              formula: "(max(previous-week CVR, trailing 4W CVR) - current CVR) * current GA4 sessions * current Shopify AOV",
              confidence: "medium",
              assumptions: ["Uses Shopify orders / GA4 sessions as CVR.", "Does not claim causality."]
            },
      paid_efficiency_pressure:
        paidEfficiencyRisk === ""
          ? null
          : {
              amount: paidEfficiencyRisk,
              currency,
              formula: "Meta spend * (1 - Meta ROAS / 2.0 target floor)",
              confidence: "low",
              assumptions: ["ROAS target floor is a guardrail estimate until margin targets are configured."]
            },
      refund_pressure:
        refunds === ""
          ? null
          : {
              amount: r2(refunds),
              currency,
              formula: "Shopify refunds for selected week",
              confidence: "high"
            }
    },
    narrative: drivers
      .filter((driver) => driver.direction !== "unknown" && driver.metric !== "refund_rate")
      .sort((a, b) => Math.abs(num(b.wow_pct)) - Math.abs(num(a.wow_pct)))
      .slice(0, 3)
      .map((driver) => `${driver.label} ${driver.direction} ${driver.wow_pct === "" ? "" : `${r2(driver.wow_pct * 100)}% WoW`}`.trim())
  };
}

function buildAdProductMappingSuggestions(reportData) {
  const products = reportData?.revenue?.products || [];
  const ads = reportData?.creative?.ads || [];
  const suggestions = [];
  for (const ad of ads) {
    const rawAdText = [
      ad.ad_name,
      ad.adset_name,
      ad.campaign_name
    ].join(" ");
    const adText = normalizedCommerceName(rawAdText);
    if (!adText) continue;
    const candidates = [];
    for (const product of products) {
      const title = normalizedCommerceName(product.product_title);
      if (!title || title.length < 4) continue;
      const tokens = title.split(" ").filter((token) => token.length > 2);
      const matches = tokens.filter((token) => adText.includes(token)).length;
      const coverage = tokens.length ? matches / tokens.length : 0;
      const exactContainment = adText.includes(title);
      const confidence = exactContainment ? Math.max(0.92, coverage) : coverage;
      if (confidence >= 0.55) candidates.push({
        product,
        confidence,
        exactContainment,
        matched_tokens: tokens.filter((token) => adText.includes(token)),
        normalized_product_title: title
      });
    }
    candidates.sort((a, b) => b.confidence - a.confidence || b.normalized_product_title.length - a.normalized_product_title.length);
    const best = candidates[0] || null;
    if (best) {
      const competing = candidates
        .filter((candidate) => candidate.product !== best.product && candidate.confidence >= Math.max(0.55, best.confidence - 0.12))
        .slice(0, 5)
        .map((candidate) => ({
          product_id: clean(candidate.product.product_id),
          product_title: clean(candidate.product.product_title),
          confidence: r2(candidate.confidence * 100),
          matched_tokens: candidate.matched_tokens
        }));
      suggestions.push({
        week_start: reportData?.week?.week_start || "",
        ad_id: clean(ad.ad_id),
        ad_name: clean(ad.ad_name),
        product_id: clean(best.product.product_id),
        product_title: clean(best.product.product_title),
        mapping_source: "deterministic_suggestion",
        confidence: r2(best.confidence * 100),
        status: competing.length ? "needs_review" : "active",
        evidence: {
          reason: best.exactContainment
            ? "Normalized ad/ad set/campaign text contains the normalized product title after removing the Coddiwomple brand and common ecommerce words."
            : "Product-title tokens appear in ad, ad set, or campaign names.",
          basis: best.exactContainment ? "exact_normalized_containment" : "token_coverage",
          ad_text: clean(rawAdText.replace(/\s+/g, " | ")),
          normalized_ad_text: adText,
          normalized_product_title: best.normalized_product_title,
          matched_tokens: best.matched_tokens,
          competing_candidates: competing,
          ambiguity_reason: competing.length ? "Another product title matched nearly as strongly; keep this as manual review." : ""
        }
      });
    }
  }
  return suggestions.sort((a, b) => b.confidence - a.confidence).slice(0, 50);
}

function normalizedCommerceName(value) {
  const common = new Set([
    "coddiwomple",
    "shop",
    "store",
    "official",
    "new",
    "best",
    "sale",
    "offer",
    "offers",
    "collection",
    "collections",
    "product",
    "products",
    "ad",
    "ads",
    "video",
    "reel",
    "campaign",
    "summer",
    "winter"
  ]);
  return clean(value)
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, " ")
    .split(/\s+/)
    .filter((token) => token.length > 1 && !common.has(token))
    .join(" ")
    .trim();
}

function productUrlHandle(value) {
  try {
    const url = new URL(clean(value));
    const match = url.pathname.match(/\/products\/([^/?#]+)/i);
    return match ? clean(match[1]).toLowerCase() : "";
  } catch (_) {
    const match = clean(value).match(/\/products\/([^/?#]+)/i);
    return match ? clean(match[1]).toLowerCase() : "";
  }
}

function productTitleHandle(title) {
  return clean(title).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

function mappingFromDestinationUrl(ad, products, metadata) {
  const handle = productUrlHandle(metadata?.destination_url || "");
  if (!handle) return null;
  const product = products.find((row) => productTitleHandle(row.product_title) === handle || productTitleHandle(row.product_title).includes(handle));
  if (!product) {
    return {
      mapping_state: "needs_manual_review",
      method: "destination_url",
      confidence: 60,
      evidence: { destination_url: metadata.destination_url, reason: "Destination URL contains a Shopify product handle, but no synced product title matched it." },
      products: []
    };
  }
  return {
    mapping_state: "mapped_product",
    method: "destination_url",
    confidence: 86,
    evidence: { destination_url: metadata.destination_url, product_title: product.product_title },
    products: [product]
  };
}

function mappingFromManual(ad, products, mappings) {
  const rows = (mappings || []).filter((row) => clean(row.ad_id) === clean(ad.ad_id) && clean(row.status) === "active");
  if (!rows.length) return null;
  const mappedProducts = rows
    .map((mapping) => products.find((product) => clean(product.product_id) === clean(mapping.product_id)) || {
      product_id: mapping.product_id,
      product_title: mapping.product_title,
      sku: mapping.sku,
      ending_inventory_units: "",
      return_rate_units: ""
    })
    .filter(Boolean);
  return {
    mapping_state: mappedProducts.length > 1 ? "multiple_mapped_products" : "mapped_product",
    method: "manual",
    confidence: Math.max(...rows.map((row) => num(row.confidence) || 100)),
    evidence: { mapping_ids: rows.map((row) => row.mapping_id), manual_override: true },
    products: mappedProducts
  };
}

function mappingFromNamingSuggestion(ad, suggestions, products) {
  const suggestion = (suggestions || []).find((row) => clean(row.ad_id) === clean(ad.ad_id));
  if (!suggestion) return null;
  const product = products.find((row) => clean(row.product_id) === clean(suggestion.product_id)) || null;
  const evidence = suggestion.evidence || {};
  const hasCompeting = Array.isArray(evidence.competing_candidates) && evidence.competing_candidates.length > 0;
  const confidence = num(suggestion.confidence);
  const mapped = product && confidence >= 80 && !hasCompeting;
  return {
    mapping_state: mapped ? "mapped_product" : "needs_manual_review",
    method: "naming_heuristic",
    confidence: mapped ? Math.min(94, confidence) : Math.min(79, confidence),
    evidence: {
      ...evidence,
      confidence_basis: mapped
        ? "High-confidence normalized naming heuristic with no close competing product."
        : hasCompeting ? "Manual review required because competing product names matched." : "Manual review required because naming confidence is below the auto-map floor."
    },
    products: product ? [product] : []
  };
}

function creativeThumbnailState(ad, metadata) {
  const candidates = [
    ["thumbnail_url", metadata?.thumbnail_url],
    ["image_url", metadata?.image_url],
    ["video_thumbnail_url", metadata?.video_thumbnail_url],
    ["thumbnail", metadata?.thumbnail],
    ["ad_thumbnail_url", ad?.thumbnail_url],
    ["ad_image_url", ad?.image_url]
  ];
  const found = candidates.find(([, value]) => clean(value));
  const previewCandidates = [
    ["preview_url", metadata?.preview_url],
    ["permalink_url", metadata?.permalink_url],
    ["effective_object_story_url", metadata?.effective_object_story_url]
  ];
  const preview = previewCandidates.find(([, value]) => clean(value));
  const metadataStatus = clean(metadata?.status);
  const noMetadataReason = "Meta creative metadata is not stored for this ad; refresh metadata or sync thumbnail_url/image_url/video thumbnail fields.";
  const noThumbReason = metadata
    ? clean(metadata.unavailable_reason || metadata.error_message) || "Meta creative metadata has no thumbnail_url, image_url, or video thumbnail field."
    : noMetadataReason;
  const noPreviewReason = metadata
    ? clean(metadata.preview_unavailable_reason || metadata.unavailable_reason || metadata.error_message) || "Meta did not return a supported preview URL/HTML for this creative."
    : noMetadataReason;
  return {
    thumbnail_url: found ? clean(found[1]) : "",
    thumbnail_source: found ? found[0] : "",
    thumbnail_status: found ? "available" : "unavailable",
    thumbnail_unavailable_reason: found ? "" : noThumbReason,
    preview_url: preview ? clean(preview[1]) : "",
    preview_source: preview ? preview[0] : "",
    preview_supported: metadataStatus === "available" || Boolean(preview),
    preview_status: metadataStatus || (preview ? "available" : "unavailable"),
    preview_unavailable_reason: metadataStatus === "available" || preview ? "" : noPreviewReason
  };
}

function classifyAdScaleState(ad, mapping) {
  const roas = metricOrBlank(ad.roas);
  const ctr = metricOrBlank(ad.ctr_link);
  const product = mapping.products?.[0] || null;
  if (!mapping.products?.length || mapping.confidence < 80) {
    return {
      state: "mapping_required",
      explanation: "Creative performance can be read, but product stock/return advice is blocked until mapping is verified."
    };
  }
  const stock = metricOrBlank(product.ending_inventory_units);
  const returnRate = metricOrBlank(product.return_rate_units);
  if (stock !== "" && stock <= 2 && (roas === "" || roas >= 1.5 || ctr >= 0.008)) {
    return {
      state: "do_not_scale_inventory",
      explanation: "Do not scale: the mapped product has insufficient stock for demand."
    };
  }
  if (returnRate !== "" && returnRate >= DIAGNOSIS_THRESHOLDS.return_rate_risk && roas !== "" && roas >= 1.5) {
    return {
      state: "do_not_scale_return_quality",
      explanation: "Do not scale until return quality is investigated for the mapped product."
    };
  }
  if (roas !== "" && roas >= 2 && stock !== "" && stock > 10) {
    return {
      state: "scalable_if_goal_aligned",
      explanation: "Ad has positive return and mapped product stock appears able to support controlled scaling."
    };
  }
  return {
    state: "observe",
    explanation: "No scale recommendation; judge ad performance with mapped product stock and return quality."
  };
}

function enrichCreativeAds(ads, products, metadataRows, manualMappings, suggestions) {
  const metadataByAd = new Map((metadataRows || []).map((row) => [clean(row.ad_id), row]));
  return (ads || []).map((ad) => {
    const metadata = metadataByAd.get(clean(ad.ad_id)) || null;
    let mapping =
      mappingFromManual(ad, products, manualMappings) ||
      mappingFromDestinationUrl(ad, products, metadata) ||
      mappingFromNamingSuggestion(ad, suggestions, products) ||
      {
        mapping_state: isCatalogLikeName(ad) ? "dynamic_catalogue_or_mixed_products" : "unmapped",
        method: "",
        confidence: 0,
        evidence: {},
        products: []
      };
    const adWithMetadata = { ...ad, creative_metadata: metadata, mapping_state: mapping.mapping_state };
    const format = adCreativeFormat(adWithMetadata);
    const multipleProductsAllowed = adSupportsMultipleProductMappings(adWithMetadata);
    if ((mapping.products || []).length > 1 && !multipleProductsAllowed) {
      mapping = {
        ...mapping,
        mapping_state: "needs_manual_review",
        confidence: 0,
        evidence: {
          ...(mapping.evidence || {}),
          policy_error: "Several products are mapped, but the ad is not classified as video or catalogue."
        }
      };
    }
    const scale = classifyAdScaleState(ad, mapping);
    const thumbnailState = creativeThumbnailState(ad, metadata);
    return {
      ...ad,
      creative_metadata: metadata,
      ...thumbnailState,
      mapping_state: mapping.mapping_state,
      mapping_method: mapping.method,
      mapping_confidence: mapping.confidence,
      mapping_evidence: mapping.evidence,
      mapped_products: mapping.products || [],
      ad_format: format,
      multi_product_mapping_allowed: multipleProductsAllowed,
      multi_product_mapping_reason: multipleProductsAllowed
        ? `${format === "catalogue" ? "Catalogue" : "Video"} ads can legitimately promote several products.`
        : "Only one product can be mapped unless Meta evidence classifies the ad as video or catalogue.",
      mapped_product_title: mapping.products?.map((row) => row.product_title).filter(Boolean).join(", "),
      mapped_product_stock: mapping.products?.length === 1 ? mapping.products[0].ending_inventory_units : "",
      mapped_product_return_rate: mapping.products?.length === 1 ? mapping.products[0].return_rate_units : "",
      scale_state: scale.state,
      scale_explanation: scale.explanation
    };
  });
}

function isCatalogLikeName(row) {
  const name = `${clean(row.ad_name)} ${clean(row.adset_name)} ${clean(row.campaign_name)}`.toLowerCase();
  return ["catalog", "catalogue", "carousel", "dynamic", "advantage+", "asc", "collection"]
    .some((term) => name.includes(term));
}

function buildEvidencePacket(reportData, diagnosis = null) {
  const dx = diagnosis || buildDeterministicDiagnosis(reportData);
  const bridge = buildPerformanceBridge(reportData);
  const evidence = [];
  const weekStart = reportData?.week?.week_start || "";
  const scoreboard = reportData?.scoreboard || {};
  const shopify = reportData?.revenue?.weekly || {};
  const ga4 = reportData?.funnel?.weekly || {};
  const meta = reportData?.paid?.weekly || {};

  for (const [metric, row] of Object.entries(scoreboard)) {
    pushEvidence(evidence, evidenceRef("kpi", "sitewide", metric), {
      week_start: weekStart,
      entity_type: "kpi",
      entity_id: "sitewide",
      entity_name: "Sitewide",
      metric,
      value: row?.current ?? "",
      source: "ReportWeekly",
      fields: row || {}
    });
  }

  for (const [metric, value] of Object.entries({
    shopify_orders: shopify.orders,
    shopify_net_sales: shopify.net_sales,
    shopify_sales_reversal_rate: shopify.sales_reversal_rate ?? shopify.refund_rate,
    ga4_sessions: ga4.sessions,
    ga4_atc_rate: ga4.atc_rate,
    ga4_checkout_completion_rate: ga4.checkout_completion_rate,
    meta_spend: meta.spend,
    meta_roas: meta.roas
  })) {
    pushEvidence(evidence, evidenceRef("source_metric", "sitewide", metric), {
      week_start: weekStart,
      entity_type: "source_metric",
      entity_id: "sitewide",
      entity_name: "Sitewide",
      metric,
      value,
      source: metric.startsWith("ga4") ? "GA4Weekly" : metric.startsWith("meta") ? "MetaWeekly" : "ShopifyWeekly",
      fields: { value }
    });
  }

  for (const row of dx.products || []) {
    pushEvidence(evidence, evidenceRef(row.entity_type, row.entity_id, "diagnosis"), {
      week_start: weekStart,
      entity_type: row.entity_type,
      entity_id: row.entity_id,
      entity_name: row.entity_name,
      metric: "diagnosis",
      value: row.classification,
      source: "deterministic_diagnosis",
      fields: row.evidence_fields || {}
    });
  }

  for (const row of dx.skus || []) {
    pushEvidence(evidence, evidenceRef(row.entity_type, row.entity_id, "diagnosis"), {
      week_start: weekStart,
      entity_type: row.entity_type,
      entity_id: row.entity_id,
      entity_name: row.entity_name,
      metric: "diagnosis",
      value: row.classification,
      source: "deterministic_diagnosis",
      fields: row.evidence_fields || {}
    });
  }

  for (const action of reportData?.actions || []) {
    const ref = evidenceRef("report_action", action.action_id || action.issue, action.severity || "action");
    pushEvidence(evidence, ref, {
      week_start: weekStart,
      entity_type: "report_action",
      entity_id: action.action_id || action.issue,
      entity_name: action.issue,
      metric: action.severity || "action",
      value: action.evidence || action.fix || "",
      source: "ReportActions",
      fields: action
    });
  }

  for (const ad of reportData?.creative?.ads || []) {
    pushEvidence(evidence, evidenceRef("ad", ad.ad_id || ad.ad_name, "performance"), {
      week_start: weekStart,
      entity_type: "ad",
      entity_id: ad.ad_id || ad.ad_name,
      entity_name: ad.ad_name,
      metric: "performance",
      value: ad.spend,
      source: "MetaAdWeekly",
      fields: {
        spend: ad.spend,
        impressions: ad.impressions,
        frequency: ad.frequency,
        roas: ad.roas,
        ctr_link: ad.ctr_link,
        hook_rate_3s: ad.hook_rate_3s,
        hold_rate_p50: ad.hold_rate_p50,
        purchases: ad.purchases,
        mapping_state: ad.mapping_state,
        mapping_confidence: ad.mapping_confidence,
        mapped_product_stock: ad.mapped_product_stock,
        mapped_product_return_rate: ad.mapped_product_return_rate
      }
    });
  }

  const warnings = [
    ...(reportData?.warnings || []),
    ...(dx.warnings || [])
  ];

  return {
    schema_version: EVIDENCE_SCHEMA_VERSION,
    week: reportData?.week || {},
    data_sources: {
      shopify_weekly_present: !!reportData?.revenue?.weekly,
      ga4_weekly_present: !!reportData?.funnel?.weekly,
      meta_weekly_present: !!reportData?.paid?.weekly,
      report_weekly_present: !!reportData?.summary
    },
    evidence,
    evidence_index: evidenceIndexFromList(evidence),
    diagnosis: dx,
    performance_bridge: bridge,
    ad_product_mapping_suggestions: buildAdProductMappingSuggestions(reportData),
    warnings
  };
}

function sourceEvidenceRefsForDiagnosis(row) {
  return [evidenceRef(row.entity_type, row.entity_id, "diagnosis")];
}

function actionSeverityFromConfidence(confidence, fallback = "Action") {
  return confidence >= 85 ? "Critical" : confidence >= 70 ? fallback : "Watch";
}

function baseCandidate(fields) {
  const candidate = {
    candidate_key: "",
    source: "deterministic_diagnosis",
    recommendation_type: "recommendation",
    action_type: "recommendation",
    category: "goal_driven",
    severity: "Action",
    intervention_type: "",
    intervention: "",
    action_title: "",
    entity_type: "sitewide",
    entity_id: "sitewide",
    entity_name: "Sitewide",
    evidence_refs: [],
    evidence_fields: {},
    evidence: "",
    hypothesis: "",
    business_hypothesis: "",
    why_supports_goal: "",
    alternative_explanations: [],
    expected_metric_affected: "net_sales",
    expected_metric: "net_sales",
    expected_direction: "increase",
    baseline: {},
    experiment_duration: "7 days",
    success_threshold: "",
    stop_condition: "",
    financial_guardrail: "",
    confidence: 60,
    owner: "Ecommerce",
    assumptions: [],
    missing_data: [],
    constraints_checked: [],
    hard_conflicts: [],
    goal_relationship: "neutral",
    money_risk: null,
    next_week_check: "",
    ...fields
  };
  const keyParts = [
    candidate.entity_type,
    candidate.entity_id,
    candidate.intervention_type || candidate.intervention || candidate.action_title,
    candidate.expected_metric
  ];
  candidate.candidate_key = candidate.candidate_key || keyParts.map((part) => slugKey(part)).join("|");
  candidate.business_hypothesis = candidate.business_hypothesis || candidate.hypothesis;
  candidate.action_title = candidate.action_title || candidate.intervention || "Action required";
  candidate.intervention = candidate.intervention || candidate.action_title;
  candidate.expected_metric = candidate.expected_metric || candidate.expected_metric_affected;
  candidate.expected_metric_affected = candidate.expected_metric_affected || candidate.expected_metric;
  return candidate;
}

function candidateFromReportAction(action) {
  const text = actionText(action);
  return baseCandidate({
    source: "ReportActions",
    recommendation_type: isMustShowAction(action) ? "mandatory_correction" : "recommendation",
    action_type: isMustShowAction(action) ? "mandatory" : "recommendation",
    category: isMustShowAction(action) ? "mandatory" : "goal_driven",
    severity: action.severity || "Action",
    entity_type: "report_action",
    entity_id: action.action_id || action.issue || action.fix,
    entity_name: action.issue || "Report action",
    intervention_type: text.includes("stock") ? "inventory_correction" : text.includes("return") ? "returns_correction" : text.includes("meta") ? "paid_allocation" : "operational_action",
    intervention: action.fix || action.issue || "Review the report action.",
    action_title: action.issue || action.fix || "Report action",
    evidence_refs: [evidenceRef("report_action", action.action_id || action.issue, action.severity || "action")],
    evidence_fields: { evidence: action.evidence, cause: action.cause, expected_impact: action.expected_impact },
    evidence: action.evidence || "",
    hypothesis: action.cause || "Existing deterministic report action identified this issue.",
    alternative_explanations: ["The source action may combine multiple operational causes."],
    expected_metric_affected: expectedMetricForAction(action, {}),
    expected_direction: expectedDirectionForAction(action),
    success_threshold: action.next_week_check || "The source issue improves in the next weekly report.",
    stop_condition: "Stop if the source metric worsens or the evidence is no longer present.",
    financial_guardrail: "Do not make margin-impacting changes without checking contribution margin.",
    confidence: /missing|N\/A|not available/i.test(action.evidence || "") ? 45 : 68,
    owner: action.owner || "Ecommerce",
    next_week_check: action.next_week_check || "",
    assumptions: ["Imported from ReportActions and preserved as evidence, not reworded as a proven cause."],
    missing_data: /missing|N\/A|not available/i.test(action.evidence || "") ? [action.evidence] : []
  });
}

function generatedCandidatesFromDiagnosis(reportData, diagnosis) {
  const candidates = [];
  const bridge = buildPerformanceBridge(reportData);
  const currency = reportData?.week?.currency || "EGP";
  const funnel = diagnosis?.funnel || {};
  const largestBottleneck = clean(funnel.largest_bottleneck);
  if (largestBottleneck) {
    const metric = largestBottleneck === "Product-page conversion" ? "conversion_rate" : largestBottleneck === "Checkout completion" ? "checkout_completion_rate" : "net_sales";
    candidates.push(baseCandidate({
      source: "deterministic_diagnosis",
      recommendation_type: largestBottleneck === "Checkout completion" ? "mandatory_correction" : "experiment",
      action_type: largestBottleneck === "Checkout completion" ? "mandatory" : "experiment",
      category: largestBottleneck === "Checkout completion" ? "mandatory" : "experiment",
      severity: largestBottleneck === "Checkout completion" ? "Critical" : "Action",
      intervention_type: largestBottleneck === "Product-page conversion" ? "pdp_offer_experiment" : "funnel_correction",
      intervention: largestBottleneck === "Product-page conversion"
        ? "Run a controlled PDP or offer experiment on the products receiving qualified traffic."
        : `Investigate and correct the ${largestBottleneck.toLowerCase()} bottleneck.`,
      action_title: largestBottleneck === "Product-page conversion"
        ? "Test PDP value communication, offer, or price as a controlled experiment"
        : `Correct ${largestBottleneck.toLowerCase()} friction`,
      entity_type: "funnel",
      entity_id: "sitewide",
      entity_name: "Sitewide funnel",
      evidence_refs: [evidenceRef("source_metric", "sitewide", "ga4_sessions"), evidenceRef("kpi", "sitewide", "conversion_rate")],
      evidence_fields: funnel.evidence_fields || {},
      evidence: `Largest funnel bottleneck: ${largestBottleneck}.`,
      hypothesis: largestBottleneck === "Product-page conversion"
        ? "Customers are reaching product pages but the current perceived value, offer clarity, price, media, sizing, or traffic match may not be strong enough to create add-to-cart intent."
        : "The funnel step is constraining orders and should be corrected before scaling demand.",
      alternative_explanations: ["Traffic quality mismatch", "Tracking gaps", "Product-market fit mismatch", "Payment or fulfillment friction"],
      expected_metric_affected: metric,
      expected_direction: "increase",
      baseline: funnel.evidence_fields || {},
      experiment_duration: "7-14 days or until at least 500 qualified product views are observed.",
      success_threshold: largestBottleneck === "Product-page conversion"
        ? "Add-to-cart rate improves by at least 15% without refund rate or MER deterioration."
        : "The bottleneck metric improves versus the selected-week baseline.",
      stop_condition: "Stop if conversion metrics worsen by 10% or paid efficiency/refund rate deteriorates materially.",
      financial_guardrail: `Do not run a discount unless gross margin can absorb it; cap any test discount exposure and measure ${currency} net sales after refunds.`,
      confidence: funnel.confidence || 65,
      owner: largestBottleneck === "Checkout completion" ? "Ecommerce / Operations" : "Ecommerce / Creative",
      next_week_check: "Compare selected funnel metric, Shopify orders, MER, and refund rate to baseline.",
      assumptions: ["Causality is uncertain; this is framed as an experiment unless a hard operational failure is found."],
      money_risk: bridge.money_at_risk?.conversion_gap_to_recent_baseline || null
    }));
  }

  const weekly = reportData?.revenue?.weekly || {};
  const refundRate = metricOrBlank(
    weekly.sales_reversal_rate ?? weekly.refund_rate ?? reportData?.returns?.refund_rate
  );
  const itemReturnRate = metricOrBlank(weekly.item_return_rate ?? reportData?.returns?.item_return_rate);
  const refundedValue = metricOrBlank(weekly.refunds);
  const returnedItems = num(weekly.returned_items ?? reportData?.returns?.returned_items);
  const returnedOrders = num(weekly.returned_orders ?? reportData?.returns?.returned_orders);
  const topReturnedSkus = (reportData?.returns?.skus || [])
    .filter((row) => num(row.returned_items) > 0)
    .slice(0, 5);
  if (
    (refundRate !== "" && refundRate >= 0.06 && refundedValue > 0) ||
    (itemReturnRate !== "" && itemReturnRate >= DIAGNOSIS_THRESHOLDS.return_rate_risk && returnedItems >= DIAGNOSIS_THRESHOLDS.minimum_return_units) ||
    (refundedValue !== "" && refundedValue >= 10000 && returnedItems >= DIAGNOSIS_THRESHOLDS.minimum_return_units)
  ) {
    candidates.push(baseCandidate({
      source: "deterministic_returns_diagnosis",
      recommendation_type: "mandatory_correction",
      action_type: "mandatory",
      category: "mandatory",
      severity: "Critical",
      intervention_type: "returns_quality_investigation",
      intervention: "Investigate refund and return leakage by SKU before scaling affected products.",
      action_title: "Investigate material returns/refund leakage",
      entity_type: "returns",
      entity_id: "sitewide",
      entity_name: "Returns and refunds",
      evidence_refs: [evidenceRef("source_metric", "sitewide", "shopify_sales_reversal_rate")],
      evidence_fields: evidenceObject({
        refund_rate: refundRate,
        item_return_rate: itemReturnRate,
        refunds: refundedValue,
        returned_items: returnedItems,
        returned_orders: returnedOrders,
        affected_skus: topReturnedSkus.map((row) => clean(row.sku || row.product_title)).filter(Boolean).join(", "),
        threshold_refund_rate: 0.06,
        threshold_return_rate_units: DIAGNOSIS_THRESHOLDS.return_rate_risk,
        threshold_returned_items: DIAGNOSIS_THRESHOLDS.minimum_return_units
      }),
      evidence: `Refund leakage crossed threshold: refund rate ${refundRate}, refunded ${refundedValue} ${currency}, returned items ${returnedItems}.`,
      hypothesis: "Likely investigation paths include size guide, product imagery, fit notes, quality issue, fulfillment issue, or expectation mismatch; the data does not prove one cause yet.",
      alternative_explanations: ["Late returns from prior orders", "Small number of high-value refunded items", "Fulfillment or expectation mismatch", "One-off quality batch"],
      expected_metric_affected: "refund_rate",
      expected_metric: "refund_rate",
      expected_direction: "decrease",
      baseline: {
        refund_rate: refundRate,
        item_return_rate: itemReturnRate,
        refunds: refundedValue,
        returned_items: returnedItems,
        affected_skus: topReturnedSkus.map((row) => clean(row.sku || row.product_title)).filter(Boolean).join(", ")
      },
      experiment_duration: "Immediate investigation; measure again after the next complete return cycle.",
      success_threshold: "Refund rate falls below 6% and item return rate moves below the configured return-risk threshold without net sales deterioration.",
      stop_condition: "Stop scaling affected SKUs if refunded value or return rate remains above threshold after the first corrective pass.",
      financial_guardrail: "Do not scale affected products until refund leakage is below threshold or the cause is isolated.",
      confidence: returnedItems >= DIAGNOSIS_THRESHOLDS.minimum_return_units ? 82 : 68,
      owner: "Operations / Customer Experience",
      assumptions: ["Cause is hypothesis-based until return reasons, customer notes, or QA evidence confirm it."],
      next_week_check: "Refund rate, refunded EGP, returned items, top returned SKUs, and customer-reason evidence.",
      money_risk: refundedValue > 0 ? {
        type: "refund leakage",
        display_label: "EGP at risk next week",
        amount: r2(refundedValue),
        currency,
        formula: "selected-week Shopify refunds, treated as next-7-days leakage if the issue persists",
        time_horizon: "next 7 days",
        period: "next 7 days",
        inputs: { refunds: refundedValue, refund_rate: refundRate, returned_items: returnedItems },
        confidence: "high",
        quantified_reason: "Refunded EGP was observed in the selected completed week and can be carried forward as next-week leakage risk."
      } : null
    }));
  }

  for (const row of diagnosis?.products || []) {
    const fields = row.evidence_fields || {};
    const classification = clean(row.classification);
    const refs = sourceEvidenceRefsForDiagnosis(row);
    if (/Supply-constrained winner|Supply-constrained continuity risk/.test(classification)) {
      const mandatory = classification === "Supply-constrained winner";
      candidates.push(baseCandidate({
        source: "deterministic_diagnosis",
        recommendation_type: mandatory ? "mandatory_correction" : "recommendation",
        action_type: mandatory ? "mandatory" : "recommendation",
        category: mandatory ? "mandatory" : "goal_driven",
        severity: mandatory ? "Critical" : "Action",
        intervention_type: "restock_or_visibility_guardrail",
        intervention: mandatory
          ? "Restock the proven winner or reduce demand-driving visibility until inventory can support it."
          : "Protect availability for the low-stock winner before increasing visibility or ad spend.",
        action_title: mandatory ? `Restock or cap demand for ${row.entity_name}` : `Protect availability for ${row.entity_name}`,
        entity_type: row.entity_type,
        entity_id: row.entity_id,
        entity_name: row.entity_name,
        evidence_refs: refs,
        evidence_fields: fields,
        evidence: `${classification}: units sold ${fields.units_sold}, stock ${fields.ending_inventory_units}, days cover ${fields.days_of_cover_7d}.`,
        hypothesis: "The product is already proving demand, but stock constraints can suppress sales and waste traffic.",
        alternative_explanations: ["Inventory snapshot timing may lag", "Variant-level size mix may be the actual constraint"],
        expected_metric_affected: "net_sales",
        expected_direction: "increase",
        baseline: fields,
        experiment_duration: "Immediate correction; review after 7 days.",
        success_threshold: "Availability improves and sales are not capped by stockout or low days of cover.",
        stop_condition: "Stop demand scaling if stock cover remains below 7 days or the SKU is out of stock.",
        financial_guardrail: "Do not scale ads or homepage visibility if forecast demand exceeds available stock.",
        confidence: row.confidence || 80,
        owner: "Operations / Merchandising",
        next_week_check: "Stock cover, units sold, stockout sold SKU rate, and net sales."
      }));
    }

    if (classification === "Demand/conversion-constrained") {
      candidates.push(baseCandidate({
        source: "deterministic_diagnosis",
        recommendation_type: "experiment",
        action_type: "experiment",
        category: "experiment",
        severity: actionSeverityFromConfidence(row.confidence, "Action"),
        intervention_type: "pdp_value_offer_price_test",
        intervention: "Run a controlled product-specific PDP, offer, bundle, or price experiment.",
        action_title: `Experiment on perceived value for ${row.entity_name}`,
        entity_type: row.entity_type,
        entity_id: row.entity_id,
        entity_name: row.entity_name,
        evidence_refs: refs,
        evidence_fields: fields,
        evidence: `High qualified traffic with weak add-to-cart: views ${fields.item_views}, view-to-cart ${fields.view_to_cart_rate}, stock ${fields.ending_inventory_units}.`,
        hypothesis: "The product may have a perceived-value, price, offer, photography, sizing, description, or traffic-match problem.",
        alternative_explanations: ["Ad traffic is unqualified", "Images do not communicate fit/value", "Sizing or fulfillment concerns", "Price is not the cause"],
        expected_metric_affected: "conversion_rate",
        expected_direction: "increase",
        baseline: fields,
        experiment_duration: "7-14 days or until at least 300 product views are observed.",
        success_threshold: "View-to-cart rate improves by at least 15% and Shopify conversion does not worsen.",
        stop_condition: "Stop if refund rate rises, MER deteriorates by more than 10%, or add-to-cart falls below baseline.",
        financial_guardrail: "Use the smallest viable discount or offer; do not discount if the active goal protects margin unless the tradeoff is explicitly accepted.",
        confidence: row.confidence || 68,
        owner: "Ecommerce / Creative",
        next_week_check: "Product view-to-cart, Shopify orders, MER, refund rate, and net sales."
      }));
    }

    if (classification === "Underexposed promising product") {
      candidates.push(baseCandidate({
        source: "deterministic_diagnosis",
        recommendation_type: "recommendation",
        action_type: "recommendation",
        category: "goal_driven",
        severity: "Action",
        intervention_type: "merchandising_visibility",
        intervention: "Increase homepage, collection, navigation, recommendation, or email visibility if stock can support demand.",
        action_title: `Increase qualified visibility for ${row.entity_name}`,
        entity_type: row.entity_type,
        entity_id: row.entity_id,
        entity_name: row.entity_name,
        evidence_refs: refs,
        evidence_fields: fields,
        evidence: `Product converts when viewed but appears underexposed: views ${fields.item_views}, view-to-purchase ${fields.view_to_purchase_rate}.`,
        hypothesis: "The product may earn more revenue if more qualified shoppers see it.",
        alternative_explanations: ["Joined GA4 product row may be low confidence", "Demand may be narrow", "Inventory may not cover additional traffic"],
        expected_metric_affected: "net_sales",
        expected_direction: "increase",
        baseline: fields,
        experiment_duration: "7 days.",
        success_threshold: "Product views and net sales rise without MER or refund-rate deterioration.",
        stop_condition: "Stop if stock cover drops below 7 days or conversion rate falls materially.",
        financial_guardrail: "Do not increase paid allocation until inventory can support forecast demand.",
        confidence: row.confidence || 65,
        owner: "Merchandising / Ecommerce"
      }));
    }

    if (/Slow-moving inventory|Dead or near-dead inventory|Slow-moving \/ insufficient traffic/.test(classification)) {
      candidates.push(baseCandidate({
        source: "deterministic_diagnosis",
        recommendation_type: "experiment",
        action_type: "experiment",
        category: "experiment",
        severity: "Action",
        intervention_type: "inventory_movement",
        intervention: classification === "Slow-moving / insufficient traffic"
          ? "Run a controlled merchandising exposure test before calling this a demand failure; use bundles or product-specific offers only after qualified exposure is observed."
          : "Reduce purchasing/visibility for the slow stock and test a controlled bundle, merchandising placement, or product-specific offer.",
        action_title: `Move or de-emphasize slow stock: ${row.entity_name}`,
        entity_type: row.entity_type,
        entity_id: row.entity_id,
        entity_name: row.entity_name,
        evidence_refs: refs,
        evidence_fields: fields,
        evidence: `${classification}: stock ${fields.ending_inventory_units}, current 7d units ${fields.current_7d_units}.`,
        hypothesis: classification === "Slow-moving / insufficient traffic"
          ? "Inventory burden is visible, but traffic is too weak to diagnose true demand; the first test is qualified exposure, then bundle/offer if sell-through stays weak."
          : "Demand is weak relative to stock, so cash may be tied up unless visibility, offer, or purchasing is adjusted.",
        alternative_explanations: ["Seasonality", "Poor discoverability", "Wrong audience", "Product detail page gaps", "Insufficient traffic sample"],
        expected_metric_affected: "sell_through_rate",
        expected_direction: "increase",
        baseline: fields,
        experiment_duration: "14 days.",
        success_threshold: classification === "Slow-moving / insufficient traffic"
          ? "Qualified product views exceed the experiment floor and sell-through improves by at least 20% without MER or refund-rate damage."
          : "Sell-through improves by at least 20% without damaging MER or refund rate.",
        stop_condition: "Stop if qualified exposure rises but sell-through does not improve, contribution margin falls below guardrail, or returns rise.",
        financial_guardrail: "Do not use broad discounts; keep any offer product-specific and margin-capped.",
        confidence: row.confidence || 70,
        owner: "Merchandising / Ecommerce"
      }));
    }

    if (classification === "Return-risk product") {
      candidates.push(baseCandidate({
        source: "deterministic_diagnosis",
        recommendation_type: "mandatory_correction",
        action_type: "mandatory",
        category: "mandatory",
        severity: "Critical",
        intervention_type: "returns_quality_investigation",
        intervention: "Investigate product quality, fit, sizing, fulfillment, and expectation mismatch before scaling this item.",
        action_title: `Investigate return risk for ${row.entity_name}`,
        entity_type: row.entity_type,
        entity_id: row.entity_id,
        entity_name: row.entity_name,
        evidence_refs: refs,
        evidence_fields: fields,
        evidence: `Return risk: returned items ${fields.returned_items}, return rate ${fields.return_rate_units}.`,
        hypothesis: "Returns may be eroding commercial quality because of quality, fit, description, photo, sizing, fulfillment, or expectation mismatch.",
        alternative_explanations: ["Small sample size", "One-off defect batch", "Late returns from prior weeks"],
        expected_metric_affected: "item_return_rate",
        expected_direction: "decrease",
        baseline: fields,
        experiment_duration: "Immediate investigation; review after the next return cycle.",
        success_threshold: "Return rate decreases and reviews/customer reasons confirm the fix.",
        stop_condition: "Pause scaling until the return reason is understood if return rate remains above threshold.",
        financial_guardrail: "Do not scale a product whose returns can erase contribution margin.",
        confidence: row.confidence || 76,
        owner: "Operations / Customer Experience"
      }));
    }
  }

  for (const row of diagnosis?.skus || []) {
    const fields = row.evidence_fields || {};
    const classification = clean(row.classification);
    if (/Supply-constrained winner|Supply-constrained continuity risk/.test(classification)) {
      candidates.push(baseCandidate({
        source: "deterministic_diagnosis",
        recommendation_type: classification === "Supply-constrained winner" ? "mandatory_correction" : "recommendation",
        action_type: classification === "Supply-constrained winner" ? "mandatory" : "recommendation",
        category: classification === "Supply-constrained winner" ? "mandatory" : "goal_driven",
        severity: classification === "Supply-constrained winner" ? "Critical" : "Action",
        intervention_type: "sku_restock_guardrail",
        intervention: "Restock, rebalance, or stop routing demand to this constrained SKU.",
        action_title: `Fix constrained SKU ${row.entity_name}`,
        entity_type: row.entity_type,
        entity_id: row.entity_id,
        entity_name: row.entity_name,
        evidence_refs: sourceEvidenceRefsForDiagnosis(row),
        evidence_fields: fields,
        evidence: `${classification}: units sold ${fields.units_sold}, stock ${fields.ending_inventory_units}, cover ${fields.days_of_cover_7d}.`,
        hypothesis: "SKU-level availability is limiting sales or customer experience.",
        alternative_explanations: ["Variant demand is concentrated in one size", "Inventory snapshot timing may lag"],
        expected_metric_affected: "net_sales",
        expected_direction: "increase",
        baseline: fields,
        experiment_duration: "Immediate correction; review after 7 days.",
        success_threshold: "Stock cover recovers above 14 days or visibility is capped until restocked.",
        stop_condition: "Stop scaling when SKU stock cover is below 7 days.",
        financial_guardrail: "Do not send paid traffic to a variant that cannot fulfill demand.",
        confidence: row.confidence || 80,
        owner: "Operations / Merchandising"
      }));
    }
  }

  return candidates;
}

function generatedCandidatesFromAds(reportData) {
  const candidates = [];
  for (const ad of reportData?.creative?.ads || []) {
    const spend = metricOrBlank(ad.spend);
    if (spend === "" || spend <= 0) continue;
    const roas = metricOrBlank(ad.roas);
    const ctr = metricOrBlank(ad.ctr_link);
    const hook = metricOrBlank(ad.hook_rate_3s);
    const hold = metricOrBlank(ad.hold_rate_p50);
    const impressions = metricOrBlank(ad.impressions);
    const frequency = metricOrBlank(ad.frequency);
    const mappingConfidence = metricOrBlank(ad.mapping_confidence);
    const adRef = evidenceRef("ad", ad.ad_id || ad.ad_name, "performance");
    if (roas !== "" && roas < 1.2 && spend >= DIAGNOSIS_THRESHOLDS.minimum_ad_spend_material) {
      candidates.push(baseCandidate({
        source: "deterministic_ad_diagnosis",
        recommendation_type: "recommendation",
        action_type: "recommendation",
        category: "goal_driven",
        severity: roas < 0.8 ? "Critical" : "Action",
        intervention_type: "paid_budget_reallocation",
        intervention: "Reduce or cap spend while diagnosing whether the problem is traffic quality, offer, PDP conversion, product fit, or inventory.",
        action_title: `Cap inefficient ad spend: ${ad.ad_name || ad.ad_id}`,
        entity_type: "ad",
        entity_id: ad.ad_id || ad.ad_name,
        entity_name: ad.ad_name || "Unnamed ad",
        evidence_refs: [adRef],
        evidence_fields: { spend, roas, ctr_link: ctr, frequency, impressions, purchases: ad.purchases, mapping_confidence: mappingConfidence },
        evidence: `Spend ${spend}, ROAS ${roas}, purchases ${ad.purchases}, mapping ${ad.mapping_state || "unmapped"}.`,
        hypothesis: "The ad is consuming budget without enough commercial return, but the root cause may be creative, audience, PDP, offer, or inventory.",
        alternative_explanations: ["Attribution lag", "Learning phase", "Retargeting window mismatch", "PDP or stock issue after click"],
        expected_metric_affected: "mer",
        expected_direction: "increase",
        baseline: { spend, roas, ctr_link: ctr, purchases: ad.purchases },
        experiment_duration: "3-7 days.",
        success_threshold: "MER and ad ROAS improve without losing profitable Shopify net sales.",
        stop_condition: "Pause if ROAS remains below 1.2 and MER does not improve.",
        financial_guardrail: "Do not scale this ad until mapped product stock and contribution margin can support demand.",
        confidence: roas < 0.8 ? 78 : 68,
        owner: "Media Buying"
      }));
    }

    if (spend >= DIAGNOSIS_THRESHOLDS.minimum_ad_spend_material && impressions >= DIAGNOSIS_THRESHOLDS.minimum_ad_impressions_material && ((hook !== "" && hook > 0 && hook < 0.18) || (hold !== "" && hold > 0 && hold < 0.25))) {
      candidates.push(baseCandidate({
        source: "deterministic_creative_diagnosis",
        recommendation_type: "experiment",
        action_type: "experiment",
        category: "experiment",
        severity: "Action",
        intervention_type: "creative_iteration",
        intervention: "Create a new creative variant with a clearer first-three-second hook and stronger product value communication.",
        action_title: `Refresh creative hook: ${ad.ad_name || ad.ad_id}`,
        entity_type: "ad",
        entity_id: ad.ad_id || ad.ad_name,
        entity_name: ad.ad_name || "Unnamed ad",
        evidence_refs: [adRef],
        evidence_fields: { hook_rate_3s: hook, hold_rate_p50: hold, spend, roas, ctr_link: ctr, frequency, impressions, mapping_confidence: mappingConfidence },
        evidence: `Hook rate ${hook}, hold rate ${hold}, spend ${spend}, impressions ${impressions}.`,
        hypothesis: "Creative attention may be weak before the shopper evaluates the product or offer.",
        alternative_explanations: ["Audience fatigue", "Poor placement mix", "Product itself is not attractive to this audience"],
        expected_metric_affected: "ctr_link",
        expected_direction: "increase",
        baseline: { hook_rate_3s: hook, hold_rate_p50: hold, ctr_link: ctr },
        experiment_duration: "3-7 days.",
        success_threshold: "Hook or hold rate improves by 20% and downstream MER does not worsen.",
        stop_condition: "Stop if CTR or MER worsens after comparable spend.",
        financial_guardrail: "Do not increase budget until creative improvement flows through to paid efficiency.",
        confidence: 62,
        owner: "Creative / Media Buying",
        missing_data: clean(ad.thumbnail_url || ad.preview_url) ? [] : ["Creative thumbnail/preview is not available from the synced Meta fields."]
      }));
    }
  }
  return candidates;
}

function generateCommercialCandidates(reportData, diagnosis = null) {
  const dx = diagnosis || buildDeterministicDiagnosis(reportData);
  return [
    ...(reportData?.actions || []).map(candidateFromReportAction),
    ...generatedCandidatesFromDiagnosis(reportData, dx),
    ...generatedCandidatesFromAds(reportData)
  ];
}

function candidateGoalRelationship(candidate, goalSpec) {
  const goal = sanitizeGoalObject(goalSpec || {});
  const text = [
    candidate.intervention_type,
    candidate.intervention,
    candidate.action_title,
    candidate.expected_metric,
    candidate.expected_metric_affected,
    candidate.hypothesis
  ].map(clean).join(" ").toLowerCase();
  const primary = clean(goal.primary_metric);
  const preferred = (goal.preferred_levers || []).map((lever) => clean(lever).toLowerCase());
  const forbidden = (goal.forbidden_levers || []).map((lever) => clean(lever).toLowerCase());
  const constraints = [...(goal.constraints || []), ...(goal.guardrails || [])].map((item) => clean(item).toLowerCase());

  if (forbidden.some((lever) => lever && text.includes(lever))) return "conflicts";
  if (/discount|markdown|price drop|lower price/.test(text) && constraints.some((item) => /margin|discount|protect/.test(item))) return "conflicts";
  if (/scale|increase ad|increase paid|homepage|visibility/.test(text) && /stock|inventory/.test(clean(candidate.financial_guardrail).toLowerCase()) && num(candidate.evidence_fields?.ending_inventory_units) <= 0) return "conflicts";
  if (primary === "sell_through_rate") {
    if (/restock|winner|stockout|low-stock|supply-constrained/.test(text)) return "neutral";
    if (/slow|dead|bundle|sell-through|clearance|move stock|high-stock|inventory_movement|de-emphasize/.test(text)) return "supports";
  }
  if (primary && (clean(candidate.expected_metric).includes(primary) || clean(candidate.expected_metric_affected).includes(primary))) return "supports";
  if (preferred.some((lever) => lever && text.includes(lever))) return "supports";

  const tags = goalTags(goal);
  const mapping = [
    ["net_sales", /sales|revenue|orders|winner|visibility|restock/],
    ["conversion_rate", /conversion|pdp|add-to-cart|offer|price|bundle|checkout/],
    ["mer", /mer|roas|paid|budget|spend|creative/],
    ["meta_roas", /roas|paid|budget|spend|creative/],
    ["refund_rate", /return|refund|fit|quality|expectation/],
    ["item_return_rate", /return|refund|fit|quality|expectation/],
    ["sell_through_rate", /slow|dead|bundle|sell-through|clearance|high-stock|inventory_movement/],
    ["ending_inventory_units", /stock|inventory|restock|purchasing/]
  ];
  for (const [metric, pattern] of mapping) {
    if ((tags.has(metric) || primary === metric) && pattern.test(text)) return "supports";
  }
  return "neutral";
}

function candidateConflicts(candidate, goalSpec, reportData) {
  const reasons = [];
  const goal = sanitizeGoalObject(goalSpec || {});
  const text = [candidate.intervention, candidate.action_title, candidate.intervention_type].map(clean).join(" ").toLowerCase();
  const constraints = [...(goal.constraints || []), ...(goal.guardrails || [])].map((item) => clean(item).toLowerCase());
  const stock = metricOrBlank(candidate.evidence_fields?.ending_inventory_units);

  if (/discount|markdown|lower price/.test(text) && constraints.some((item) => /protect margin|margin|no discount|avoid discount/.test(item))) {
    reasons.push("Discount or lower-price lever conflicts with the active margin guardrail.");
  }
  if (/scale|increase paid|increase visibility|homepage/.test(text) && stock !== "" && stock <= 0) {
    reasons.push("Scaling or increasing visibility conflicts with zero available stock for the referenced item.");
  }
  if (/scale|increase paid/.test(text) && stock !== "" && stock > 0 && stock < 5) {
    reasons.push("Scaling is blocked because referenced inventory appears too thin to support forecast demand.");
  }
  if (candidate.expected_metric === "refund_rate" && goal.primary_metric === "net_sales" && candidate.expected_direction === "increase") {
    reasons.push("Expected direction would worsen refund performance.");
  }
  if (!reportData?.week?.week_start) reasons.push("Selected week is missing from report data.");
  return reasons;
}

function validateCandidateEvidence(candidate, evidencePacket) {
  const refs = candidate.evidence_refs || [];
  const missing = refs.filter((ref) => !evidencePacket?.evidence_index?.[ref]);
  if (!refs.length) missing.push("no_evidence_refs");
  return missing;
}

function meaningfulEvidenceFacts(fields = {}) {
  return Object.entries(fields || {})
    .filter(([key, value]) => {
      if (/signals|thresholds/i.test(key)) return clean(value) !== "";
      if (value === "" || value == null) return false;
      if (typeof value === "number") return Number.isFinite(value) && value !== 0;
      return clean(value) !== "" && clean(value) !== "0";
    })
    .map(([key, value]) => ({ key, value }));
}

function materialityAmount(candidate, reportData) {
  const risk = estimateCandidateMoneyRisk(candidate, reportData);
  if (risk?.amount && num(risk.amount) > 0) return num(risk.amount);
  const fields = candidate.evidence_fields || {};
  if (/paid|budget|creative/.test(clean(candidate.intervention_type).toLowerCase())) return num(fields.spend);
  if (/return|refund/.test(clean(candidate.intervention_type).toLowerCase())) return num(fields.refunds || fields.refund_amount);
  if (/inventory|slow|stock|restock|availability/.test(clean(candidate.intervention_type).toLowerCase())) return num(fields.net_sales);
  return 0;
}

function isSpecificIntervention(candidate) {
  const text = clean(candidate.intervention || candidate.action_title);
  if (text.length < 30) return false;
  return !/^(review|monitor|check|investigate)$/i.test(text);
}

function candidateHasSufficientSample(candidate) {
  const fields = candidate.evidence_fields || {};
  const type = clean(candidate.intervention_type).toLowerCase();
  const entity = clean(candidate.entity_type).toLowerCase();
  const units = num(fields.units_sold);
  const orders = num(fields.orders);
  const views = num(fields.item_views);
  const returned = num(fields.returned_items);
  const spend = num(fields.spend);
  const impressions = num(fields.impressions);
  const current7d = num(fields.current_7d_units);
  const velocity = num(fields.daily_velocity_7d);

  if (candidate.source === "ReportActions") {
    return candidate.action_type === "mandatory" || clean(candidate.severity) === "Critical";
  }
  if (entity === "funnel") {
    return num(fields.sessions) >= 500 || views >= DIAGNOSIS_THRESHOLDS.minimum_experiment_views;
  }
  if (/restock|stock|availability|winner/.test(type)) {
    return units >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ||
      orders >= DIAGNOSIS_THRESHOLDS.minimum_winner_orders ||
      current7d >= DIAGNOSIS_THRESHOLDS.minimum_restock_units ||
      velocity >= DIAGNOSIS_THRESHOLDS.minimum_restock_daily_velocity;
  }
  if (/pdp|offer|price|conversion|visibility/.test(type)) {
    return views >= DIAGNOSIS_THRESHOLDS.minimum_experiment_views;
  }
  if (/inventory_movement|slow/.test(type)) {
    return num(fields.ending_inventory_units) >= DIAGNOSIS_THRESHOLDS.slow_inventory_units;
  }
  if (/return|refund/.test(type)) {
    return returned >= DIAGNOSIS_THRESHOLDS.minimum_return_units &&
      (units >= 10 || orders >= 5 || num(fields.refunds || fields.refund_amount) > 0);
  }
  if (/paid|budget|creative/.test(type) || entity === "ad") {
    return spend >= DIAGNOSIS_THRESHOLDS.minimum_ad_spend_material &&
      (impressions >= DIAGNOSIS_THRESHOLDS.minimum_ad_impressions_material || num(fields.clicks || fields.link_clicks) >= 30);
  }
  return meaningfulEvidenceFacts(fields).length >= 2;
}

function candidateMaterialityReasons(candidate, reportData) {
  const reasons = [];
  const type = clean(candidate.intervention_type).toLowerCase();
  const fields = candidate.evidence_fields || {};
  const baseSales = metricValueFromReportData(reportData, "net_sales");
  const materialAmount = materialityAmount(candidate, reportData);
  if (candidate.action_type === "mandatory" && /tracking|checkout|sync|api|return|refund|stockout|paid/.test(type + " " + clean(candidate.action_title).toLowerCase())) {
    return reasons;
  }
  if (/paid|budget|creative/.test(type) && num(fields.spend) < DIAGNOSIS_THRESHOLDS.minimum_ad_spend_material) {
    reasons.push("Paid/creative candidate spend is below the materiality floor.");
  }
  if (/pdp|offer|price|conversion/.test(type) && num(fields.item_views) < DIAGNOSIS_THRESHOLDS.minimum_experiment_views) {
    reasons.push("Product experiment traffic is below the materiality floor.");
  }
  if (/restock|availability|winner/.test(type) && !hasProvenCurrentDemand(fields)) {
    reasons.push("Restock candidate lacks proven current demand or sales velocity.");
  }
  if (/return|refund/.test(type) && num(fields.returned_items) < DIAGNOSIS_THRESHOLDS.minimum_return_units) {
    reasons.push("Return candidate is based on too few returned units.");
  }
  if (baseSales !== "" && materialAmount > 0 && materialAmount / Math.max(1, num(baseSales)) < 0.005) {
    reasons.push("Estimated impact is below 0.5% of current net sales.");
  }
  return reasons;
}

function candidateEvidenceQualityReasons(candidate, evidencePacket) {
  const reasons = [...validateCandidateEvidence(candidate, evidencePacket)];
  const facts = meaningfulEvidenceFacts(candidate.evidence_fields);
  if (candidate.action_type !== "mandatory" && facts.length < 2) {
    reasons.push("Evidence has fewer than two meaningful supporting facts.");
  }
  if (!isSpecificIntervention(candidate)) {
    reasons.push("Intervention is too generic to be an executive decision.");
  }
  if (!clean(candidate.success_threshold)) {
    reasons.push("Missing measurable success threshold.");
  }
  if (!clean(candidate.stop_condition)) {
    reasons.push("Missing stop condition.");
  }
  return reasons;
}

function candidateMappingReasons(candidate) {
  const reasons = [];
  if (clean(candidate.entity_type).toLowerCase() !== "ad") return reasons;
  const requiresProductAdvice = /stock|inventory|return|product|scale|do not scale/.test([
    candidate.intervention,
    candidate.hypothesis,
    candidate.financial_guardrail
  ].map(clean).join(" ").toLowerCase());
  if (requiresProductAdvice && num(candidate.evidence_fields?.mapping_confidence) < 80) {
    reasons.push("Ad-product mapping is missing or below the confidence required for product-stock advice.");
  }
  return reasons;
}

function candidateFinancialReasons(candidate, reportData) {
  const reasons = [];
  const risk = estimateCandidateMoneyRisk(candidate, reportData);
  if (risk && (!risk.amount || num(risk.amount) <= 0)) {
    reasons.push("Money estimate was invalid or non-positive.");
  }
  return reasons;
}

function candidateGoalEligibilityReasons(candidate, goalSpec) {
  if (candidate.action_type === "mandatory" || candidate.category === "mandatory") return [];
  if (candidate.goal_relationship !== "supports") {
    return ["Non-mandatory candidate does not directly support the active goal."];
  }
  return [];
}

function candidateStrictEligibilityReasons(candidate, evidencePacket, goalSpec, reportData) {
  const reasons = [
    ...candidateEvidenceQualityReasons(candidate, evidencePacket),
    ...candidateConflicts(candidate, goalSpec, reportData),
    ...candidateMappingReasons(candidate),
    ...candidateMaterialityReasons(candidate, reportData),
    ...candidateFinancialReasons(candidate, reportData),
    ...candidateGoalEligibilityReasons(candidate, goalSpec)
  ];
  if (!candidateHasSufficientSample(candidate)) {
    reasons.push("Candidate failed the minimum sample-size gate.");
  }
  if (candidate.goal_relationship === "conflicts") {
    reasons.push("Candidate conflicts with the active business goal or hard constraints.");
  }
  return [...new Set(reasons.filter(Boolean))];
}

function displayCategoryForCandidate(candidate) {
  if (candidate.action_type === "mandatory" || candidate.category === "mandatory") {
    return candidate.goal_relationship === "supports" ? "mandatory_goal_aligned" : "mandatory";
  }
  if (candidate.recommendation_type === "experiment" || candidate.category === "experiment") return "experiment";
  return "goal_driven";
}

function categoryReason(candidate) {
  const display = candidate.display_category || displayCategoryForCandidate(candidate);
  if (display === "mandatory_goal_aligned") return "Material correction that must be addressed and directly supports the active goal.";
  if (display === "mandatory") return "Material correction that protects data integrity, availability, revenue quality, or spend regardless of the active goal.";
  if (display === "experiment") return "Grounded test with uncertain causality and a measurable success/stop condition.";
  return "Material action that directly advances the active approved goal.";
}

function estimateCandidateMoneyRisk(candidate, reportData) {
  const currency = reportData?.week?.currency || "EGP";
  const aov = metricOrBlank(reportData?.scoreboard?.aov?.current);
  const stock = metricOrBlank(candidate.evidence_fields?.ending_inventory_units);
  const units = metricOrBlank(candidate.evidence_fields?.units_sold);
  const bridgeRisk = candidate.money_risk;
  if (bridgeRisk?.amount !== undefined && num(bridgeRisk.amount) > 0) {
    return {
      ...bridgeRisk,
      display_label: bridgeRisk.display_label || (/upside/i.test(clean(bridgeRisk.type)) ? "EGP upside next week" : "EGP at risk next week"),
      period: bridgeRisk.period || "next 7 days",
      time_horizon: "next 7 days",
      quantified_reason: bridgeRisk.quantified_reason || "Quantified from observed selected-week evidence and shown as next-week run-rate risk/upside."
    };
  }
  if (/stock|restock|availability|winner/.test(clean(candidate.intervention_type).toLowerCase()) && aov !== "" && units !== "") {
    const constrainedUnits = stock === "" ? units : Math.max(0, units - stock);
    const amount = r2(Math.max(0, constrainedUnits) * aov);
    if (!amount || amount <= 0 || units < DIAGNOSIS_THRESHOLDS.minimum_restock_units) return null;
    return {
      type: "revenue at risk",
      display_label: "EGP at risk next week",
      amount,
      currency,
      formula: "max(0, weekly units sold - current stock) * current Shopify AOV",
      time_horizon: "next 7 days",
      period: "next 7 days",
      inputs: { units_sold: units, ending_inventory_units: stock, aov },
      confidence: stock === "" ? "low" : "medium",
      assumptions: ["Assumes next-week demand resembles the selected completed week.", "Uses AOV as a revenue proxy because product margin is not supplied."],
      quantified_reason: "Proven demand and thin current stock produce a measurable next-week revenue cap."
    };
  }
  if (/pdp|offer|price|conversion/.test(clean(candidate.intervention_type).toLowerCase())) {
    const views = metricOrBlank(candidate.evidence_fields?.item_views);
    const cvr = metricOrBlank(candidate.evidence_fields?.view_to_purchase_rate);
    const netSales = metricOrBlank(candidate.evidence_fields?.net_sales);
    const productUnits = metricOrBlank(candidate.evidence_fields?.units_sold);
    const unitValue = productUnits !== "" && productUnits > 0 && netSales !== "" ? div(netSales, productUnits) : aov;
    if (views !== "" && cvr !== "" && unitValue !== "" && views >= DIAGNOSIS_THRESHOLDS.minimum_experiment_views) {
      const target = Math.max(DIAGNOSIS_THRESHOLDS.healthy_product_conversion_rate, num(cvr) * 1.15);
      const amount = r2(Math.max(0, views * (target - num(cvr)) * unitValue));
      if (amount > 0) {
        return {
          type: "revenue upside",
          display_label: "EGP upside next week",
          amount,
          currency,
          formula: "product views * (target view-to-purchase rate - current view-to-purchase rate) * product value per unit",
          time_horizon: "next 7 days",
          period: "next 7 days",
          inputs: { item_views: views, current_view_to_purchase_rate: cvr, target_view_to_purchase_rate: r4(target), value_per_unit: r2(unitValue) },
          confidence: "low",
          assumptions: ["Conversion-lift upside is hypothesis-based and must be validated by a controlled experiment."],
          quantified_reason: "Traffic, stock, and product value are present, so conversion upside can be estimated."
        };
      }
    }
  }
  if (/paid|budget|roas/.test(clean(candidate.intervention_type).toLowerCase())) {
    const spend = metricOrBlank(candidate.evidence_fields?.spend);
    const roas = metricOrBlank(candidate.evidence_fields?.roas);
    if (spend !== "" && roas !== "" && roas < 2) {
      const amount = r2(spend * (1 - Math.max(0, roas) / 2));
      if (!amount || amount <= 0) return null;
      return {
        type: "spend at risk",
        display_label: "EGP at risk next week",
        amount,
        currency,
        formula: "ad spend * (1 - ROAS / 2.0 target floor)",
        time_horizon: "next 7 days",
        period: "next 7 days",
        inputs: { spend, roas, target_roas_floor: 2 },
        confidence: "low",
        assumptions: ["Assumes spend pace continues for the next completed week.", "Efficiency pressure estimate, not profit loss."],
        quantified_reason: "Spend and ROAS are available, so inefficient next-week spend can be bounded."
      };
    }
  }
  if (/return|refund/.test(clean(candidate.intervention_type).toLowerCase())) {
    const refunds = metricOrBlank(candidate.evidence_fields?.refunds || candidate.evidence_fields?.refund_amount);
    if (refunds !== "" && refunds > 0) {
      return {
        type: "refund leakage",
        display_label: "EGP at risk next week",
        amount: r2(refunds),
        currency,
        formula: "selected-week Shopify refunds, treated as next-7-days leakage if the issue persists",
        time_horizon: "next 7 days",
        period: "next 7 days",
        inputs: {
          refunds,
          refund_rate: candidate.evidence_fields?.refund_rate,
          returned_items: candidate.evidence_fields?.returned_items
        },
        confidence: "high",
        assumptions: ["Refunded EGP is observed leakage; cause remains hypothesis-based until investigated."],
        quantified_reason: "Refund value is directly observed and can be used as next-week run-rate risk."
      };
    }
  }
  return null;
}

function deterministicCandidateScore(candidate, goalSpec, reportData) {
  const relationship = candidate.goal_relationship || candidateGoalRelationship(candidate, goalSpec);
  const mustShow = candidate.category === "mandatory" || candidate.action_type === "mandatory";
  const financialBase = metricValueFromReportData(reportData, "net_sales");
  const money = estimateCandidateMoneyRisk(candidate, reportData);
  const confidence = clamp(candidate.confidence || 60);
  const evidenceStrength = (candidate.evidence_refs || []).length && !(candidate.missing_data || []).length ? 82 : 55;
  const components = {
    goal_alignment:
      relationship === "mandatory" ? 100 :
        relationship === "supports" ? 86 :
          relationship === "conflicts" ? 0 :
            42,
    financial_materiality:
      financialBase === "" ? 0 :
        money?.amount ? clamp((Math.abs(num(money.amount)) / Math.max(1, num(financialBase))) * 250) :
          /stock|conversion|paid|return/.test(clean(candidate.intervention_type).toLowerCase()) ? 65 : 45,
    urgency:
      clean(candidate.severity) === "Critical" ? 92 :
        mustShow ? 88 :
          candidate.recommendation_type === "experiment" ? 58 : 68,
    severity_guardrail:
      mustShow ? 100 :
        relationship === "conflicts" ? 0 :
          clean(candidate.severity) === "Critical" ? 90 : 58,
    confidence,
    evidence_strength: evidenceStrength,
    time_to_impact:
      /immediate|cap|pause|restock|reduce/.test(clean(candidate.intervention).toLowerCase()) ? 78 :
        candidate.recommendation_type === "experiment" ? 55 : 62,
    cross_functional_value: clean(candidate.owner).includes("/") ? 78 : 48
  };
  const formula = COMMERCIAL_ACTION_SCORE_FORMULA;
  const total =
    components.goal_alignment * formula.goal_alignment +
    components.financial_materiality * formula.financial_materiality +
    components.urgency * formula.urgency +
    components.severity_guardrail * formula.severity_guardrail +
    components.confidence * formula.confidence +
    components.evidence_strength * formula.evidence_strength +
    components.time_to_impact * formula.time_to_impact +
    components.cross_functional_value * formula.cross_functional_value;
  return {
    total_score: r2(total),
    goal_alignment_score: r2(components.goal_alignment),
    financial_score: r2(components.financial_materiality),
    urgency_score: r2(components.urgency),
    confidence_score: r2(components.confidence),
    severity_guardrail_score: r2(components.severity_guardrail),
    evidence_strength_score: r2(components.evidence_strength),
    time_to_impact_score: r2(components.time_to_impact),
    cross_functional_value_score: r2(components.cross_functional_value),
    formula: {
      coefficients: formula,
      components,
      note: "Scores rank validated candidate interventions; evidence and source metrics are preserved."
    }
  };
}

function validateAndScoreCandidates(candidates, evidencePacket, goalSpec, reportData) {
  const accepted = [];
  const rejected = [];
  for (const candidate of candidates) {
    const normalized = baseCandidate(candidate);
    normalized.goal_relationship = candidateGoalRelationship(normalized, goalSpec);
    normalized.display_category = displayCategoryForCandidate(normalized);
    normalized.category_reason = categoryReason(normalized);
    normalized.money_risk = estimateCandidateMoneyRisk(normalized, reportData);
    const rejectionReasons = candidateStrictEligibilityReasons(normalized, evidencePacket, goalSpec, reportData);
    if (rejectionReasons.length) {
      rejected.push({
        ...normalized,
        validation_status: "rejected",
        rejection_reasons: [...new Set(rejectionReasons)]
      });
      continue;
    }
    const score = deterministicCandidateScore(normalized, goalSpec, reportData);
    accepted.push({
      ...normalized,
      validation_status: "accepted",
      rejection_reasons: [],
      survived_filter_reason: "Passed evidence quality, sample size, materiality, goal, mapping, financial, specificity, and duplicate eligibility gates.",
      ...score
    });
  }
  return { accepted, rejected };
}

function dedupeCommercialCandidates(candidates) {
  const byKey = new Map();
  for (const item of candidates) {
    const existing = byKey.get(item.candidate_key);
    if (!existing || item.total_score > existing.total_score || (item.category === "mandatory" && existing.category !== "mandatory")) {
      byKey.set(item.candidate_key, item);
    }
  }
  return [...byKey.values()];
}

function rankCommercialCandidates(candidates) {
  const categoryRank = (item) =>
    item.display_category === "mandatory_goal_aligned" ? 0 :
      item.display_category === "mandatory" ? 1 :
        item.display_category === "goal_driven" ? 2 :
          item.display_category === "experiment" ? 3 : 4;
  const riskAmount = (item) => {
    const risk = item.money_risk || estimateCandidateMoneyRisk(item, {});
    return risk && num(risk.amount) > 0 ? num(risk.amount) : 0;
  };
  return [...candidates].sort((a, b) =>
    categoryRank(a) - categoryRank(b) ||
    riskAmount(b) - riskAmount(a) ||
    num(b.confidence_score || b.confidence) - num(a.confidence_score || a.confidence) ||
    b.total_score - a.total_score ||
    clean(a.candidate_key).localeCompare(clean(b.candidate_key))
  );
}

function selectVisibleActions(eligibleCandidates) {
  const ranked = rankCommercialCandidates(eligibleCandidates);
  const used = new Set();
  const take = (predicate, limit) => {
    const selected = [];
    for (const item of ranked) {
      if (selected.length >= limit) break;
      if (used.has(item.candidate_key)) continue;
      if (!predicate(item)) continue;
      selected.push(item);
      used.add(item.candidate_key);
    }
    return selected;
  };
  const mandatory = take(
    (item) => ["mandatory", "mandatory_goal_aligned"].includes(item.display_category),
    ACTION_PRESENTATION_LIMITS.mandatory
  );
  const goalDriven = take(
    (item) => item.display_category === "goal_driven",
    Math.min(ACTION_PRESENTATION_LIMITS.goal_driven, ACTION_PRESENTATION_LIMITS.total - mandatory.length)
  );
  const experiments = take(
    (item) => item.display_category === "experiment",
    Math.min(ACTION_PRESENTATION_LIMITS.experiment, ACTION_PRESENTATION_LIMITS.total - mandatory.length - goalDriven.length)
  );
  const visible = [...mandatory, ...goalDriven, ...experiments]
    .slice(0, ACTION_PRESENTATION_LIMITS.total)
    .map((item, index) => ({ ...item, rank: index + 1 }));
  const hiddenEligible = ranked.filter((item) => !used.has(item.candidate_key));
  const outrankedBy = visible[visible.length - 1];
  return {
    visible: visible.map((item) => ({
      ...item,
      outranked_reason: hiddenEligible.length
        ? `Survived strict eligibility and outranked ${hiddenEligible.length} eligible candidates by category cap, materiality, confidence, and total score.`
        : "Survived strict eligibility; no stronger eligible candidate was hidden by the presentation cap."
    })),
    hidden_eligible: hiddenEligible.map((item) => ({
      ...item,
      not_displayed_reason: outrankedBy
        ? `Eligible but below the presentation cap; last visible score was ${outrankedBy.total_score}.`
        : "Eligible but not selected for the main report."
    }))
  };
}

function finalActionFromCandidate(item, goalSpec) {
  const quantified = item.money_risk && num(item.money_risk.amount) > 0 ? item.money_risk : null;
  return {
    action_title: item.action_title || item.intervention,
    intervention: item.intervention,
    intervention_type: item.intervention_type,
    recommendation_type: item.recommendation_type,
    action_type: item.action_type,
    category: item.category,
    display_category: item.display_category || displayCategoryForCandidate(item),
    category_reason: item.category_reason || categoryReason(item),
    survived_filter_reason: item.survived_filter_reason || "",
    outranked_reason: item.outranked_reason || "",
    severity: item.severity,
    entity_type: item.entity_type,
    entity_id: item.entity_id,
    entity_name: item.entity_name,
    evidence: conciseCandidateEvidence(item),
    evidence_refs: item.evidence_refs,
    evidence_fields: item.evidence_fields,
    hypothesis: item.hypothesis,
    business_hypothesis: item.business_hypothesis || item.hypothesis,
    why_supports_goal: item.why_supports_goal || (
      item.action_type === "mandatory" && item.goal_relationship === "supports"
        ? `Mandatory correction and goal-aligned: supports ${goalSpec.name || goalSpec.primary_metric} through ${item.expected_metric_affected}.`
        : item.action_type === "mandatory"
          ? "Mandatory correction: visible under every business goal."
          : item.goal_relationship === "supports"
            ? `Supports ${goalSpec.name || goalSpec.primary_metric} through ${item.expected_metric_affected}.`
            : "Useful operational evidence, but not a primary goal lever."
    ),
    goal_connection: item.why_supports_goal || (
      item.action_type === "mandatory" && item.goal_relationship === "supports"
        ? `Mandatory and directly supports ${goalSpec.name || goalSpec.primary_metric}.`
        : item.action_type === "mandatory"
          ? "Mandatory correction: visible under every business goal."
          : item.goal_relationship === "supports"
            ? `Supports ${goalSpec.name || goalSpec.primary_metric}.`
            : "Monitor or supporting context."
    ),
    goal_relationship: item.goal_relationship,
    alternative_explanations: item.alternative_explanations || [],
    expected_metric_affected: item.expected_metric_affected,
    expected_metric: item.expected_metric,
    expected_direction: item.expected_direction,
    baseline: item.baseline || {},
    experiment_duration: item.experiment_duration,
    success_threshold: item.success_threshold,
    stop_condition: item.stop_condition,
    financial_guardrail: item.financial_guardrail,
    money_risk: quantified,
    money_risk_status: quantified ? "quantified" : "not_quantifiable_with_current_data",
    priority_score: item.total_score,
    confidence: item.confidence_score,
    owner: item.owner,
    assumptions: item.assumptions || [],
    missing_data: item.missing_data || [],
    next_week_check: item.next_week_check || ""
  };
}

function formatEvidenceValue(key, value) {
  if (value === "" || value == null) return "";
  if (/rate|pct|conversion|sell_through|view_to|roas|mer|frequency/i.test(key) && Number.isFinite(Number(value))) {
    if (/roas|mer|frequency/i.test(key)) return `${r2(value)}x`;
    return `${r2(Number(value) * 100)}%`;
  }
  return String(value);
}

function conciseCandidateEvidence(candidate) {
  const fields = candidate.evidence_fields || {};
  const facts = meaningfulEvidenceFacts(fields);
  const preferred = [
    "item_views",
    "view_to_cart_rate",
    "units_sold",
    "orders",
    "net_sales",
    "ending_inventory_units",
    "days_of_cover_7d",
    "daily_velocity_7d",
    "current_7d_units",
    "returned_items",
    "return_rate_units",
    "spend",
    "roas",
    "ctr_link",
    "frequency",
    "impressions",
    "mapping_confidence"
  ];
  const ordered = [
    ...preferred.map((key) => facts.find((fact) => fact.key === key)).filter(Boolean),
    ...facts.filter((fact) => !preferred.includes(fact.key))
  ].slice(0, 5);
  if (!ordered.length) return clean(candidate.evidence || "Evidence is stored in the source record.");
  const values = ordered
    .map(({ key, value }) => `${key.replace(/_/g, " ")} ${formatEvidenceValue(key, value)}`)
    .join(", ");
  return `${candidate.entity_name || candidate.entity_id || "Selected entity"}: ${values}.`;
}

function commercialCandidateJsonSchema() {
  return {
    type: "object",
    additionalProperties: false,
    required: ["candidates"],
    properties: {
      candidates: {
        type: "array",
        maxItems: 8,
        items: {
          type: "object",
          additionalProperties: false,
          required: [
            "intervention",
            "intervention_type",
            "recommendation_type",
            "entity_type",
            "entity_id",
            "entity_name",
            "evidence_refs",
            "hypothesis",
            "alternative_explanations",
            "expected_metric",
            "expected_direction",
            "experiment_duration",
            "success_threshold",
            "stop_condition",
            "financial_guardrail",
            "confidence",
            "owner"
          ],
          properties: {
            intervention: { type: "string" },
            intervention_type: { type: "string" },
            recommendation_type: { type: "string", enum: ["recommendation", "experiment", "mandatory_correction", "monitor"] },
            entity_type: { type: "string" },
            entity_id: { type: "string" },
            entity_name: { type: "string" },
            evidence_refs: { type: "array", items: { type: "string" } },
            hypothesis: { type: "string" },
            alternative_explanations: { type: "array", items: { type: "string" } },
            expected_metric: { type: "string" },
            expected_direction: { type: "string", enum: ["increase", "decrease", "protect", "monitor"] },
            experiment_duration: { type: "string" },
            success_threshold: { type: "string" },
            stop_condition: { type: "string" },
            financial_guardrail: { type: "string" },
            confidence: { type: "number" },
            owner: { type: "string" }
          }
        }
      }
    }
  };
}

async function proposeCommercialCandidatesWithLLM(env, evidencePacket, goalSpec, requested = false) {
  if (!requested) {
    return { status: "skipped", reason: "LLM candidate generation was not requested.", candidates: [] };
  }
  if (!clean(env.OPENAI_API_KEY)) {
    return { status: "skipped", reason: "OPENAI_API_KEY is not configured.", candidates: [] };
  }
  const model = clean(env.OPENAI_MODEL || DEFAULT_OPENAI_MODEL);
  const allowedEvidenceRefs = (evidencePacket?.evidence || []).map((item) => item.ref);
  const compactEvidence = (evidencePacket?.evidence || []).slice(0, 90).map((item) => ({
    ref: item.ref,
    source: item.source,
    entity_type: item.entity_type,
    entity_id: item.entity_id,
    entity_name: item.entity_name,
    metric: item.metric,
    value: item.value,
    fields: item.fields
  }));

  try {
    const response = await fetch("https://api.openai.com/v1/responses", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${clean(env.OPENAI_API_KEY)}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        model,
        input: [
          {
            role: "system",
            content:
              "Propose ecommerce candidate interventions from structured evidence only. " +
              "Never invent metrics, evidence, entities, weeks, or causal certainty. " +
              "Every candidate must cite evidence_refs from the provided allowed list. " +
              "When causality is uncertain, frame the action as an experiment. " +
              "Respect inventory, returns, paid-efficiency, margin, and goal guardrails."
          },
          {
            role: "user",
            content: JSON.stringify({
              prompt_version: RECOMMENDATION_PROMPT_VERSION,
              evidence_schema_version: EVIDENCE_SCHEMA_VERSION,
              active_goal: sanitizeGoalObject(goalSpec || {}),
              week: evidencePacket?.week || {},
              allowed_evidence_refs: allowedEvidenceRefs,
              diagnosis: evidencePacket?.diagnosis || {},
              performance_bridge: evidencePacket?.performance_bridge || {},
              evidence: compactEvidence
            })
          }
        ],
        text: {
          format: {
            type: "json_schema",
            name: "commercial_candidates",
            strict: true,
            schema: commercialCandidateJsonSchema()
          }
        }
      })
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      return {
        status: "failed",
        reason: clean(payload?.error?.message || `OpenAI returned HTTP ${response.status}.`),
        candidates: []
      };
    }
    const parsed = JSON.parse(extractResponseText(payload) || "{\"candidates\":[]}");
    const candidates = (parsed.candidates || []).map((item) => baseCandidate({
      ...item,
      source: "llm_candidate_generation",
      action_type: item.recommendation_type === "mandatory_correction" ? "mandatory" : item.recommendation_type,
      category:
        item.recommendation_type === "mandatory_correction" ? "mandatory" :
          item.recommendation_type === "experiment" ? "experiment" :
            item.recommendation_type === "monitor" ? "monitor" :
              "goal_driven",
      expected_metric_affected: item.expected_metric,
      business_hypothesis: item.hypothesis,
      assumptions: ["LLM-originated candidate; accepted only if deterministic evidence validation passes."]
    }));
    return {
      status: "generated",
      model,
      prompt_version: RECOMMENDATION_PROMPT_VERSION,
      candidates,
      raw_candidate_count: candidates.length
    };
  } catch (err) {
    return { status: "failed", reason: truncateOperationalError(err), candidates: [] };
  }
}

function goalTags(goalSpec) {
  const goal = sanitizeGoalObject(goalSpec || {});
  const weights = goal.metric_weights || {};
  const tags = new Set([goal.primary_metric]);
  for (const [key, value] of Object.entries(weights)) {
    if (num(value) >= 0.12) tags.add(key);
  }
  for (const lever of goal.preferred_levers || []) tags.add(clean(lever).toLowerCase());
  return tags;
}

function actionText(action) {
  return [
    action.source,
    action.severity,
    action.issue,
    action.evidence,
    action.cause,
    action.fix,
    action.owner,
    action.expected_impact
  ].map(clean).join(" ").toLowerCase();
}

function canonicalActionKey(action) {
  const text = actionText(action);
  const root =
    text.includes("stock") || text.includes("inventory") ? "inventory" :
      text.includes("return") || text.includes("refund") ? "returns" :
        text.includes("checkout") ? "checkout" :
          text.includes("roas") || text.includes("meta") || text.includes("paid") ? "paid_efficiency" :
            text.includes("add-to-cart") || text.includes("pdp") || text.includes("product") ? "conversion" :
              clean(action.source || "report").toLowerCase();
  const entityMatch = clean(action.evidence).match(/([A-Z0-9][A-Z0-9_-]{2,})/);
  const entity = entityMatch ? entityMatch[1].toLowerCase() : clean(action.issue).toLowerCase().slice(0, 48);
  const intervention = clean(action.fix).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim().split(" ").slice(0, 8).join("-");
  return [clean(action.week_start), root, entity, intervention].join("|");
}

function isMustShowAction(action) {
  if (clean(action.severity) === "Critical") return true;
  const text = actionText(action);
  return MUST_SHOW_PATTERNS.some((pattern) => pattern.test(text));
}

function goalAlignmentScore(action, goalSpec) {
  const tags = goalTags(goalSpec);
  const text = actionText(action);
  let score = 20;
  const matches = [
    ["revenue_growth", /sales|revenue|orders|scale|winner/],
    ["conversion", /conversion|add-to-cart|checkout|pdp|product page|cart/],
    ["paid_efficiency", /meta|roas|mer|paid|spend|ctr|cpc|creative/],
    ["margin_quality", /margin|discount|refund|return|efficiency|mer/],
    ["returns_quality", /return|refund|fit|quality|expectation/],
    ["inventory_availability", /stock|out of stock|restock|cover|availability/],
    ["inventory_movement", /slow|dead|inventory|sell-through|clearance|stock/],
    ["cash_generation", /cash|sales|revenue|slow|dead|inventory/],
    ["risk_protection", /critical|missing|failed|stockout|refund|checkout|tracking/]
  ];
  for (const [tag, pattern] of matches) {
    if (tags.has(tag) && pattern.test(text)) score += 12;
  }
  if (text.includes(clean(goalSpec.primary_metric).replace(/_/g, " "))) score += 8;
  return clamp(score);
}

function scoreAction(action, goalSpec, reportData) {
  const text = actionText(action);
  const severity = clean(action.severity);
  const mustShow = isMustShowAction(action);
  const financialBase = metricValueFromReportData(reportData, "net_sales");
  const components = {
    goal_alignment: goalAlignmentScore(action, goalSpec),
    financial_materiality: financialBase === "" ? 0 : clamp(
      text.includes("meta") || text.includes("spend") ? 65 :
        text.includes("stock") || text.includes("winner") ? 80 :
          text.includes("return") || text.includes("refund") ? 70 :
            text.includes("checkout") || text.includes("conversion") ? 75 : 45
    ),
    urgency: severity === "Critical" ? 95 : severity === "Action" ? 72 : severity === "Watch" ? 48 : 35,
    severity_guardrail: mustShow ? 100 : severity === "Critical" ? 92 : severity === "Action" ? 65 : 40,
    confidence: /missing|N\/A|not available/i.test(action.evidence || "") ? 45 : 70,
    time_to_impact: /audit|inspect|review|check/i.test(action.fix || "") ? 70 : 55,
    cross_functional_value: clean(action.owner).includes("/") ? 80 : 50
  };
  const total =
    components.goal_alignment * GOAL_SCORE_FORMULA.goal_alignment +
    components.financial_materiality * GOAL_SCORE_FORMULA.financial_materiality +
    components.urgency * GOAL_SCORE_FORMULA.urgency +
    components.severity_guardrail * GOAL_SCORE_FORMULA.severity_guardrail +
    components.confidence * GOAL_SCORE_FORMULA.confidence +
    components.time_to_impact * GOAL_SCORE_FORMULA.time_to_impact +
    components.cross_functional_value * GOAL_SCORE_FORMULA.cross_functional_value;

  return {
    action_key: canonicalActionKey(action),
    source_action: action,
    total_score: r2(total),
    goal_alignment_score: r2(components.goal_alignment),
    financial_score: r2(components.financial_materiality),
    urgency_score: r2(components.urgency),
    confidence_score: r2(components.confidence),
    severity_guardrail_score: r2(components.severity_guardrail),
    time_to_impact_score: r2(components.time_to_impact),
    cross_functional_value_score: r2(components.cross_functional_value),
    must_show: mustShow,
    formula: {
      coefficients: GOAL_SCORE_FORMULA,
      components,
      note: "Scores rank deterministic actions only; they do not change source facts or evidence."
    }
  };
}

function dedupeScoredActions(scored) {
  const byKey = new Map();
  for (const item of scored) {
    const existing = byKey.get(item.action_key);
    if (!existing || item.total_score > existing.total_score || (item.must_show && !existing.must_show)) {
      byKey.set(item.action_key, item);
    }
  }
  return [...byKey.values()];
}

function finalActionFromScore(item, goalSpec) {
  const action = item.source_action;
  return {
    ...action,
    action_title: clean(action.issue || action.fix || "Action required"),
    why_it_matters: clean(action.cause || action.expected_impact || "This action addresses a measurable report issue."),
    goal_connection: item.must_show
      ? "Mandatory correction: visible under every goal."
      : `Goal-driven: supports ${goalSpec.name || goalSpec.primary_metric}.`,
    expected_metric_affected: expectedMetricForAction(action, goalSpec),
    expected_direction: expectedDirectionForAction(action),
    priority_score: item.total_score,
    confidence: item.confidence_score,
    action_type: item.must_show ? "mandatory" : "goal_driven",
    assumptions: [],
    missing_data: /missing|N\/A|not available/i.test(action.evidence || "") ? [action.evidence] : []
  };
}

function expectedMetricForAction(action, goalSpec) {
  const text = actionText(action);
  if (/return|refund/.test(text)) return "refund_rate";
  if (/meta|roas|mer|paid|spend/.test(text)) return "mer";
  if (/checkout|conversion|add-to-cart|pdp|cart/.test(text)) return "conversion_rate";
  if (/stock|inventory|winner|slow|dead/.test(text)) return "net_sales";
  return goalSpec.primary_metric || "net_sales";
}

function expectedDirectionForAction(action) {
  const metric = expectedMetricForAction(action, {});
  return ["refund_rate", "item_return_rate"].includes(metric) ? "decrease" : "increase";
}

function buildScoredActions(reportData, goalSpec, options = {}) {
  const diagnosis = options.diagnosis || buildDeterministicDiagnosis(reportData);
  const evidencePacket = options.evidence_packet || options.evidencePacket || buildEvidencePacket(reportData, diagnosis);
  const rawCandidates = [
    ...generateCommercialCandidates(reportData, diagnosis),
    ...(options.extra_candidates || options.extraCandidates || [])
  ];
  const validation = validateAndScoreCandidates(rawCandidates, evidencePacket, goalSpec, reportData);
  const eligible = rankCommercialCandidates(dedupeCommercialCandidates(validation.accepted));
  const selection = selectVisibleActions(eligible);
  const scored = selection.visible
    .map((item, index) => ({
      ...item,
      action_key: item.candidate_key,
      must_show: ["mandatory", "mandatory_goal_aligned"].includes(item.display_category),
      rank: index + 1,
      final_action: finalActionFromCandidate(item, goalSpec)
    }));

  return {
    week_start: reportData?.week?.week_start || "",
    goal_id: goalSpec.goal_id,
    goal_version: goalSpec.version,
    goal_name: goalSpec.name,
    engine_version: RECOMMENDATION_ENGINE_VERSION,
    evidence_schema_version: EVIDENCE_SCHEMA_VERSION,
    prompt_version: RECOMMENDATION_PROMPT_VERSION,
    llm_generation: options.llm_generation || { status: "not_requested" },
    formula: COMMERCIAL_ACTION_SCORE_FORMULA,
    evidence_packet: evidencePacket,
    diagnosis,
    performance_bridge: evidencePacket.performance_bridge,
    generated_candidate_count: rawCandidates.length,
    eligible_candidate_count: eligible.length,
    hidden_eligible_candidates: selection.hidden_eligible,
    rejected_candidates: validation.rejected,
    presentation_limits: ACTION_PRESENTATION_LIMITS,
    mandatory_goal_aligned: scored.filter((item) => item.display_category === "mandatory_goal_aligned"),
    mandatory_corrections: scored.filter((item) => item.display_category === "mandatory"),
    goal_driven_priorities: scored.filter((item) => item.display_category === "goal_driven"),
    experiments_opportunities: scored.filter((item) => item.display_category === "experiment"),
    monitor: [],
    supporting_actions: [],
    all_eligible: eligible,
    all: scored
  };
}

async function storeActionScores(env, scoredActions) {
  const db = syncDb(env);
  if (!db || !scoredActions?.goal_id) return [];
  const stored = [];
  for (const item of scoredActions.all || []) {
    const scoreId = `score_${(await hashString([
      scoredActions.week_start,
      scoredActions.goal_id,
      scoredActions.goal_version,
      item.action_key
    ].join("|"))).slice(0, 48)}`;
    await db.prepare(
      `INSERT INTO action_scores
       (score_id, week_start, goal_id, goal_version, action_key, source_action_json,
        total_score, goal_alignment_score, financial_score, urgency_score, confidence_score,
        severity_guardrail_score, time_to_impact_score, cross_functional_value_score, must_show,
        rank, formula_json, final_action_json, eligibility_version, display_category, superseded_at, superseded_by_version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(week_start, goal_id, goal_version, action_key) DO UPDATE SET
        source_action_json = excluded.source_action_json,
        total_score = excluded.total_score,
        goal_alignment_score = excluded.goal_alignment_score,
        financial_score = excluded.financial_score,
        urgency_score = excluded.urgency_score,
        confidence_score = excluded.confidence_score,
        severity_guardrail_score = excluded.severity_guardrail_score,
        time_to_impact_score = excluded.time_to_impact_score,
        cross_functional_value_score = excluded.cross_functional_value_score,
        must_show = excluded.must_show,
        rank = excluded.rank,
        formula_json = excluded.formula_json,
        final_action_json = excluded.final_action_json,
        eligibility_version = excluded.eligibility_version,
        display_category = excluded.display_category,
        superseded_at = excluded.superseded_at,
        superseded_by_version = excluded.superseded_by_version,
        created_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')`
    ).bind(
      scoreId,
      scoredActions.week_start,
      scoredActions.goal_id,
      scoredActions.goal_version,
      item.action_key,
      JSON.stringify(item.source_action || item.final_action || item || {}),
      item.total_score,
      item.goal_alignment_score,
      item.financial_score,
      item.urgency_score,
      item.confidence_score,
      item.severity_guardrail_score,
      item.time_to_impact_score,
      item.cross_functional_value_score,
      item.must_show ? 1 : 0,
      item.rank,
      JSON.stringify(item.formula || {}),
      JSON.stringify(item.final_action || {}),
      ELIGIBILITY_RULE_VERSION,
      item.display_category || item.final_action?.display_category || "",
      "",
      ""
    ).run();
    stored.push(scoreId);
  }
  return stored;
}

async function dataHashForObject(value) {
  return (await hashString(JSON.stringify(value || {}))).slice(0, 64);
}

async function storeDiagnosisSnapshot(env, scoredActions) {
  const db = syncDb(env);
  if (!db || !scoredActions?.evidence_packet) return null;
  try {
    const dataHash = await dataHashForObject({
      evidence_schema_version: scoredActions.evidence_schema_version,
      evidence: scoredActions.evidence_packet.evidence,
      diagnosis: scoredActions.diagnosis,
      bridge: scoredActions.performance_bridge
    });
    const snapshotId = `dx_${(await hashString([
      scoredActions.week_start,
      scoredActions.goal_id || "",
      scoredActions.goal_version || "",
      dataHash
    ].join("|"))).slice(0, 48)}`;
    await db.prepare(
      `INSERT INTO diagnosis_snapshots
       (snapshot_id, week_start, goal_id, goal_version, evidence_schema_version, data_hash,
        diagnosis_json, evidence_packet_json, performance_bridge_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(week_start, goal_id, goal_version, data_hash) DO UPDATE SET
        diagnosis_json = excluded.diagnosis_json,
        evidence_packet_json = excluded.evidence_packet_json,
        performance_bridge_json = excluded.performance_bridge_json,
        created_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')`
    ).bind(
      snapshotId,
      scoredActions.week_start,
      scoredActions.goal_id || "",
      scoredActions.goal_version || 0,
      scoredActions.evidence_schema_version || EVIDENCE_SCHEMA_VERSION,
      dataHash,
      JSON.stringify(scoredActions.diagnosis || {}),
      JSON.stringify(scoredActions.evidence_packet || {}),
      JSON.stringify(scoredActions.performance_bridge || {})
    ).run();
    return { snapshot_id: snapshotId, data_hash: dataHash };
  } catch (err) {
    return { error: truncateOperationalError(err) };
  }
}

async function storeRecommendationGenerationRun(env, scoredActions, snapshot = null) {
  const db = syncDb(env);
  if (!db || !scoredActions) return null;
  try {
    const dataHash = snapshot?.data_hash || await dataHashForObject(scoredActions.evidence_packet || {});
    const generationId = `gen_${(await hashString([
      scoredActions.week_start,
      scoredActions.goal_id || "",
      scoredActions.goal_version || "",
      RECOMMENDATION_PROMPT_VERSION,
      dataHash
    ].join("|"))).slice(0, 48)}`;
    await db.prepare(
      `INSERT INTO recommendation_generation_runs
       (generation_id, week_start, goal_id, goal_version, model, prompt_version, evidence_schema_version,
        data_hash, input_json, output_json, status, error_message, eligibility_version, superseded_at, superseded_by_version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(week_start, goal_id, goal_version, prompt_version, data_hash) DO UPDATE SET
        output_json = excluded.output_json,
        status = excluded.status,
        error_message = excluded.error_message,
        eligibility_version = excluded.eligibility_version,
        superseded_at = excluded.superseded_at,
        superseded_by_version = excluded.superseded_by_version,
        created_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')`
    ).bind(
      generationId,
      scoredActions.week_start,
      scoredActions.goal_id || "",
      scoredActions.goal_version || 0,
      RECOMMENDATION_ENGINE_VERSION,
      RECOMMENDATION_PROMPT_VERSION,
      scoredActions.evidence_schema_version || EVIDENCE_SCHEMA_VERSION,
      dataHash,
      JSON.stringify({
        evidence_schema_version: scoredActions.evidence_schema_version,
        candidate_count: scoredActions.generated_candidate_count,
        goal_id: scoredActions.goal_id,
        goal_version: scoredActions.goal_version
      }),
      JSON.stringify({
        accepted: (scoredActions.all || []).length,
        rejected: (scoredActions.rejected_candidates || []).length,
        categories: {
          mandatory: (scoredActions.mandatory_corrections || []).length,
          goal_driven: (scoredActions.goal_driven_priorities || []).length,
          experiments: (scoredActions.experiments_opportunities || []).length,
          monitor: (scoredActions.monitor || []).length
        }
      }),
      "generated",
      "",
      ELIGIBILITY_RULE_VERSION,
      "",
      ""
    ).run();
    return { generation_id: generationId, data_hash: dataHash };
  } catch (err) {
    return { error: truncateOperationalError(err) };
  }
}

async function storeCommercialCandidates(env, scoredActions, generation = null) {
  const db = syncDb(env);
  if (!db || !scoredActions) return [];
  const dataHash = generation?.data_hash || await dataHashForObject(scoredActions.evidence_packet || {});
  const generationId = generation?.generation_id || "";
  const stored = [];
  const allCandidates = [
    ...(scoredActions.all_eligible || []),
    ...(scoredActions.all || []),
    ...(scoredActions.rejected_candidates || [])
  ];
  const byKey = new Map();
  for (const item of allCandidates) {
    if (!byKey.has(item.candidate_key) || clean(item.validation_status) === "accepted") byKey.set(item.candidate_key, item);
  }
  for (const item of byKey.values()) {
    try {
      const candidateId = `cand_${(await hashString([
        scoredActions.week_start,
        scoredActions.goal_id || "",
        scoredActions.goal_version || "",
        item.candidate_key,
        dataHash
      ].join("|"))).slice(0, 48)}`;
      await db.prepare(
        `INSERT INTO commercial_candidate_actions
         (candidate_id, week_start, goal_id, goal_version, candidate_key, generation_id, data_hash,
          category, recommendation_type, entity_type, entity_id, entity_name, intervention_type,
          expected_metric, expected_direction, confidence, validation_status, rejection_reasons_json,
          evidence_refs_json, evidence_json, assumptions_json, action_json, score_json, rank,
          prompt_version, eligibility_version, engine_version, display_category, survived_filter_reason, outranked_reason, superseded_at, superseded_by_version)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(week_start, goal_id, goal_version, candidate_key, data_hash) DO UPDATE SET
          category = excluded.category,
          recommendation_type = excluded.recommendation_type,
          confidence = excluded.confidence,
          validation_status = excluded.validation_status,
          rejection_reasons_json = excluded.rejection_reasons_json,
          evidence_json = excluded.evidence_json,
          assumptions_json = excluded.assumptions_json,
          action_json = excluded.action_json,
          score_json = excluded.score_json,
          rank = excluded.rank,
          prompt_version = excluded.prompt_version,
          eligibility_version = excluded.eligibility_version,
          engine_version = excluded.engine_version,
          display_category = excluded.display_category,
          survived_filter_reason = excluded.survived_filter_reason,
          outranked_reason = excluded.outranked_reason,
          superseded_at = excluded.superseded_at,
          superseded_by_version = excluded.superseded_by_version,
          created_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')`
      ).bind(
        candidateId,
        scoredActions.week_start,
        scoredActions.goal_id || "",
        scoredActions.goal_version || 0,
        item.candidate_key,
        generationId,
        dataHash,
        item.category || "monitor",
        item.recommendation_type || item.action_type || "recommendation",
        item.entity_type || "",
        item.entity_id || "",
        item.entity_name || "",
        item.intervention_type || "",
        item.expected_metric || item.expected_metric_affected || "",
        item.expected_direction || "",
        num(item.confidence || item.confidence_score),
        item.validation_status || "accepted",
        JSON.stringify(item.rejection_reasons || []),
        JSON.stringify(item.evidence_refs || []),
        JSON.stringify(item.evidence_fields || {}),
        JSON.stringify(item.assumptions || []),
        JSON.stringify(item.final_action || item || {}),
        JSON.stringify(item.formula || {}),
        item.rank || 0,
        scoredActions.prompt_version || RECOMMENDATION_PROMPT_VERSION,
        ELIGIBILITY_RULE_VERSION,
        scoredActions.engine_version || RECOMMENDATION_ENGINE_VERSION,
        item.display_category || "",
        item.survived_filter_reason || "",
        item.outranked_reason || item.not_displayed_reason || "",
        "",
        ""
      ).run();
      stored.push(candidateId);
    } catch (_) {
      // Audit writes should not block report rendering.
    }
  }
  return stored;
}

async function storeMoneyRiskEstimates(env, scoredActions) {
  const db = syncDb(env);
  if (!db || !scoredActions) return [];
  const stored = [];
  for (const item of scoredActions.all || []) {
    const risk = item.money_risk || item.final_action?.money_risk;
    if (!risk || risk.amount === "" || risk.amount == null) continue;
    try {
      const estimateId = `risk_${(await hashString([
        scoredActions.week_start,
        item.candidate_key,
        item.expected_metric || item.expected_metric_affected,
        risk.amount
      ].join("|"))).slice(0, 48)}`;
      await db.prepare(
        `INSERT INTO money_risk_estimates
         (estimate_id, week_start, candidate_key, metric, amount, currency, formula, confidence, assumptions_json)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(week_start, candidate_key, metric) DO UPDATE SET
          amount = excluded.amount,
          currency = excluded.currency,
          formula = excluded.formula,
          confidence = excluded.confidence,
          assumptions_json = excluded.assumptions_json,
          created_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')`
      ).bind(
        estimateId,
        scoredActions.week_start,
        item.candidate_key,
        item.expected_metric || item.expected_metric_affected || "net_sales",
        num(risk.amount),
        risk.currency || scoredActions.evidence_packet?.performance_bridge?.currency || "",
        risk.formula || "",
        risk.confidence || "low",
        JSON.stringify(risk.assumptions || [])
      ).run();
      stored.push(estimateId);
    } catch (_) {
      // Audit writes should not block report rendering.
    }
  }
  return stored;
}

async function supersedePriorRecommendationVersions(env, weekStart, goalId, goalVersion) {
  const db = syncDb(env);
  if (!db) return { ok: false, reason: "No D1 binding." };
  const now = new Date().toISOString();
  const bindings = [now, `${RECOMMENDATION_ENGINE_VERSION}|${ELIGIBILITY_RULE_VERSION}`, clean(weekStart), clean(goalId), num(goalVersion)];
  const results = {};
  try {
    results.candidates = await db.prepare(
      `UPDATE commercial_candidate_actions
       SET superseded_at = ?, superseded_by_version = ?
       WHERE week_start = ? AND goal_id = ? AND goal_version = ?
         AND (superseded_at IS NULL OR superseded_at = '')
         AND (prompt_version IS NULL OR prompt_version <> '${RECOMMENDATION_PROMPT_VERSION}'
              OR eligibility_version IS NULL OR eligibility_version <> '${ELIGIBILITY_RULE_VERSION}'
              OR engine_version IS NULL OR engine_version <> '${RECOMMENDATION_ENGINE_VERSION}')`
    ).bind(...bindings).run();
  } catch (err) {
    results.candidates_error = truncateOperationalError(err);
  }
  try {
    results.generation_runs = await db.prepare(
      `UPDATE recommendation_generation_runs
       SET superseded_at = ?, superseded_by_version = ?
       WHERE week_start = ? AND goal_id = ? AND goal_version = ?
         AND (superseded_at IS NULL OR superseded_at = '')
         AND (prompt_version IS NULL OR prompt_version <> '${RECOMMENDATION_PROMPT_VERSION}'
              OR eligibility_version IS NULL OR eligibility_version <> '${ELIGIBILITY_RULE_VERSION}')`
    ).bind(...bindings).run();
  } catch (err) {
    results.generation_runs_error = truncateOperationalError(err);
  }
  try {
    results.action_scores = await db.prepare(
      `UPDATE action_scores
       SET superseded_at = ?, superseded_by_version = ?
       WHERE week_start = ? AND goal_id = ? AND goal_version = ?
         AND (superseded_at IS NULL OR superseded_at = '')
         AND (eligibility_version IS NULL OR eligibility_version <> '${ELIGIBILITY_RULE_VERSION}')`
    ).bind(...bindings).run();
  } catch (err) {
    results.action_scores_error = truncateOperationalError(err);
  }
  return { ok: true, ...results };
}

async function storeRecommendationAudit(env, scoredActions) {
  await supersedePriorRecommendationVersions(
    env,
    scoredActions.week_start,
    scoredActions.goal_id || "",
    scoredActions.goal_version || 0
  );
  const snapshot = await storeDiagnosisSnapshot(env, scoredActions);
  const generation = await storeRecommendationGenerationRun(env, scoredActions, snapshot);
  const candidate_ids = await storeCommercialCandidates(env, scoredActions, generation);
  const money_risk_ids = await storeMoneyRiskEstimates(env, scoredActions);
  return {
    snapshot,
    generation,
    candidate_ids,
    money_risk_ids
  };
}

function buildGoalProgress(reportData, goalRow) {
  if (!goalRow) {
    return {
      active_goal: null,
      progress: null,
      warning: "No active business goal is configured for this selected week."
    };
  }
  const goalSpec = goalRow.goal_spec || goalRow;
  return {
    active_goal: goalRow,
    progress: calculateGoalProgress(goalSpec, reportData, reportData?.week?.week_start || "")
  };
}

async function buildGoalProgressResponse(env, requestedWeekStart = "") {
  const reportData = await buildReportData(env, requestedWeekStart);
  const goalRow = await activeGoalForWeek(env, reportData.week.week_start);
  return {
    ok: true,
    week: reportData.week,
    ...buildGoalProgress(reportData, goalRow),
    diagnosis: buildDeterministicDiagnosis(reportData),
    schema_version: GOAL_SCHEMA_VERSION
  };
}

async function buildScoredActionsResponse(env, requestedWeekStart = "", options = {}) {
  const selectedWeek = clean(requestedWeekStart);
  const earlyGoal = selectedWeek ? await activeGoalForWeek(env, selectedWeek) : null;
  if (selectedWeek && !earlyGoal) {
    return {
      ok: true,
      week: { week_start: selectedWeek },
      active_goal: null,
      progress: null,
      diagnosis: null,
      scored_actions: null,
      unscored_actions: [],
      warning: "No active business goal is configured; skipped report rebuild and action scoring."
    };
  }
  const reportData = await buildReportData(env, requestedWeekStart);
  const goalRow = earlyGoal || await activeGoalForWeek(env, reportData.week.week_start);
  if (!goalRow) {
    return {
      ok: true,
      week: reportData.week,
      active_goal: null,
      progress: null,
      diagnosis: buildDeterministicDiagnosis(reportData),
      scored_actions: null,
      unscored_actions: reportData.actions || [],
      warning: "No active business goal is configured; existing deterministic actions are available but not goal-scored."
    };
  }
  const diagnosis = buildDeterministicDiagnosis(reportData);
  const evidencePacket = buildEvidencePacket(reportData, diagnosis);
  const llmGeneration = await proposeCommercialCandidatesWithLLM(
    env,
    evidencePacket,
    goalRow.goal_spec,
    !!options.use_llm
  );
  const scoredActions = buildScoredActions(reportData, goalRow.goal_spec, {
    diagnosis,
    evidence_packet: evidencePacket,
    extra_candidates: llmGeneration.candidates || [],
    llm_generation: llmGeneration
  });
  const stored_score_ids = await storeActionScores(env, scoredActions);
  const audit = await storeRecommendationAudit(env, scoredActions);
  return {
    ok: true,
    week: reportData.week,
    active_goal: goalRow,
    progress: calculateGoalProgress(goalRow.goal_spec, reportData, reportData.week.week_start),
    diagnosis: scoredActions.diagnosis,
    performance_bridge: scoredActions.performance_bridge,
    evidence_packet: scoredActions.evidence_packet,
    scored_actions: scoredActions,
    stored_score_ids,
    audit
  };
}

async function buildDiagnosisResponse(env, requestedWeekStart = "") {
  const reportData = await buildReportData(env, requestedWeekStart);
  const goalRow = await activeGoalForWeek(env, reportData.week.week_start);
  const diagnosis = buildDeterministicDiagnosis(reportData);
  const evidencePacket = buildEvidencePacket(reportData, diagnosis);
  const snapshot = await storeDiagnosisSnapshot(env, {
    week_start: reportData.week.week_start,
    goal_id: goalRow?.goal_id || "",
    goal_version: goalRow?.version || 0,
    evidence_schema_version: EVIDENCE_SCHEMA_VERSION,
    diagnosis,
    evidence_packet: evidencePacket,
    performance_bridge: evidencePacket.performance_bridge
  });
  return {
    ok: true,
    week: reportData.week,
    active_goal: goalRow,
    diagnosis,
    evidence_packet: evidencePacket,
    performance_bridge: evidencePacket.performance_bridge,
    snapshot
  };
}

async function buildCreativeMetadataResponse(env, requestedWeekStart = "") {
  const reportData = await buildReportData(env, requestedWeekStart);
  const metadata = reportData.creative?.metadata || [];
  return {
    ok: true,
    week: reportData.week,
    supported: metadata.some((row) => row.status === "available" && (row.thumbnail_url || row.preview_url)),
    unavailable_reason: metadata.length
      ? "Creative preview records exist only when Meta creative fields have been synced or manually imported."
      : "MetaAdWeekly currently contains performance fields but no creative thumbnail, body, destination, or preview fields.",
    ads: reportData.creative?.ads || [],
    metadata
  };
}

async function refreshCreativeMetadataResponse(env, requestedWeekStart = "", options = {}) {
  const reportData = await buildReportData(env, requestedWeekStart);
  const requestedAdIds = (Array.isArray(options.ad_ids) ? options.ad_ids : [])
    .map(clean)
    .filter(Boolean)
    .slice(0, 24);
  const refreshed = await refreshMetaCreativeMetadata(env, reportData, {
    ad_ids: requestedAdIds,
    max_ads: requestedAdIds.length || 24,
    batch_size: 5,
    missing_only: requestedAdIds.length === 0
  });
  if (!refreshed.requested_ads) {
    return {
      ok: true,
      week: reportData.week,
      supported: (reportData.creative?.metadata || []).some((row) => clean(row.thumbnail_url)),
      stored_ids: [],
      stored_image_ids: [],
      requested_ads: 0,
      errors: [],
      unavailable_reason: "All selected ads already have stored creative images."
    };
  }
  if (!refreshed.stored_ids.length) {
    const reason = refreshed.errors.length
      ? `Meta creative enrichment returned no stored creatives. First error: ${refreshed.errors[0]}`
      : "Meta creative preview enrichment returned no creative metadata for the selected ads.";
    const stored_ids = await markCreativeMetadataUnavailable(
      env,
      reportData,
      reason,
      refreshed.requested_ad_ids
    );
    return {
      ok: true,
      week: reportData.week,
      supported: false,
      stored_ids,
      stored_image_ids: [],
      requested_ads: refreshed.requested_ads,
      errors: refreshed.errors,
      unavailable_reason: reason
    };
  }
  return {
    ok: true,
    week: reportData.week,
    supported: true,
    stored_ids: refreshed.stored_ids,
    stored_image_ids: refreshed.stored_image_ids,
    requested_ads: refreshed.requested_ads,
    errors: refreshed.errors,
    unavailable_reason: refreshed.errors.length ? "Some creatives could not be fetched; available creatives were stored." : ""
  };
}

async function buildAdProductMappingsResponse(env, requestedWeekStart = "") {
  const reportData = await buildReportData(env, requestedWeekStart);
  return {
    ok: true,
    week: reportData.week,
    mappings: reportData.creative?.ad_product_mappings || [],
    suggestions: reportData.creative?.ad_product_mapping_suggestions || [],
    warning: "Suggestions are deterministic name matches and must be treated as low-confidence until accepted manually."
  };
}

function goalsResponse(goals) {
  return {
    ok: true,
    schema_version: GOAL_SCHEMA_VERSION,
    presets: goalPresetDefinitions(),
    goals,
    active_goal: goals.find((goal) => goal.status === "active") || null,
    scoring_formula: COMMERCIAL_ACTION_SCORE_FORMULA,
    legacy_scoring_formula: GOAL_SCORE_FORMULA,
    diagnostic_thresholds: DIAGNOSIS_THRESHOLDS
  };
}

async function buildReportData(env, requestedWeekStart = "") {
  const tabData = await readAllTabs(env);
  const config = parseConfig(tabData.Config, env);
  const weekStart = resolveWeekStartInput(requestedWeekStart, config);

  const boundaries = weekBoundaries(weekStart, config.timezone);
  const warnings = [];

  const reportRows = rowsForWeek(tabData, "ReportWeekly", weekStart);
  const actionRows = rowsForWeek(tabData, "ReportActions", weekStart);
  const shopifyRows = rowsForWeek(tabData, "ShopifyWeekly", weekStart);
  const productRows = rowsForWeek(tabData, "ShopifyProductWeekly", weekStart);
  const skuRows = rowsForWeek(tabData, "ShopifySkuWeekly", weekStart);
  const productDiagnosisRows = rowsForWeek(
    tabData,
    "ShopifyProductDiagnosis",
    weekStart
  );
  const skuDiagnosisRows = rowsForWeek(
    tabData,
    "ShopifySkuDiagnosis",
    weekStart
  );
  const ga4Rows = rowsForWeek(tabData, "GA4Weekly", weekStart);
  const ga4ProductRows = rowsForWeek(tabData, "GA4ProductWeekly", weekStart);
  const metaRows = rowsForWeek(tabData, "MetaWeekly", weekStart);
  const campaignRows = rowsForWeek(tabData, "MetaCampaignWeekly", weekStart);
  const adRows = rowsForWeek(tabData, "MetaAdWeekly", weekStart);

  const selectedTabs = [
    ["ReportWeekly", reportRows],
    ["ReportActions", actionRows],
    ["ShopifyWeekly", shopifyRows],
    ["ShopifyProductWeekly", productRows],
    ["ShopifySkuWeekly", skuRows],
    ["ShopifyProductDiagnosis", productDiagnosisRows],
    ["ShopifySkuDiagnosis", skuDiagnosisRows],
    ["GA4Weekly", ga4Rows],
    ["GA4ProductWeekly", ga4ProductRows],
    ["MetaWeekly", metaRows],
    ["MetaCampaignWeekly", campaignRows],
    ["MetaAdWeekly", adRows]
  ];

  for (const [tab, rows] of selectedTabs) {
    if (!rows.length) {
      warnings.push(`No ${tab} rows found for week_start ${weekStart}.`);
    }
  }

  const report = reportRows[0] || null;
  const shopify = shopifyRows[0] || null;
  const ga4 = ga4Rows[0] || null;
  const meta = metaRows[0] || null;
  const syncStatus = await getRunByWeek(env, weekStart);
  const cvrShopifyHistory = new Map(
    objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly)
      .map((r) => [clean(r.week_start), r])
  );
  const cvrGa4History = new Map(
    objectsFromTab(tabData, "GA4Weekly", HEADERS.GA4Weekly)
      .map((r) => [clean(r.week_start), r])
  );
  const cvrReportHistory = new Map(
    objectsFromTab(tabData, "ReportWeekly", HEADERS.ReportWeekly)
      .map((r) => [clean(r.week_start), r])
  );
  const sourceShopifyCvr = shopifyConversionRate(shopify, ga4);
  const reportShopifyCvr = numericValueOrFallback(report?.ga4_shopify_cvr, "");
  const currentShopifyCvr =
    reportShopifyCvr !== ""
      ? reportShopifyCvr
      : sourceShopifyCvr !== ""
        ? r4(sourceShopifyCvr)
        : "";
  const sourceShopifyCvrComp = cvrComparisonForWeek(
    boundaries,
    currentShopifyCvr,
    cvrShopifyHistory,
    cvrGa4History,
    cvrReportHistory
  );

  if (report && reportShopifyCvr === "" && sourceShopifyCvr !== "") {
    warnings.push(
      `ReportWeekly.ga4_shopify_cvr was blank for ${weekStart}; /report-data calculated Shopify orders / GA4 sessions from selected-week source rows.`
    );
  }

  if (currentShopifyCvr === "") {
    if (!ga4) {
      warnings.push(`Shopify conversion rate unavailable because GA4Weekly is missing for ${weekStart}.`);
    } else if (!hasNumericValue(ga4.sessions)) {
      warnings.push(`Shopify conversion rate unavailable because GA4Weekly.sessions is missing for ${weekStart}.`);
    } else if (num(ga4.sessions) <= 0) {
      warnings.push(`Shopify conversion rate unavailable because GA4Weekly.sessions is zero for ${weekStart}.`);
    } else if (!shopify) {
      warnings.push(`Shopify conversion rate unavailable because ShopifyWeekly is missing for ${weekStart}.`);
    } else if (!hasNumericValue(shopify.orders)) {
      warnings.push(`Shopify conversion rate unavailable because ShopifyWeekly.orders is missing for ${weekStart}.`);
    }
  }

  const productsByRevenue = sortByNumberDesc(productRows, "net_sales");
  const skusByRevenue = sortByNumberDesc(skuRows, "net_sales");
  const ga4ProductsByViews = sortByNumberDesc(ga4ProductRows, "item_views");
  const campaignsBySpend = sortByNumberDesc(campaignRows, "spend");
  const adsBySpend = sortByNumberDesc(adRows, "spend");
  const creativeMetadata = await listCreativeMetadata(env, weekStart);
  const manualAdProductMappings = await listAdProductMappings(env, weekStart);
  const actions = [...actionRows].sort(
    (a, b) =>
      severityRank(a.severity) - severityRank(b.severity) ||
      clean(a.action_id).localeCompare(clean(b.action_id))
  );

  const inventoryProducts = [...productRows].sort(
    (a, b) =>
      num(a.days_of_cover_7d) - num(b.days_of_cover_7d) ||
      num(b.units_sold) - num(a.units_sold)
  );
  const inventorySkus = [...skuRows].sort(
    (a, b) =>
      (clean(b.is_oos) === "TRUE" ? 1 : 0) -
        (clean(a.is_oos) === "TRUE" ? 1 : 0) ||
      num(a.days_of_cover_7d) - num(b.days_of_cover_7d) ||
      num(b.units_sold) - num(a.units_sold)
  );
  const returnedProducts = sortByNumberDesc(
    productRows.filter((row) => num(row.returned_items) > 0),
    "returned_items"
  );
  const returnedSkus = sortByNumberDesc(
    skuRows.filter((row) => num(row.returned_items) > 0),
    "returned_items"
  );
  const adProductMappingSuggestions = buildAdProductMappingSuggestions({
    week: { week_start: boundaries.week_start },
    revenue: { products: productsByRevenue },
    creative: { ads: adsBySpend }
  });
  const enrichedAds = enrichCreativeAds(
    adsBySpend,
    productsByRevenue,
    creativeMetadata,
    manualAdProductMappings,
    adProductMappingSuggestions
  );

  // The same three signals the weekly surface renders. Carried on reportData so
  // the AI narrative reasons from the SAME facts the dashboard shows — otherwise
  // the two disagree in public and the reader cannot tell which is wrong.
  // tabData is already in scope, so this costs no extra read.
  const surfaceSignals = {
    drop_comparison: buildDropComparison(tabData, shopify || {}),
    change_attribution: explainOrderChange(tabData, boundaries.week_start),
    diagnosis_trust: diagnosisTrust(tabData, ga4 || {})
  };

  const reportData = {
    week: {
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      timezone: config.timezone,
      currency: clean(shopify?.currency || meta?.currency || config.currency),
      defaulted: !clean(requestedWeekStart)
    },
    sync_status: syncStatus,
    warnings,
    surface_signals: surfaceSignals,
    summary: report,
    scoreboard: {
      net_sales: {
        current: report?.shopify_net_sales ?? shopify?.net_sales ?? "",
        previous_week: report?.net_sales_previous_week ?? "",
        wow_pct: report?.net_sales_wow_pct ?? "",
        four_week_average: report?.net_sales_4w_avg ?? "",
        vs_four_week_average_pct: report?.net_sales_vs_4w_avg_pct ?? ""
      },
      orders: {
        current: report?.shopify_orders ?? shopify?.orders ?? "",
        previous_week: report?.orders_previous_week ?? "",
        wow_pct: report?.orders_wow_pct ?? "",
        four_week_average: report?.orders_4w_avg ?? "",
        vs_four_week_average_pct: report?.orders_vs_4w_avg_pct ?? ""
      },
      units: {
        current: report?.shopify_units_sold ?? shopify?.net_items_sold ?? "",
        previous_week: report?.units_previous_week ?? "",
        wow_pct: report?.units_wow_pct ?? "",
        four_week_average: report?.units_4w_avg ?? "",
        vs_four_week_average_pct: report?.units_vs_4w_avg_pct ?? ""
      },
      aov: {
        current: report?.shopify_aov ?? shopify?.aov ?? "",
        previous_week: report?.aov_previous_week ?? "",
        wow_pct: report?.aov_wow_pct ?? "",
        four_week_average: report?.aov_4w_avg ?? "",
        vs_four_week_average_pct: report?.aov_vs_4w_avg_pct ?? ""
      },
      conversion_rate: {
        current: currentShopifyCvr,
        previous_week: numericValueOrFallback(report?.shopify_cvr_previous_week, sourceShopifyCvrComp.previous),
        wow_pct: numericValueOrFallback(report?.shopify_cvr_wow_pct, sourceShopifyCvrComp.wow),
        four_week_average: numericValueOrFallback(report?.shopify_cvr_4w_avg, sourceShopifyCvrComp.avg4),
        vs_four_week_average_pct: numericValueOrFallback(report?.shopify_cvr_vs_4w_avg_pct, sourceShopifyCvrComp.vs4)
      },
      mer: {
        current: report?.mer ?? "",
        previous_week: report?.mer_previous_week ?? "",
        wow_pct: report?.mer_wow_pct ?? "",
        four_week_average: report?.mer_4w_avg ?? "",
        vs_four_week_average_pct: report?.mer_vs_4w_avg_pct ?? ""
      }
    },
    revenue: {
      weekly: shopify,
      products: productsByRevenue,
      skus: skusByRevenue
    },
    funnel: {
      weekly: ga4,
      products: ga4ProductsByViews
    },
    paid: {
      weekly: meta,
      campaigns: campaignsBySpend
    },
    creative: {
      ads: enrichedAds,
      metadata: creativeMetadata,
      ad_product_mappings: manualAdProductMappings,
      ad_product_mapping_suggestions: adProductMappingSuggestions,
      preview_support: creativeMetadata.some((row) => row.status === "available" && (row.thumbnail_url || row.preview_url))
        ? "available"
        : "unavailable"
    },
    inventory: {
      products: inventoryProducts,
      skus: inventorySkus,
      product_diagnoses: productDiagnosisRows,
      sku_diagnoses: skuDiagnosisRows
    },
    returns: {
      refund_rate: shopify?.refund_rate ?? "",
      item_return_rate: shopify?.item_return_rate ?? "",
      returned_items: shopify?.returned_items ?? "",
      returned_orders: shopify?.returned_orders ?? "",
      products: returnedProducts,
      skus: returnedSkus
    },
    actions
  };
  reportData.diagnosis = buildDeterministicDiagnosis(reportData);
  return reportData;
}

function aiReportSuggestedGoals() {
  return [
    "Grow net sales next week",
    "Protect margin",
    "Sell through slow-moving inventory",
    "Scale paid ads safely",
    "Reduce refunds and returns",
    "Clear inventory without hurting winners",
    "Find why revenue dropped",
    "Prepare restock/buying plan for next week",
    "Improve conversion rate",
    "Reduce wasted ad spend",
    "Identify what to scale",
    "Identify what to stop"
  ];
}

function aiReportGoalProfile(goalText = "", mode = "general") {
  const text = clean(goalText).toLowerCase();
  const presetId =
    mode !== "goal" ? "balance_growth_efficiency" :
      /sell through|slow-moving|slow moving|clear inventory/.test(text) ? "sell_through_slow_inventory" :
        /margin|profit|protect/.test(text) ? "protect_margin" :
          /refund|return/.test(text) ? "reduce_returns_refunds" :
            /wasted|waste|spend|roas|paid/.test(text) ? "improve_paid_efficiency" :
              /conversion|cvr|checkout|cart/.test(text) ? "improve_conversion_rate" :
                /scale|winner|restock|buying/.test(text) ? "scale_proven_winners" :
                  "grow_net_sales";
  const goalSpec = presetGoalSpec(presetId, {
    original_text: clean(goalText) || (mode === "goal" ? "Goal-focused weekly report" : "General weekly commercial report")
  });
  const profiles = {
    sell_through_slow_inventory: {
      goal_summary: "Move cash tied in slow inventory without pretending low-exposure products are proven demand failures.",
      inclusion_rules: ["High stock", "Weak sell-through", "Low-exposure tests", "Bundle/merchandising/offer experiments"],
      exclusion_rules: ["Unnecessary restocks", "Scaling products with weak stock", "Unrelated growth actions"],
      priority_weighting: "Inventory burden and sell-through first; mandatory corrections still visible.",
      tradeoffs: ["Exposure tests should precede broad discounting when traffic is insufficient."],
      success_threshold: "Sell-through improves by at least 20% without MER/refund deterioration.",
      stop_condition: "Stop if exposure rises but sell-through does not improve or margin/refunds worsen.",
      report_framing: "Frame weak products as slow-moving, low-exposure, or demand-constrained only when traffic supports it."
    },
    protect_margin: {
      goal_summary: "Protect commercial quality by reducing refund leakage, inefficient spend, discount pressure, and return-risk products.",
      inclusion_rules: ["Refund leakage", "Poor ROAS spend", "High frequency fatigue", "Return-risk SKUs", "Discount pressure"],
      exclusion_rules: ["Growth actions that worsen MER/refunds", "Discount-first fixes without margin proof"],
      priority_weighting: "Risk protection and paid efficiency before revenue expansion.",
      tradeoffs: ["Revenue growth may be intentionally deprioritized if it worsens returns or paid efficiency."],
      success_threshold: "Refund rate, inefficient spend, or discount pressure falls without material sales damage.",
      stop_condition: "Stop if sales fall while margin proxies do not improve.",
      report_framing: "Use ROAS, MER, refunds, discounts, and return rates as proxies; do not invent true margin."
    },
    reduce_returns_refunds: {
      goal_summary: "Reduce refund and return leakage while treating causes as hypotheses until return reasons prove them.",
      inclusion_rules: ["Return-risk products/SKUs", "Refunded EGP", "High return rate", "Scaling blocks on return-risk products"],
      exclusion_rules: ["Scaling affected products before return cause is understood"],
      priority_weighting: "Refund leakage and product quality risk before scale.",
      tradeoffs: ["Some revenue may be capped until return drivers are isolated."],
      success_threshold: "Refund rate and returned units fall below thresholds.",
      stop_condition: "Pause scaling if return rate remains above threshold after corrective work.",
      report_framing: "Separate observed return/refund facts from hypotheses like sizing, fit, imagery, QA, fulfillment, or expectation mismatch."
    },
    improve_paid_efficiency: {
      goal_summary: "Reduce wasted spend and protect MER while keeping scalable ads only when product stock and quality can support demand.",
      inclusion_rules: ["Poor ROAS spend", "High spend/weak return", "Fatigue", "Mapping confidence", "Do-not-scale stock blocks"],
      exclusion_rules: ["Product-stock recommendations from low-confidence mappings", "Scaling low-stock or return-risk products"],
      priority_weighting: "Paid efficiency, mapping confidence, and stock safety first.",
      tradeoffs: ["Spend cuts may reduce revenue if creative/product evidence is ambiguous."],
      success_threshold: "MER/ROAS improves without losing profitable Shopify net sales.",
      stop_condition: "Stop if spend cuts reduce profitable revenue or mapping remains inconclusive.",
      report_framing: "Connect creative performance to mapped products only when mapping confidence supports it."
    },
    improve_conversion_rate: {
      goal_summary: "Find where traffic leaks into product-page, offer, cart, checkout, or stock friction.",
      inclusion_rules: ["Material traffic", "Weak ATC/CVR", "Checkout leakage", "Stock available", "Product-level funnel gaps"],
      exclusion_rules: ["Calling low-traffic products demand-constrained", "Discounting before exposure/offer evidence exists"],
      priority_weighting: "Traffic-qualified conversion gaps before weak-sample products.",
      tradeoffs: ["Conversion tests can conflict with margin if they require discounts."],
      success_threshold: "ATC/CVR improves by at least 15% without refund/MER deterioration.",
      stop_condition: "Stop if conversion worsens or refund/MER guardrails deteriorate.",
      report_framing: "Separate funnel bottlenecks from inventory and traffic-quality issues."
    },
    scale_proven_winners: {
      goal_summary: "Scale only proven products and creatives that have enough stock and no return-quality blocker.",
      inclusion_rules: ["Winners with stock", "High-confidence scalable creatives", "Restock blockers", "Low-stock winners"],
      exclusion_rules: ["Scaling low-stock products", "Scaling return-risk products", "Weak sample winners"],
      priority_weighting: "Revenue upside with availability and quality guardrails.",
      tradeoffs: ["Some high-ROAS ads should be capped if mapped products cannot fulfill demand."],
      success_threshold: "Net sales rises while stock cover, MER, and refunds remain within guardrails.",
      stop_condition: "Stop scaling when stock cover drops below 7 days or return risk rises.",
      report_framing: "Call out scale blockers explicitly."
    },
    grow_net_sales: {
      goal_summary: "Grow next-week sales by fixing proven availability, scalable creative, and material conversion gaps.",
      inclusion_rules: ["Revenue winners", "Restock blockers", "Scalable ads", "Material funnel upside"],
      exclusion_rules: ["Actions with weak evidence", "Scaling into low stock", "Growth that worsens return risk"],
      priority_weighting: "Net sales upside with inventory and quality guardrails.",
      tradeoffs: ["Mandatory return, checkout, and stock issues remain visible even if not pure growth levers."],
      success_threshold: "Net sales and orders improve without MER or refund-rate deterioration.",
      stop_condition: "Stop if growth worsens MER/refunds or hits stockout constraints.",
      report_framing: "Prioritize concrete sales movers, not vanity metrics."
    },
    balance_growth_efficiency: {
      goal_summary: "Explain the commercial week and prioritize the safest next decision across growth, efficiency, inventory, and risk.",
      inclusion_rules: ["Material sales changes", "Funnel bottlenecks", "Inventory constraints", "Returns", "Paid efficiency", "Creative/product mapping"],
      exclusion_rules: ["Weak sample conclusions", "Unmapped ad/product claims", "Invented margin"],
      priority_weighting: "Commercial materiality, risk, confidence, and next-week actionability.",
      tradeoffs: ["The report may recommend not scaling even when revenue grew if stock, returns, or paid efficiency are weak."],
      success_threshold: "Next week has clearer sales, efficiency, inventory, and quality movement.",
      stop_condition: "Stop actions that worsen MER, refunds, stockouts, or confidence.",
      report_framing: "Straight commercial read of the week."
    }
  };
  return {
    mode,
    goal_text: clean(goalText),
    preset_id: presetId,
    goal_spec: goalSpec,
    ...(profiles[presetId] || profiles.balance_growth_efficiency)
  };
}

function compactRows(rows = [], fields = [], limit = 10) {
  return (rows || []).slice(0, limit).map((row) => {
    const out = {};
    for (const field of fields) out[field] = row?.[field] ?? "";
    return out;
  });
}

function comparisonSummary(scoreboard = {}) {
  const out = {};
  for (const [metric, row] of Object.entries(scoreboard || {})) {
    out[metric] = {
      current: row?.current ?? "",
      previous_week: row?.previous_week ?? "",
      wow_pct: row?.wow_pct ?? "",
      four_week_average: row?.four_week_average ?? "",
      vs_four_week_average_pct: row?.vs_four_week_average_pct ?? ""
    };
  }
  return out;
}

function compactDiagnosisRow(row = {}) {
  const fields = row.evidence_fields || {};
  const explanation = row.classification_explanation || {};
  return {
    entity_type: row.entity_type,
    entity_id: row.entity_id,
    entity_name: row.entity_name,
    classification: row.classification,
    confidence: row.confidence,
    join_confidence: row.join_confidence,
    evidence_fields: fields,
    why_assigned: explanation.summary || explanation.investigation_path || "",
    thresholds_passed: explanation.passed_thresholds || [],
    thresholds_failed: explanation.failed_thresholds || [],
    urgent_thresholds: explanation.urgent_thresholds || [],
    money_next_week: explanation.money || null,
    variant_stock: explanation.variant_stock || null,
    warnings: row.missing_data_warnings || []
  };
}

function productClassificationIndex(diagnosis = {}) {
  const byTitle = new Map();
  for (const row of diagnosis.products || []) {
    byTitle.set(normalizedProductKey(row.entity_name), compactDiagnosisRow(row));
  }
  return byTitle;
}

function buildCreativeProductConclusions(reportData, diagnosis) {
  const productDx = productClassificationIndex(diagnosis);
  const productSpend = new Map();
  for (const ad of reportData?.creative?.ads || []) {
    const products = ad.mapped_products || [];
    if (!products.length || num(ad.mapping_confidence) < 80) continue;
    for (const product of products) {
      const key = normalizedProductKey(product.product_title);
      const current = productSpend.get(key) || { spend: 0, purchase_value: 0, ads: [] };
      current.spend += num(ad.spend);
      current.purchase_value += num(ad.purchase_value);
      current.ads.push(clean(ad.ad_name || ad.ad_id));
      productSpend.set(key, current);
    }
  }
  const conclusions = [];
  for (const product of reportData?.revenue?.products || []) {
    const key = normalizedProductKey(product.product_title);
    const paid = productSpend.get(key) || { spend: 0, purchase_value: 0, ads: [] };
    const dx = productDx.get(key) || null;
    const revenue = num(product.net_sales);
    const paidRatio = revenue > 0 ? paid.spend / revenue : "";
    conclusions.push({
      product_id: clean(product.product_id),
      product_title: clean(product.product_title),
      net_sales: product.net_sales,
      units_sold: product.units_sold,
      paid_spend_mapped: r2(paid.spend),
      mapped_purchase_value: r2(paid.purchase_value),
      paid_spend_to_revenue_ratio: paidRatio === "" ? "" : r4(paidRatio),
      mapped_ads: paid.ads.slice(0, 5),
      classification: dx?.classification || "",
      conclusion:
        paid.spend > 0 && paidRatio !== "" && paidRatio >= 0.2
          ? "Performance appears materially paid-driven based on mapped spend versus product revenue."
          : revenue > 0 && paid.spend <= 0
            ? "Product appears commercially/organically strong relative to mapped paid support."
            : dx?.classification === "Low exposure - cannot diagnose demand constraint yet" || dx?.classification === "Slow-moving / insufficient traffic"
              ? "Product looks weak but lacks enough traffic to diagnose demand."
              : ""
    });
  }
  return conclusions
    .filter((row) => clean(row.conclusion))
    .sort((a, b) => num(b.net_sales) - num(a.net_sales))
    .slice(0, 12);
}

function compactActionForAi(item = {}) {
  const action = item.final_action || item;
  return {
    display_category: action.display_category || item.display_category,
    action_title: action.action_title,
    intervention: action.intervention,
    entity_type: action.entity_type,
    entity_name: action.entity_name,
    evidence: action.evidence,
    expected_metric_impact: action.expected_metric_affected || action.expected_metric,
    success_threshold: action.success_threshold,
    stop_condition: action.stop_condition,
    owner: action.owner,
    confidence: action.confidence || item.confidence_score,
    money_risk: action.money_risk || item.money_risk || null,
    why_visible: action.survived_filter_reason || action.category_reason || item.survived_filter_reason || ""
  };
}

function aiNumber(value, digits = 0) {
  return value === "" || value == null || !Number.isFinite(Number(value)) ? "N/A" : formatNumber(value, digits);
}

function aiPercent(value, digits = 1) {
  return value === "" || value == null || !Number.isFinite(Number(value)) ? "N/A" : `${formatNumber(Number(value) * 100, digits)}%`;
}

function aiMoney(value, currency = "EGP") {
  return value === "" || value == null || !Number.isFinite(Number(value)) ? "N/A" : formatMoney(value, currency);
}

function aiMultiple(value) {
  return value === "" || value == null || !Number.isFinite(Number(value)) ? "N/A" : `${formatNumber(value, 2)}x`;
}

function aiDeltaPct(current, previous) {
  if (current === "" || previous === "" || current == null || previous == null) return "";
  if (!Number.isFinite(Number(current)) || !Number.isFinite(Number(previous)) || Number(previous) === 0) return "";
  return r4((Number(current) - Number(previous)) / Math.abs(Number(previous)));
}

function aiMetricChange(metric = {}) {
  if (metric?.wow_pct !== "" && metric?.wow_pct != null && Number.isFinite(Number(metric.wow_pct))) return Number(metric.wow_pct);
  return aiDeltaPct(metric?.current, metric?.previous_week);
}

function aiChangeLabel(value, up = "up", down = "down", flat = "flat") {
  if (value === "" || value == null || !Number.isFinite(Number(value))) return "unknown";
  if (Number(value) > 0.05) return up;
  if (Number(value) < -0.05) return down;
  return flat;
}

function aiProofCard(title, label, stats = [], meaning = "", anchor = "#evidence", type = "neutral") {
  return {
    title: clean(title),
    label: clean(label),
    stats: (stats || []).map(clean).filter(Boolean).slice(0, 3),
    meaning: truncateAiReportText(meaning, 180),
    anchor: clean(anchor || "#evidence"),
    type: clean(type || "neutral")
  };
}

function buildRevenueDriverInsight(reportData = {}) {
  const scoreboard = reportData.scoreboard || {};
  const weekly = reportData.revenue?.weekly || {};
  const funnel = reportData.funnel?.weekly || {};
  const paid = reportData.paid?.weekly || {};
  const ordersChange = aiMetricChange(scoreboard.orders || {});
  const aovChange = aiMetricChange(scoreboard.aov || {});
  const cvrChange = aiMetricChange(scoreboard.conversion_rate || {});
  const sessionsChange = aiDeltaPct(funnel.sessions, funnel.previous_week_sessions || scoreboard.sessions?.previous_week);
  const merChange = aiMetricChange(scoreboard.mer || {});
  const candidates = [
    { key: "orders_volume", label: "Order volume", change: ordersChange },
    { key: "aov", label: "AOV", change: aovChange },
    { key: "conversion", label: "Conversion", change: cvrChange },
    { key: "traffic", label: "Traffic", change: sessionsChange },
    { key: "paid_efficiency", label: "Paid efficiency", change: merChange }
  ].filter((item) => item.change !== "" && Number.isFinite(Number(item.change)));
  const primary = candidates.sort((a, b) => Math.abs(Number(b.change)) - Math.abs(Number(a.change)))[0] || { key: "unknown", label: "Revenue movement", change: "" };
  const direction = aiChangeLabel(primary.change, "improved", "weakened", "held");
  const revenueChange = aiMetricChange(scoreboard.net_sales || {});
  const label = primary.key === "unknown"
    ? "Revenue driver unclear"
    : `${primary.label} ${direction}`;
  return {
    likely_driver: primary.key,
    label,
    conclusion: primary.key === "unknown"
      ? "Revenue movement cannot be decomposed from the available comparison fields."
      : `Revenue movement is most likely tied to ${primary.label.toLowerCase()} because it moved more than the other available proxy drivers.`,
    proxy_notice: "Driver read is a proxy when full decomposition fields are missing.",
    stats: [
      `Net sales ${aiMoney(scoreboard.net_sales?.current, reportData.week?.currency || "EGP")} (${aiPercent(revenueChange)} WoW)`,
      `Orders ${aiNumber(scoreboard.orders?.current)} (${aiPercent(ordersChange)} WoW)`,
      `AOV ${aiMoney(scoreboard.aov?.current, reportData.week?.currency || "EGP")} (${aiPercent(aovChange)} WoW)`
    ],
    support: { weekly, funnel, paid, candidates }
  };
}

function buildPaidEfficiencyInsight(reportData = {}) {
  const paid = reportData.paid?.weekly || {};
  const mer = reportData.scoreboard?.mer || {};
  const roas = num(paid.roas);
  const frequency = num(paid.frequency);
  const ctr = num(paid.ctr_link);
  const merChange = aiMetricChange(mer);
  let label = "Spend not the main issue";
  let type = "neutral";
  if ((roas > 0 && roas < 1.5) || (merChange !== "" && merChange < -0.1)) {
    label = "Paid efficiency weakened";
    type = "risk";
  } else if (frequency >= 2.5 && ctr > 0 && ctr < 0.008) {
    label = "Possible creative fatigue";
    type = "risk";
  } else if (roas >= 2.5 && (merChange === "" || merChange >= -0.05)) {
    label = "Efficient enough to scale selectively";
    type = "opportunity";
  }
  return {
    label,
    type,
    conclusion: label === "Possible creative fatigue"
      ? "Frequency is high while click response is weak, so traffic quality or creative fatigue should be checked before scaling."
      : label === "Paid efficiency weakened"
        ? "Paid demand is a commercial risk because efficiency weakened relative to sales output."
        : "Paid does not appear to be the only explanation, but scaling still needs product stock and mapping proof.",
    stats: [
      `MER ${aiMultiple(mer.current)} (${aiPercent(merChange)} WoW)`,
      `Meta ROAS ${aiMultiple(paid.roas)}`,
      `Spend ${aiMoney(paid.spend, reportData.week?.currency || "EGP")}`
    ],
    support: { roas: paid.roas, spend: paid.spend, frequency: paid.frequency, ctr_link: paid.ctr_link }
  };
}

function buildInventoryRiskInsights(diagnosis = {}, reportData = {}) {
  const currency = reportData.week?.currency || "EGP";
  return (diagnosis.products || [])
    .filter((row) => /Supply-constrained/.test(clean(row.classification)))
    .map((row) => {
      const fields = row.evidence_fields || {};
      const money = row.classification_explanation?.money || {};
      return {
        product: row.entity_name,
        units_sold: fields.units_sold,
        stock_left: fields.ending_inventory_units,
        stock_cover: fields.days_of_cover_7d,
        next_week_risk: money.amount || "",
        conclusion: money.amount
          ? `${row.entity_name} has proven demand but low cover, so pushing demand may cap next-week revenue.`
          : `${row.entity_name} has proven demand and stock pressure, but next-week EGP risk is not defensible from current data.`,
        stats: [
          `${aiNumber(fields.units_sold)} units sold`,
          `${aiNumber(fields.ending_inventory_units)} left`,
          money.amount ? `${aiMoney(money.amount, money.currency || currency)} at risk` : "EGP risk unquantified"
        ]
      };
    })
    .sort((a, b) => num(b.next_week_risk) - num(a.next_week_risk) || num(a.stock_cover) - num(b.stock_cover))
    .slice(0, 5);
}

function buildProductTruthMatrix(diagnosis = {}) {
  const products = diagnosis.products || [];
  const bucket = (name, pattern) => ({
    name,
    count: products.filter((row) => pattern.test(clean(row.classification))).length,
    examples: products.filter((row) => pattern.test(clean(row.classification))).slice(0, 3).map((row) => row.entity_name)
  });
  return [
    bucket("proven + stocked", /Healthy|monitor/i),
    bucket("proven + constrained", /Supply-constrained/i),
    bucket("traffic but weak conversion", /Demand\/conversion/i),
    bucket("slow / low exposure", /Slow-moving|Low exposure|insufficient traffic|Dead/i),
    bucket("weak sample", /Weak sample|reject/i)
  ];
}

function buildCreativeTruthInsights(reportData = {}, diagnosis = {}) {
  const productDx = productClassificationIndex(diagnosis);
  const ads = reportData.creative?.ads || [];
  return ads
    .filter((ad) => num(ad.spend) > 0 || num(ad.purchase_value) > 0 || clean(ad.scale_state))
    .map((ad) => {
      const products = ad.mapped_products || [];
      const mapped = products[0] || {};
      const dx = productDx.get(normalizedProductKey(mapped.product_title)) || {};
      const lowStock = num(mapped.ending_inventory_units ?? mapped.stock) > 0 && num(mapped.ending_inventory_units ?? mapped.stock) <= 3;
      const scaleState = clean(ad.scale_state);
      let conclusion = "Creative/product link needs review before a scale decision.";
      let type = "neutral";
      if (/do_not_scale_inventory/.test(scaleState) || lowStock || /Supply-constrained/.test(clean(dx.classification))) {
        conclusion = "Strong creative + low stock = do not scale until availability is fixed.";
        type = "risk";
      } else if (num(ad.roas) >= 2.5 && num(ad.mapping_confidence) >= 80) {
        conclusion = "Creative is a selective scaling candidate if mapped product stock and returns stay healthy.";
        type = "opportunity";
      } else if (num(ad.spend) >= 500 && num(ad.roas) > 0 && num(ad.roas) < 1.5) {
        conclusion = "High spend with weak return should be cut or fixed before more budget is added.";
        type = "risk";
      }
      return {
        ad_name: ad.ad_name || ad.ad_id,
        mapped_product: mapped.product_title || "",
        mapping_confidence: ad.mapping_confidence,
        stock: mapped.ending_inventory_units ?? mapped.stock ?? "",
        spend: ad.spend,
        roas: ad.roas,
        type,
        conclusion,
        stats: [
          `ROAS ${aiMultiple(ad.roas)}`,
          `Spend ${aiMoney(ad.spend, reportData.week?.currency || "EGP")}`,
          mapped.product_title ? `Stock ${aiNumber(mapped.ending_inventory_units ?? mapped.stock)}` : "Mapping not verified"
        ]
      };
    })
    .sort((a, b) => (a.type === "risk" ? -1 : 1) - (b.type === "risk" ? -1 : 1) || num(b.spend) - num(a.spend))
    .slice(0, 6);
}

function buildFunnelStatusInsight(reportData = {}, diagnosis = {}) {
  const weekly = reportData.funnel?.weekly || {};
  const funnelDx = diagnosis.funnel || {};
  const atc = num(weekly.atc_rate);
  const checkout = num(weekly.checkout_completion_rate);
  const cvr = reportData.scoreboard?.conversion_rate?.current;
  let label = "Not enough funnel evidence";
  let conclusion = "Funnel data is missing or too thin to call the main bottleneck.";
  let type = "neutral";
  if (atc > 0 && atc < 0.05) {
    label = "Product page / ATC bottleneck";
    conclusion = "Customers are reaching products but not showing enough add-to-cart intent, so product appeal, offer, or traffic match is the likely test area.";
    type = "risk";
  } else if (checkout > 0 && checkout < 0.3) {
    label = "Checkout bottleneck";
    conclusion = "Checkout completion is weak enough to investigate checkout or payment friction before blaming traffic alone.";
    type = "risk";
  } else if (cvr !== "" && Number.isFinite(Number(cvr)) && Number(cvr) >= 0.015) {
    label = "Funnel not the main break";
    conclusion = "Conversion is not showing a major sitewide break, so the priority is demand quality, product selection, or availability.";
    type = "opportunity";
  }
  return {
    label,
    type,
    conclusion: clean(funnelDx.summary || conclusion),
    stats: [
      `Sessions ${aiNumber(weekly.sessions)}`,
      `ATC ${aiPercent(weekly.atc_rate)}`,
      `Checkout completion ${aiPercent(weekly.checkout_completion_rate)}`
    ]
  };
}

function buildGoalSpecificImplications(goalProfile = {}, compiled = {}) {
  const preset = clean(goalProfile.preset_id);
  const base = {
    goal_restatement: goalProfile.goal_summary || "Explain the week and choose the safest next commercial move.",
    what_changes: goalProfile.report_framing || "Priorities should follow commercial materiality and confidence.",
    best_path: "Use the strongest evidence first; avoid weak-sample decisions.",
    deprioritize: goalProfile.exclusion_rules || [],
    tradeoffs: goalProfile.tradeoffs || []
  };
  if (preset === "sell_through_slow_inventory") {
    return {
      ...base,
      best_path: "Separate high-stock products with enough exposure from products nobody saw; discount or bundle only after exposure proves demand weakness.",
      deprioritize: ["Restocking winners unless continuity is mandatory", "Blanket discounting low-exposure products", ...(goalProfile.exclusion_rules || [])]
    };
  }
  if (preset === "protect_margin") {
    return {
      ...base,
      best_path: "Cut inefficient spend, protect MER, investigate refunds, and avoid discount-led fixes unless proxy economics improve.",
      deprioritize: ["Broad scaling", "Discount-first slow mover fixes", "Low-confidence product mapping claims", ...(goalProfile.exclusion_rules || [])]
    };
  }
  if (preset === "grow_net_sales" || preset === "scale_proven_winners") {
    return {
      ...base,
      best_path: "Prioritize stocked winners, scalable creatives, restock blockers, and material conversion lifts with enough traffic.",
      deprioritize: ["Slow movers without exposure proof", "Low-stock scale attempts", "Return-risk products", ...(goalProfile.exclusion_rules || [])]
    };
  }
  return base;
}

function buildAiInsightCompiler(reportData, options = {}) {
  const diagnosis = options.diagnosis || buildDeterministicDiagnosis(reportData);
  const goalProfile = options.goal_profile || aiReportGoalProfile(options.goal_text || "", options.mode || "general");
  const revenueDriver = buildRevenueDriverInsight(reportData);
  const paidEfficiency = buildPaidEfficiencyInsight(reportData);
  const inventoryRisks = buildInventoryRiskInsights(diagnosis, reportData);
  const productTruthMatrix = buildProductTruthMatrix(diagnosis);
  const creativeTruths = buildCreativeTruthInsights(reportData, diagnosis);
  const funnelStatus = buildFunnelStatusInsight(reportData, diagnosis);
  const creativeConclusions = buildCreativeProductConclusions(reportData, diagnosis);
  const slowMoverExposure = (diagnosis.products || [])
    .filter((row) => /Slow-moving|Low exposure|insufficient traffic|Weak sample/.test(clean(row.classification)))
    .slice(0, 8)
    .map(compactDiagnosisRow);
  const scaleBlocker = creativeTruths.find((row) => /do not scale|low stock/i.test(row.conclusion)) || null;
  const proof_cards = [
    aiProofCard("Revenue change driver", revenueDriver.label, revenueDriver.stats, revenueDriver.conclusion, "#leadership", revenueDriver.likely_driver === "unknown" ? "neutral" : "decision"),
    aiProofCard("Paid efficiency signal", paidEfficiency.label, paidEfficiency.stats, paidEfficiency.conclusion, "#evidence", paidEfficiency.type),
    aiProofCard("Inventory risk signal", inventoryRisks.length ? "Low-cover seller risk" : "No major stock cap found", inventoryRisks[0]?.stats || ["No constrained winner above threshold"], inventoryRisks[0]?.conclusion || "No top constrained product has enough evidence for a quantified next-week risk.", "#product-diagnosis", inventoryRisks.length ? "risk" : "neutral"),
    aiProofCard("Product truth matrix", "Demand buckets separated", productTruthMatrix.map((row) => `${row.name}: ${row.count}`).slice(0, 3), "Products are separated into demand, stock, conversion, exposure, and weak-sample truths before actions are chosen.", "#product-diagnosis", "decision"),
    aiProofCard("Creative/product truth", scaleBlocker ? "Scale blocker found" : "Creative scale needs guardrails", scaleBlocker?.stats || creativeTruths[0]?.stats || ["No mapped creative scale proof"], scaleBlocker?.conclusion || creativeTruths[0]?.conclusion || "Creative claims remain guarded by mapping confidence, stock, and return quality.", "#evidence", scaleBlocker ? "risk" : "neutral"),
    aiProofCard("Funnel signal", funnelStatus.label, funnelStatus.stats, funnelStatus.conclusion, "#diagnosis", funnelStatus.type)
  ];
  const central = [
    revenueDriver.conclusion,
    paidEfficiency.conclusion,
    funnelStatus.conclusion,
    inventoryRisks[0]?.conclusion || ""
  ].filter(Boolean);
  return {
    compiler_version: "phase6.insight-compiler.v1",
    central_diagnosis_candidates: central,
    top_positive_drivers: [
      ...creativeTruths.filter((row) => row.type === "opportunity").map((row) => row.conclusion),
      ...creativeConclusions.filter((row) => /organically strong|paid-driven/i.test(row.conclusion)).slice(0, 3).map((row) => `${row.product_title}: ${row.conclusion}`)
    ].slice(0, 6),
    top_negative_drivers: [
      revenueDriver.label,
      paidEfficiency.type === "risk" ? paidEfficiency.conclusion : "",
      funnelStatus.type === "risk" ? funnelStatus.conclusion : "",
      ...inventoryRisks.slice(0, 3).map((row) => row.conclusion)
    ].filter(Boolean).slice(0, 6),
    likely_cause_chains: central.map((item) => ({ claim: item, confidence: /cannot|missing|proxy/i.test(item) ? "low" : "medium" })),
    revenue_driver: revenueDriver,
    paid_efficiency_status: paidEfficiency,
    inventory_risks: inventoryRisks,
    product_truth_matrix: productTruthMatrix,
    creative_product_truths: creativeTruths,
    paid_vs_product_driven: creativeConclusions,
    funnel_bottleneck_status: funnelStatus,
    return_refund_status: {
      label: num(reportData.returns?.refund_rate ?? reportData.revenue?.weekly?.refund_rate) >= 0.05 ? "Refund leakage material" : "Returns not the lead issue",
      stats: [
        `Refund rate ${aiPercent(reportData.returns?.refund_rate ?? reportData.revenue?.weekly?.refund_rate)}`,
        `Returned items ${aiNumber(reportData.returns?.returned_items ?? reportData.revenue?.weekly?.returned_items)}`
      ]
    },
    slow_mover_status: {
      label: slowMoverExposure.length ? "Slow movers need exposure proof" : "No material slow-mover exposure issue found",
      exposure_test_candidates: slowMoverExposure,
      rule: "Do not discount slow movers until enough exposure proves demand weakness."
    },
    goal_specific_implications: buildGoalSpecificImplications(goalProfile),
    contradictions_tradeoffs: [
      inventoryRisks.length ? "Scaling demand into constrained winners may cap revenue or create stockouts." : "",
      slowMoverExposure.length ? "Slow inventory may need exposure tests before discounts; low sales alone is not proof of weak demand." : "",
      creativeTruths.some((row) => row.type === "risk") ? "Creative scale can conflict with stock or mapping confidence." : "",
      goalProfile.tradeoffs?.[0] || ""
    ].filter(Boolean),
    missing_or_unquantified_notes: [
      marginAvailability(reportData).note,
      revenueDriver.proxy_notice
    ],
    proof_cards
  };
}

function firstCleanValue(...values) {
  for (const value of values) {
    const text = clean(value);
    if (text) return text;
  }
  return "";
}

function productImageState(rows = []) {
  const imageUrl = firstCleanValue(...rows.map((row) => row?.featured_image_url || row?.product_image_url || row?.image_url || row?.featured_image || row?.product_image));
  return {
    image_url: imageUrl,
    image_missing_reason: imageUrl ? "" : "No Shopify product image URL is stored in the synced report tabs."
  };
}

function productKeyCandidates(row = {}) {
  return [
    clean(row.product_id),
    normalizedProductKey(row.product_title || row.item_name || row.product_name || row.name),
    normalizedCommerceName(row.product_title || row.item_name || row.product_name || row.name)
  ].filter(Boolean);
}

function productDisplayName(row = {}) {
  return clean(row.product_title || row.item_name || row.product_name || row.name || row.title);
}

function productNameMatchScore(left, right) {
  const a = normalizedCommerceName(left) || normalizedProductKey(left);
  const b = normalizedCommerceName(right) || normalizedProductKey(right);
  if (!a || !b) return 0;
  if (a === b) return 100;
  const shorter = a.length <= b.length ? a : b;
  const longer = a.length > b.length ? a : b;
  if (shorter.length >= 4 && longer.includes(shorter)) return 90;
  const shortTokens = shorter.split(/\s+/).filter((token) => token.length > 1);
  const longTokens = new Set(longer.split(/\s+/).filter(Boolean));
  if (!shortTokens.length) return 0;
  const matched = shortTokens.filter((token) => longTokens.has(token)).length;
  const coverage = matched / shortTokens.length;
  if (shortTokens.length >= 2 && coverage >= 0.75) return 82;
  if (shortTokens.length === 1 && coverage === 1 && shortTokens[0].length >= 5) return 72;
  return 0;
}

function productRowMatchScore(identity = {}, row = {}) {
  const identityId = clean(identity.product_id);
  const rowId = clean(row.product_id);
  if (identityId && rowId) return identityId === rowId ? 100 : 0;
  return productNameMatchScore(identity.title || identity.product_title || identity.item_name, productDisplayName(row));
}

function bestProductRowFor(identity = {}, rows = [], minScore = 72) {
  let best = null;
  let bestScore = 0;
  for (const row of rows || []) {
    const score = productRowMatchScore(identity, row);
    if (score > bestScore) {
      best = row;
      bestScore = score;
    }
  }
  return bestScore >= minScore ? best : {};
}

function productMetric(row, fields = []) {
  for (const field of fields) {
    if (row && row[field] !== "" && row[field] != null && Number.isFinite(Number(row[field]))) return num(row[field]);
  }
  return "";
}

function firstProductMetric(...values) {
  for (const value of values) {
    if (value !== "" && value != null && Number.isFinite(Number(value))) return num(value);
  }
  return "";
}

function productWow(current, previous) {
  if (current === "" || previous === "" || !Number.isFinite(Number(current)) || !Number.isFinite(Number(previous)) || Number(previous) === 0) return "";
  return r4((Number(current) - Number(previous)) / Number(previous));
}

function productHistoricalSignal(product, variants = []) {
  const units = product.sales.units_sold === "" ? 0 : num(product.sales.units_sold);
  const prevUnits = product.sales.previous_units_sold;
  const wow = product.sales.units_wow_pct;
  const stock = product.inventory.ending_inventory_units === "" ? 0 : num(product.inventory.ending_inventory_units);
  const recent30 = Math.max(...variants.map((row) => num(row.current_30d_units)).filter((value) => Number.isFinite(value)), num(product.sales.current_30d_units || 0));
  if (units >= 8 && wow !== "" && wow >= 1 && (prevUnits === "" || prevUnits <= 2)) return { label: "One-week spike", confidence: "medium", note: "Treat as a current-week spike until another week confirms repeatability." };
  if (units >= 8 && stock > 0 && (wow === "" || wow > -0.2)) return { label: "Proven this week", confidence: "medium", note: "Current demand is strong enough to protect stock and traffic quality." };
  if (wow !== "" && wow <= -0.25) return { label: "Declining WoW", confidence: "medium", note: "Sales dropped versus the available previous-period signal." };
  if (!units && stock > 0) return { label: "Active in-stock, not selling", confidence: "medium", note: "Stock exists but this week did not convert into units sold." };
  if (recent30 > units && units > 0) return { label: "Has recent history", confidence: "low", note: "Recent rolling units exist, but the weekly comparison is limited." };
  return { label: "Weak or limited history", confidence: "low", note: "Insufficient history to call this a durable winner." };
}

function productFunnelSignal(row = {}) {
  const views = productMetric(row, ["item_views", "views", "view_item_events"]);
  const addToCarts = productMetric(row, ["add_to_carts", "add_to_cart_events"]);
  const beginCheckouts = productMetric(row, ["begin_checkouts", "begin_checkout_events", "checkout_starts"]);
  const purchases = productMetric(row, ["purchases", "purchase_events"]);
  const atcRate = firstProductMetric(
    productMetric(row, ["view_to_cart_rate", "atc_rate"]),
    views !== "" && addToCarts !== "" ? r4(div(addToCarts, views)) : ""
  );
  const cartToCheckoutRate = firstProductMetric(
    productMetric(row, ["cart_to_checkout_rate", "checkout_start_rate"]),
    addToCarts !== "" && beginCheckouts !== "" ? r4(div(beginCheckouts, addToCarts)) : ""
  );
  const checkoutToPurchaseRate = firstProductMetric(
    productMetric(row, ["checkout_to_purchase_rate", "checkout_completion_rate"]),
    beginCheckouts !== "" && purchases !== "" ? r4(div(purchases, beginCheckouts)) : ""
  );
  const purchaseRate = firstProductMetric(
    productMetric(row, ["view_to_purchase_rate", "purchase_rate"]),
    views !== "" && purchases !== "" ? r4(div(purchases, views)) : ""
  );
  let label = "Funnel signal limited";
  if (views !== "" && views < 30) label = "Low exposure";
  else if (views !== "" && atcRate !== "" && atcRate < 0.03) label = "Weak product interest";
  else if (cartToCheckoutRate !== "" && cartToCheckoutRate < DIAGNOSIS_THRESHOLDS.low_cart_to_checkout_rate) label = "Cart-to-checkout friction";
  else if (checkoutToPurchaseRate !== "" && checkoutToPurchaseRate < DIAGNOSIS_THRESHOLDS.low_checkout_completion_rate) label = "Checkout completion issue";
  else if (views !== "" && purchaseRate !== "" && purchaseRate < 0.01) label = "Conversion issue";
  else if (purchaseRate !== "" && purchaseRate >= 0.02) label = "Converting traffic";
  const evidence = views === ""
    ? "No product-level GA4 row was available."
    : [
        `${aiNumber(views)} views`,
        `${aiNumber(addToCarts)} add-to-carts (${aiPercent(atcRate)} of views)`,
        `${aiNumber(beginCheckouts)} checkout starts (${aiPercent(cartToCheckoutRate)} of carts)`,
        `${aiNumber(purchases)} purchases (${aiPercent(checkoutToPurchaseRate)} of checkout starts; ${aiPercent(purchaseRate)} of views)`
      ].join(", ") + ".";
  return {
    item_views: views,
    add_to_carts: addToCarts,
    begin_checkouts: beginCheckouts,
    purchases,
    view_to_cart_rate: atcRate,
    cart_to_checkout_rate: cartToCheckoutRate,
    checkout_to_purchase_rate: checkoutToPurchaseRate,
    view_to_purchase_rate: purchaseRate,
    view_to_checkout_rate: views !== "" && beginCheckouts !== "" ? r4(div(beginCheckouts, views)) : "",
    view_to_cart_dropoff: views !== "" && addToCarts !== "" ? Math.max(0, num(views) - num(addToCarts)) : "",
    cart_to_checkout_dropoff: addToCarts !== "" && beginCheckouts !== "" ? Math.max(0, num(addToCarts) - num(beginCheckouts)) : "",
    checkout_to_purchase_dropoff: beginCheckouts !== "" && purchases !== "" ? Math.max(0, num(beginCheckouts) - num(purchases)) : "",
    signal_label: label,
    evidence
  };
}

function productVariantRows(product, skuRows = []) {
  const byVariant = new Map();
  for (const row of skuRows || []) {
    if (productRowMatchScore(product.identity, row) < 72) continue;
    const key = clean(row.variant_id || row.sku || row.variant_title) || normalizedProductKey(`${row.product_title || ""} ${row.variant_title || ""}`);
    const existing = byVariant.get(key) || {};
    byVariant.set(key, {
      ...existing,
      ...row,
      product_id: clean(existing.product_id) || clean(row.product_id),
      product_title: clean(existing.product_title) || clean(row.product_title),
      variant_id: clean(existing.variant_id) || clean(row.variant_id),
      variant_title: clean(existing.variant_title) || clean(row.variant_title),
      sku: clean(existing.sku) || clean(row.sku),
      units_sold: firstProductMetric(productMetric(existing, ["units_sold", "net_units_sold"]), productMetric(row, ["units_sold", "net_units_sold"])),
      net_sales: firstProductMetric(productMetric(existing, ["net_sales", "gross_sales"]), productMetric(row, ["net_sales", "gross_sales"])),
      ending_inventory_units: firstProductMetric(productMetric(row, ["ending_inventory_units", "current_stock"]), productMetric(existing, ["ending_inventory_units", "current_stock"])),
      days_of_cover_7d: firstProductMetric(productMetric(row, ["days_of_cover_7d"]), productMetric(existing, ["days_of_cover_7d"])),
      is_oos: clean(row.is_oos) || clean(existing.is_oos)
    });
  }
  return [...byVariant.values()]
    .map((row) => {
      const stock = productMetric(row, ["ending_inventory_units", "current_stock"]);
      const units = productMetric(row, ["units_sold", "net_units_sold"]);
      const cover = productMetric(row, ["days_of_cover_7d"]);
      const available = stock !== "" && stock > 0 && clean(row.is_oos).toUpperCase() !== "TRUE";
      return {
        variant_id: clean(row.variant_id || row.sku),
        variant_title: clean(row.variant_title || row.sku || "Variant"),
        sku: clean(row.sku),
        units_sold: units,
        net_sales: productMetric(row, ["net_sales", "gross_sales"]),
        ending_inventory_units: stock,
        days_of_cover_7d: cover,
        availability_state: available ? "available" : "unavailable",
        availability_label: available ? "Available" : "OOS / blocked",
        flags: [
          units > 0 ? "sold_this_week" : "",
          available && !units ? "stocked_not_selling" : "",
          cover !== "" && cover < DIAGNOSIS_THRESHOLDS.low_days_cover ? "low_cover" : ""
        ].filter(Boolean)
      };
    })
    .sort((a, b) => num(b.units_sold) - num(a.units_sold) || num(a.ending_inventory_units) - num(b.ending_inventory_units))
    .slice(0, 12);
}

function productMappedAds(product, ads = []) {
  return (ads || [])
    .filter((ad) => (ad.mapped_products || []).some((mapped) => productRowMatchScore(product.identity, mapped) >= 72))
    .map((ad) => {
      const confidence = num(ad.mapping_confidence);
      const highConfidence = confidence >= 80 && !/review/i.test(clean(ad.mapping_state));
      return {
        ad_id: clean(ad.ad_id),
        ad_name: clean(ad.ad_name),
        campaign_name: clean(ad.campaign_name),
        adset_name: clean(ad.adset_name),
        status: clean(ad.status),
        effective_status: clean(ad.effective_status),
        spend: productMetric(ad, ["spend"]),
        impressions: productMetric(ad, ["impressions"]),
        link_clicks: productMetric(ad, ["link_clicks"]),
        landing_page_views: productMetric(ad, ["landing_page_views"]),
        purchase_value: productMetric(ad, ["purchase_value", "conversion_value"]),
        roas: productMetric(ad, ["roas"]),
        ctr_link: productMetric(ad, ["ctr_link", "ctr"]),
        frequency: productMetric(ad, ["frequency"]),
        purchases: productMetric(ad, ["purchases"]),
        cost_per_purchase: productMetric(ad, ["cost_per_purchase", "cpa"]),
        creative_id: clean(ad.creative_metadata?.creative_id || ad.creative_id || ad.ad_id),
        creative_name: clean(ad.creative_metadata?.creative_name || ad.creative_name || ad.ad_name),
        thumbnail_url: clean(ad.thumbnail_url || ad.image_url),
        thumbnail_status: clean(ad.thumbnail_status) || (clean(ad.thumbnail_url || ad.image_url) ? "available" : "unavailable"),
        thumbnail_unavailable_reason: clean(ad.thumbnail_unavailable_reason) || "No Meta thumbnail/image URL is stored for this creative.",
        mapping_confidence: confidence,
        mapping_basis: clean(ad.mapping_evidence?.basis || ad.mapping_evidence?.confidence_basis || ad.mapping_method || ""),
        mapping_state: clean(ad.mapping_state),
        mapping_method: clean(ad.mapping_method),
        mapping_quality: highConfidence ? "high_confidence" : "review_only",
        scale_state: clean(ad.scale_state),
        scale_reason: clean(ad.scale_explanation),
        can_drive_product_conclusion: highConfidence
      };
    })
    .sort((a, b) => num(b.spend) - num(a.spend))
    .slice(0, 10);
}

function paidSupportSummary(mappedAds = []) {
  const high = mappedAds.filter((ad) => ad.can_drive_product_conclusion);
  const review = mappedAds.filter((ad) => !ad.can_drive_product_conclusion);
  const spend = r2(high.reduce((sum, ad) => sum + num(ad.spend), 0));
  const hasValueSignal = high.some((ad) => hasNumericValue(ad.purchase_value) || hasNumericValue(ad.roas));
  const value = r2(high.reduce((sum, ad) => {
    if (ad.purchase_value !== "" && ad.purchase_value != null && Number.isFinite(Number(ad.purchase_value))) {
      return sum + num(ad.purchase_value);
    }
    return sum + (hasNumericValue(ad.roas) ? num(ad.spend) * num(ad.roas) : 0);
  }, 0));
  const roas = spend > 0 && hasValueSignal ? r2(value / spend) : "";
  // Was: `!/inactive|paused|archived|deleted/i.test(status)`. Because status was
  // always blank (Landmine #3), the negation always passed and every ad with
  // spend counted as active. The blank is the bug, not the regex: an absent
  // status means UNKNOWN, and unknown must never be reported as running.
  //
  // Ads are now partitioned three ways, and the unknowns are counted out loud so
  // a failed status fetch degrades the number visibly instead of silently
  // inflating it.
  const spending = high.filter((ad) => num(ad.spend) > 0);
  const statusKnown = spending.filter((ad) => adEffectiveStatus(ad) !== "");
  const active = statusKnown.filter((ad) => adIsDeliverable(ad));
  const unknownStatus = spending.length - statusKnown.length;
  const impressions = Math.round(high.reduce((sum, ad) => sum + num(ad.impressions), 0));
  const linkClicks = Math.round(high.reduce((sum, ad) => sum + num(ad.link_clicks), 0));
  const creativeIds = new Set(high.map((ad) => clean(ad.creative_id || ad.ad_id)).filter(Boolean));
  const campaigns = new Set(high.map((ad) => clean(ad.campaign_name)).filter(Boolean));
  const adsets = new Set(high.map((ad) => clean(ad.adset_name)).filter(Boolean));
  return {
    mapped_spend: spend,
    mapped_purchase_value: value,
    mapped_roas: roas,
    high_confidence_ads: high.length,
    review_only_ads: review.length,
    // Blank, not 0, when nothing is known. A "0 active ads" on a week that spent
    // money reads as a finding; it is actually an absence of data.
    active_ads: statusKnown.length ? active.length : "",
    ads_with_unknown_status: unknownStatus,
    active_ads_basis: !spending.length
      ? "no_spending_ads"
      : (statusKnown.length === spending.length
        ? "meta_effective_status"
        : (statusKnown.length ? "partial_status_coverage" : "status_unavailable")),
    creative_count: creativeIds.size,
    campaign_count: campaigns.size,
    adset_count: adsets.size,
    impressions,
    link_clicks: linkClicks,
    ctr_link: impressions > 0 ? r4(linkClicks / impressions) : "",
    label: high.length ? (spend >= 1500 ? "Paid support visible" : "Light paid support") : review.length ? "Ads need mapping review" : "No mapped paid support"
  };
}

function productStatusAndAction(product) {
  const units = product.sales.units_sold === "" ? 0 : num(product.sales.units_sold);
  const revenue = product.sales.net_sales === "" ? 0 : num(product.sales.net_sales);
  const stock = product.inventory.ending_inventory_units === "" ? 0 : num(product.inventory.ending_inventory_units);
  const lowCover = product.inventory.days_of_cover_7d !== "" && product.inventory.days_of_cover_7d < DIAGNOSIS_THRESHOLDS.low_days_cover;
  const paidSpend = num(product.paid_support.mapped_spend);
  const highConfidenceAds = num(product.paid_support.high_confidence_ads);
  const views = product.funnel.item_views;
  const purchaseRate = product.funnel.view_to_purchase_rate;
  const returnRate = product.returns.return_rate_units;
  let status = "Needs review / weak data";
  let action = "Review sales, traffic, stock, and mapping before making a merchandising change.";
  let confidence = "low";
  if (units > 0 && paidSpend >= Math.max(1500, revenue * 0.18) && highConfidenceAds) {
    status = "Paid-driven";
    action = lowCover ? "Protect stock before adding paid spend." : "Keep spend controlled and verify organic demand before scaling.";
    confidence = "medium";
  } else if (units >= 5 && paidSpend < Math.max(1000, revenue * 0.08)) {
    status = "Genuine winner";
    action = lowCover ? "Restock or protect best variants before it caps demand." : "Feature organically and keep stock cover healthy.";
    confidence = "medium";
  } else if (!units && stock > 0 && views !== "" && views >= 40 && purchaseRate !== "" && purchaseRate < 0.01) {
    status = "Demand/conversion issue";
    action = "Improve PDP/offer or test clearer product creative before discounting.";
    confidence = "medium";
  } else if (!units && stock > 0) {
    status = "Active but not selling";
    action = "Give it qualified exposure before calling it a demand failure.";
    confidence = "medium";
  } else if (stock <= 0 || lowCover) {
    status = "Low stock";
    action = "Pause scale pressure and restock or route demand to substitutes.";
    confidence = "medium";
  } else if (units > 0) {
    status = "Selling this week";
    action = "Monitor whether this repeats and keep variant availability clean.";
    confidence = "medium";
  }
  if (returnRate !== "" && returnRate >= DIAGNOSIS_THRESHOLDS.return_rate_risk) {
    action = "Investigate fit/quality/expectation issues before scaling more traffic.";
  }
  return {
    status_label: status,
    primary_action: action,
    confidence,
    card_diagnosis: `${product.identity.title} is ${status.toLowerCase()} because sales, stock, funnel, and paid mapping point to ${status === "Needs review / weak data" ? "an incomplete signal" : status.toLowerCase()}.`
  };
}

function productGuideBenchmarks(products = []) {
  const numeric = (selector, positiveOnly = false) => (products || [])
    .map(selector)
    .filter((value) => value !== "" && value != null && Number.isFinite(Number(value)))
    .map(Number)
    .filter((value) => !positiveOnly || value > 0);
  const viewsMedian = medianNumeric(numeric((row) => row.funnel?.item_views, true));
  const spendMedian = medianNumeric(numeric((row) => row.paid_support?.mapped_spend, true));
  const revenueMedian = medianNumeric(numeric((row) => row.sales?.net_sales, true));
  const atcMedian = medianNumeric(numeric((row) => row.funnel?.view_to_cart_rate));
  const purchaseMedian = medianNumeric(numeric((row) => row.funnel?.view_to_purchase_rate));
  const roasMedian = medianNumeric(numeric((row) => row.paid_support?.mapped_roas, true));
  const coverMedian = medianNumeric(numeric((row) => row.inventory?.days_of_cover_7d, true));
  const returnRateMedian = medianNumeric(numeric((row) => row.returns?.return_rate_units));
  const creativeMedian = medianNumeric(numeric((row) => row.paid_support?.creative_count, true));
  return {
    views_median: viewsMedian,
    spend_median: spendMedian,
    revenue_median: revenueMedian,
    atc_median: atcMedian,
    purchase_median: purchaseMedian,
    roas_median: roasMedian,
    days_of_cover_median: coverMedian,
    return_rate_median: returnRateMedian,
    creative_count_median: creativeMedian,
    high_traffic_floor: Math.max(DIAGNOSIS_THRESHOLDS.minimum_product_views, num(viewsMedian)),
    low_exposure_ceiling: Math.max(30, num(viewsMedian) * 0.5),
    material_spend_floor: Math.max(500, num(spendMedian)),
    material_revenue_floor: Math.max(1000, num(revenueMedian)),
    healthy_atc_floor: Math.max(0.05, num(atcMedian)),
    healthy_purchase_floor: Math.max(DIAGNOSIS_THRESHOLDS.healthy_product_conversion_rate, num(purchaseMedian)),
    healthy_cart_to_checkout_floor: DIAGNOSIS_THRESHOLDS.low_cart_to_checkout_rate,
    healthy_checkout_to_purchase_floor: DIAGNOSIS_THRESHOLDS.low_checkout_completion_rate,
    weak_roas_ceiling: 1.5,
    efficient_roas_floor: 2
  };
}

function productGuideAction(product, benchmarks = {}, currency = "EGP") {
  const title = product.identity?.title || "Unnamed product";
  const views = product.funnel?.item_views;
  const atcRate = product.funnel?.view_to_cart_rate;
  const cartToCheckout = product.funnel?.cart_to_checkout_rate;
  const checkoutToPurchase = product.funnel?.checkout_to_purchase_rate;
  const purchaseRate = product.funnel?.view_to_purchase_rate;
  const addToCarts = product.funnel?.add_to_carts;
  const beginCheckouts = product.funnel?.begin_checkouts;
  const purchases = product.funnel?.purchases;
  const units = num(product.sales?.units_sold);
  const revenue = num(product.sales?.net_sales);
  const stockValue = product.inventory?.ending_inventory_units;
  const stock = num(stockValue);
  const cover = product.inventory?.days_of_cover_7d;
  const sellThrough = product.inventory?.weekly_sell_through_rate;
  const spend = num(product.paid_support?.mapped_spend);
  const roas = product.paid_support?.mapped_roas;
  const activeAds = metricOrBlank(product.paid_support?.active_ads);
  const creativeCount = num(product.paid_support?.creative_count);
  const impressions = num(product.paid_support?.impressions);
  const ctr = product.paid_support?.ctr_link;
  const returnRate = product.returns?.return_rate_units;
  const returnedItems = num(product.returns?.returned_items);
  const observedUnitValue = product.sales?.observed_net_revenue_per_unit;
  const discountRate = product.sales?.discount_rate;
  const variantsAvailable = (product.variants || []).filter((row) => row.availability_state === "available").length;
  const variantsTotal = (product.variants || []).length;

  const highTraffic = views !== "" && num(views) >= benchmarks.high_traffic_floor;
  const lowExposure = views !== "" && num(views) < benchmarks.low_exposure_ceiling;
  const weakAtc = atcRate !== "" && num(atcRate) < benchmarks.healthy_atc_floor;
  const healthyAtc = atcRate !== "" && num(atcRate) >= benchmarks.healthy_atc_floor;
  const weakCartToCheckout = cartToCheckout !== "" && num(cartToCheckout) < benchmarks.healthy_cart_to_checkout_floor;
  const weakCheckoutToPurchase = checkoutToPurchase !== "" && num(checkoutToPurchase) < benchmarks.healthy_checkout_to_purchase_floor;
  const efficientConversion = purchaseRate !== "" && num(purchaseRate) >= benchmarks.healthy_purchase_floor;
  const materialSpend = spend >= benchmarks.material_spend_floor;
  const weakRoas = roas !== "" && spend > 0 && num(roas) < benchmarks.weak_roas_ceiling;
  const efficientRoas = roas !== "" && spend > 0 && num(roas) >= benchmarks.efficient_roas_floor;
  const sufficientCreativeTest = creativeCount >= 2;
  const sufficientlyTested = highTraffic && materialSpend && sufficientCreativeTest;
  const weakCreativeResponse = impressions >= DIAGNOSIS_THRESHOLDS.minimum_ad_impressions_material && ctr !== "" && num(ctr) < 0.007;
  const stockConstrained = product.inventory?.low_stock ||
    (hasNumericValue(stockValue) && stock <= 2) ||
    (hasNumericValue(cover) && num(cover) < DIAGNOSIS_THRESHOLDS.low_days_cover);
  const returnRisk = (returnRate !== "" && num(returnRate) >= DIAGNOSIS_THRESHOLDS.return_rate_risk) || returnedItems >= DIAGNOSIS_THRESHOLDS.minimum_return_units;
  const commerciallyProven = efficientConversion || efficientRoas || units >= DIAGNOSIS_THRESHOLDS.minimum_winner_units;
  const insufficientEvidence = (views === "" || num(views) < DIAGNOSIS_THRESHOLDS.minimum_product_views) &&
    spend < benchmarks.material_spend_floor &&
    creativeCount < 2;
  const paidRisk = spend * Math.max(0, benchmarks.efficient_roas_floor - num(roas)) / benchmarks.efficient_roas_floor;
  const revenueWeight = Math.min(28, revenue / Math.max(1, benchmarks.material_revenue_floor) * 8);
  const spendWeight = Math.min(34, spend / Math.max(1, benchmarks.material_spend_floor) * 8);
  const priceEvidence = [
    hasNumericValue(observedUnitValue) ? `observed net revenue per unit ${aiMoney(observedUnitValue, currency)}` : "",
    hasNumericValue(discountRate) ? `discount rate ${aiPercent(discountRate)}` : ""
  ].filter(Boolean).join(" and ");
  const availabilityEvidence = `${aiNumber(stockValue)} units in stock${hasNumericValue(cover) ? ` with ${aiNumber(cover, 1)} days of cover` : ""}${variantsTotal ? ` and ${variantsAvailable}/${variantsTotal} variants available` : ""}`;

  let actionType = "monitor";
  let actionLabel = "Maintain";
  let priorityScore = 30 + revenueWeight;
  let confidence = "medium";
  let sentence = `${title} sold ${aiNumber(units)} units for ${aiMoney(revenue, currency)} from ${aiNumber(views)} product views at ${aiPercent(purchaseRate)} view-to-purchase conversion, with ${aiMoney(spend, currency)} mapped spend at ${aiMultiple(roas)} ROAS; the available signals do not isolate a material funnel or paid-efficiency failure, so maintain current exposure this week and monitor whether conversion, stock cover, and ROAS hold before making a larger budget or merchandising change.`;

  if (weakRoas && sufficientlyTested && (weakAtc || (purchaseRate !== "" && num(purchaseRate) < benchmarks.healthy_purchase_floor))) {
    actionType = "pause_paid_spend";
    actionLabel = "Pause";
    priorityScore = 125 + spendWeight + Math.min(25, paidRisk / Math.max(1, benchmarks.material_spend_floor) * 8);
    confidence = "high";
    sentence = `${title} received ${aiMoney(spend, currency)} across ${aiNumber(activeAds)} active mapped ads and ${aiNumber(creativeCount)} creatives at ${aiMultiple(roas)} ROAS, while ${aiNumber(views)} product views converted at only ${aiPercent(atcRate)} to cart and ${aiPercent(purchaseRate)} to purchase; traffic, paid testing, and observed product visibility are already sufficient, so pause the mapped ads this week and restore spend only after a material change to the first image, positioning, price or offer presentation produces a stronger add-to-cart and purchase result.`;
  } else if (weakRoas && materialSpend && weakCreativeResponse && lowExposure) {
    actionType = "reduce_spend_refresh_creative";
    actionLabel = "Reduce + creatives";
    priorityScore = 112 + spendWeight;
    confidence = "high";
    sentence = `${title} spent ${aiMoney(spend, currency)} for ${aiNumber(impressions)} mapped impressions at ${aiPercent(ctr)} link CTR and ${aiMultiple(roas)} ROAS but generated only ${aiNumber(views)} product views; the loss is occurring before enough shoppers reach the product page, which points to weak creative interest or traffic quality rather than a proven product-demand failure, so reduce spend this week and replace the current hooks and visuals with at least three materially different creatives before judging the product itself.`;
  } else if (weakRoas && materialSpend && weakAtc) {
    actionType = "reduce_spend_fix_positioning";
    actionLabel = "Reduce + reposition";
    priorityScore = 108 + spendWeight;
    confidence = highTraffic ? "high" : "medium";
    sentence = `${title} absorbed ${aiMoney(spend, currency)} at ${aiMultiple(roas)} ROAS and received ${aiNumber(views)} product views, but only ${aiPercent(atcRate)} of those views became add-to-carts versus the ${aiPercent(benchmarks.healthy_atc_floor)} healthy floor; visibility is not the primary problem and the break is at product desire, so reduce paid allocation and test stronger first imagery, product positioning, value explanation, sizing clarity, and price or offer presentation this week before adding budget.`;
  } else if (weakRoas && materialSpend && healthyAtc && weakCartToCheckout) {
    actionType = "reduce_spend_test_price_offer";
    actionLabel = "Test price / offer";
    priorityScore = 106 + spendWeight;
    confidence = "medium";
    sentence = `${title} spent ${aiMoney(spend, currency)} at ${aiMultiple(roas)} ROAS and converted ${aiPercent(atcRate)} of ${aiNumber(views)} views into ${aiNumber(addToCarts)} carts, but only ${aiPercent(cartToCheckout)} of carts became ${aiNumber(beginCheckouts)} checkout starts${priceEvidence ? `, with ${priceEvidence}` : ""}; customers are showing product intent and then hesitating before checkout, so reduce spend while testing clearer total-price and shipping communication, size availability, urgency, and a controlled price or offer change this week.`;
  } else if (weakRoas && materialSpend && healthyAtc && weakCheckoutToPurchase) {
    actionType = "reduce_spend_fix_checkout";
    actionLabel = "Fix checkout";
    priorityScore = 104 + spendWeight;
    confidence = "medium";
    sentence = `${title} spent ${aiMoney(spend, currency)} at ${aiMultiple(roas)} ROAS, moved ${aiNumber(addToCarts)} carts into ${aiNumber(beginCheckouts)} checkout starts, and then converted only ${aiPercent(checkoutToPurchase)} of those starts into ${aiNumber(purchases)} purchases; product intent exists but customers are being lost at the final purchase stage, so cap spend this week while checking payment failures, shipping cost, delivery promise, checkout trust, and stock availability before changing the product proposition.`;
  } else if (weakRoas && materialSpend) {
    actionType = "reduce_spend_audit_efficiency";
    actionLabel = "Reduce + audit";
    priorityScore = 100 + spendWeight;
    confidence = "medium";
    sentence = `${title} used ${aiMoney(spend, currency)} across ${aiNumber(activeAds)} active mapped ads and ${aiNumber(creativeCount)} creatives at only ${aiMultiple(roas)} ROAS, while its measured product funnel shows ${aiNumber(views)} views, ${aiPercent(atcRate)} view-to-cart conversion, and ${aiPercent(purchaseRate)} view-to-purchase conversion; no single later-stage break is strong enough to justify an unsupported price or checkout claim, so reduce budget by 20% to 30% this week, verify ad-to-product mapping and purchase value, and retain spend only on creatives that recover above the ${aiMultiple(benchmarks.weak_roas_ceiling)} weak-return ceiling.`;
  } else if (returnRisk && (revenue >= benchmarks.material_revenue_floor || materialSpend || units >= DIAGNOSIS_THRESHOLDS.minimum_winner_units)) {
    actionType = "investigate_returns";
    actionLabel = "Returns risk";
    priorityScore = 102 + revenueWeight + spendWeight;
    confidence = returnedItems >= DIAGNOSIS_THRESHOLDS.minimum_return_units ? "high" : "medium";
    sentence = `${title} generated ${aiMoney(revenue, currency)} from ${aiNumber(units)} units but recorded ${aiNumber(returnedItems)} returned items at ${aiPercent(returnRate)} unit return rate, alongside ${aiMoney(spend, currency)} mapped spend; demand may be real but scaling it would amplify a fit, quality, or expectation problem, so hold budget growth this week and review return reasons, size accuracy, product description, and imagery against the delivered item before sending more traffic.`;
  } else if (stockConstrained && commerciallyProven) {
    actionType = "protect_stock";
    actionLabel = "Protect stock";
    priorityScore = 96 + revenueWeight + (efficientRoas ? 12 : 0);
    confidence = "high";
    sentence = `${title} sold ${aiNumber(units)} units for ${aiMoney(revenue, currency)} at ${aiPercent(sellThrough)} weekly sell-through${spend > 0 ? ` and ${aiMultiple(roas)} mapped ROAS` : ""}, but has ${availabilityEvidence}; performance is commercially useful but availability is the immediate growth constraint, so protect the remaining variants, stop any broad spend increase, and restock or route demand to an in-stock substitute this week.`;
  } else if (commerciallyProven && lowExposure && !stockConstrained && !returnRisk) {
    actionType = "scale_visibility";
    actionLabel = "Scale visibility";
    priorityScore = 90 + revenueWeight + (efficientRoas ? 10 : 0);
    confidence = efficientConversion && (efficientRoas || units > 0) ? "high" : "medium";
    sentence = `${title} converts ${aiPercent(purchaseRate)} of its ${aiNumber(views)} product views, sold ${aiNumber(units)} units for ${aiMoney(revenue, currency)}${spend > 0 ? `, and returned ${aiMultiple(roas)} ROAS on ${aiMoney(spend, currency)}` : ""}, yet its traffic is below the ${aiNumber(benchmarks.views_median)}-view product median with only ${aiNumber(activeAds)} active mapped ads and ${aiNumber(creativeCount)} creatives; demand appears efficient but underexposed, so give it stronger homepage or collection placement, produce at least two additional creative variations, and raise spend gradually while its current conversion efficiency holds.`;
  } else if (highTraffic && weakAtc) {
    actionType = "fix_product_positioning";
    actionLabel = "Fix PDP / imagery";
    priorityScore = 86 + revenueWeight;
    confidence = "high";
    sentence = `${title} received ${aiNumber(views)} product views, which meets the ${aiNumber(benchmarks.high_traffic_floor)}-view high-traffic floor, but only ${aiNumber(addToCarts)} visitors added it to cart at ${aiPercent(atcRate)} versus the ${aiPercent(benchmarks.healthy_atc_floor)} healthy floor; shoppers are reaching the page but the product, first imagery, positioning, perceived value, sizing clarity, or price and offer presentation is not creating enough desire, so run one focused PDP and creative repositioning test this week before increasing traffic or discounting.`;
  } else if (healthyAtc && weakCartToCheckout && num(addToCarts) > 0) {
    actionType = "test_price_offer";
    actionLabel = "Test price / offer";
    priorityScore = 84 + revenueWeight;
    confidence = "medium";
    sentence = `${title} turns ${aiPercent(atcRate)} of ${aiNumber(views)} views into ${aiNumber(addToCarts)} add-to-carts but only ${aiPercent(cartToCheckout)} of those carts become ${aiNumber(beginCheckouts)} checkout starts${priceEvidence ? `, with ${priceEvidence}` : ""}; customers want the product but hesitate when commitment and total cost become clearer, so test the displayed price or offer, shipping-cost visibility, delivery promise, size availability, and urgency this week while keeping the product imagery constant.`;
  } else if (healthyAtc && weakCheckoutToPurchase && num(beginCheckouts) > 0) {
    actionType = "fix_checkout";
    actionLabel = "Fix checkout";
    priorityScore = 82 + revenueWeight;
    confidence = "medium";
    sentence = `${title} creates ${aiNumber(addToCarts)} carts and ${aiNumber(beginCheckouts)} checkout starts from ${aiNumber(views)} views, but only ${aiPercent(checkoutToPurchase)} of checkout starts complete as ${aiNumber(purchases)} purchases; the product is creating intent and the largest measured loss is at final purchase, so inspect payment success, shipping fees, delivery messaging, trust signals, checkout errors, and live variant availability this week before changing price or creative.`;
  } else if (efficientRoas && creativeCount <= 1 && !stockConstrained && !returnRisk) {
    actionType = "add_creatives_before_scale";
    actionLabel = "Add creatives";
    priorityScore = 76 + spendWeight + revenueWeight;
    confidence = "high";
    sentence = `${title} generated ${aiMultiple(roas)} ROAS from ${aiMoney(spend, currency)} mapped spend and sold ${aiNumber(units)} units, but performance depends on only ${aiNumber(activeAds)} active ad and ${aiNumber(creativeCount)} mapped creative; efficiency is promising but concentrated, so produce three new hook, visual, or format variations this week and validate that at least two can hold ROAS before increasing budget aggressively.`;
  } else if (insufficientEvidence) {
    actionType = "test_before_judging";
    actionLabel = "Gather evidence";
    priorityScore = 46 + (stock > 0 ? 8 : 0);
    confidence = "low";
    sentence = `${title} has ${availabilityEvidence}, ${aiNumber(views)} measured product views, ${aiMoney(spend, currency)} mapped spend, ${aiNumber(activeAds)} active mapped ads, and ${aiNumber(units)} units sold; the product has not received enough traffic, paid testing, creative coverage, or observed site exposure to support a scale, price-cut, or pause decision, so give it at least ${aiNumber(DIAGNOSIS_THRESHOLDS.minimum_product_views)} qualified views with two distinct creatives and visible collection placement this week before judging demand.`;
  } else if (!units && stock > 0 && highTraffic) {
    actionType = "fix_product_positioning";
    actionLabel = "Fix PDP / offer";
    priorityScore = 80 + revenueWeight;
    confidence = "medium";
    sentence = `${title} held ${availabilityEvidence} and received ${aiNumber(views)} product views but sold ${aiNumber(units)} units at ${aiPercent(purchaseRate)} view-to-purchase conversion; the product has enough observed visibility to rule out simple underexposure, so revise its imagery, positioning, value proposition, sizing information, and price or offer presentation this week and require a measurable add-to-cart lift before restoring or adding spend.`;
  }

  return {
    product_id: clean(product.identity?.product_id),
    product_title: clean(title),
    action_type: actionType,
    action_label: actionLabel,
    priority_score: r2(priorityScore),
    priority_band: priorityScore >= 105 ? "Immediate" : priorityScore >= 80 ? "This week" : priorityScore >= 60 ? "Build next" : "Monitor",
    confidence,
    sentence,
    business_impact: r2(spend + revenue),
    metrics: {
      views,
      add_to_carts: addToCarts,
      begin_checkouts: beginCheckouts,
      purchases,
      view_to_cart_rate: atcRate,
      cart_to_checkout_rate: cartToCheckout,
      checkout_to_purchase_rate: checkoutToPurchase,
      view_to_purchase_rate: purchaseRate,
      units_sold: product.sales?.units_sold,
      net_sales: product.sales?.net_sales,
      weekly_sell_through_rate: sellThrough,
      mapped_spend: product.paid_support?.mapped_spend,
      mapped_roas: roas,
      active_ads: activeAds,
      creative_count: creativeCount
    }
  };
}

function buildProductIntelligenceGuide(products = [], reportData = {}) {
  const currency = clean(reportData?.week?.currency || "EGP");
  const benchmarks = productGuideBenchmarks(products);
  const actions = (products || [])
    .map((product) => productGuideAction(product, benchmarks, currency))
    .sort((a, b) =>
      num(b.priority_score) - num(a.priority_score) ||
      num(b.business_impact) - num(a.business_impact) ||
      clean(a.product_title).localeCompare(clean(b.product_title))
    )
    .map((action, index) => ({ ...action, rank: index + 1 }));
  const wasteActions = actions.filter((row) => row.action_type.startsWith("pause_") || row.action_type.startsWith("reduce_"));
  const scaleActions = actions.filter((row) => row.action_type === "scale_visibility");
  const creativeActions = actions.filter((row) => row.action_type === "add_creatives_before_scale" || row.action_type === "reduce_spend_refresh_creative");
  const funnelActions = actions.filter((row) => ["fix_product_positioning", "test_price_offer", "fix_checkout"].includes(row.action_type));
  const wasteSpend = r2(wasteActions.reduce((sum, row) => sum + num(row.metrics?.mapped_spend), 0));
  const rangeAction = wasteActions.length
    ? `${wasteActions.length} product${wasteActions.length === 1 ? "" : "s"} account for ${aiMoney(wasteSpend, currency)} of mapped spend that needs an immediate pause, reduction, or evidence-backed conversion fix; protect that budget first, then redirect only toward products whose conversion, stock, returns, and creative coverage support controlled scale.`
    : scaleActions.length
      ? `${scaleActions.length} efficiently converting product${scaleActions.length === 1 ? "" : "s"} are underexposed relative to the ${aiNumber(benchmarks.views_median)}-view product median; the range-wide priority is to improve collection visibility and creative coverage for those products while holding stock and return guardrails.`
      : funnelActions.length
        ? `${funnelActions.length} product${funnelActions.length === 1 ? "" : "s"} show a measured product-page, cart, or checkout-stage loss; the range-wide priority is to fix the highest-traffic funnel breaks before buying more visits.`
        : `The product range has no single measured paid-waste or funnel emergency this week; maintain current exposure, protect constrained stock, and collect enough product views and creative tests before making broad price, pause, or scale decisions.`;
  return {
    title: "Product Intelligence Guide for the Week",
    subtitle: `${actions.length} product actions ranked by business impact and urgency.`,
    range_action: rangeAction,
    actions,
    summary: {
      total_actions: actions.length,
      immediate_actions: actions.filter((row) => row.priority_band === "Immediate").length,
      mapped_spend_needing_attention: wasteSpend,
      scale_visibility: scaleActions.length,
      creative_coverage: creativeActions.length,
      funnel_fixes: funnelActions.length
    },
    benchmarks,
    data_coverage: {
      available: [
        "Shopify sales, units, discounts, returns, inventory, sell-through, and variants",
        "GA4 product views, add-to-carts, checkout starts, purchases, stage rates, and drop-offs",
        "High-confidence mapped Meta spend, ROAS, impressions, CTR, active ads, and creative count"
      ],
      limitations: [
        "Homepage and collection positions are not tracked directly; relative product-view volume is the website-visibility proxy.",
        "List price, offer copy, and image quality are not scored directly; observed net revenue per unit, discount rate, image availability, and measured funnel behavior are used only as evidence-backed test signals.",
        "Low-confidence, mixed, catalogue, and unmapped ads remain review-only and do not drive product actions."
      ]
    }
  };
}

function productWeeklyDemandProjection(product = {}) {
  const candidates = [
    ["selected week units", product.sales?.units_sold],
    ["rolling 7-day units", product.sales?.current_7d_units],
    ["previous week units", product.sales?.previous_units_sold],
    ["rolling 30-day weekly equivalent", hasNumericValue(product.sales?.current_30d_units)
      ? r2(num(product.sales.current_30d_units) * 7 / 30)
      : ""]
  ]
    .filter(([, value]) => hasNumericValue(value) && num(value) >= 0)
    .map(([label, value]) => ({ label, value: num(value) }));
  const unique = [];
  for (const candidate of candidates) {
    if (!unique.some((row) => Math.abs(row.value - candidate.value) < 0.01)) unique.push(candidate);
  }
  const positive = unique.filter((row) => row.value > 0);
  if (!positive.length) {
    return {
      available: false,
      expected_units_low: 0,
      expected_units_high: 0,
      basis: unique.length
        ? "Available weekly demand references are zero; no positive next-week demand range is supportable."
        : "No current, prior-week, rolling 7-day, or rolling 30-day unit reference is available."
    };
  }
  const values = positive.map((row) => row.value);
  const low = values.length >= 2
    ? Math.max(0, Math.floor(Math.min(...values)))
    : Math.max(0, Math.floor(values[0] * 0.8));
  const high = values.length >= 2
    ? Math.max(low, Math.ceil(Math.max(...values)))
    : Math.max(low, Math.ceil(values[0] * 1.2));
  return {
    available: true,
    expected_units_low: low,
    expected_units_high: high,
    basis: values.length >= 2
      ? `Range uses the observed ${positive.map((row) => `${row.label} (${aiNumber(row.value, 1)})`).join(" and ")} without adding an assumed growth rate.`
      : `Range is 80%-120% of the only positive demand reference: ${positive[0].label} (${aiNumber(positive[0].value, 1)}).`
  };
}

function productCatalogRank(products = [], product = {}, selector, higherIsBetter = true) {
  const value = selector(product);
  if (!hasNumericValue(value)) return { rank: "", out_of: 0, percentile: "" };
  const rows = (products || [])
    .map((row) => ({ row, value: selector(row) }))
    .filter((row) => hasNumericValue(row.value))
    .sort((a, b) => higherIsBetter ? num(b.value) - num(a.value) : num(a.value) - num(b.value));
  const index = rows.findIndex((row) => row.row === product);
  if (index < 0) return { rank: "", out_of: rows.length, percentile: "" };
  return {
    rank: index + 1,
    out_of: rows.length,
    percentile: rows.length > 1 ? r2(1 - index / (rows.length - 1)) : 1
  };
}

function productImpactEstimate(id, type, direction, low, high, currency, basis, confidence = "medium") {
  const amountLow = Math.max(0, r2(low));
  const amountHigh = Math.max(amountLow, r2(high));
  if (!amountHigh) return null;
  return {
    estimate_id: id,
    type,
    direction,
    amount_low: amountLow,
    amount_high: amountHigh,
    currency,
    basis: clean(basis),
    confidence
  };
}

function productCommercialAnalysis(product = {}, products = [], benchmarks = {}, currency = "EGP") {
  const demand = productWeeklyDemandProjection(product);
  const stock = product.inventory?.ending_inventory_units;
  const unitValue = product.sales?.observed_net_revenue_per_unit;
  const variants = product.variants || [];
  const sellingVariants = variants.filter((row) => num(row.units_sold) > 0);
  const leadingVariantUnits = sellingVariants.reduce((sum, row) => sum + num(row.units_sold), 0);
  const meaningfulVariants = sellingVariants.length
    ? sellingVariants
        .filter((row) => leadingVariantUnits <= 0 || div(row.units_sold, leadingVariantUnits) >= 0.1)
        .slice(0, 5)
    : variants.slice(0, 5);
  const leadingVariants = meaningfulVariants.map((row) => {
    const variantDemandLow = num(row.units_sold) > 0 ? Math.max(0, Math.floor(num(row.units_sold) * 0.8)) : 0;
    const variantDemandHigh = num(row.units_sold) > 0 ? Math.max(variantDemandLow, Math.ceil(num(row.units_sold) * 1.2)) : 0;
    const variantStock = row.ending_inventory_units;
    return {
      variant_title: clean(row.variant_title || row.sku || "Variant"),
      units_sold: row.units_sold,
      demand_share: leadingVariantUnits > 0 ? r4(div(row.units_sold, leadingVariantUnits)) : "",
      ending_inventory_units: variantStock,
      days_of_cover_7d: row.days_of_cover_7d,
      available: row.availability_state === "available",
      expected_next_week_units_low: variantDemandLow,
      expected_next_week_units_high: variantDemandHigh,
      projected_units_after_high_demand: hasNumericValue(variantStock)
        ? Math.max(0, r2(num(variantStock) - variantDemandHigh))
        : ""
    };
  });
  const meaningfulVariantsAvailable = leadingVariants.length
    ? leadingVariants.every((row) => row.available)
    : variants.length
      ? variants.every((row) => row.availability_state === "available")
      : false;
  const productStockoutLow = hasNumericValue(stock) && demand.available
    ? Math.max(0, demand.expected_units_low - num(stock))
    : 0;
  const productStockoutHigh = hasNumericValue(stock) && demand.available
    ? Math.max(0, demand.expected_units_high - num(stock))
    : 0;
  const variantStockoutLow = leadingVariants.reduce((sum, row) =>
    sum + (hasNumericValue(row.ending_inventory_units)
      ? Math.max(0, row.expected_next_week_units_low - num(row.ending_inventory_units))
      : 0), 0);
  const variantStockoutHigh = leadingVariants.reduce((sum, row) =>
    sum + (hasNumericValue(row.ending_inventory_units)
      ? Math.max(0, row.expected_next_week_units_high - num(row.ending_inventory_units))
      : 0), 0);
  const stockoutLow = Math.max(productStockoutLow, variantStockoutLow);
  const stockoutHigh = Math.max(productStockoutHigh, variantStockoutHigh);
  const coversExpectedNextWeek = hasNumericValue(stock) && demand.available &&
    num(stock) >= demand.expected_units_high && meaningfulVariantsAvailable;
  const views = product.funnel?.item_views;
  const purchaseRate = product.funnel?.view_to_purchase_rate;
  const spend = product.paid_support?.mapped_spend;
  const roas = product.paid_support?.mapped_roas;
  const returnRate = product.returns?.return_rate_units;
  const impactEstimates = [];

  const stockRisk = productImpactEstimate(
    "stockout_revenue_risk",
    "Revenue exposed to a product or leading-variant stockout",
    "risk",
    hasNumericValue(unitValue) ? stockoutLow * num(unitValue) : 0,
    hasNumericValue(unitValue) ? stockoutHigh * num(unitValue) : 0,
    currency,
    `Expected unmet units (${aiNumber(stockoutLow, 1)}-${aiNumber(stockoutHigh, 1)}) multiplied by observed net revenue per unit (${aiMoney(unitValue, currency)}).`,
    leadingVariants.length ? "medium" : "low"
  );
  if (stockRisk) impactEstimates.push(stockRisk);

  if (
    hasNumericValue(spend) &&
    num(spend) > 0 &&
    hasNumericValue(roas) &&
    hasNumericValue(benchmarks.roas_median) &&
    num(benchmarks.roas_median) > num(roas)
  ) {
    const efficiencyGap = num(spend) * (num(benchmarks.roas_median) - num(roas)) / Math.max(num(benchmarks.roas_median), 0.01);
    const paidRisk = productImpactEstimate(
      "paid_efficiency_exposure",
      "Next-week spend-equivalent efficiency gap if current spend and ROAS repeat",
      "risk",
      efficiencyGap * 0.8,
      Math.min(num(spend), efficiencyGap * 1.2),
      currency,
      `Current mapped spend (${aiMoney(spend, currency)}) scaled by the ROAS shortfall versus the catalogue median (${aiMultiple(roas)} vs ${aiMultiple(benchmarks.roas_median)}); range allows 20% weekly variation.`,
      product.paid_support?.high_confidence_ads >= 2 ? "medium" : "low"
    );
    if (paidRisk) impactEstimates.push(paidRisk);
  }

  if (
    hasNumericValue(views) &&
    num(views) >= 30 &&
    hasNumericValue(purchaseRate) &&
    hasNumericValue(benchmarks.purchase_median) &&
    num(purchaseRate) > num(benchmarks.purchase_median) &&
    num(views) < num(benchmarks.views_median) &&
    hasNumericValue(unitValue)
  ) {
    const additionalViews = Math.max(0, num(benchmarks.views_median) - num(views));
    const opportunity = additionalViews * num(purchaseRate) * num(unitValue);
    const underexposure = productImpactEstimate(
      "underexposure_revenue_opportunity",
      "Revenue opportunity if visibility reaches the catalogue median while current conversion holds",
      "upside",
      opportunity * 0.6,
      opportunity,
      currency,
      `${aiNumber(additionalViews)} additional product views to reach the catalogue median, multiplied by current view-to-purchase rate (${aiPercent(purchaseRate)}) and observed net revenue per unit (${aiMoney(unitValue, currency)}).`,
      num(views) >= 100 ? "medium" : "low"
    );
    if (underexposure) impactEstimates.push(underexposure);
  }

  if (
    hasNumericValue(views) &&
    num(views) >= 100 &&
    hasNumericValue(purchaseRate) &&
    hasNumericValue(benchmarks.purchase_median) &&
    num(purchaseRate) < num(benchmarks.purchase_median) &&
    hasNumericValue(unitValue)
  ) {
    const conversionGap = num(views) * (num(benchmarks.purchase_median) - num(purchaseRate)) * num(unitValue);
    const conversionRecovery = productImpactEstimate(
      "conversion_recovery_opportunity",
      "Revenue opportunity from closing part of the view-to-purchase gap",
      "upside",
      conversionGap * 0.5,
      conversionGap,
      currency,
      `Current product views (${aiNumber(views)}) multiplied by the gap between current and catalogue-median view-to-purchase rates (${aiPercent(purchaseRate)} vs ${aiPercent(benchmarks.purchase_median)}) and observed net revenue per unit (${aiMoney(unitValue, currency)}).`,
      "medium"
    );
    if (conversionRecovery) impactEstimates.push(conversionRecovery);
  }

  if (
    demand.available &&
    hasNumericValue(returnRate) &&
    num(returnRate) > 0 &&
    hasNumericValue(unitValue)
  ) {
    const returnExposure = productImpactEstimate(
      "return_revenue_exposure",
      "Next-week revenue exposed to returns if the observed return rate repeats",
      "risk",
      demand.expected_units_low * num(returnRate) * num(unitValue),
      demand.expected_units_high * num(returnRate) * num(unitValue),
      currency,
      `Expected next-week units (${aiNumber(demand.expected_units_low)}-${aiNumber(demand.expected_units_high)}) multiplied by current unit return rate (${aiPercent(returnRate)}) and observed net revenue per unit (${aiMoney(unitValue, currency)}).`,
      num(product.returns?.returned_items) >= DIAGNOSIS_THRESHOLDS.minimum_return_units ? "medium" : "low"
    );
    if (returnExposure) impactEstimates.push(returnExposure);
  }

  impactEstimates.sort((a, b) => num(b.amount_high) - num(a.amount_high));
  return {
    catalogue_position: {
      revenue: productCatalogRank(products, product, (row) => row.sales?.net_sales),
      units: productCatalogRank(products, product, (row) => row.sales?.units_sold),
      product_views: productCatalogRank(products, product, (row) => row.funnel?.item_views),
      view_to_purchase_rate: productCatalogRank(products, product, (row) => row.funnel?.view_to_purchase_rate),
      mapped_spend: productCatalogRank(products, product, (row) => row.paid_support?.mapped_spend),
      mapped_roas: productCatalogRank(products, product, (row) => row.paid_support?.mapped_roas)
    },
    expected_next_week_demand: demand,
    stock_outlook: {
      current_stock: stock,
      days_of_cover: product.inventory?.days_of_cover_7d,
      projected_stock_after_low_demand: hasNumericValue(stock) && demand.available
        ? r2(num(stock) - demand.expected_units_low)
        : "",
      projected_stock_after_high_demand: hasNumericValue(stock) && demand.available
        ? r2(num(stock) - demand.expected_units_high)
        : "",
      covers_expected_next_week_high_case: coversExpectedNextWeek,
      estimated_unmet_units_low: stockoutLow,
      estimated_unmet_units_high: stockoutHigh,
      meaningful_variants_available: meaningfulVariantsAvailable,
      leading_variants: leadingVariants,
      restock_lead_time_days: "",
      restock_lead_time_available: false,
      planned_paid_scaling_available: false
    },
    catalogue_comparisons: {
      views_vs_median: hasNumericValue(views) && hasNumericValue(benchmarks.views_median)
        && num(benchmarks.views_median) > 0
        ? r2(div(views, benchmarks.views_median))
        : "",
      purchase_rate_vs_median: hasNumericValue(purchaseRate) && hasNumericValue(benchmarks.purchase_median)
        && num(benchmarks.purchase_median) > 0
        ? r2(div(purchaseRate, benchmarks.purchase_median))
        : "",
      spend_vs_median: hasNumericValue(spend) && hasNumericValue(benchmarks.spend_median)
        && num(benchmarks.spend_median) > 0
        ? r2(div(spend, benchmarks.spend_median))
        : "",
      roas_vs_median: hasNumericValue(roas) && hasNumericValue(benchmarks.roas_median)
        && num(benchmarks.roas_median) > 0
        ? r2(div(roas, benchmarks.roas_median))
        : ""
    },
    impact_estimates: impactEstimates,
    largest_credible_impact_high: impactEstimates.length ? impactEstimates[0].amount_high : 0,
    missing_decision_inputs: [
      "Restocking lead time is not stored.",
      "Planned paid scaling is not stored.",
      "Homepage and collection placement are not tracked directly."
    ]
  };
}

function buildProductIntelligenceGuideEvidence(products = [], reportData = {}) {
  const currency = clean(reportData?.week?.currency || "EGP");
  const benchmarks = productGuideBenchmarks(products);
  for (const product of products || []) {
    product.commercial_analysis = productCommercialAnalysis(product, products, benchmarks, currency);
  }
  return {
    purpose: "Structured evidence for the AI-written Product Intelligence Guide; these are calculations and comparisons, not predetermined conclusions.",
    products_analyzed: products.length,
    currency,
    catalogue_benchmarks: benchmarks,
    methodology: [
      "Next-week unit ranges use current week, prior week, rolling 7-day, and rolling 30-day weekly-equivalent demand references when available.",
      "Stock risk is present only when product-level or leading-variant stock falls below the derived next-week demand range.",
      "Catalogue ranks and medians provide context; crossing a benchmark does not itself require action.",
      "Money estimates are bounded scenarios calculated from observed values. The AI may select a supplied estimate but may not create a new amount."
    ],
    data_coverage: {
      available: [
        "Shopify sales, units, discounts, returns, inventory, sell-through, and variants",
        "GA4 product views, add-to-carts, checkout starts, purchases, stage rates, and drop-offs",
        "High-confidence mapped Meta spend, ROAS, impressions, CTR, active ads, and creative count"
      ],
      limitations: [
        "Restocking lead time and planned paid scaling are not stored, so the AI must state that boundary before treating post-week inventory as a replenishment constraint.",
        "Homepage and collection positions are not tracked directly; relative product-view volume is only a website-visibility proxy.",
        "Low-confidence, mixed, catalogue, and unmapped ads remain review-only and cannot support product actions or money estimates."
      ]
    }
  };
}

function buildProductIntelligencePack(reportData, options = {}) {
  const diagnosis = options.diagnosis || buildDeterministicDiagnosis(reportData);
  const productDx = productClassificationIndex(diagnosis);
  const productRows = [
    ...(reportData?.revenue?.products || []),
    ...(reportData?.inventory?.products || []),
    ...(reportData?.returns?.products || [])
  ];
  const skuRows = [
    ...(reportData?.revenue?.skus || []),
    ...(reportData?.inventory?.skus || [])
  ];
  const funnelRows = reportData?.funnel?.products || [];
  const ads = reportData?.creative?.ads || [];
  for (const ad of ads) for (const mapped of ad.mapped_products || []) productRows.push(mapped);

  const byKey = new Map();
  function ensureProduct(row = {}) {
    const title = clean(row.product_title || row.item_name || row.product_name || row.name);
    const id = clean(row.product_id);
    if (!title && !id) return null;
    let key = id || normalizedProductKey(title);
    if (!id) {
      for (const [existingKey, existing] of byKey.entries()) {
        if (productRowMatchScore(existing.identity, row) >= 90) {
          key = existingKey;
          break;
        }
      }
    }
    if (!byKey.has(key)) byKey.set(key, { source_rows: [], identity: { product_id: id, title, status: clean(row.status) || "" } });
    const product = byKey.get(key);
    product.source_rows.push(row);
    product.identity.product_id = product.identity.product_id || id;
    product.identity.title = product.identity.title || title;
    product.identity.status = product.identity.status || clean(row.status) || "";
    product.identity.handle = product.identity.handle || clean(row.handle);
    return product;
  }
  productRows.forEach(ensureProduct);
  skuRows.forEach(ensureProduct);

  const products = [];
  for (const product of byKey.values()) {
    const rows = product.source_rows;
    const revenueRow = bestProductRowFor(product.identity, reportData?.revenue?.products || []);
    const inventoryRow = bestProductRowFor(product.identity, reportData?.inventory?.products || []);
    const returnsRow = bestProductRowFor(product.identity, reportData?.returns?.products || []);
    const funnelRow = bestProductRowFor(product.identity, funnelRows);
    const dx = productDx.get(normalizedProductKey(product.identity.title)) || null;
    const image = productImageState([revenueRow, inventoryRow, ...rows]);
    const variants = productVariantRows(product, skuRows);
    const mappedAds = productMappedAds(product, ads);
    const paid = paidSupportSummary(mappedAds);
    const salesUnits = productMetric(revenueRow, ["units_sold", "net_units_sold"]);
    const previousUnits = productMetric(revenueRow, ["previous_units_sold", "units_sold_previous_week", "prior_units_sold"]);
    const salesRevenue = productMetric(revenueRow, ["net_sales", "gross_sales"]);
    const previousRevenue = productMetric(revenueRow, ["previous_net_sales", "net_sales_previous_week", "prior_net_sales"]);
    const sales = {
      units_sold: salesUnits,
      net_sales: salesRevenue,
      gross_sales: productMetric(revenueRow, ["gross_sales"]),
      discounts: productMetric(revenueRow, ["discounts"]),
      discount_rate: productMetric(revenueRow, ["discount_rate"]),
      observed_net_revenue_per_unit: salesUnits !== "" && salesUnits > 0 && salesRevenue !== "" ? r2(salesRevenue / salesUnits) : "",
      orders: productMetric(revenueRow, ["orders"]),
      current_7d_units: productMetric(revenueRow, ["current_7d_units"]),
      current_30d_units: productMetric(revenueRow, ["current_30d_units"]),
      previous_units_sold: previousUnits,
      previous_net_sales: previousRevenue,
      units_wow_pct: firstProductMetric(productMetric(revenueRow, ["units_sold_wow_pct", "units_wow_pct"]), productWow(salesUnits, previousUnits)),
      revenue_wow_pct: firstProductMetric(productMetric(revenueRow, ["net_sales_wow_pct", "revenue_wow_pct"]), productWow(salesRevenue, previousRevenue))
    };
    const stock = firstProductMetric(productMetric(inventoryRow, ["ending_inventory_units", "current_stock"]), productMetric(revenueRow, ["ending_inventory_units", "current_stock"]));
    const inventory = {
      ending_inventory_units: stock,
      days_of_cover_7d: firstProductMetric(productMetric(inventoryRow, ["days_of_cover_7d"]), productMetric(revenueRow, ["days_of_cover_7d"])),
      weekly_sell_through_rate: firstProductMetric(productMetric(inventoryRow, ["weekly_sell_through_rate"]), productMetric(revenueRow, ["weekly_sell_through_rate"])),
      oos_variant_rate: firstProductMetric(productMetric(inventoryRow, ["oos_variant_rate"]), productMetric(revenueRow, ["oos_variant_rate"])),
      active_variant_count: firstProductMetric(productMetric(inventoryRow, ["active_variant_count"]), productMetric(revenueRow, ["active_variant_count"])),
      low_stock: stock !== "" && (stock <= 2 || (firstProductMetric(productMetric(inventoryRow, ["days_of_cover_7d"]), productMetric(revenueRow, ["days_of_cover_7d"])) !== "" && firstProductMetric(productMetric(inventoryRow, ["days_of_cover_7d"]), productMetric(revenueRow, ["days_of_cover_7d"])) < DIAGNOSIS_THRESHOLDS.low_days_cover)),
      stockout_variants: variants.filter((row) => row.availability_state === "unavailable").length
    };
    const funnel = productFunnelSignal(funnelRow);
    const returns = {
      returned_items: productMetric(returnsRow, ["returned_items"]),
      refunds: productMetric(returnsRow, ["refunds"]),
      return_rate_units: productMetric(returnsRow, ["return_rate_units"]),
      refund_rate_revenue: productMetric(returnsRow, ["refund_rate_revenue"]),
      signal_label: productMetric(returnsRow, ["return_rate_units"]) >= DIAGNOSIS_THRESHOLDS.return_rate_risk ? "Return quality watch" : "No material return flag"
    };
    const packed = {
      identity: { ...product.identity, ...image },
      sales,
      historical_signal: null,
      inventory,
      variants,
      funnel,
      returns,
      mapped_ads: mappedAds,
      paid_support: paid,
      diagnosis_bucket: dx?.classification || "",
      deterministic_diagnosis: dx?.classification_explanation?.summary || dx?.evidence || "",
      conclusion_candidates: [
        dx?.classification ? `Diagnosis bucket: ${dx.classification}` : "",
        funnel.signal_label,
        paid.label,
        returns.signal_label,
        inventory.low_stock ? "Low stock/cover may constrain next-week sales." : ""
      ].filter(Boolean)
    };
    packed.historical_signal = productHistoricalSignal(packed, variants);
    const status = productStatusAndAction(packed);
    Object.assign(packed, status);
    packed.detail = {
      why_selling_or_not: packed.card_diagnosis,
      what_is_working: [
        salesUnits > 0 ? `${salesUnits} units sold this week.` : "",
        paid.high_confidence_ads ? `${paid.high_confidence_ads} high-confidence mapped ad(s) support the read.` : "",
        funnel.signal_label === "Converting traffic" ? "Product-level funnel is converting traffic." : ""
      ].filter(Boolean),
      what_is_not_working: [
        !salesUnits && stock > 0 ? "It is active/in-stock but did not sell this week." : "",
        inventory.low_stock ? "Stock cover is low or variants are unavailable." : "",
        funnel.signal_label === "Conversion issue" || funnel.signal_label === "Weak product interest" ? funnel.evidence : "",
        returns.signal_label === "Return quality watch" ? "Returns/refunds are high enough to investigate before scale." : ""
      ].filter(Boolean),
      action_to_take: packed.primary_action,
      evidence: [
        `Units ${salesUnits === "" ? "unknown" : salesUnits}; revenue ${salesRevenue === "" ? "unknown" : salesRevenue}.`,
        `Stock ${stock === "" ? "unknown" : stock}; variants available ${variants.filter((row) => row.availability_state === "available").length}/${variants.length || 0}.`,
        funnel.evidence,
        `${paid.label}: spend ${paid.mapped_spend || 0}, purchase value ${paid.mapped_purchase_value || 0}.`,
        returns.signal_label
      ].filter(Boolean).slice(0, 8),
      what_not_to_do: [
        "Do not call one week of sales a permanent winner.",
        mappedAds.some((ad) => !ad.can_drive_product_conclusion) ? "Do not use review-only ad mappings to make product conclusions." : "",
        inventory.low_stock ? "Do not add paid pressure before stock/variant availability is fixed." : "",
        !salesUnits && stock > 0 ? "Do not discount solely because units were zero without checking exposure first." : ""
      ].filter(Boolean),
      confidence: packed.confidence
    };
    products.push(packed);
  }

  products.sort((a, b) => num(b.sales.units_sold) - num(a.sales.units_sold) || num(b.sales.net_sales) - num(a.sales.net_sales));
  const guideEvidence = buildProductIntelligenceGuideEvidence(products, reportData);
  return {
    title: "Product Intelligence",
    subtitle: "Every active product connected to sales, stock, variants, ads, funnel, returns, and historical performance.",
    default_sort: "most_sold",
    filters: ["Selling this week", "Active but not selling", "Low stock", "Demand/conversion issue", "Paid-driven", "Genuine winner", "Needs review / weak data"],
    products,
    guide_evidence: guideEvidence,
    summary: {
      total_products: products.length,
      sold_products: products.filter((row) => num(row.sales.units_sold) > 0).length,
      active_in_stock_zero_sales: products.filter((row) => !num(row.sales.units_sold) && num(row.inventory.ending_inventory_units) > 0).length,
      paid_driven: products.filter((row) => row.status_label === "Paid-driven").length,
      genuine_winners: products.filter((row) => row.status_label === "Genuine winner").length,
      low_stock: products.filter((row) => row.status_label === "Low stock" || row.inventory.low_stock).length
    },
    mapping_rule_notes: [
      "High-confidence ad-product conclusions require mapping confidence >= 80 with no close competing candidates.",
      "Low-confidence, ambiguous, unmapped, and dynamic catalogue ads are review-only and do not drive product recommendations.",
      "The normalized naming heuristic removes Coddiwomple/common ecommerce words, so CODDIWOMPLE BLACK BOOTCUT JEANS maps to Black Bootcut Jeans when no competing candidate is present."
    ]
  };
}

function adsCreativeBenchmarks(ads = []) {
  const active = ads.filter((ad) => num(ad.spend) > 0);
  return {
    spend_median: r2(medianNumeric(active.map((ad) => ad.spend))),
    roas_median: r2(medianNumeric(active.map((ad) => ad.roas).filter(hasNumericValue))),
    ctr_link_median: r4(medianNumeric(active.map((ad) => ad.ctr_link).filter(hasNumericValue))),
    cpc_link_median: r2(medianNumeric(active.map((ad) => ad.cpc_link || ad.cpc).filter(hasNumericValue))),
    frequency_median: r2(medianNumeric(active.map((ad) => ad.frequency).filter(hasNumericValue))),
    cost_per_purchase_median: r2(medianNumeric(active.map((ad) => ad.cost_per_purchase || ad.cpa).filter(hasNumericValue)))
  };
}

function mappedProductContext(mapped = {}, productIntelligence = {}) {
  const products = productIntelligence.products || [];
  const product = products.find((row) =>
    (clean(mapped.product_id) && clean(row.identity?.product_id) === clean(mapped.product_id)) ||
    normalizedProductKey(row.identity?.title) === normalizedProductKey(mapped.product_title || mapped.title)
  );
  if (!product) {
    return {
      product_id: clean(mapped.product_id),
      product_title: clean(mapped.product_title || mapped.title),
      status_label: "",
      sales: {},
      inventory: {
        ending_inventory_units: mapped.ending_inventory_units,
        weekly_sell_through_rate: mapped.weekly_sell_through_rate
      },
      variants: {},
      funnel: {},
      returns: {},
      evidence_missing: "No Product Intelligence row matched this mapped product."
    };
  }
  const variants = product.variants || [];
  const leading = variants
    .filter((variant) => num(variant.units_sold) > 0)
    .slice(0, 4)
    .map((variant) => ({
      variant_id: clean(variant.variant_id),
      variant_title: clean(variant.variant_title),
      units_sold: variant.units_sold,
      ending_inventory_units: variant.ending_inventory_units,
      availability_state: variant.availability_state
    }));
  return {
    product_id: clean(product.identity?.product_id),
    product_title: clean(product.identity?.title),
    status_label: clean(product.status_label),
    diagnosis: clean(product.card_diagnosis),
    sales: {
      units_sold: product.sales?.units_sold,
      net_sales: product.sales?.net_sales,
      units_wow_pct: product.sales?.units_wow_pct,
      revenue_wow_pct: product.sales?.revenue_wow_pct
    },
    inventory: {
      ending_inventory_units: product.inventory?.ending_inventory_units,
      days_of_cover_7d: product.inventory?.days_of_cover_7d,
      weekly_sell_through_rate: product.inventory?.weekly_sell_through_rate,
      low_stock: product.inventory?.low_stock,
      projected_stock_after_high_demand: product.commercial_analysis?.stock_outlook?.projected_stock_after_high_demand,
      covers_expected_next_week_high_case: product.commercial_analysis?.stock_outlook?.covers_expected_next_week_high_case
    },
    variants: {
      total: variants.length,
      available: variants.filter((variant) => variant.availability_state === "available").length,
      unavailable: variants.filter((variant) => variant.availability_state !== "available").length,
      leading
    },
    funnel: {
      item_views: product.funnel?.item_views,
      add_to_carts: product.funnel?.add_to_carts,
      begin_checkouts: product.funnel?.begin_checkouts,
      purchases: product.funnel?.purchases,
      view_to_cart_rate: product.funnel?.view_to_cart_rate,
      cart_to_checkout_rate: product.funnel?.cart_to_checkout_rate,
      checkout_to_purchase_rate: product.funnel?.checkout_to_purchase_rate,
      view_to_purchase_rate: product.funnel?.view_to_purchase_rate,
      signal_label: product.funnel?.signal_label
    },
    returns: {
      returned_items: product.returns?.returned_items,
      return_rate_units: product.returns?.return_rate_units,
      refunds: product.returns?.refunds,
      signal_label: product.returns?.signal_label
    },
    creative_coverage: {
      mapped_ads: product.paid_support?.high_confidence_ads,
      active_ads: product.paid_support?.active_ads,
      creative_count: product.paid_support?.creative_count,
      mapped_spend: product.paid_support?.mapped_spend,
      mapped_roas: product.paid_support?.mapped_roas
    }
  };
}

function adImpactEstimates(ad = {}, benchmarks = {}, currency = "EGP") {
  const estimates = [];
  const adId = clean(ad.ad_id || ad.creative_id || "unknown");
  const spend = num(ad.spend);
  const value = num(ad.purchase_value);
  const roas = hasNumericValue(ad.roas) ? num(ad.roas) : (spend > 0 ? r2(value / spend) : 0);
  const purchases = num(ad.purchases);
  const frequency = num(ad.frequency);
  const ctr = num(ad.ctr_link);
  const medianRoas = Math.max(1, num(benchmarks.roas_median));
  const medianCtr = num(benchmarks.ctr_link_median);
  const products = ad.product_context || [];
  const stockConstrained = products.some((product) =>
    product.inventory?.low_stock ||
    (hasNumericValue(product.inventory?.ending_inventory_units) && num(product.inventory.ending_inventory_units) <= 3) ||
    product.inventory?.covers_expected_next_week_high_case === false
  );
  const stockHealthy = products.length > 0 && products.every((product) =>
    (!hasNumericValue(product.inventory?.ending_inventory_units) || num(product.inventory.ending_inventory_units) > 10) &&
    product.inventory?.covers_expected_next_week_high_case !== false
  );

  if (spend >= Math.max(500, num(benchmarks.spend_median) * 0.5) && roas < Math.min(1.2, medianRoas * 0.65)) {
    estimates.push({
      estimate_id: `ad:${adId}:weekly_spend_exposure`,
      type: "Weekly spend exposed if current weak return persists",
      direction: "risk",
      amount_low: r2(spend * 0.8),
      amount_high: r2(spend * 1.2),
      currency,
      basis: `Current weekly spend (${r2(spend)} ${currency}) with ROAS ${r2(roas)}; range allows 20% delivery variation and represents budget exposed, not proven avoidable waste.`,
      confidence: purchases >= 3 ? "medium" : "low"
    });
  }
  if (stockConstrained && value > 0 && roas >= 1.5) {
    estimates.push({
      estimate_id: `ad:${adId}:stock_constrained_revenue`,
      type: "Attributed revenue run-rate exposed by product availability",
      direction: "risk",
      amount_low: r2(value * 0.8),
      amount_high: r2(value * 1.2),
      currency,
      basis: `Current attributed weekly purchase value (${r2(value)} ${currency}) with a mapped product stock constraint; range allows 20% weekly variation and is not a lost-sales forecast.`,
      confidence: products.length === 1 ? "medium" : "low"
    });
  }
  if (stockHealthy && spend >= 250 && purchases >= 3 && roas >= Math.max(2, medianRoas)) {
    const incrementalSpend = spend * 0.2;
    const runRateValue = incrementalSpend * roas;
    estimates.push({
      estimate_id: `ad:${adId}:controlled_scale_test`,
      type: "Attributed revenue run-rate from a controlled 20% budget test",
      direction: "upside",
      amount_low: r2(runRateValue * 0.8),
      amount_high: r2(runRateValue * 1.2),
      currency,
      basis: `A 20% test increase on current spend at observed ROAS ${r2(roas)}, bounded by 20% delivery variation; it is an attributed revenue test range, not guaranteed incremental revenue.`,
      confidence: purchases >= 5 ? "medium" : "low"
    });
  }
  if (spend >= 500 && frequency >= 3 && medianCtr > 0 && ctr < medianCtr * 0.75) {
    estimates.push({
      estimate_id: `ad:${adId}:fatigue_budget_exposure`,
      type: "Budget exposed while likely fatigue is tested",
      direction: "risk",
      amount_low: r2(spend * 0.2),
      amount_high: r2(spend * 0.4),
      currency,
      basis: `20%-40% of current weekly spend while frequency (${r2(frequency)}) is elevated and link CTR (${r4(ctr)}) trails the account median (${r4(medianCtr)}).`,
      confidence: "low"
    });
  }
  return estimates;
}

function compactAdEvidence(ad = {}, productIntelligence = {}, benchmarks = {}, currency = "EGP") {
  const productContext = (ad.mapped_products || [])
    .map((mapped) => mappedProductContext(mapped, productIntelligence))
    .slice(0, 12);
  const row = {
    ad_id: clean(ad.ad_id),
    ad_name: clean(ad.ad_name),
    campaign_id: clean(ad.campaign_id),
    campaign_name: clean(ad.campaign_name),
    adset_id: clean(ad.adset_id),
    adset_name: clean(ad.adset_name),
    delivery_status: clean(ad.status),
    creative_id: clean(ad.creative_metadata?.creative_id || ad.creative_id || `ad_${ad.ad_id}`),
    creative_name: clean(ad.creative_metadata?.creative_name || ad.creative_name || ad.ad_name),
    ad_format: clean(ad.ad_format || adCreativeFormat(ad)),
    performance: {
      spend: ad.spend,
      purchase_value: ad.purchase_value,
      roas: ad.roas,
      purchases: ad.purchases,
      cost_per_purchase: ad.cost_per_purchase || ad.cpa,
      impressions: ad.impressions,
      reach: ad.reach,
      frequency: ad.frequency,
      cpm: ad.cpm,
      clicks: ad.clicks,
      ctr_all: ad.ctr_all,
      link_clicks: ad.link_clicks,
      ctr_link: ad.ctr_link,
      cpc_link: ad.cpc_link || ad.cpc,
      landing_page_views: ad.landing_page_views,
      lpv_rate_from_link_click: ad.lpv_rate_from_link_click,
      cost_per_lpv: ad.cost_per_lpv
    },
    video_attention: {
      video_plays_3s: ad.video_plays_3s,
      video_thruplays: ad.video_thruplays,
      hook_rate_3s: ad.hook_rate_3s,
      hold_rate_p50: ad.hold_rate_p50,
      completion_rate: ad.completion_rate
    },
    mapping: {
      state: clean(ad.mapping_state),
      method: clean(ad.mapping_method),
      confidence: ad.mapping_confidence,
      multiple_products_allowed: Boolean(ad.multi_product_mapping_allowed),
      mapped_product_count: productContext.length,
      competing_candidates: ad.mapping_evidence?.competing_candidates || []
    },
    product_context: productContext,
    scale_guardrail: {
      state: clean(ad.scale_state),
      explanation: clean(ad.scale_explanation)
    },
    evidence_quality: {
      meaningful_spend: num(ad.spend) >= 500,
      meaningful_purchase_sample: num(ad.purchases) >= 3,
      product_mapping_verified: num(ad.mapping_confidence) >= 80 && productContext.length > 0,
      post_click_data_available: hasNumericValue(ad.landing_page_views),
      video_metrics_available: num(ad.video_plays_3s) > 0
    }
  };
  row.impact_estimates = adImpactEstimates({ ...ad, product_context: productContext }, benchmarks, currency);
  return row;
}

function aggregateCreativeEvidence(ads = [], benchmarks = {}, currency = "EGP") {
  const groups = new Map();
  for (const ad of ads) {
    const key = clean(ad.creative_id || `ad_${ad.ad_id}`);
    const group = groups.get(key) || {
      creative_id: key,
      creative_name: clean(ad.creative_name || ad.ad_name),
      ad_format: clean(ad.ad_format),
      ads: [],
      campaigns: new Set(),
      adsets: new Set(),
      products: new Map()
    };
    group.ads.push(ad);
    if (clean(ad.campaign_name)) group.campaigns.add(clean(ad.campaign_name));
    if (clean(ad.adset_name)) group.adsets.add(clean(ad.adset_name));
    for (const product of ad.product_context || []) {
      group.products.set(mappingProductIdentity(product), product);
    }
    groups.set(key, group);
  }

  return [...groups.values()].map((group) => {
    const sum = (key) => r2(group.ads.reduce((total, ad) => total + num(ad.performance?.[key]), 0));
    const spend = sum("spend");
    const value = sum("purchase_value");
    const impressions = Math.round(sum("impressions"));
    const reach = Math.round(sum("reach"));
    const clicks = Math.round(sum("clicks"));
    const linkClicks = Math.round(sum("link_clicks"));
    const lpvs = Math.round(sum("landing_page_views"));
    const purchases = sum("purchases");
    const video3s = Math.round(group.ads.reduce((total, ad) => total + num(ad.video_attention?.video_plays_3s), 0));
    const video50 = Math.round(group.ads.reduce((total, ad) =>
      total + num((ad.video_attention?.video_plays_3s || 0) * (ad.video_attention?.hold_rate_p50 || 0)), 0));
    const row = {
      creative_id: group.creative_id,
      creative_name: group.creative_name,
      ad_format: group.ad_format,
      ad_ids: group.ads.map((ad) => ad.ad_id),
      ad_names: group.ads.map((ad) => ad.ad_name),
      campaign_names: [...group.campaigns],
      adset_names: [...group.adsets],
      product_context: [...group.products.values()],
      performance: {
        ad_count: group.ads.length,
        spend,
        purchase_value: value,
        roas: spend > 0 ? r4(value / spend) : "",
        purchases,
        cost_per_purchase: purchases > 0 ? r2(spend / purchases) : "",
        impressions,
        summed_reach: reach,
        frequency_proxy: reach > 0 ? r4(impressions / reach) : "",
        clicks,
        ctr_all: impressions > 0 ? r4(clicks / impressions) : "",
        link_clicks: linkClicks,
        ctr_link: impressions > 0 ? r4(linkClicks / impressions) : "",
        cpc_link: linkClicks > 0 ? r2(spend / linkClicks) : "",
        landing_page_views: lpvs,
        lpv_rate_from_link_click: linkClicks > 0 ? r4(lpvs / linkClicks) : "",
        cost_per_lpv: lpvs > 0 ? r2(spend / lpvs) : ""
      },
      video_attention: {
        video_plays_3s: video3s,
        hook_rate_3s: impressions > 0 ? r4(video3s / impressions) : "",
        hold_rate_p50: video3s > 0 ? r4(video50 / video3s) : ""
      },
      consistency_context: {
        campaign_count: group.campaigns.size,
        adset_count: group.adsets.size,
        products_promoted: group.products.size,
        cross_setup_read_available: group.ads.length > 1,
        weekly_trend_available: false
      }
    };
    row.impact_estimates = adImpactEstimates({
      ad_id: `creative:${group.creative_id}`,
      creative_id: group.creative_id,
      ...row.performance,
      frequency: row.performance.frequency_proxy,
      product_context: row.product_context
    }, benchmarks, currency);
    return row;
  }).sort((a, b) => num(b.performance.spend) - num(a.performance.spend));
}

function buildAdsCreativeIntelligencePack(reportData, productIntelligence) {
  const currency = clean(reportData?.week?.currency || "EGP");
  const sourceAds = (reportData?.creative?.ads || [])
    .filter((ad) => clean(ad.ad_id))
    .sort((a, b) => num(b.spend) - num(a.spend));
  const relevantAds = sourceAds.filter((ad) =>
    num(ad.spend) > 0 ||
    num(ad.impressions) > 0 ||
    num(ad.purchases) > 0 ||
    num(ad.purchase_value) > 0
  );
  const selectedAds = (relevantAds.length ? relevantAds : sourceAds).slice(0, AI_AD_OUTPUT_LIMIT);
  const benchmarks = adsCreativeBenchmarks(selectedAds);
  const ads = selectedAds.map((ad) => compactAdEvidence(ad, productIntelligence, benchmarks, currency));
  const creatives = aggregateCreativeEvidence(ads, benchmarks, currency).slice(0, AI_CREATIVE_OUTPUT_LIMIT);
  const impactEstimates = [
    ...ads.flatMap((ad) => ad.impact_estimates || []),
    ...creatives.flatMap((creative) => creative.impact_estimates || [])
  ];
  const unresolvedAds = ads.filter((ad) =>
    !ad.mapping.product_mapping_verified ||
    ["unmapped", "needs_manual_review", "dynamic_catalogue_or_mixed_products"].includes(clean(ad.mapping.state))
  );
  return {
    title: "Ads & Creative Intelligence",
    subtitle: "Meta ads and creative decisions connected to product demand, funnel quality, stock, variants, returns, and commercial context.",
    summary: {
      source_ads: sourceAds.length,
      relevant_ads: relevantAds.length,
      ads_in_analysis: ads.length,
      creatives_in_analysis: creatives.length,
      mapped_ads: ads.filter((ad) => ad.mapping.product_mapping_verified).length,
      ads_needing_mapping: unresolvedAds.length,
      multi_product_ads: ads.filter((ad) => ad.mapping.mapped_product_count > 1).length,
      spend: r2(ads.reduce((sum, ad) => sum + num(ad.performance.spend), 0)),
      purchase_value: r2(ads.reduce((sum, ad) => sum + num(ad.performance.purchase_value), 0))
    },
    benchmarks,
    ads,
    creatives,
    guide_evidence: {
      purpose: "Structured evidence for one AI-written ranked Ads & Creative Intelligence Guide; these are not predetermined decisions.",
      impact_estimates: impactEstimates,
      mapping_queue: unresolvedAds.map((ad) => ({
        ad_id: ad.ad_id,
        ad_name: ad.ad_name,
        mapping_state: ad.mapping.state,
        spend: ad.performance.spend
      })),
      data_coverage: {
        all_relevant_ads_included: selectedAds.length === relevantAds.length,
        omitted_relevant_ads: Math.max(0, relevantAds.length - selectedAds.length),
        limitations: [
          "Meta ad rows are weekly aggregates; statistical significance, attribution lag, audience overlap, and placement breakdown are unavailable.",
          "Creative trend is unavailable without a comparable prior-week creative identifier series.",
          "Catalogue product-level delivery and attribution are unavailable; do not invent which mapped product received spend or generated revenue.",
          marginAvailability(reportData).note,
          "Low-confidence or unresolved product mappings can support ad-platform observations but cannot support product, stock, or funnel conclusions."
        ]
      }
    }
  };
}

// it. Before this, four separate prompt strings asserted COGS did not exist,
// which would have kept the model reasoning in proxies while real margin sat in
// the pack — and worse, would have made it treat a supplied margin as invented.
//
// Returns the single description every prompt and pack section should use, so
// they cannot drift apart again.
function marginAvailability(reportData) {
  const weekly = reportData?.revenue?.weekly || {};
  const basis = clean(weekly.margin_basis);
  const coverage = metricOrBlank(weekly.cogs_coverage_rate);
  const coveragePct = coverage === "" ? "" : `${r2(coverage * 100)}%`;

  if (basis === "measured") {
    return {
      available: true,
      basis: "measured",
      coverage_rate: coverage,
      note: `True COGS is available with ${coveragePct} cost coverage. gross_margin and gross_margin_rate are measured. State them as margin, not as proxies.`
    };
  }

  if (basis === "estimated") {
    return {
      available: true,
      basis: "estimated",
      coverage_rate: coverage,
      note: `COGS covers ${coveragePct} of sold units. gross_margin_estimated prices the remainder at the units-weighted average cost of covered units and is an ESTIMATE — label it as such every time and never present it as measured. covered_gross_margin is the measured margin on covered units only. The estimate is more likely optimistic than pessimistic: the uncovered SKUs skew toward higher-cost items.`
    };
  }

  return {
    available: false,
    basis: "unavailable",
    coverage_rate: coverage,
    note: "True margin/COGS is unavailable for this week; margin claims must use MER, ROAS, discounts, and refunds as proxies."
  };
}

function buildAiReportPack(reportData, options = {}) {
  const mode = clean(options.mode || "general") === "goal" ? "goal" : "general";
  const goalProfile = options.goal_profile || aiReportGoalProfile(options.goal_text || "", mode);
  const diagnosis = options.diagnosis || buildDeterministicDiagnosis(reportData);
  const scored = options.scored_actions || buildScoredActions(reportData, goalProfile.goal_spec, { diagnosis });
  const compiledInsights = options.compiled_insights || buildAiInsightCompiler(reportData, { mode, goal_text: goalProfile.goal_text, goal_profile: goalProfile, diagnosis });
  const productIntelligence = options.product_intelligence || buildProductIntelligencePack(reportData, { diagnosis });
  const adsCreativeIntelligence = options.ads_creative_intelligence ||
    buildAdsCreativeIntelligencePack(reportData, productIntelligence);
  const creativeConnections = adsCreativeIntelligence.ads.map((ad) => {
    const mappedProducts = (ad.product_context || []).map((product) => ({
      product_id: clean(product.product_id),
      product_title: clean(product.product_title),
      stock: product.inventory?.ending_inventory_units,
      sell_through: product.inventory?.weekly_sell_through_rate,
      return_rate: product.returns?.return_rate_units,
      classification: clean(product.status_label),
      classification_confidence: ""
    }));
    return {
      ad_id: ad.ad_id,
      ad_name: ad.ad_name,
      campaign_name: ad.campaign_name,
      adset_name: ad.adset_name,
      creative_id: ad.creative_id,
      creative_name: ad.creative_name,
      spend: ad.performance.spend,
      purchase_value: ad.performance.purchase_value,
      roas: ad.performance.roas,
      ctr_link: ad.performance.ctr_link,
      cpc: ad.performance.cpc_link,
      cpm: ad.performance.cpm,
      frequency: ad.performance.frequency,
      purchases: ad.performance.purchases,
      cost_per_purchase: ad.performance.cost_per_purchase,
      creative_format: ad.ad_format,
      mapping_state: ad.mapping.state,
      mapping_method: ad.mapping.method,
      mapping_confidence: ad.mapping.confidence,
      competing_candidates: ad.mapping.competing_candidates,
      mapped_products: mappedProducts,
      scale_state: ad.scale_guardrail.state,
      scale_explanation: ad.scale_guardrail.explanation
    };
  });
  return {
    pack_version: AI_REPORT_PACK_VERSION,
    generated_from: "deterministic report-data, diagnosis, creative mapping, and scored-action engines",
    rules: [
      "Use only these structured facts.",
      "Do not invent margin, causes, products, ads, or numbers.",
      "If data is missing, say it is missing.",
      "Causal explanations are hypotheses unless the pack proves them.",
      // Revenue is drop-driven. A model handed week-over-week deltas will call
      // every post-drop week a collapse; these rules point it at the comparison
      // that is actually valid.
      "Revenue is drop-driven. Judge whether a week is good ONLY from surface_signals.drop_comparison. Never from week-over-week or 4-week-average deltas.",
      "If surface_signals.drop_comparison.peer.comparable is false, say the week cannot be judged against prior drops and give the stated reason. Do not substitute a week-over-week verdict.",
      "Explain what MOVED a number only from surface_signals.change_attribution. If its verdict is bought or spend_cut, the change was paid for at unchanged efficiency and is not evidence of a demand shift.",
      "If surface_signals.diagnosis_trust.trusted is false, do not repeat the funnel diagnosis as a finding. State that its threshold does not describe this store and give the numbers."
    ],
    week: reportData?.week || {},
    mode,
    // §7 surface signals. These are the only sanctioned answers to "did it move
    // and why" — the pack carries week-over-week deltas in `scoreboard`, and a
    // model left alone with those will narrate a post-drop week as a collapse.
    surface_signals: reportData?.surface_signals || {},
    goal_interpretation: goalProfile,
    product_intelligence: productIntelligence,
    ads_creative_intelligence: adsCreativeIntelligence,
    compiled_insights: compiledInsights,
    commercial_summary: reportData?.summary || {},
    scoreboard: comparisonSummary(reportData?.scoreboard || {}),
    shopify_sales: {
      weekly: reportData?.revenue?.weekly || {},
      top_products: compactRows(reportData?.revenue?.products || [], ["product_id", "product_title", "net_sales", "gross_sales", "orders", "units_sold", "returned_items", "ending_inventory_units", "weekly_sell_through_rate", "days_of_cover_7d"], 15),
      top_skus_variants: compactRows(reportData?.revenue?.skus || reportData?.inventory?.skus || [], ["product_id", "product_title", "variant_id", "variant_title", "sku", "net_sales", "orders", "units_sold", "returned_items", "ending_inventory_units", "weekly_sell_through_rate", "days_of_cover_7d"], 15)
    },
    product_sku_diagnosis: {
      products: (diagnosis.products || []).slice(0, 25).map(compactDiagnosisRow),
      skus: (diagnosis.skus || []).slice(0, 25).map(compactDiagnosisRow),
      warnings: diagnosis.warnings || []
    },
    inventory: {
      low_stock_winners: (diagnosis.products || []).filter((row) => /Supply-constrained/.test(row.classification)).slice(0, 12).map(compactDiagnosisRow),
      slow_movers: (diagnosis.products || []).filter((row) => /Slow-moving|Dead or near-dead|Low exposure/.test(row.classification)).slice(0, 12).map(compactDiagnosisRow),
      demand_constrained: (diagnosis.products || []).filter((row) => /Demand\/conversion/.test(row.classification)).slice(0, 12).map(compactDiagnosisRow),
      do_not_restock_without_demand: (diagnosis.products || []).filter((row) => /Weak sample|Low exposure|insufficient traffic/.test(row.classification)).slice(0, 12).map(compactDiagnosisRow)
    },
    returns_refunds: {
      summary: reportData?.returns || {},
      products: compactRows(reportData?.returns?.products || [], ["product_id", "product_title", "net_sales", "returned_items", "return_rate_units", "refunds"], 12),
      skus: compactRows(reportData?.returns?.skus || [], ["product_id", "product_title", "variant_id", "variant_title", "sku", "returned_items", "return_rate_units", "refunds"], 12),
      material_hypotheses_only: ["sizing", "fit notes", "product imagery", "quality issue", "fulfillment issue", "expectation mismatch"]
    },
    ga4_funnel: {
      weekly: reportData?.funnel?.weekly || {},
      diagnosis: diagnosis.funnel || {},
      product_funnel: compactRows(reportData?.funnel?.products || [], ["item_name", "item_views", "view_to_cart_rate", "view_to_purchase_rate", "add_to_carts", "purchases"], 20)
    },
    meta_ads: {
      weekly: reportData?.paid?.weekly || {},
      campaigns: compactRows(reportData?.paid?.campaigns || [], ["campaign_name", "spend", "purchase_value", "roas", "ctr_link", "cpc", "cpm", "frequency", "purchases", "cost_per_purchase"], 15),
      ads: creativeConnections
    },
    creative_product_mapping: {
      connections: creativeConnections,
      conclusions: buildCreativeProductConclusions(reportData, diagnosis),
      low_confidence_ads: creativeConnections.filter((ad) => num(ad.mapping_confidence) > 0 && num(ad.mapping_confidence) < 80).slice(0, 10),
      unmapped_or_mixed_ads: creativeConnections.filter((ad) => ["unmapped", "needs_manual_review", "dynamic_catalogue_or_mixed_products"].includes(clean(ad.mapping_state))).slice(0, 10)
    },
    pricing_offer_margin_proxies: {
      true_margin_available: marginAvailability(reportData).available,
      margin_basis: marginAvailability(reportData).basis,
      cogs_coverage_rate: marginAvailability(reportData).coverage_rate,
      gross_margin: reportData?.revenue?.weekly?.gross_margin ?? "",
      gross_margin_rate: reportData?.revenue?.weekly?.gross_margin_rate ?? "",
      gross_margin_estimated: reportData?.revenue?.weekly?.gross_margin_estimated ?? "",
      covered_gross_margin: reportData?.revenue?.weekly?.covered_gross_margin ?? "",
      note: marginAvailability(reportData).note,
      aov: reportData?.scoreboard?.aov || {},
      discounts: {
        discounts: reportData?.revenue?.weekly?.discounts ?? "",
        discount_rate: reportData?.revenue?.weekly?.discount_rate ?? ""
      },
      refunds: {
        refunds: reportData?.revenue?.weekly?.refunds ?? "",
        refund_rate: reportData?.revenue?.weekly?.refund_rate ?? reportData?.returns?.refund_rate ?? ""
      },
      paid_efficiency: {
        mer: reportData?.scoreboard?.mer || {},
        meta_roas: reportData?.paid?.weekly?.roas ?? ""
      }
    },
    deterministic_actions: {
      generated_candidate_count: scored.generated_candidate_count,
      eligible_candidate_count: scored.eligible_candidate_count,
      visible_actions: (scored.all || []).slice(0, 10).map(compactActionForAi),
      rejected_or_excluded: (scored.rejected_candidates || []).slice(0, 15).map((item) => ({
        entity_name: item.entity_name,
        intervention_type: item.intervention_type,
        rejection_reasons: item.rejection_reasons,
        goal_relationship: item.goal_relationship
      })),
      hidden_eligible: (scored.hidden_eligible_candidates || []).slice(0, 10).map(compactActionForAi),
      goal_counts: {
        mandatory_goal_aligned: scored.mandatory_goal_aligned?.length || 0,
        mandatory: scored.mandatory_corrections?.length || 0,
        goal_driven: scored.goal_driven_priorities?.length || 0,
        experiments: scored.experiments_opportunities?.length || 0
      }
    },
    evidence_links: [
      { label: "Product diagnosis", anchor: "#product-diagnosis" },
      { label: "Creative performance", anchor: "#evidence" },
      { label: "Returns", anchor: "#evidence" },
      { label: "Funnel", anchor: "#diagnosis" },
      { label: "Actions", anchor: "#actions" },
      { label: "Inventory", anchor: "#product-diagnosis" }
    ]
  };
}

