function compactAiReportOutput(report) {
  const warnings = [];
  if (!report || typeof report !== "object" || Array.isArray(report)) {
    return { report, warnings };
  }

  const originalWords = wordCount(JSON.stringify(report));
  const input = report.product_intelligence || report;
  const adsInput = report.ads_creative_intelligence || {};
  const originalProducts = Array.isArray(input.products) ? input.products.length : 0;
  const originalAds = Array.isArray(adsInput.ads) ? adsInput.ads.length : 0;
  const originalCreatives = Array.isArray(adsInput.creatives) ? adsInput.creatives.length : 0;
  let compacted = {
    product_intelligence: {
      title: truncateAiReportText(input.title || "Product Intelligence", 80),
      subtitle: truncateAiReportText(input.subtitle || "Every active product connected to sales, stock, variants, ads, funnel, returns, and historical performance.", 180),
      guide: compactAiProductGuide(input.guide || {}),
      products: (Array.isArray(input.products) ? input.products : []).slice(0, 80).map((product) => {
        const detail = product?.detail || {};
        return {
          product_id: truncateAiReportText(product?.product_id || product?.identity?.product_id || "", 80),
          title: truncateAiReportText(product?.title || product?.identity?.title || "Unnamed product", 120),
          status_label: truncateAiReportText(product?.status_label || "Needs review / weak data", 60),
          card_diagnosis: truncateAiReportText(product?.card_diagnosis || product?.diagnosis || "", 170),
          primary_action: truncateAiReportText(product?.primary_action || product?.action || "", 150),
          confidence: truncateAiReportText(product?.confidence || detail.confidence || "low", 40),
          detail: {
            why_selling_or_not: truncateAiReportText(detail.why_selling_or_not || product?.card_diagnosis || "", 240),
            what_is_working: compactAiReportList(detail.what_is_working, 4, 150),
            what_is_not_working: compactAiReportList(detail.what_is_not_working, 4, 150),
            action_to_take: truncateAiReportText(detail.action_to_take || product?.primary_action || "", 180),
            evidence: compactAiReportList(detail.evidence, 6, 140),
            what_not_to_do: compactAiReportList(detail.what_not_to_do, 4, 140),
            confidence: truncateAiReportText(detail.confidence || product?.confidence || "low", 40)
          }
        };
      })
    },
    ads_creative_intelligence: {
      title: truncateAiReportText(adsInput.title || "Ads & Creative Intelligence", 90),
      subtitle: truncateAiReportText(adsInput.subtitle || "Meta ads and creative decisions connected to complete product context.", 190),
      account_read: truncateAiReportText(adsInput.account_read || "No account-level read was supplied.", 320),
      guide: compactAiAdsGuide(adsInput.guide || {}),
      ads: (Array.isArray(adsInput.ads) ? adsInput.ads : [])
        .slice(0, AI_AD_OUTPUT_LIMIT)
        .map(compactAiAdDecision),
      creatives: (Array.isArray(adsInput.creatives) ? adsInput.creatives : [])
        .slice(0, AI_CREATIVE_OUTPUT_LIMIT)
        .map(compactAiCreativeDecision)
    }
  };

  if (originalProducts > compacted.product_intelligence.products.length) warnings.push("AI product intelligence output was compacted to the 80-product cap.");
  if (originalAds > compacted.ads_creative_intelligence.ads.length) warnings.push(`AI ad decisions were compacted to the ${AI_AD_OUTPUT_LIMIT}-ad cap.`);
  if (originalCreatives > compacted.ads_creative_intelligence.creatives.length) warnings.push(`AI creative decisions were compacted to the ${AI_CREATIVE_OUTPUT_LIMIT}-creative cap.`);

  if (originalWords > wordCount(JSON.stringify(compacted))) {
    warnings.push("AI report was compacted for display without failing generation.");
  }
  if (wordCount(JSON.stringify(compacted)) > 7000) {
    warnings.push("AI report exceeded the combined fast-read target and was normalized.");
  }

  return { report: compacted, warnings: [...new Set(warnings)] };
}

function validateAiReportOutput(report, options = {}) {
  const errors = [];
  const warnings = [];
  if (!report || typeof report !== "object" || Array.isArray(report)) return { ok: false, errors: ["AI report output must be an object."], warnings };
  const productIntelligence = report.product_intelligence || null;
  if (!productIntelligence || typeof productIntelligence !== "object" || Array.isArray(productIntelligence)) {
    errors.push("Missing product_intelligence.");
    return { ok: false, errors, warnings };
  }
  if (!clean(productIntelligence.title)) errors.push("Missing product_intelligence.title.");
  if (!clean(productIntelligence.subtitle)) errors.push("Missing product_intelligence.subtitle.");
  const guide = productIntelligence.guide;
  if (!guide || typeof guide !== "object" || Array.isArray(guide)) {
    errors.push("Missing product_intelligence.guide.");
  } else {
    for (const key of ["title", "subtitle", "range_read"]) {
      if (!clean(guide[key])) errors.push(`Missing product_intelligence.guide.${key}.`);
    }
    if (!Array.isArray(guide.steps)) {
      errors.push("Missing product_intelligence.guide.steps.");
    } else {
      if (guide.steps.length > 12) errors.push("Product intelligence guide exceeds 12 ranked steps.");
      for (const [index, step] of guide.steps.entries()) {
        for (const key of ["product_title", "urgency", "headline", "what_is_happening", "judgment", "action", "next_signal", "confidence"]) {
          if (!clean(step?.[key])) errors.push(`Missing product_intelligence.guide.steps[${index}].${key}.`);
        }
        if (!Array.isArray(step?.evidence)) errors.push(`Missing product_intelligence.guide.steps[${index}].evidence.`);
        if (typeof step?.needs_action_this_week !== "boolean") errors.push(`Missing product_intelligence.guide.steps[${index}].needs_action_this_week.`);
        if (!step?.estimated_impact || typeof step.estimated_impact !== "object") {
          errors.push(`Missing product_intelligence.guide.steps[${index}].estimated_impact.`);
        } else if (step.estimated_impact.applicable && (!hasNumericValue(step.estimated_impact.amount_high) || num(step.estimated_impact.amount_high) <= 0)) {
          errors.push(`Invalid product_intelligence.guide.steps[${index}] estimated impact.`);
        }
      }
    }
  }
  if (!Array.isArray(productIntelligence.products)) errors.push("Missing product_intelligence.products.");
  for (const [index, product] of (productIntelligence.products || []).entries()) {
    for (const key of ["title", "status_label", "card_diagnosis", "primary_action", "confidence"]) {
      if (!clean(product?.[key])) errors.push(`Missing product_intelligence.products[${index}].${key}.`);
    }
    const detail = product?.detail || {};
    for (const key of ["why_selling_or_not", "action_to_take", "confidence"]) {
      if (!clean(detail[key])) errors.push(`Missing product_intelligence.products[${index}].detail.${key}.`);
    }
    for (const key of ["what_is_working", "what_is_not_working", "evidence", "what_not_to_do"]) {
      if (!Array.isArray(detail[key])) errors.push(`Missing product_intelligence.products[${index}].detail.${key}.`);
    }
  }
  if ((productIntelligence.products || []).length > 80) errors.push("Product intelligence exceeds 80 products.");

  const adsIntelligence = report.ads_creative_intelligence || null;
  if (!adsIntelligence || typeof adsIntelligence !== "object" || Array.isArray(adsIntelligence)) {
    errors.push("Missing ads_creative_intelligence.");
  } else {
    for (const key of ["title", "subtitle", "account_read"]) {
      if (!clean(adsIntelligence[key])) errors.push(`Missing ads_creative_intelligence.${key}.`);
    }
    const adsGuide = adsIntelligence.guide;
    if (!adsGuide || typeof adsGuide !== "object" || Array.isArray(adsGuide)) {
      errors.push("Missing ads_creative_intelligence.guide.");
    } else {
      for (const key of ["title", "subtitle", "range_read"]) {
        if (!clean(adsGuide[key])) errors.push(`Missing ads_creative_intelligence.guide.${key}.`);
      }
      if (!Array.isArray(adsGuide.steps)) {
        errors.push("Missing ads_creative_intelligence.guide.steps.");
      } else {
        if (adsGuide.steps.length > 12) errors.push("Ads and creative guide exceeds 12 ranked steps.");
        for (const [index, step] of adsGuide.steps.entries()) {
          for (const key of ["headline", "primary_entity_type", "primary_entity_id", "action_label", "urgency", "what_is_happening", "judgment", "cause_owner", "action", "next_signal", "confidence"]) {
            if (!clean(step?.[key])) errors.push(`Missing ads_creative_intelligence.guide.steps[${index}].${key}.`);
          }
          for (const key of ["ad_ids", "creative_ids", "product_ids", "evidence"]) {
            if (!Array.isArray(step?.[key])) errors.push(`Missing ads_creative_intelligence.guide.steps[${index}].${key}.`);
          }
          if (!step?.estimated_impact || typeof step.estimated_impact !== "object") {
            errors.push(`Missing ads_creative_intelligence.guide.steps[${index}].estimated_impact.`);
          } else if (step.estimated_impact.applicable && (!hasNumericValue(step.estimated_impact.amount_high) || num(step.estimated_impact.amount_high) <= 0)) {
            errors.push(`Invalid ads_creative_intelligence.guide.steps[${index}] estimated impact.`);
          }
        }
      }
    }
    if (!Array.isArray(adsIntelligence.ads)) {
      errors.push("Missing ads_creative_intelligence.ads.");
    } else {
      if (adsIntelligence.ads.length > AI_AD_OUTPUT_LIMIT) errors.push(`Ads intelligence exceeds ${AI_AD_OUTPUT_LIMIT} ads.`);
      for (const [index, ad] of adsIntelligence.ads.entries()) {
        for (const key of ["ad_id", "ad_name", "creative_id", "creative_name", "action_label", "cause_owner", "diagnosis", "action", "next_signal", "confidence"]) {
          if (!clean(ad?.[key])) errors.push(`Missing ads_creative_intelligence.ads[${index}].${key}.`);
        }
        for (const key of ["product_titles", "evidence"]) {
          if (!Array.isArray(ad?.[key])) errors.push(`Missing ads_creative_intelligence.ads[${index}].${key}.`);
        }
      }
    }
    if (!Array.isArray(adsIntelligence.creatives)) {
      errors.push("Missing ads_creative_intelligence.creatives.");
    } else {
      if (adsIntelligence.creatives.length > AI_CREATIVE_OUTPUT_LIMIT) errors.push(`Ads intelligence exceeds ${AI_CREATIVE_OUTPUT_LIMIT} creatives.`);
      for (const [index, creative] of adsIntelligence.creatives.entries()) {
        for (const key of ["creative_id", "creative_name", "action_label", "cause_owner", "diagnosis", "action", "next_signal", "confidence"]) {
          if (!clean(creative?.[key])) errors.push(`Missing ads_creative_intelligence.creatives[${index}].${key}.`);
        }
        for (const key of ["ad_ids", "product_titles", "evidence"]) {
          if (!Array.isArray(creative?.[key])) errors.push(`Missing ads_creative_intelligence.creatives[${index}].${key}.`);
        }
      }
    }
  }

  if (wordCount(JSON.stringify(productIntelligence)) > 3200) {
    const message = "AI product intelligence exceeds the fast-read length cap.";
    if (options.strictLength) errors.push(message);
    else warnings.push(message);
  }
  if (adsIntelligence && wordCount(JSON.stringify(adsIntelligence)) > 4000) {
    const message = "AI ads and creative intelligence exceeds the fast-read length cap.";
    if (options.strictLength) errors.push(message);
    else warnings.push(message);
  }
  if (wordCount(JSON.stringify(report)) > 7000) warnings.push("Combined AI report exceeds the fast-read length target.");
  return { ok: !errors.length, errors, warnings };
}

function aiReportSystemPrompt() {
  return [
    "You are a senior ecommerce commercial and Meta performance analyst advising the owner after reviewing the complete selected-week evidence.",
    "Return Product Intelligence and Ads & Creative Intelligence together in the supplied JSON schema. This is one coordinated report and one response, not two isolated analyses.",
    "Do not hallucinate missing data.",
    "Use only the structured report_pack. Do not invent missing data, products, ads, creatives, variants, revenue, attribution, margin, COGS, causes, dates, financial estimates, lead times, website positions, audiences, placements, scaling plans, or catalogue product delivery.",
    "COGS may be present. Read pricing_offer_margin_proxies.margin_basis before making any margin statement: 'measured' means state it as margin; 'estimated' means it is extrapolated over incomplete cost coverage and MUST be labelled an estimate every time it is used; 'unavailable' means fall back to MER, ROAS, discounts and refunds as proxies. Never present an estimated margin as measured, and never call a supplied margin invented.",
    "Explain conflicting signals and state when the evidence is insufficient. Causal explanations are hypotheses unless the pack proves them.",
    "",
    "PRODUCT INTELLIGENCE:",
    "Use product_intelligence as the source of truth. It connects sales, products, SKUs, variants, inventory, sell-through, WoW history, funnel stages, mapped Meta ads and creatives, returns, and pricing or offer proxies.",
    "The commercial_analysis fields and guide_evidence contain server-calculated demand ranges, projected stock, leading-variant availability, catalogue comparisons, ranks, and bounded impact estimates. Treat them as evidence to interpret, not conclusions to repeat mechanically.",
    "Write the guide as a ranked sequence of no more than 12 true business priorities. Do not create a step for every product. Rank by likely impact during the coming week, actionability, evidence quality, wasted spend, missed revenue, stock exposure, and material effect on the business.",
    "Compare products with one another and challenge misleading isolated signals. Crossing a threshold or having strong sell-through does not by itself make a product urgent.",
    "For stock decisions, reason across current stock, derived next-week demand, projected stock after the high-demand case, meaningful variant availability, leading-variant demand, current ad pressure, and whether stock can actually constrain revenue this week.",
    "Restocking lead time and planned paid scaling are unavailable unless explicitly supplied. If stock covers the high-demand next-week case and meaningful variants are available, do not call availability an immediate growth constraint. Maintain current activity or prepare replenishment as appropriate, and name the missing lead-time signal that would change the decision.",
    "Distinguish a noteworthy observation from a situation that needs action this week. It is valid to recommend maintaining current performance and monitoring one exact signal.",
    "Explain conflicting metrics rather than selecting one and ignoring the rest. State when the evidence is too weak for a reliable commercial decision.",
    "Do not force products into scale, fix, pause, or restock categories. Form one coherent course of action based on the complete relationship between metrics.",
    "Avoid reusable sentence templates and repeated phrases. Each step must sound like an experienced analyst formed a product-specific opinion.",
    "Each guide step must state what is happening, the decisive evidence, whether action is truly required this week, one exact action, and the next measurable signal that determines the follow-up decision.",
    "Copy each guide step's product_id and product_title exactly from the product_intelligence product record so the server can ground its selected estimate.",
    "Guide evidence must use the actual supplied figures, but do not metric dump. Include only the numbers that explain the judgment.",
    "For estimated_impact, choose estimate_id from that product's commercial_analysis.impact_estimates, or use 'none'. Never create, adjust, add, or repeat a money amount in prose. The server will insert the selected estimate's calculated range and basis after generation.",
    "Select a money estimate only when it materially supports the ranked decision. Do not force an estimate onto every step.",
    "Never say only improve the funnel, revise the offer, increase visibility, fix conversion, watch inventory, or scale cautiously. Name the measured stage, the likely interpretation, the specific change to make this week, and the success or stop signal.",
    "Name the exact measured funnel stage: product view to add-to-cart, cart to checkout start, or checkout start to purchase.",
    "Treat low-spend, low-view, or single-creative products as insufficiently tested; do not call them bad products or recommend a pause without adequate evidence.",
    "Recommend price, offer, imagery, positioning, or website visibility changes only when the measured stage and proxy evidence support that hypothesis. Label unmeasured causes as tests rather than facts.",
    "Separate paid-driven sellers from genuine product strength only where the mapped spend, conversion, and organic evidence support that distinction.",
    "Do not invent margin. If margin is missing, use only supplied discount, refund, MER, ROAS, AOV, and pricing or offer proxies.",
    "Do not call one week of sales a permanent winner. Do not use low-confidence, ambiguous, unmapped, mixed, or dynamic-catalogue ads for product recommendations.",
    "Keep guide steps skimmable and decisive. Keep product card and detail copy compact.",
    "For every product card, connect sales, stock, variants, funnel, returns, mapped paid support, and evidence quality into one practical read and one primary action.",
    "The Product Intelligence title must be Product Intelligence and its subtitle must be: Every active product connected to sales, stock, variants, ads, funnel, returns, and historical performance.",
    "",
    "ADS & CREATIVE INTELLIGENCE:",
    "Use ads_creative_intelligence as the source of truth for every ad, underlying creative, mapped product, performance metric, stock guardrail, funnel signal, return signal, benchmark, and deterministic money estimate.",
    "Write one ranked Ads & Creative Intelligence Guide with no more than 12 actions ordered by likely financial and operational impact during the coming week.",
    "Also return one compact decision record for every supplied ad and every supplied creative. Copy ad_id, creative_id, ad names, creative names, and mapped product titles exactly. Do not omit low-spend records; label them insufficiently tested when appropriate.",
    "Judge ads with spend, attributed revenue, ROAS, purchases, cost per purchase, impressions, reach, frequency, CPM, clicks, CTR, CPC, landing-page views, post-click quality, video attention, campaign/ad-set context, mapping quality, and complete mapped-product context.",
    "Judge each creative across every ad in which its creative_id appears. Separate the individual ad result from the underlying creative, product, audience, campaign, ad-set, and delivery context.",
    "Compare ads promoting the same product and creatives used across several ads. A strong creative in one weak setup is not automatically weak, and a strong ad may be benefiting from product demand rather than creative quality.",
    "For each decision, set cause_owner to the primary issue: ad, creative, product, audience, delivery, stock, offer, price, post-click experience, catalogue structure, mapping, or insufficient evidence. Choose one primary owner after weighing alternatives.",
    "Use action_label to give a concise decision such as scale, maintain, reduce, pause, replace, replicate, test, monitor, or map. Do not force every record into scale or pause.",
    "High ROAS does not justify scaling when stock, leading variants, returns, or evidence quality cannot support additional demand. Preserve a proven creative and recommend a stock-safe hold, substitute product, or later reactivation when supported.",
    "Good CTR or cheap clicks with weak product funnel conversion means the ad may be attracting attention while the product, offer, PDP, price, or post-click experience fails. Name the exact measured stage and label unmeasured causes as tests.",
    "Weak CTR with strong post-click conversion means product demand may be healthy while the creative fails to attract enough qualified attention. Preserve the product and specify the creative change and measurement condition.",
    "Several weak creatives for the same product plus weak product conversion may indicate a product, offer, pricing, or positioning issue rather than one bad creative. One consistently strong creative across setups should be replicated without assuming the exact hook or message when creative content is unavailable.",
    "Treat strong results from low spend or few purchases as promising but unproven. Treat weak results from minimal delivery as insufficient evidence rather than an automatic pause.",
    "Identify dependency risk when one creative carries substantial product demand, and likely fatigue only when frequency plus attention or conversion evidence supports it.",
    "For catalogue or multi-product ads, assess the ad and catalogue structure without assigning spend, delivery, purchases, or revenue to individual products unless that breakdown is explicitly supplied. State this limitation and never use overall ROAS alone.",
    "Low-confidence, unresolved, or mixed mappings can support ad-platform observations but cannot support product, stock, funnel, or product-attribution conclusions.",
    "The final guide must be AI judgment, not fixed threshold labels or sentence templates. Use the deterministic fields as evidence and guardrails, not final prose.",
    "Never write only scale this ad, pause this creative, improve the creative, watch performance, test new angles, optimize the campaign, or fix the funnel. Name the entity, decisive metrics, meaning, primary problem owner, exact action this week, and measurable next-decision condition.",
    "For ads estimated_impact, choose an estimate_id exactly from ads_creative_intelligence.guide_evidence.impact_estimates or use 'none'. Never create or alter an amount and never repeat an amount in prose; the server hydrates the selected range.",
    "Use money estimates only when they materially clarify spend exposure, revenue run-rate at risk, a controlled scale test, or fatigue exposure. Do not force a financial estimate.",
    "Keep the ranked guide and decision records compact, varied, and skimmable while retaining the decisive figures.",
    "The Ads & Creative Intelligence title must be Ads & Creative Intelligence and its subtitle must be: Meta ads and creative decisions connected to product demand, funnel quality, stock, variants, returns, and commercial context."
  ].join("\n");
}

async function callAiReportProvider(env, reportPack) {
  const model = clean(env.OPENAI_MODEL || DEFAULT_OPENAI_MODEL);
  const response = await fetch("https://api.openai.com/v1/responses", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${clean(env.OPENAI_API_KEY)}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      model,
      input: [
        { role: "system", content: aiReportSystemPrompt() },
        { role: "user", content: JSON.stringify({ report_pack: reportPack }) }
      ],
      text: {
        format: {
          type: "json_schema",
          name: "ai_weekly_decision_report",
          strict: true,
          schema: aiReportJsonSchema()
        }
      }
    })
  });
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(clean(payload?.error?.message || `OpenAI returned HTTP ${response.status}.`));
  }
  const rawText = extractResponseText(payload);
  let report = {};
  try {
    report = JSON.parse(rawText);
  } catch (err) {
    throw new Error(`AI report output was not valid JSON: ${err.message}`);
  }
  const compacted = compactAiReportOutput(report);
  const hydrated = hydrateAiGuideImpactEstimates(compacted.report, reportPack);
  const validation = validateAiReportOutput(hydrated.report);
  if (!validation.ok) {
    throw new Error(`AI report failed validation: ${validation.errors.join(" ")}`);
  }
  return {
    report: hydrated.report,
    raw_output: payload,
    model,
    provider: "openai",
    validation_warnings: [...new Set([
      ...(compacted.warnings || []),
      ...(hydrated.warnings || []),
      ...(validation.warnings || [])
    ])]
  };
}

async function ensureAiReportsTable(env) {
  const db = syncDb(env);
  if (!db) return false;
  await db.prepare(
    `CREATE TABLE IF NOT EXISTS ai_weekly_reports (
      report_id TEXT PRIMARY KEY,
      week_start TEXT NOT NULL,
      mode TEXT NOT NULL,
      goal_hash TEXT NOT NULL,
      goal_text TEXT,
      pack_hash TEXT NOT NULL,
      pack_version TEXT NOT NULL,
      prompt_version TEXT NOT NULL,
      provider TEXT NOT NULL,
      model TEXT NOT NULL,
      status TEXT NOT NULL,
      report_json TEXT NOT NULL,
      metadata_json TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
    )`
  ).run();
  await db.prepare(
    "CREATE INDEX IF NOT EXISTS idx_ai_weekly_reports_lookup ON ai_weekly_reports (week_start, mode, goal_hash, pack_hash, created_at)"
  ).run();
  return true;
}

function normalizeAiReportRow(row) {
  if (!row) return null;
  return {
    report_id: clean(row.report_id),
    week_start: clean(row.week_start),
    mode: clean(row.mode),
    goal_text: clean(row.goal_text),
    pack_hash: clean(row.pack_hash),
    pack_version: clean(row.pack_version),
    prompt_version: clean(row.prompt_version),
    provider: clean(row.provider),
    model: clean(row.model),
    status: clean(row.status),
    report: parseJsonObject(row.report_json, {}),
    metadata: parseJsonObject(row.metadata_json, {}),
    created_at: clean(row.created_at)
  };
}

async function getCachedAiReport(env, weekStart, mode, goalHash) {
  const db = syncDb(env);
  if (!db) return null;
  try {
    await ensureAiReportsTable(env);
    const row = await db.prepare(
      `SELECT * FROM ai_weekly_reports
       WHERE week_start = ? AND mode = ? AND goal_hash = ? AND status = 'generated'
       ORDER BY created_at DESC LIMIT 1`
    ).bind(clean(weekStart), clean(mode), clean(goalHash)).first();
    return normalizeAiReportRow(row);
  } catch (_) {
    return null;
  }
}

async function storeAiReport(env, metadata, report) {
  const db = syncDb(env);
  if (!db) return null;
  try {
    await ensureAiReportsTable(env);
    const reportId = `air_${(await hashString([
      metadata.week_start,
      metadata.mode,
      metadata.goal_hash,
      metadata.report_pack_hash,
      metadata.generated_at
    ].join("|"))).slice(0, 48)}`;
    await db.prepare(
      `INSERT INTO ai_weekly_reports
       (report_id, week_start, mode, goal_hash, goal_text, pack_hash, pack_version, prompt_version,
        provider, model, status, report_json, metadata_json)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      reportId,
      metadata.week_start,
      metadata.mode,
      metadata.goal_hash,
      metadata.goal_text || "",
      metadata.report_pack_hash,
      metadata.report_pack_version,
      metadata.prompt_version,
      metadata.provider,
      metadata.model,
      "generated",
      JSON.stringify(report),
      JSON.stringify({ ...metadata, report_id: reportId })
    ).run();
    return reportId;
  } catch (err) {
    return { error: truncateOperationalError(err) };
  }
}

async function buildAiReportRequestContext(env, body = {}) {
  const mode = clean(body.mode || "general").toLowerCase() === "goal" ? "goal" : "general";
  const goalText = mode === "goal" ? clean(body.goal_text || body.goal || body.custom_goal) : "";
  if (mode === "goal" && !goalText) throw new Error("goal_text is required for a goal-focused AI report.");
  const reportData = await buildReportData(env, clean(body.week_start || body.selected_week || ""));
  const goalProfile = aiReportGoalProfile(goalText, mode);
  const reportPack = buildAiReportPack(reportData, { mode, goal_text: goalText, goal_profile: goalProfile });
  const reportPackHash = await dataHashForObject(reportPack);
  const goalHash = await hashString(`${mode}|${goalText}`);
  return {
    mode,
    goalText,
    goalHash,
    reportData,
    reportPack,
    reportPackHash,
    goalProfile
  };
}

function hasCurrentAiReportGuides(report = {}) {
  const productGuide = report?.product_intelligence?.guide;
  const adsIntelligence = report?.ads_creative_intelligence;
  const adsGuide = adsIntelligence?.guide;
  return Boolean(
    productGuide &&
    clean(productGuide.range_read) &&
    Array.isArray(productGuide.steps) &&
    adsGuide &&
    clean(adsGuide.range_read) &&
    Array.isArray(adsGuide.steps) &&
    Array.isArray(adsIntelligence.ads) &&
    Array.isArray(adsIntelligence.creatives)
  );
}

async function generateAiReport(env, body = {}) {
  const requestedWeek = clean(body.week_start || body.selected_week);
  if (!requestedWeek) {
    throw new Error("week_start is required. AI reports can only be generated for the explicitly selected reporting week.");
  }
  const context = await buildAiReportRequestContext(env, body);
  const now = new Date().toISOString();
  const metadataBase = {
    selected_week: context.reportData.week?.week_start || "",
    week_start: context.reportData.week?.week_start || "",
    mode: context.mode,
    goal_text: context.goalText,
    goal_hash: context.goalHash,
    generated_at: now,
    report_pack_version: AI_REPORT_PACK_VERSION,
    report_pack_hash: context.reportPackHash,
    prompt_version: AI_REPORT_PROMPT_VERSION,
    provider: "openai",
    model: clean(env.OPENAI_MODEL || DEFAULT_OPENAI_MODEL)
  };

  if (!clean(env.OPENAI_API_KEY)) {
      return {
        ok: true,
        status: "blocked",
        unavailable: true,
        error: "AI report generation is not configured. Missing server-side AI provider key.",
        metadata: metadataBase,
        suggested_goals: aiReportSuggestedGoals()
      };
  }

  if (!body.regenerate) {
    const cached = await getCachedAiReport(env, metadataBase.week_start, context.mode, context.goalHash);
    if (cached?.report && hasCurrentAiReportGuides(cached.report)) {
      const evidenceChanged = cached.pack_hash !== context.reportPackHash;
      return {
        ok: true,
        status: "cached",
        report: cached.report,
        metadata: {
          ...cached.metadata,
          cached: true,
          evidence_changed_since_generation: evidenceChanged,
          current_report_pack_hash: context.reportPackHash
        },
        product_intelligence: context.reportPack.product_intelligence,
        ads_creative_intelligence: context.reportPack.ads_creative_intelligence,
        insights: context.reportPack.compiled_insights,
        suggested_goals: aiReportSuggestedGoals()
      };
    }
  }

  const generated = await callAiReportProvider(env, context.reportPack);
  const metadata = {
    ...metadataBase,
    provider: generated.provider,
    model: generated.model,
    cached: false,
    validation_warnings: generated.validation_warnings || []
  };
  const reportId = await storeAiReport(env, metadata, generated.report);
  return {
    ok: true,
    status: "generated",
    report: generated.report,
    product_intelligence: context.reportPack.product_intelligence,
    ads_creative_intelligence: context.reportPack.ads_creative_intelligence,
    insights: context.reportPack.compiled_insights,
    metadata: {
      ...metadata,
      report_id: typeof reportId === "string" ? reportId : "",
      storage_warning: reportId?.error || ""
    },
    suggested_goals: aiReportSuggestedGoals()
  };
}

async function getAiReport(env, body = {}) {
  const context = await buildAiReportRequestContext(env, body);
  const cached = await getCachedAiReport(env, context.reportData.week?.week_start || "", context.mode, context.goalHash);
  if (!cached) {
    return {
      ok: true,
      status: "not_found",
      has_saved_report: false,
      metadata: {
        selected_week: context.reportData.week?.week_start || "",
        mode: context.mode,
        goal_text: context.goalText,
        report_pack_version: AI_REPORT_PACK_VERSION,
        report_pack_hash: context.reportPackHash
      },
      suggested_goals: aiReportSuggestedGoals()
    };
  }
  const evidenceChanged = cached.pack_hash !== context.reportPackHash;
  const guideUpgradeRequired = !hasCurrentAiReportGuides(cached.report);
  return {
    ok: true,
    status: "cached",
    has_saved_report: true,
    report: cached.report,
    metadata: {
      ...cached.metadata,
      cached: true,
      guide_upgrade_required: guideUpgradeRequired,
      evidence_changed_since_generation: evidenceChanged,
      current_report_pack_hash: context.reportPackHash
    },
    product_intelligence: context.reportPack.product_intelligence,
    ads_creative_intelligence: context.reportPack.ads_creative_intelligence,
    insights: context.reportPack.compiled_insights,
    suggested_goals: aiReportSuggestedGoals()
  };
}

function escapeHtml(value) {
  return clean(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function formatNumber(value, digits = 0) {
  if (value === "" || value == null || !Number.isFinite(Number(value))) return "N/A";
  return new Intl.NumberFormat("en-US", {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits
  }).format(Number(value));
}

function formatMoney(value, currency = "EGP") {
  if (value === "" || value == null || !Number.isFinite(Number(value))) return "N/A";
  return `${formatNumber(value, 0)} ${escapeHtml(currency)}`;
}

function formatPercent(value, digits = 2) {
  if (value === "" || value == null || !Number.isFinite(Number(value))) return "N/A";
  return `${formatNumber(Number(value) * 100, digits)}%`;
}

function formatMultiple(value, digits = 2) {
  if (value === "" || value == null || !Number.isFinite(Number(value))) return "N/A";
  return `${formatNumber(value, digits)}x`;
}

function formatReportDate(value, includeTime = false) {
  const date = new Date(includeTime ? value : `${value}T00:00:00Z`);
  if (!value || !Number.isFinite(date.getTime())) return "Not available";

  return new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
    ...(includeTime ? { hour: "numeric", minute: "2-digit", timeZone: "UTC" } : {}),
    timeZone: "UTC"
  }).format(date);
}

function metricTone(change, inverse = false) {
  if (change === "" || change == null || !Number.isFinite(Number(change))) return "neutral";
  const adjusted = Number(change) * (inverse ? -1 : 1);
  if (adjusted >= 0.05) return "good";
  if (adjusted <= -0.05) return "bad";
  return "warning";
}

function renderMetricCard({
  label,
  value,
  previous = "",
  wow = "",
  avg4 = "",
  vs4 = "",
  format = formatNumber,
  inverse = false
}) {
  const tone = metricTone(wow, inverse);
  const wowText = wow === "" ? "No WoW comparison" : `${Number(wow) >= 0 ? "+" : ""}${formatPercent(wow)}`;

  return `
    <article class="metric-card ${tone}">
      <div class="metric-label">${escapeHtml(label)}</div>
      <div class="metric-value">${format(value)}</div>
      <div class="metric-change">${escapeHtml(wowText)} <span>vs last week</span></div>
      <dl class="metric-context">
        <div><dt>Previous</dt><dd>${format(previous)}</dd></div>
        <div><dt>4W avg</dt><dd>${format(avg4)}</dd></div>
        <div><dt>vs 4W</dt><dd>${vs4 === "" ? "N/A" : formatPercent(vs4)}</dd></div>
      </dl>
    </article>
  `;
}

function renderDataTable(title, columns, rows, emptyMessage = "No data available.") {
  const body = rows.length
    ? rows.map((row) => `
        <tr>
          ${columns.map((column) => `<td data-label="${escapeHtml(column.label)}">${column.render(row)}</td>`).join("")}
        </tr>
      `).join("")
    : `<tr><td colspan="${columns.length}" class="empty">${escapeHtml(emptyMessage)}</td></tr>`;

  return `
    <div class="table-card">
      <h3>${escapeHtml(title)}</h3>
      <div class="table-scroll">
        <table>
          <thead><tr>${columns.map((column) => `<th>${escapeHtml(column.label)}</th>`).join("")}</tr></thead>
          <tbody>${body}</tbody>
        </table>
      </div>
    </div>
  `;
}

