async function fetchAllVariants(shop, token) {
  const query = `
    query GetActiveProducts($cursor: String) {
      products(first: 100, after: $cursor, query: "status:active") {
        edges {
          cursor
          node {
            id
            title
            productType
            vendor
            status
            featuredMedia {
              preview {
                image {
                  url
                }
              }
            }
            variants(first: 100) {
              edges {
                node {
                  id
                  sku
                  title
                  inventoryQuantity
                  inventoryPolicy
                  price
                  compareAtPrice
                  selectedOptions {
                    name
                    value
                  }
                  inventoryItem {
                    unitCost {
                      amount
                      currencyCode
                    }
                  }
                }
              }
            }
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  `;

  const all = [];
  let cursor = null;

  while (true) {
    const data = await shopifyGraphQL(shop, token, query, { cursor });
    const conn = data.products;

    for (const edge of conn.edges || []) {
      const product = edge.node;

      for (const variantEdge of product.variants?.edges || []) {
        all.push({
          ...variantEdge.node,
          product: {
            id: product.id,
            title: product.title,
            productType: product.productType,
            vendor: product.vendor,
            status: product.status,
            featuredMedia: product.featuredMedia
          }
        });
      }
    }

    if (!conn.pageInfo?.hasNextPage) break;
    cursor = conn.pageInfo.endCursor;
    if (!cursor) break;
  }

  return all;
}

//
// The weekly `sales_reversals` figure is cancellations (RTO), not refunds, and
// ShopifyQL books it on the CANCEL date. Measured over the full 2026-07-19 →
// belongs to an order placed in a different week. Every weekly net_sales and MER
// therefore subtracts a different week's RTO.
//
// SIGN CONVENTION — the sharpest edge in this code.
//   ShopifyQL returns `discounts` and `sales_reversals` NEGATIVE, and
//   net = gross + discounts + reversals algebraically.
//   This codebase stores POSITIVE magnitudes (fetchSalesAnalyticsForWeek applies
//   Math.abs), and net_sales is taken from ShopifyQL rather than recomputed.
//   Verified live on week 2026-08-23:
//   Everything below normalises to POSITIVE magnitude at the boundary, so the
//   attributed formula reads as plain addition and subtraction.
const REVERSAL_LOOKBACK_WEEKS = 8;

// 21 days is the evidence-based threshold; 28 keeps margin. Derived from cohorts
// with a FULL 28 days of observation at the 2026-08-30 measurement edge — only
// 2026-07-19 (n=6, p90 16) and 2026-07-26 (n=76, p90 9) qualify. 08-02 (~22
// days) and 08-09 (~15) were still accruing and their p90s are censored-low, so
// the base is n=82 across two cohorts, not four. Re-derive after ~2026-09-13.
const REVERSAL_SETTLED_DAYS = 28;

const REVERSAL_ID_CHUNK = 100;

function shopifyQLRows(tableData) {
  const columns = (tableData?.columns || []).map((c) => c.name);
  return (tableData?.rows || []).map((row) =>
    Array.isArray(row) ? Object.fromEntries(columns.map((c, i) => [c, row[i]])) : row
  );
}

// ShopifyQL hands back negative values for reversals and discounts. Store the
// magnitude so downstream arithmetic is not sign-dependent.
function reversalMagnitude(value) {
  return Math.abs(num(value));
}

function chunkList(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

// order_id is numeric in ShopifyQL and must be UNQUOTED. Quoting raises
// "Invalid Types: Enter a number only".
function orderIdInClause(ids) {
  return `order_id IN (${ids.map((id) => clean(id)).filter(Boolean).join(", ")})`;
}

// Every query here carries the P1.11 exclusion predicate. Without it the
// attribution measures a different population than the weekly fields it
// one and not the other.
async function computeReversalAttribution(shop, token, boundaries, options = {}) {
  const asOf = clean(options.asOf) || formatDateOnlyFromUtcMs(Date.now());
  const lookbackStart = addDays(boundaries.week_start, -7 * REVERSAL_LOOKBACK_WEEKS);

  const unavailable = (reason) => ({
    available: false,
    reason,
    as_of: asOf,
    lookback_weeks: REVERSAL_LOOKBACK_WEEKS
  });

  try {
    // ── Backward (diagnostic): reversals BOOKED in W, and which week each
    //    belongs to. Settles immediately and never changes.
    const bookedTable = await shopifyQL(
      shop,
      token,
      `FROM sales SHOW sales_reversals GROUP BY order_id
       SINCE ${boundaries.week_start} UNTIL ${boundaries.week_end}
       WHERE ${shopifyQLExclusionPredicate()}`
    );

    const bookedByOrder = new Map();
    for (const row of shopifyQLRows(bookedTable)) {
      const value = reversalMagnitude(row.sales_reversals);
      const id = clean(row.order_id);
      if (id && value > 0) bookedByOrder.set(id, value);
    }

    const bookedTotal = [...bookedByOrder.values()].reduce((a, b) => a + b, 0);
    let crossWeekValue = 0;
    let unattributedValue = 0;
    let unattributedOrders = 0;
    const lagDays = [];

    if (bookedByOrder.size) {
      const orderWeekById = new Map();

      for (const chunk of chunkList([...bookedByOrder.keys()], REVERSAL_ID_CHUNK)) {
        const table = await shopifyQL(
          shop,
          token,
          `FROM sales SHOW orders GROUP BY order_id TIMESERIES week
           SINCE ${lookbackStart} UNTIL ${boundaries.week_end}
           WHERE (${shopifyQLExclusionPredicate()}) AND (${orderIdInClause(chunk)})`
        );

        for (const row of shopifyQLRows(table)) {
          const id = clean(row.order_id);
          if (id && num(row.orders) > 0) orderWeekById.set(id, clean(row.week).slice(0, 10));
        }
      }

      for (const [id, value] of bookedByOrder) {
        const orderWeek = orderWeekById.get(id);

        if (!orderWeek) {
          // Order week is outside the lookback. Reported, never dropped.
          unattributedValue += value;
          unattributedOrders += 1;
          continue;
        }

        if (orderWeek !== boundaries.week_start) crossWeekValue += value;

        lagDays.push(
          Math.round((dateOnlyToUtcMs(boundaries.week_start) - dateOnlyToUtcMs(orderWeek)) / DAY_MS)
        );
      }
    }

    // ── Forward (the metric): reversals belonging to orders PLACED in W,
    //    whenever booked. This is what makes net_sales and MER correct.
    const placedTable = await shopifyQL(
      shop,
      token,
      `FROM sales SHOW orders GROUP BY order_id
       SINCE ${boundaries.week_start} UNTIL ${boundaries.week_end}
       WHERE ${shopifyQLExclusionPredicate()}`
    );

    const placedIds = shopifyQLRows(placedTable)
      .filter((row) => num(row.orders) > 0)
      .map((row) => clean(row.order_id))
      .filter(Boolean);

    let cohortReversals = 0;

    for (const chunk of chunkList(placedIds, REVERSAL_ID_CHUNK)) {
      const table = await shopifyQL(
        shop,
        token,
        `FROM sales SHOW sales_reversals GROUP BY order_id
         SINCE ${boundaries.week_start} UNTIL ${asOf}
         WHERE (${shopifyQLExclusionPredicate()}) AND (${orderIdInClause(chunk)})`
      );

      for (const row of shopifyQLRows(table)) {
        cohortReversals += reversalMagnitude(row.sales_reversals);
      }
    }

    const ageDays = Math.round(
      (dateOnlyToUtcMs(asOf) - dateOnlyToUtcMs(boundaries.week_end)) / DAY_MS
    );

    const percentile = (arr, p) => {
      if (!arr.length) return "";
      const sorted = [...arr].sort((a, b) => a - b);
      return sorted[Math.min(sorted.length - 1, Math.floor(p * sorted.length))];
    };

    return {
      available: true,
      basis: "shopifyql",
      as_of: asOf,
      lookback_weeks: REVERSAL_LOOKBACK_WEEKS,
      settled_threshold_days: REVERSAL_SETTLED_DAYS,

      // Backward diagnostic
      reversals_booked: r2(bookedTotal),
      reversals_booked_orders: bookedByOrder.size,
      reversals_booked_cross_week: r2(crossWeekValue),
      reversals_booked_cross_week_pct: bookedTotal ? r4(crossWeekValue / bookedTotal) : "",
      reversals_unattributed: r2(unattributedValue),
      reversals_unattributed_orders: unattributedOrders,

      // Forward metric
      reversals_for_orders_placed_in_week: r2(cohortReversals),
      cohort_orders: placedIds.length,

      // Settling
      attribution_age_days: ageDays,
      attribution_settled: ageDays >= REVERSAL_SETTLED_DAYS,
      reversal_lag_p50_days: percentile(lagDays, 0.5),
      reversal_lag_p90_days: percentile(lagDays, 0.9)
    };
  } catch (err) {
    // Attribution is additive. It must never fail the sync that carries it.
    return unavailable(truncateOperationalError(err));
  }
}

async function fetchSalesAnalyticsForWeek(shop, token, boundaries, options = {}) {
  // Excluded on the same population as the Orders API path. Applying this to one
  // basis only would fix the SKU rows and leave net_sales wrong.
  const q = `
    FROM sales
    SHOW gross_sales, discounts, returns, net_sales, shipping_charges, taxes, total_sales, orders
    SINCE ${boundaries.week_start}
    UNTIL ${boundaries.week_end}
    ${options.includeExcluded ? "" : shopifyQLExclusionClause()}
  `;

  const table = await shopifyQL(shop, token, q);
  const row = shopifyQLRowObject(table, 0);

  return {
    gross_sales: num(row.gross_sales),
    discounts: Math.abs(num(row.discounts)),
    refunds: Math.abs(num(row.returns)),
    net_sales: num(row.net_sales),
    shipping_revenue: num(row.shipping_charges),
    taxes: num(row.taxes),
    total_sales: num(row.total_sales),
    orders: num(row.orders),
    raw: table
  };
}

async function fetchFulfillmentAnalyticsForWeek(shop, token, boundaries) {
  const q = `
    FROM fulfillments
    SHOW orders_fulfilled
    SINCE ${boundaries.week_start}
    UNTIL ${boundaries.week_end}
  `;

  const table = await shopifyQL(shop, token, q);

  return {
    orders_fulfilled: getShopifyQLMetric(table, "orders_fulfilled"),
    raw: table
  };
}

