function validOrder(order) {
  return !order.cancelledAt && !order.test;
}

//
// Orders that are real in Shopify but are not commerce: showroom/UGC seeding and
// codebase was validOrder above — no staff or seeding exclusion had ever been
// implemented, despite the project rules assuming one for weeks.
//
// One rule table, two renderings. The weekly financial totals come from the
// ShopifyQL aggregate and the product/SKU rows come from the Orders API, so an
// exclusion applied to only one basis fixes the SKU rows while net_sales stays
// wrong. Keeping both expressions of a rule in the same object is what stops the
// two bases drifting apart.
//
// Predicates verified against live data 2026-04-01 → 08-29:
//               was rejected: it matches 18 orders, over-excluding 16.
//               off, so excluding them moves gross_sales, discounts,
//               discount_rate, orders, AOV and CVR, but NOT net_sales or MER.
// The two rules are disjoint: every staff order has a non-null customer_id.
const ORDER_EXCLUSION_RULES = [
  {
    id: "seeding",
    reason: "Showroom/UGC seeding order: manual fixed-amount discount with no customer.",
    shopifyql: "(discount_type = 'fixed_amount' AND customer_id IS NULL)",
    // customer_id = '' raises a ShopifyQL type error; IS NULL is the working form.
    matchesOrder: (order) =>
      !clean(order?.customer?.id) && orderDiscountCodeList(order).includes("Custom discount")
  },
  {
    id: "staff_100",
    reason: "Staff 100% discount order.",
    shopifyql: "discount_code = 'STAFF_CODE_EXAMPLE'",
    matchesOrder: (order) => orderDiscountCodeList(order).includes("STAFF_CODE_EXAMPLE")
  }
];

function orderDiscountCodeList(order) {
  return (order?.discountCodes || []).map((code) => clean(code)).filter(Boolean);
}

// Appended to every ShopifyQL sales aggregate so the weekly financial fields are
// computed on the same population as the product/SKU rows.
// Returns a bare predicate so it can compose. Callers combining it with
// another condition MUST parenthesise both sides:
//   WHERE (${predicate}) AND (${other})
// ShopifyQL silently mis-parses `NOT (...) AND ...` — verified live, it
// excluded, rather than raising an error.
function shopifyQLExclusionPredicate() {
  return `NOT (${ORDER_EXCLUSION_RULES.map((r) => r.shopifyql).join(" OR ")})`;
}

function shopifyQLExclusionClause() {
  return `WHERE ${shopifyQLExclusionPredicate()}`;
}

function orderExclusionRuleId(order) {
  for (const rule of ORDER_EXCLUSION_RULES) {
    if (rule.matchesOrder(order)) return rule.id;
  }
  return "";
}

// Splits an order list into kept and excluded, with enough detail that a future
// seeding order surfaces in the sync result rather than silently vanishing.
function partitionExcludedOrders(orders) {
  const kept = [];
  const excluded = [];

  for (const order of orders || []) {
    const ruleId = orderExclusionRuleId(order);
    if (!ruleId) {
      kept.push(order);
      continue;
    }
    excluded.push({ order, rule_id: ruleId });
  }

  return { kept, excluded };
}

function summarizeExcludedOrders(excluded) {
  const byRule = {};

  for (const { rule_id } of excluded) {
    byRule[rule_id] = (byRule[rule_id] || 0) + 1;
  }

  return {
    // Always emitted, including at zero: an absent field is indistinguishable
    // from a sync that never checked.
    count: excluded.length,
    by_rule: byRule,
    order_names: excluded.map(({ order }) => clean(order.name)).filter(Boolean),
    rules_applied: ORDER_EXCLUSION_RULES.map((r) => r.id)
    // Money impact is NOT derived from the Orders API here. These orders are
    // typically cancelled, which zeroes their current* money fields, so
    // lineFinancials falls back to gross and reports net == gross. The value is
    // measured on the ShopifyQL basis instead - see excluded_orders.impact,
    // which is the same basis the weekly financial fields are written from.
  };
}

function variantMeta(v) {
  const p = v.product || {};
  const selected = (v.selectedOptions || [])
    .map((o) => o.value)
    .filter(Boolean)
    .join(" / ");

  return {
    product_id: clean(p.id),
    product_title: clean(p.title),
    product_type: clean(p.productType),
    vendor: clean(p.vendor),
    status: clean(p.status),
    featured_image_url: clean(p.featuredMedia?.preview?.image?.url),
    variant_id: clean(v.id),
    variant_title: selected || clean(v.title),
    sku: clean(v.sku) || shortGid(v.id),
    inventory_policy: clean(v.inventoryPolicy),
    current_stock: num(v.inventoryQuantity),

    // P1.1. inventoryItem.unitCost is Shopify's built-in cost field, NOT a
    // metafield. metricOrBlank, never num: a missing cost must stay blank so it
    // is visibly absent rather than silently costing zero, which would report a
    // (non-negotiable #2). Two live nulls exist — CODDIWOMPLE GREY SWEATPANTS V2
    // and MAD CITY BLACK TEE — so this path is exercised on real data.
    unit_cost: metricOrBlank(v.inventoryItem?.unitCost?.amount),
    unit_price: metricOrBlank(v.price),
    compare_at_price: metricOrBlank(v.compareAtPrice)
  };
}

// Margin helpers. Every one returns blank rather than 0 when cost is unknown:
// a fabricated zero cost reports full price as pure profit.
function grossMargin(netSales, unitCost, units) {
  const cost = metricOrBlank(unitCost);
  const sales = metricOrBlank(netSales);
  const qty = metricOrBlank(units);
  if (cost === "" || sales === "" || qty === "") return "";
  return r2(sales - cost * qty);
}

function grossMarginRate(netSales, unitCost, units) {
  const margin = grossMargin(netSales, unitCost, units);
  const sales = metricOrBlank(netSales);
  if (margin === "" || sales === "" || sales === 0) return "";
  return r4(margin / sales);
}

// Cost of units that were ordered and then cancelled. Post-dispatch RTO also
// eats round-trip shipping, which is not modelled here — this is the goods cost
// alone, and is a floor on the true loss, not the whole of it.
function reversedUnitCost(unitCost, reversedUnits) {
  const cost = metricOrBlank(unitCost);
  const qty = metricOrBlank(reversedUnits);
  if (cost === "" || qty === "") return "";
  return r2(cost * qty);
}

function lineMeta(line) {
  const p = line.product || line.variant?.product || {};

  const productTitle = clean(p.title || line.title || line.name || "Unknown product");
  const productId = clean(p.id) || `line_product:${productTitle}`;

  const variantTitle = clean(line.variant?.title || line.variantTitle || "");
  const sku = clean(line.sku || line.variant?.sku) || shortGid(line.variant?.id || line.id);

  return {
    product_id: productId,
    product_title: productTitle,
    product_type: clean(p.productType),
    vendor: clean(p.vendor || line.vendor),
    status: clean(p.status),
    featured_image_url: clean(p.featuredMedia?.preview?.image?.url),
    variant_id: clean(line.variant?.id) || `line_variant:${sku || clean(line.id)}`,
    variant_title: variantTitle,
    sku,
    inventory_policy: "",
    current_stock: num(line.variant?.inventoryQuantity)
  };
}

function lineFinancials(line) {
  const orderedQty = num(line.quantity);
  const currentQty = num(line.currentQuantity ?? line.quantity);

  const originalUnit =
    money(line.originalUnitPriceSet) ||
    div(money(line.originalTotalSet), orderedQty) ||
    0;

  const gross =
    money(line.originalTotalSet) ||
    originalUnit * orderedQty;

  const discountedLineTotal =
    money(line.discountedTotalSet) ||
    gross;

  const discounts =
    money(line.totalDiscountSet) ||
    Math.max(0, gross - discountedLineTotal);

  // Before refund-event accounting.
  // Refunds/returns are applied separately using refundLineItems processed during the week.
  const net = gross - discounts;

  return {
    orderedQty,
    currentQty,
    gross,
    net,
    discounts,
    refunds: 0
  };
}

function emptyAgg() {
  return {
    gross_sales: 0,
    net_sales: 0,
    discounts: 0,
    refunds: 0,

    // Gross ordered units from orders created in the week.
    units_sold: 0,
    ordered_items: 0,

    // Return/refund quantity processed during the week.
    returned_items: 0,

    orderIds: new Set(),
    meta: null
  };
}

function getAgg(map, key) {
  if (!map.has(key)) map.set(key, emptyAgg());
  return map.get(key);
}

function ensureRoll(map, key) {
  if (!map.has(key)) {
    map.set(key, {
      units_3d: 0,
      units_7d: 0,
      units_14d: 0,
      units_30d: 0
    });
  }

  return map.get(key);
}

function orderRawShipping(order) {
  return money(order.currentShippingPriceSet);
}

function orderShippingLineSummaryAmount(order) {
  const v = money(order.shippingLine?.discountedPriceSet);

  if (order.shippingLine && Number.isFinite(Number(v))) {
    return v;
  }

  return "";
}

function discountApplicationLabel(app) {
  return clean(app.code || app.title || "");
}

function discountValueAmount(app, baseAmount) {
  const value = app.value || {};

  if (value.percentage != null) {
    return baseAmount * (num(value.percentage) / 100);
  }

  if (value.amount != null) {
    return num(value.amount);
  }

  return 0;
}

function isShippingDiscountApplication(app) {
  const targetType = clean(app.targetType);
  const label = discountApplicationLabel(app).toLowerCase();

  return (
    targetType === "SHIPPING_LINE" ||
    targetType === "SHIPPING_LINES" ||
    label.includes("free shipping") ||
    label.includes("free delivery") ||
    label.includes("shipping") ||
    label.includes("delivery") ||
    label.includes("شحن") ||
    label.includes("توصيل")
  );
}

function orderShippingDiscountFromApplications(order) {
  const rawShipping = orderRawShipping(order);
  const apps = order.discountApplications?.edges || [];

  let shippingDiscount = 0;

  for (const edge of apps) {
    const app = edge.node || {};

    if (!isShippingDiscountApplication(app)) continue;

    shippingDiscount += discountValueAmount(app, rawShipping);
  }

  return Math.min(rawShipping, shippingDiscount);
}

function orderShopifyShippingCharge(order) {
  return orderRawShipping(order);
}

function aggregateOrders(weeklyOrders, rollingOrders, endUtcMs) {
  const weekly = {
    gross_sales: 0,
    net_sales: 0,
    discounts: 0,
    refunds: 0,
    shipping_revenue: 0,
    taxes: 0,
    orders: 0,

    total_quantity_ordered: 0,
    net_items_sold: 0,
    returned_items: 0,
    returned_orders: 0,

    total_sales: 0
  };

  const productAgg = new Map();
  const skuAgg = new Map();
  const rollingProduct = new Map();
  const rollingSku = new Map();

  // 1) Orders created in the selected report week.
  // These power product/SKU weekly sales rows.
  for (const order of weeklyOrders) {
    if (!validOrder(order)) continue;

    weekly.orders += 1;
    weekly.shipping_revenue += orderShopifyShippingCharge(order);
    weekly.taxes += money(order.currentTotalTaxSet);
    weekly.discounts += money(order.currentTotalDiscountsSet);

    for (const edge of order.lineItems?.edges || []) {
      const line = edge.node;
      const meta = lineMeta(line);
      const f = lineFinancials(line);

      weekly.gross_sales += f.gross;
      weekly.net_sales += f.net;
      weekly.total_quantity_ordered += f.orderedQty;

      const pAgg = getAgg(productAgg, meta.product_id);
      const sAgg = getAgg(skuAgg, meta.variant_id);

      for (const agg of [pAgg, sAgg]) {
        agg.gross_sales += f.gross;
        agg.net_sales += f.net;
        agg.discounts += f.discounts;
        agg.refunds += f.refunds;

        // Gross units ordered in the report week.
        // Returns are tracked separately later.
        agg.units_sold += f.orderedQty;
        agg.ordered_items += f.orderedQty;
        agg.orderIds.add(order.id);

        if (!agg.meta) agg.meta = meta;
      }
    }
  }

  // 2) Rolling 3/7/14/30-day velocity window ending at report week end.
  // This powers days_of_cover and inventory pressure.
  for (const order of rollingOrders) {
    if (!validOrder(order)) continue;

    const ageMs = endUtcMs - new Date(order.createdAt).getTime();

    if (ageMs < 0 || ageMs > 30 * DAY_MS) continue;

    for (const edge of order.lineItems?.edges || []) {
      const line = edge.node;
      const meta = lineMeta(line);
      const qty = num(line.currentQuantity ?? line.quantity);

      const p = ensureRoll(rollingProduct, meta.product_id);
      const s = ensureRoll(rollingSku, meta.variant_id);

      if (ageMs <= 3 * DAY_MS) {
        p.units_3d += qty;
        s.units_3d += qty;
      }

      if (ageMs <= 7 * DAY_MS) {
        p.units_7d += qty;
        s.units_7d += qty;
      }

      if (ageMs <= 14 * DAY_MS) {
        p.units_14d += qty;
        s.units_14d += qty;
      }

      if (ageMs <= 30 * DAY_MS) {
        p.units_30d += qty;
        s.units_30d += qty;
      }
    }
  }

  return {
    weekly,
    productAgg,
    skuAgg,
    rollingProduct,
    rollingSku
  };
}

function daily(units, days) {
  return r2(num(units) / days);
}

function daysCover(stock, velocity) {
  return num(velocity) > 0 ? r2(num(stock) / num(velocity)) : num(stock) > 0 ? 999 : 0;
}

function sellThrough(units, stock) {
  return r4(div(num(units), num(units) + num(stock)));
}

// `freight` is optional and blank when absent. It was read here but never passed in,
// and the ReferenceError failed the 2026-09-13 scheduled sync (week 2026-09-06).
function buildRows({ config, boundaries, syncedAt, variants, aggregate, attribution, dropPosition, attributionCapture, delivery, skuDelivery = {}, freight = null }) {
  const variantMap = new Map();
  const productInv = new Map();

  for (const v of variants) {
const m = variantMeta(v);
if (!m.variant_id) continue;
if (!m.product_id || !m.product_title) continue;

    variantMap.set(m.variant_id, m);

    if (!productInv.has(m.product_id)) {
      productInv.set(m.product_id, {
        meta: m,
        ending_inventory_units: 0,
        variant_count: 0,
        active_variant_count: 0,
        oos_variant_count: 0
      });
    }

    const p = productInv.get(m.product_id);

    p.ending_inventory_units += m.current_stock;
    p.variant_count += 1;

    if (m.status === "ACTIVE") p.active_variant_count += 1;
    if (m.current_stock <= 0) p.oos_variant_count += 1;
  }

  const allVariantIds = new Set([...variantMap.keys(), ...aggregate.skuAgg.keys()]);
  const skuRows = [];

  for (const variantId of allVariantIds) {
    const sales = aggregate.skuAgg.get(variantId) || emptyAgg();
    const meta = variantMap.get(variantId) || sales.meta || {};
    const roll = aggregate.rollingSku.get(variantId) || {
      units_3d: 0,
      units_7d: 0,
      units_14d: 0,
      units_30d: 0
    };

    const stock = num(meta.current_stock);
    const v3 = daily(roll.units_3d, 3);
    const v7 = daily(roll.units_7d, 7);
    const v14 = daily(roll.units_14d, 14);
    const v30 = daily(roll.units_30d, 30);

    skuRows.push({
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      synced_at: syncedAt,
      product_id: meta.product_id || "",
      product_title: meta.product_title || "",
      variant_id: variantId,
      variant_title: meta.variant_title || "",
      sku: meta.sku || shortGid(variantId),
      product_type: meta.product_type || "",

      units_shipped: skuDelivery[meta.sku || shortGid(variantId)]?.units_shipped ?? "",
      units_not_delivered: skuDelivery[meta.sku || shortGid(variantId)]?.units_not_delivered ?? "",
      rto_rate_units: skuDelivery[meta.sku || shortGid(variantId)]?.rto_rate_units ?? "",
      rto_revenue_not_delivered: skuDelivery[meta.sku || shortGid(variantId)]?.revenue_not_delivered ?? "",
      rto_basis: skuDelivery[meta.sku || shortGid(variantId)]?.rto_basis ?? "",

      vendor: meta.vendor || "",
      status: meta.status || "",
      featured_image_url: meta.featured_image_url || "",
gross_sales: r2(sales.gross_sales),
discounts: r2(sales.discounts),
discount_rate: r4(div(sales.discounts, sales.gross_sales)),
refunds: r2(sales.refunds),
refund_rate_revenue: r4(div(sales.refunds, sales.gross_sales)),
net_sales: r2(sales.net_sales),
orders: sales.orderIds.size,

// Gross units ordered in the report week.
units_sold: sales.units_sold,

// Return/refund units processed in the report week.
returned_items: sales.returned_items,

// Return-adjusted unit result.
net_units_sold: num(sales.units_sold) - num(sales.returned_items),

return_rate_units: r4(div(sales.returned_items, sales.ordered_items)),
ending_inventory_units: stock,
      is_oos: stock <= 0 ? "TRUE" : "FALSE",
      weekly_sell_through_rate: sellThrough(sales.units_sold, stock),
      current_3d_units: roll.units_3d,
      current_7d_units: roll.units_7d,
      current_14d_units: roll.units_14d,
      current_30d_units: roll.units_30d,
      daily_velocity_3d: v3,
      daily_velocity_7d: v7,
      daily_velocity_14d: v14,
      daily_velocity_30d: v30,
      days_of_cover_7d: daysCover(stock, v7),
      stock_left_pct: "",
      size_share_pct: "",
      sku_rank_units: "",

      unit_cost: meta.unit_cost ?? "",
      // Costed on NET units, not ordered units. Cancelled goods are returned to
      // inventory and resold (confirmed by the founder 2026-09-05), so their
      // cost belongs to whichever week they eventually sell in, not this one.
      // Costing ordered units overstates COGS and understates margin by the
      // full goods value of every cancellation.
      gross_margin: grossMargin(sales.net_sales, meta.unit_cost, num(sales.units_sold) - num(sales.returned_items)),
      gross_margin_rate: grossMarginRate(sales.net_sales, meta.unit_cost, num(sales.units_sold) - num(sales.returned_items)),
      // Goods cost of cancelled units. RTO stock is not costless: without this
      // a cancelled order looks like a pure revenue reversal when it also
      reversed_unit_cost: reversedUnitCost(meta.unit_cost, sales.returned_items)
    });
  }

  const productTotalUnits = new Map();

  for (const r of skuRows) {
    productTotalUnits.set(r.product_id, num(productTotalUnits.get(r.product_id)) + num(r.units_sold));
  }

  skuRows.forEach((r) => {
    r.size_share_pct =
      r.product_id && num(productTotalUnits.get(r.product_id))
        ? r4(num(r.units_sold) / num(productTotalUnits.get(r.product_id)))
        : "";
  });

  [...skuRows]
    .sort((a, b) => num(b.units_sold) - num(a.units_sold))
    .forEach((r, i) => {
      r.sku_rank_units = i + 1;
    });

  const allProductIds = new Set([...productInv.keys(), ...aggregate.productAgg.keys()]);
  const productRows = [];

  for (const productId of allProductIds) {
    const sales = aggregate.productAgg.get(productId) || emptyAgg();
    const inv = productInv.get(productId) || null;
const meta = sales.meta || inv?.meta || {};
    const roll = aggregate.rollingProduct.get(productId) || {
      units_3d: 0,
      units_7d: 0,
      units_14d: 0,
      units_30d: 0
    };

    const stock = num(inv?.ending_inventory_units);
    const v7 = daily(roll.units_7d, 7);

    productRows.push({
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      synced_at: syncedAt,
product_id: productId || meta.product_id || "",
product_title: meta.product_title || sales.meta?.product_title || inv?.meta?.product_title || "",
      product_type: meta.product_type || "",
      vendor: meta.vendor || "",
      status: meta.status || "",
      featured_image_url: meta.featured_image_url || "",
gross_sales: r2(sales.gross_sales),
discounts: r2(sales.discounts),
discount_rate: r4(div(sales.discounts, sales.gross_sales)),
refunds: r2(sales.refunds),
refund_rate_revenue: r4(div(sales.refunds, sales.gross_sales)),
net_sales: r2(sales.net_sales),
orders: sales.orderIds.size,

// Gross units ordered in the report week.
units_sold: sales.units_sold,

// Return/refund units processed in the report week.
returned_items: sales.returned_items,

// Return-adjusted unit result.
net_units_sold: num(sales.units_sold) - num(sales.returned_items),

return_rate_units: r4(div(sales.returned_items, sales.ordered_items)),
ending_inventory_units: stock,
      variant_count: inv?.variant_count || 0,
      active_variant_count: inv?.active_variant_count || 0,
      oos_variant_count: inv?.oos_variant_count || 0,
      oos_variant_rate: inv?.variant_count ? r4(num(inv.oos_variant_count) / num(inv.variant_count)) : "",
      weekly_sell_through_rate: sellThrough(sales.units_sold, stock),
      current_7d_units: roll.units_7d,
      current_14d_units: roll.units_14d,
      current_30d_units: roll.units_30d,
      daily_velocity_7d: v7,
      days_of_cover_7d: daysCover(stock, v7),
      stock_left_pct: "",
      product_rank_revenue: "",
      product_rank_units: ""
    });
  }

  // variant's meta — variants of the same product can carry different costs.
  //
  // cogs_coverage_rate is the share of the product's sold units whose cost is
  // known. Reported per product because a blended margin computed over partial
  const skusByProduct = new Map();
  for (const r of skuRows) {
    if (!r.product_id) continue;
    if (!skusByProduct.has(r.product_id)) skusByProduct.set(r.product_id, []);
    skusByProduct.get(r.product_id).push(r);
  }

  for (const row of productRows) {
    const skus = skusByProduct.get(row.product_id) || [];
    const soldSkuRows = skus.filter((r) => num(r.units_sold) > 0);
    const coveredRows = soldSkuRows.filter((r) => metricOrBlank(r.unit_cost) !== "");

    const coveredUnits = coveredRows.reduce((a, r) => a + num(r.units_sold), 0);
    const soldUnits = soldSkuRows.reduce((a, r) => a + num(r.units_sold), 0);

    row.cogs_coverage_rate = soldUnits ? r4(coveredUnits / soldUnits) : "";

    // A single blended unit cost is only meaningful where every sold unit has
    // one. Weighted by units, not a flat average across variants.
    const costWeighted = coveredRows.reduce(
      (a, r) => a + metricOrBlank(r.unit_cost) * num(r.units_sold),
      0
    );

    if (soldUnits > 0 && coveredUnits === soldUnits) {
      row.unit_cost = r2(costWeighted / soldUnits);
      row.gross_margin = r2(num(row.net_sales) - costWeighted);
      row.gross_margin_rate = num(row.net_sales)
        ? r4((num(row.net_sales) - costWeighted) / num(row.net_sales))
        : "";
    } else {
      row.unit_cost = "";
      row.gross_margin = "";
      row.gross_margin_rate = "";
    }
  }

  [...productRows]
    .sort((a, b) => num(b.net_sales) - num(a.net_sales))
    .forEach((r, i) => {
      r.product_rank_revenue = i + 1;
    });

  [...productRows]
    .sort((a, b) => num(b.units_sold) - num(a.units_sold))
    .forEach((r, i) => {
      r.product_rank_units = i + 1;
    });

  // Weekly COGS roll-up from the SKU rows.
  const soldSkuRows = skuRows.filter((r) => num(r.units_sold) > 0);
  const coveredSkuRows = soldSkuRows.filter((r) => metricOrBlank(r.unit_cost) !== "");
  const weeklySoldUnits = soldSkuRows.reduce((a, r) => a + Math.max(0, num(r.units_sold) - num(r.returned_items)), 0);
  const weeklyCoveredUnits = coveredSkuRows.reduce((a, r) => a + Math.max(0, num(r.units_sold) - num(r.returned_items)), 0);
  // NET units throughout: RTO stock returns to inventory and resells, so its
  // cost is not consumed by the week the cancellation landed in.
  const netUnits = (r) => Math.max(0, num(r.units_sold) - num(r.returned_items));
  const weeklyCostOfSold = coveredSkuRows.reduce(
    (a, r) => a + metricOrBlank(r.unit_cost) * netUnits(r),
    0
  );
  const weeklyReversedCost = skuRows.reduce(
    (a, r) => a + (metricOrBlank(r.reversed_unit_cost) === "" ? 0 : metricOrBlank(r.reversed_unit_cost)),
    0
  );
  const coveredNetSales = coveredSkuRows.reduce((a, r) => a + num(r.net_sales), 0);
  const soldNetSalesSkuBasis = soldSkuRows.reduce((a, r) => a + num(r.net_sales), 0);

  const weeklyFullyCovered = weeklySoldUnits > 0 && weeklyCoveredUnits === weeklySoldUnits;
  const weeklyNetSales = num(aggregate.weekly.net_sales);

  // Units-weighted average cost of the covered units, used to price the rest.
  const avgCoveredUnitCost = weeklyCoveredUnits ? r2(weeklyCostOfSold / weeklyCoveredUnits) : "";

  // Estimate the RATE on the SKU basis, then apply it to the ShopifyQL week.
  const estimatedTotalCost =
    avgCoveredUnitCost === ""
      ? ""
      : weeklyCostOfSold + avgCoveredUnitCost * (weeklySoldUnits - weeklyCoveredUnits);

  const estimatedMarginRate =
    estimatedTotalCost === "" || soldNetSalesSkuBasis <= 0
      ? ""
      : r4((soldNetSalesSkuBasis - estimatedTotalCost) / soldNetSalesSkuBasis);

  const estimatedMargin =
    estimatedMarginRate === "" || weeklyNetSales === 0
      ? ""
      : r2(weeklyNetSales * estimatedMarginRate);

  // Net sales attributable to the units whose cost is known, so the covered
  // margin is computed on a like-for-like basis rather than dividing full-week
  // revenue by partial cost.
  //
  // TWO BASES — do not subtract one from the other. SKU rows come from the
  // Orders API; aggregate.weekly.net_sales is overwritten from ShopifyQL. The
  // first version of this estimate derived uncovered revenue as
  // (weekly net - covered net) and produced an estimated margin HIGHER than the
  // measured one, because the gap is mostly basis mismatch rather than
  // uncovered units. Everything below stays on the SKU basis; the ShopifyQL
  // week is only ever multiplied by a RATE derived there.


  const weeklyCogs = {
    coverage_rate: weeklySoldUnits ? r4(weeklyCoveredUnits / weeklySoldUnits) : "",

    // The week's true margin. Blank below full coverage — presenting a partial
    // figure as the week's margin would be a fabricated number dressed as a
    // measurement.
    gross_margin: weeklyFullyCovered ? r2(weeklyNetSales - weeklyCostOfSold) : "",
    gross_margin_rate:
      weeklyFullyCovered && weeklyNetSales
        ? r4((weeklyNetSales - weeklyCostOfSold) / weeklyNetSales)
        : "",

    // Margin over the covered units ONLY. Measured, not extrapolated.
    covered_gross_margin: coveredSkuRows.length ? r2(coveredNetSales - weeklyCostOfSold) : "",
    covered_gross_margin_rate:
      coveredSkuRows.length && coveredNetSales
        ? r4((coveredNetSales - weeklyCostOfSold) / coveredNetSales)
        : "",
    covered_net_sales: coveredSkuRows.length ? r2(coveredNetSales) : "",

    // ESTIMATED full-week margin, for use while costs are still being filled in.
    //
    // Method: price the uncovered units at the units-weighted average cost of the
    // covered ones, then subtract from full-week net sales. Stated assumption —
    // the uncovered units cost roughly what the covered ones did.
    //
    // That assumption is the weak point and must travel with the number. The
    // uncovered SKUs are not a random sample: sweatpants and a tee, where
    // sweatpants almost certainly cost more than the catalogue average. So the
    // estimate is more likely optimistic than pessimistic. It is a working
    // figure, never a measurement, and `margin_basis` says which it is.
    gross_margin_estimated: estimatedMargin,
    gross_margin_rate_estimated: estimatedMarginRate,
    estimated_unit_cost_applied: avgCoveredUnitCost,
    uncovered_units: weeklySoldUnits - weeklyCoveredUnits,

    // measured | estimated | unavailable — the single field a consumer should
    // branch on before rendering any margin number.
    margin_basis: weeklyFullyCovered
      ? "measured"
      : (estimatedMargin === "" ? "unavailable" : "estimated"),
    estimate_assumption:
      weeklyFullyCovered || estimatedMargin === ""
        ? ""
        : "Rate computed on the SKU (Orders API) basis by pricing uncovered units at the units-weighted average cost of covered units, then applied to the ShopifyQL weekly net sales. Likely optimistic: the uncovered SKUs skew toward higher-cost items.",
    reversed_unit_cost: coveredSkuRows.length ? r2(weeklyReversedCost) : "",

    // Booked in the week the cancellation was ENTERED, not the week the order
    // margin curve must read this first: across drop weeks the shape is an
    // artifact of batch timing, not economics.
    reversed_cost_basis: "cancel_week",

    // RESOLVED 2026-09-05 (founder): cancelled goods ARE returned to inventory
    // and resold. So this is NOT a write-off and must never be deducted from
    // margin. It is the goods value that cycled out and back — a working-capital
    // and freight cost, useful for sizing RTO's drag on cash and for the
    // round-trip shipping bill, not for margin.
    reversed_cost_is_write_off: "no",
    reversed_cost_meaning: "goods_value_cycled_not_lost",
    sold_units: weeklySoldUnits,
    covered_units: weeklyCoveredUnits,
    missing_cost_skus: soldSkuRows
      .filter((r) => metricOrBlank(r.unit_cost) === "")
      .map((r) => ({ sku: clean(r.sku), product_title: clean(r.product_title), units_sold: num(r.units_sold) }))
      .slice(0, 20)
  };

  const activeSkus = skuRows.filter((r) => r.status === "ACTIVE").length;
  const soldSkus = skuRows.filter((r) => num(r.units_sold) > 0).length;
  const stockoutSkus = skuRows.filter((r) => r.is_oos === "TRUE").length;
  const stockoutSoldSkus = skuRows.filter((r) => num(r.units_sold) > 0 && r.is_oos === "TRUE").length;
  const endingInventoryUnits = skuRows.reduce((sum, r) => sum + num(r.ending_inventory_units), 0);

  const topProductRevenue =
    [...productRows].sort((a, b) => num(b.net_sales) - num(a.net_sales))[0]?.product_title || "";

  const topProductUnits =
    [...productRows].sort((a, b) => num(b.units_sold) - num(a.units_sold))[0]?.product_title || "";

  const topSkuUnits =
    [...skuRows].sort((a, b) => num(b.units_sold) - num(a.units_sold))[0]?.sku || "";

  const weeklyRow = {
    week_start: boundaries.week_start,
    week_end: boundaries.week_end,
    synced_at: syncedAt,
    shop_domain: config.shopDomain,
    currency: config.currency,
    gross_sales: r2(aggregate.weekly.gross_sales),
discounts: r2(aggregate.weekly.discounts),
discount_rate: r4(div(aggregate.weekly.discounts, aggregate.weekly.gross_sales)),
sales_reversals: r2(aggregate.weekly.refunds),
sales_reversal_rate: r4(div(aggregate.weekly.refunds, aggregate.weekly.gross_sales)),
net_sales: r2(aggregate.weekly.net_sales),
shipping_revenue: r2(aggregate.weekly.shipping_revenue),
taxes: r2(aggregate.weekly.taxes),
total_sales: r2(aggregate.weekly.total_sales),

orders: aggregate.weekly.orders,

aov: r2(div(
  num(aggregate.weekly.gross_sales) - num(aggregate.weekly.discounts),
  aggregate.weekly.orders
)),

total_quantity_ordered: aggregate.weekly.total_quantity_ordered,
net_items_sold: aggregate.weekly.net_items_sold,
returned_items: aggregate.weekly.returned_items,
returned_orders: aggregate.weekly.returned_orders,

item_return_rate: r4(div(
  aggregate.weekly.returned_items,
  aggregate.weekly.total_quantity_ordered
)),

order_return_rate: r4(div(
  aggregate.weekly.returned_orders,
  aggregate.weekly.orders
)),

items_per_order_ordered: r2(div(
  aggregate.weekly.total_quantity_ordered,
  aggregate.weekly.orders
)),

net_items_per_order: r2(div(
  aggregate.weekly.net_items_sold,
  aggregate.weekly.orders
)),
    active_skus: activeSkus,
    sold_skus: soldSkus,
    stockout_skus: stockoutSkus,
    stockout_sold_skus: stockoutSoldSkus,
    sold_sku_oos_rate: r4(div(stockoutSoldSkus, soldSkus)),
    ending_inventory_units: endingInventoryUnits,
weekly_sell_through_rate: sellThrough(aggregate.weekly.net_items_sold, endingInventoryUnits),
    top_product_by_revenue: topProductRevenue,
    top_product_by_units: topProductUnits,
    top_sku_by_units: topSkuUnits,

    // P1.9 attribution. All magnitudes are POSITIVE (see the sign convention
    // note on computeReversalAttribution): net_sales already has this week's
    // BOOKED reversals subtracted, so add those back and subtract this week's
    // own cohort instead. Blank, never zero, when attribution is unavailable —
    // a fabricated 0 would read as "no reversals" (non-negotiable #2).
    net_sales_attributed: attribution?.available
      ? r2(
          num(aggregate.weekly.net_sales) +
            num(aggregate.weekly.refunds) -
            num(attribution.reversals_for_orders_placed_in_week)
        )
      : "",
    reversals_for_orders_placed_in_week: attribution?.available
      ? attribution.reversals_for_orders_placed_in_week
      : "",
    net_sales_attributed_as_of: attribution?.available ? attribution.as_of : "",
    // TRUE/FALSE as text: the sheet has no boolean type and blank must stay
    // distinguishable from false.
    attribution_settled: attribution?.available
      ? (attribution.attribution_settled ? "TRUE" : "FALSE")
      : "",
    attribution_age_days: attribution?.available ? attribution.attribution_age_days : "",
    reversals_booked_cross_week_pct: attribution?.available
      ? attribution.reversals_booked_cross_week_pct
      : "",
    reversals_unattributed: attribution?.available ? attribution.reversals_unattributed : "",
    reversal_lag_p50_days: attribution?.available ? attribution.reversal_lag_p50_days : "",
    reversal_lag_p90_days: attribution?.available ? attribution.reversal_lag_p90_days : "",

    // P1.2. Blank, never zero, when no drop governs the week — a 0 would read as
    // "the drop is today".
    drop_id: dropPosition?.drop_id || "",
    days_since_drop: dropPosition ? dropPosition.days_since_drop : "",
    drop_week_index: dropPosition ? dropPosition.drop_week_index : "",
    drop_week_label: dropPosition?.drop_week_label || "",
    drop_lift: dropLift(dropPosition, aggregate.weekly.orders),

    // complete: a blended margin over partial coverage describes only the
    // covered share, and presenting it as the week's margin would be a
    // fabricated number dressed as a measurement.
    // P1.24 measured delivery outcome, from courier events. Not estimated.
    delivered_orders: delivery ? delivery.delivered : "",
    not_delivered_orders: delivery ? delivery.not_delivered : "",
    delivery_pending_orders: delivery ? delivery.pending : "",
    not_delivered_rate: delivery ? delivery.not_delivered_rate : "",
    post_dispatch_failures: delivery ? delivery.post_dispatch_failures : "",
    failures_without_carrier_data: delivery ? delivery.failures_without_carrier_data : "",
    post_dispatch_share: delivery ? delivery.post_dispatch_share : "",
    carrier_reporting_rate: delivery ? delivery.carrier_reporting_rate : "",
    delivery_settled: delivery ? (delivery.delivery_settled ? "TRUE" : "FALSE") : "",
    median_days_to_outcome: delivery ? delivery.median_days_to_outcome : "",
    multi_attempt_orders: delivery ? delivery.multi_attempt_orders : "",

    attribution_health: attributionCapture?.health || "",
    unattributed_share: attributionCapture ? attributionCapture.unattributed_share : "",
    attributed_orders: attributionCapture ? attributionCapture.attributed_orders : "",
    freight_outbound_cost: freight ? freight.outbound_cost : "",
    freight_return_cost: freight ? freight.return_cost : "",
    freight_total_cost: freight ? freight.total_cost : "",
    freight_priced_orders: freight ? freight.priced_orders : "",
    freight_coverage_rate: freight ? freight.coverage_rate : "",
    freight_basis: freight ? freight.basis : "",
    cod_collected_value: freight ? freight.cod_collected_value : "",
    cod_fee: freight ? freight.cod_fee : "",
    cod_fee_rate: freight ? freight.cod_fee_rate : "",
    cod_fee_basis: freight ? freight.cod_fee_basis : "",

    attributed_platforms: attributionCapture ? attributionCapture.attributed_platforms : "",
    non_meta_attributed_orders: attributionCapture ? attributionCapture.non_meta_attributed_orders : "",
    cogs_coverage_rate: weeklyCogs.coverage_rate,
    gross_margin: weeklyCogs.gross_margin,
    gross_margin_rate: weeklyCogs.gross_margin_rate,
    margin_basis: weeklyCogs.margin_basis,
    gross_margin_estimated: weeklyCogs.gross_margin_estimated,
    gross_margin_rate_estimated: weeklyCogs.gross_margin_rate_estimated,
    covered_gross_margin: weeklyCogs.covered_gross_margin,
    covered_gross_margin_rate: weeklyCogs.covered_gross_margin_rate,
    reversed_unit_cost: weeklyCogs.reversed_unit_cost
  };

  const snapshotRows = skuRows.map((r) => ({
    snapshot_at: syncedAt,
    week_start: boundaries.week_start,
    product_id: r.product_id,
    product_title: r.product_title,
    variant_id: r.variant_id,
    variant_title: r.variant_title,
    sku: r.sku,
    product_type: r.product_type,
    vendor: r.vendor,
    status: r.status,
    featured_image_url: r.featured_image_url,
    current_stock: r.ending_inventory_units,
    inventory_policy: variantMap.get(r.variant_id)?.inventory_policy || "",
    is_oos: r.is_oos,
    current_3d_units: r.current_3d_units,
    current_7d_units: r.current_7d_units,
    current_14d_units: r.current_14d_units,
    current_30d_units: r.current_30d_units,
    daily_velocity_7d: r.daily_velocity_7d,
    days_of_cover_7d: r.days_of_cover_7d,
    stock_left_pct: r.stock_left_pct
  }));

  return {
    cogs: weeklyCogs,
    weeklyRow,
    productRows,
    skuRows,
    snapshotRows
  };
}

function severityRank(s) {
  return {
    Critical: 0,
    Action: 1,
    Watch: 2,
    Info: 3
  }[s] ?? 9;
}

function buildDiagnoses({ boundaries, syncedAt, productRows, skuRows }) {
  const productDiagnosis = [];
  const skuDiagnosis = [];

  function addProduct(r, severity, label, evidence, cause, action, check) {
    productDiagnosis.push({
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      synced_at: syncedAt,
      product_id: r.product_id,
      product_title: r.product_title,
      severity,
      diagnosis_label: label,
      evidence,
      cause_guess: cause,
      recommended_action: action,
      owner: "",
      next_week_check: check,
      net_sales: r.net_sales,
      units_sold: r.units_sold,
      ending_inventory_units: r.ending_inventory_units,
      oos_variant_rate: r.oos_variant_rate,
      daily_velocity_7d: r.daily_velocity_7d,
      days_of_cover_7d: r.days_of_cover_7d,
      weekly_sell_through_rate: r.weekly_sell_through_rate
    });
  }

  function addSku(r, severity, label, evidence, cause, action, check) {
    skuDiagnosis.push({
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      synced_at: syncedAt,
      product_id: r.product_id,
      product_title: r.product_title,
      variant_id: r.variant_id,
      variant_title: r.variant_title,
      sku: r.sku,
      severity,
      diagnosis_label: label,
      evidence,
      cause_guess: cause,
      recommended_action: action,
      owner: "",
      next_week_check: check,
      units_sold: r.units_sold,
      ending_inventory_units: r.ending_inventory_units,
      is_oos: r.is_oos,
      daily_velocity_3d: r.daily_velocity_3d,
      daily_velocity_7d: r.daily_velocity_7d,
      days_of_cover_7d: r.days_of_cover_7d,
      weekly_sell_through_rate: r.weekly_sell_through_rate
    });
  }

  for (const r of skuRows) {
    const stock = num(r.ending_inventory_units);
    const units = num(r.units_sold);
    const u30 = num(r.current_30d_units);
    const v3 = num(r.daily_velocity_3d);
    const v7 = num(r.daily_velocity_7d);
    const cover = num(r.days_of_cover_7d);

    if (units > 0 && r.is_oos === "TRUE") {
      addSku(r, "Critical", "STOCKOUT_WINNER", `Sold ${units} units this week and current stock is 0.`, "Winner SKU has stocked out.", "Restock urgently or push substitute. Stop sending traffic to unavailable variant.", "Check if stock/substitute recovered sales next week.");
    } else if (v7 > 0 && cover < 7) {
      addSku(r, "Critical", "CRITICAL_DAYS_COVER", `7d velocity ${v7}/day and only ${cover} days of cover.`, "Demand is faster than available stock.", "Restock urgently and protect this SKU from unnecessary discounting.", "Check stock cover and lost sales risk next week.");
    } else if (v7 > 0 && cover < 14) {
      addSku(r, "Action", "LOW_DAYS_COVER", `7d velocity ${v7}/day and ${cover} days of cover.`, "Stock may run out soon.", "Prepare reorder or shift demand to close substitute.", "Check if cover moved above 14 days.");
    }

    if (v7 > 0 && v3 > v7 * 1.3) {
      addSku(r, "Watch", "DEMAND_SPIKE", `3d velocity ${v3}/day is 30%+ above 7d velocity ${v7}/day.`, "Recent demand spike.", "Monitor closely, avoid discounting, prepare restock if trend continues.", "Check whether 3d spike sustained next week.");
    }

    if (u30 === 0 && stock > 10) {
      addSku(r, "Action", "DEAD_SKU", `0 units sold in 30d while ${stock} units remain.`, "Dead stock or weak demand/exposure.", "Do not reorder. Consider bundle, markdown, or lower-priority placement.", "Check clearance movement next week.");
    } else if (u30 > 0 && u30 < 3 && stock > 10) {
      addSku(r, "Watch", "SLOW_SKU", `${u30} units sold in 30d while ${stock} units remain.`, "Slow mover.", "Bundle/discount/test placement before reordering.", "Check if velocity improved next week.");
    }
  }

  for (const r of productRows) {
    const stock = num(r.ending_inventory_units);
    const units = num(r.units_sold);
    const u30 = num(r.current_30d_units);
    const v7 = num(r.daily_velocity_7d);
    const cover = num(r.days_of_cover_7d);
    const oosRate = num(r.oos_variant_rate);

    if (units > 0 && v7 > 0 && cover < 7) {
      addProduct(r, "Critical", "RESTOCK_PRIORITY", `Sold ${units} units this week with ${cover} days of cover.`, "Winning product may run out.", "Restock urgently. If restock is impossible, push substitute products.", "Check whether product still has enough sellable sizes next week.");
    }

    if (units > 0 && oosRate >= 0.5) {
      addProduct(r, "Critical", "MANY_VARIANTS_OOS", `${Math.round(oosRate * 100)}% of variants are OOS.`, "Size/variant availability is limiting product sales.", "Stop pushing unavailable variants, restock key sizes, and push substitute.", "Check OOS variant rate next week.");
    }

    if (u30 === 0 && stock > 20) {
      addProduct(r, "Action", "DEAD_STOCK", `0 units sold in 30d while ${stock} units remain.`, "Product is not moving.", "Do not reorder. Use clearance, bundles, or repositioning.", "Check if clearance moved units next week.");
    } else if (u30 > 0 && u30 < 5 && stock > 20) {
      addProduct(r, "Watch", "SLOW_MOVER", `${u30} units sold in 30d while ${stock} units remain.`, "Slow product velocity.", "Improve placement or offer; consider bundle/discount if no improvement.", "Check 7d and 30d velocity next week.");
    }

    if (num(r.weekly_sell_through_rate) >= 0.4 && cover < 14) {
      addProduct(r, "Action", "FAST_SELLER_LOW_STOCK", `Sell-through ${r.weekly_sell_through_rate} and ${cover} days cover.`, "High demand with low remaining cover.", "Protect winner from discounting and plan restock.", "Check sell-through and cover next week.");
    }
  }

  productDiagnosis.sort((a, b) => severityRank(a.severity) - severityRank(b.severity));
  skuDiagnosis.sort((a, b) => severityRank(a.severity) - severityRank(b.severity));

  return {
    productDiagnosis,
    skuDiagnosis
  };
}

function pctChange(current, previous) {
  if (previous === "" || previous == null || num(previous) === 0) return "";
  return r4((num(current) - num(previous)) / num(previous));
}

function avg(nums) {
  const cleanNums = nums.map(num).filter((n) => Number.isFinite(n));
  return cleanNums.length ? cleanNums.reduce((a, b) => a + b, 0) / cleanNums.length : "";
}

function metric(row, name) {
  return row ? num(row[name]) : "";
}

function cvrForWeekFromMaps(weekStart, shopifyHistory, ga4History, reportHistory) {
  const sourceCvr = shopifyConversionRate(
    shopifyHistory.get(weekStart) || null,
    ga4History.get(weekStart) || null
  );
  if (sourceCvr !== "") return sourceCvr;
  return metric(reportHistory.get(weekStart) || null, "ga4_shopify_cvr");
}

function cvrComparisonForWeek(boundaries, currentValue, shopifyHistory, ga4History, reportHistory) {
  if (currentValue === "") {
    return { previous: "", wow: "", avg4: "", vs4: "" };
  }

  const current = num(currentValue);
  const previousFourWeekStarts = [-7, -14, -21, -28].map((d) =>
    addDays(boundaries.week_start, d)
  );
  const prev = cvrForWeekFromMaps(
    addDays(boundaries.week_start, -7),
    shopifyHistory,
    ga4History,
    reportHistory
  );
  const previousFourCvrValues = previousFourWeekStarts
    .map((weekStart) => cvrForWeekFromMaps(weekStart, shopifyHistory, ga4History, reportHistory))
    .filter((v) => v !== "");
  const avg4 = previousFourCvrValues.length === 4 ? avg(previousFourCvrValues) : "";

  return {
    previous: prev === "" ? "" : r4(prev),
    wow: prev === "" ? "" : pctChange(current, prev),
    avg4: avg4 === "" ? "" : r4(avg4),
    vs4: avg4 === "" ? "" : pctChange(current, avg4)
  };
}





function buildReportWeekly(
  boundaries,
  syncedAt,
  weeklyRow,
  ga4Row,
  metaRow,
  shopifyHistory,
  ga4History,
  reportHistory,
  productDiagnosis,
  skuDiagnosis
) {
  const previousShopify = shopifyHistory.get(addDays(boundaries.week_start, -7)) || null;
  const previousReport = reportHistory.get(addDays(boundaries.week_start, -7)) || null;

  const previousFourWeekStarts = [-7, -14, -21, -28].map((d) =>
    addDays(boundaries.week_start, d)
  );

  const previousFourShopifyRows = previousFourWeekStarts
    .map((w) => shopifyHistory.get(w))
    .filter(Boolean);

  const previousFourReportRows = previousFourWeekStarts
    .map((w) => reportHistory.get(w))
    .filter(Boolean);

  function compShopify(name) {
    const current = metric(weeklyRow, name);
    const prev = previousShopify ? metric(previousShopify, name) : "";
    const avg4 =
      previousFourShopifyRows.length === 4
        ? avg(previousFourShopifyRows.map((r) => metric(r, name)))
        : "";

    return {
      previous: prev === "" ? "" : r2(prev),
      wow: prev === "" ? "" : pctChange(current, prev),
      avg4: avg4 === "" ? "" : r2(avg4),
      vs4: avg4 === "" ? "" : pctChange(current, avg4)
    };
  }

  function compReport(name, currentValue) {
    const current = num(currentValue);
    const prev = previousReport ? metric(previousReport, name) : "";
    const avg4 =
      previousFourReportRows.length === 4
        ? avg(previousFourReportRows.map((r) => metric(r, name)))
        : "";

    return {
      previous: prev === "" ? "" : r2(prev),
      wow: prev === "" ? "" : pctChange(current, prev),
      avg4: avg4 === "" ? "" : r2(avg4),
      vs4: avg4 === "" ? "" : pctChange(current, avg4)
    };
  }

  const ga4 = ga4Row || {};
  const meta = metaRow || {};

  const shopifyNetSales = num(weeklyRow.net_sales);
  const shopifyOrders = num(weeklyRow.orders);
  const shopifyItems = num(weeklyRow.net_items_sold);
  const shopifyAov = num(weeklyRow.aov);

  const ga4Sessions = num(ga4.sessions);
  const ga4Users = num(ga4.users);
  const ga4EngagedSessions = num(ga4.engaged_sessions);
  const ga4EngagementRate = num(ga4.engagement_rate);
  const ga4ProductViews = num(ga4.view_item_events);
  const ga4AddToCarts = num(ga4.add_to_cart_events);
  const ga4BeginCheckouts = num(ga4.begin_checkout_events);
  const ga4Purchases = num(ga4.purchase_events);
  const ga4ProductViewRate = num(ga4.product_view_rate);
  const ga4AtcRate = num(ga4.atc_rate);
  const ga4CheckoutStartRate = num(ga4.checkout_start_rate);
  const ga4CheckoutCompletionRate = num(ga4.checkout_completion_rate);

  const metaSpend = num(meta.spend);
  const metaImpressions = num(meta.impressions);
  const metaReach = num(meta.reach);
  const metaFrequency = num(meta.frequency);
  const metaCpm = num(meta.cpm);
  const metaCtrLink = num(meta.ctr_link);
  const metaCpcLink = num(meta.cpc_link);
  const metaLinkClicks = num(meta.link_clicks);
  const metaLpvs = num(meta.landing_page_views);
  const metaPurchases = num(meta.purchases);
  const metaPurchaseValue = num(meta.purchase_value);
  const metaCpa = num(meta.cpa);
  const metaRoas = num(meta.roas);
  const metaLpvRate = num(meta.lpv_rate_from_link_click);

  const shopifyCvr = shopifyConversionRate(weeklyRow, ga4Row);
  const mer = div(shopifyNetSales, metaSpend);
  const blendedCac = div(metaSpend, shopifyOrders);
  const spendPctRevenue = div(metaSpend, shopifyNetSales);

  // Every figure above divides by META spend alone. That is only the whole story
  // not: `_cw_platform: tiktok` appears in the capture attributes while the
  // pipeline has no TikTok source.
  //
  // them presenting an incomplete denominator as a complete one, which is the
  // same numerator/denominator-from-different-populations trap that has already
  // shipped three times here.
  //
  // Derived from the orders rather than from a config flag, so it self-corrects:
  // the day TikTok stops running, the basis goes back to complete on its own, and
  // the day a fourth channel starts it is caught without anyone remembering to
  // update anything.
  const nonMetaOrders = metricOrBlank(weeklyRow.non_meta_attributed_orders);
  const capturedPlatforms = clean(weeklyRow.attributed_platforms);
  const captureLive = clean(weeklyRow.attribution_health) !== "not_live" &&
    clean(weeklyRow.attribution_health) !== "";

  const paidSpendBasis = !captureLive
    ? "meta_only_unverified"
    : (nonMetaOrders !== "" && num(nonMetaOrders) > 0 ? "meta_only_incomplete" : "meta_only_confirmed");

  const paidSpendNote =
    paidSpendBasis === "meta_only_incomplete"
      ? `Understates spend: ${num(nonMetaOrders)} order${num(nonMetaOrders) === 1 ? "" : "s"} came from ${capturedPlatforms.split(",").filter((x) => x && x !== "meta").join(" and ") || "another platform"}, whose spend this pipeline does not sync. Efficiency reads better than it is.`
      : paidSpendBasis === "meta_only_unverified"
        ? "Attribution capture is not live, so whether Meta was the only paid channel this week cannot be verified."
        : "";

  // Reversed orders are still a full loss even though the goods come back.
  // What is lost is the revenue, the acquisition spend, and the round-trip
  // freight — only the goods are recovered. Three consequences, none of which
  // the pipeline expressed until now:
  //
  //  1. blended_cac divides spend by ALL orders, including ones that came back.
  //     That is the ordered-revenue error applied to CAC: it flatters the number
  //     by exactly the reversal rate.
  //  2. The share of ad spend that bought nothing was never stated.
  //  3. Neither figure appeared anywhere a decision gets made.
  //
  // Share is taken on VALUE (sales_reversals / gross_sales) rather than order
  // counts, because sales_reversals is the verified cancellation measure while
  // returned_orders is derived from the refund path and measures something else.
  // Which reversals belong to this week's SPEND is the cohort's, not the ones
  // that happened to be keyed this week. Using booked reversals made the Jul 26
  // drop week read 0.9% — because its cancellations had not been entered yet —
  // that. The same cross-week defect as P1.9, surfacing in a new metric.
  //
  // Use the order-week attributed figure when the week has settled; fall back to
  // booked otherwise, and always say which was used.
  const grossForShare = num(weeklyRow.gross_sales);
  const attributedReversals = metricOrBlank(weeklyRow.reversals_for_orders_placed_in_week);
  const attributionSettledForShare =
    clean(weeklyRow.attribution_settled).toUpperCase() === "TRUE";

  const useAttributed = attributionSettledForShare && attributedReversals !== "";
  const reversalBasis = useAttributed ? "order_week_attributed" : "booked_in_week";

  const reversalShare =
    grossForShare > 0
      ? r4((useAttributed ? attributedReversals : num(weeklyRow.sales_reversals)) / grossForShare)
      : "";

  // the reversal-share estimate only while parcels are still in flight, and say
  // which was used — an estimate and a measurement must never look alike.
  const measuredDelivered = metricOrBlank(weeklyRow.delivered_orders);
  const deliverySettled = clean(weeklyRow.delivery_settled).toUpperCase() === "TRUE";
  const useMeasuredDelivery = deliverySettled && measuredDelivered !== "";

  const deliveredOrders = useMeasuredDelivery
    ? measuredDelivered
    : (reversalShare === "" || shopifyOrders === ""
        ? ""
        : Math.round(shopifyOrders * (1 - reversalShare)));

  const deliveredOrdersBasis = useMeasuredDelivery ? "courier_measured" : "reversal_share_estimate";

  // CAC against orders that actually stuck. Always >= blended_cac.
  const deliveredCac = deliveredOrders === "" || deliveredOrders === 0 ? "" : div(metaSpend, deliveredOrders);

  // Ad spend consumed by orders that reversed. This is the figure that makes RTO
  // comparable against the cost of pre-dispatch confirmation calls.
  const wastedAdSpend = reversalShare === "" ? "" : r2(metaSpend * reversalShare);

  const netSales = compShopify("net_sales");
  const orders = compShopify("orders");
  const units = compShopify("net_items_sold");
  const aov = compShopify("aov");

  const shopifyCvrComp = cvrComparisonForWeek(
    boundaries,
    shopifyCvr,
    shopifyHistory,
    ga4History,
    reportHistory
  );
  const merComp = compReport("mer", mer);

  const restockPriorityCount =
    productDiagnosis.filter((d) =>
      ["RESTOCK_PRIORITY", "FAST_SELLER_LOW_STOCK"].includes(d.diagnosis_label)
    ).length +
    skuDiagnosis.filter((d) =>
      ["STOCKOUT_WINNER", "CRITICAL_DAYS_COVER", "LOW_DAYS_COVER"].includes(d.diagnosis_label)
    ).length;

  const deadStockCount =
    productDiagnosis.filter((d) => d.diagnosis_label === "DEAD_STOCK").length +
    skuDiagnosis.filter((d) => d.diagnosis_label === "DEAD_SKU").length;

  const slowMoverCount =
    productDiagnosis.filter((d) => d.diagnosis_label === "SLOW_MOVER").length +
    skuDiagnosis.filter((d) => d.diagnosis_label === "SLOW_SKU").length;

  const combinedDiagnosis = [...skuDiagnosis, ...productDiagnosis].sort(
    (a, b) => severityRank(a.severity) - severityRank(b.severity)
  );

  const hasGa4 = !!ga4Row;
  const hasMeta = !!metaRow;

  // P1.9 settling gate.
  //
  // An unsettled week's own cohort reversals have not arrived yet, so its
  // attributed figure reads HIGH and decays as batches land — measured at 25-45%
  // on week 2026-08-23 at 6 days of age. A decline computed against such a week
  // is an accounting artifact, not a commercial signal, and would land exactly
  // when the next drop date is being decided.
  //
  // salesDown stays as-is: as-booked net_sales is a complete, stable fact even
  // when attribution is not. What the gate withholds is the CONFIRMED reading
  // that is allowed to escalate to Critical, and every attributed comparison.
  const attributionSettled = clean(weeklyRow?.attribution_settled).toUpperCase() === "TRUE";
  const attributionAgeDays = metricOrBlank(weeklyRow?.attribution_age_days);

  const salesDown =
    netSales.wow !== "" && num(netSales.wow) <= -0.1;

  // P1.2 post-drop suppression.
  //
  // Revenue is drop-driven: each drop spikes then decays toward a floor, so a
  // WoW decline in W+1..W+4 is expected decay, not a conversion failure. But
  // suppressing on days_since_drop ALONE is too blunt. Measured across the
  // and CTR dropped 24% in the single step W0->W+1: the decline was attention,
  // not conversion.
  //
  // So the suppression requires BOTH the drop window AND evidence that the loss
  // is top-of-funnel. A drop-normalised week with FLAT CTR and falling orders is
  // a real conversion problem — that is the case the diagnosis exists for, and
  // it must still raise.
  // W+1..W+4, keyed off the drop-relative index rather than raw elapsed days.
  // A day window is wrong for mid-week drops — see dropPositionForWeek.
  const dropWeekIndex = metricOrBlank(weeklyRow?.drop_week_index);
  const inPostDropWindow =
    dropWeekIndex !== "" && num(dropWeekIndex) >= 1 && num(dropWeekIndex) <= 4;

  // Previous week's Meta figures come from ReportWeekly, which already carries
  // meta_ctr and meta_link_clicks — no metaHistory parameter needed.
  const ctrCurrent = metricOrBlank(meta.ctr_link);
  const ctrPrevious = metricOrBlank(previousReport?.meta_ctr);
  const ctrDecayed =
    ctrCurrent !== "" && ctrPrevious !== "" && ctrPrevious !== 0 &&
    (ctrCurrent - ctrPrevious) / Math.abs(ctrPrevious) <= -0.1;

  // Click-to-order roughly flat means conversion is holding: the loss is upstream.
  const clickToOrder = div(num(weeklyRow?.orders), num(meta.link_clicks));
  const clickToOrderPrev = div(num(previousShopify?.orders), num(previousReport?.meta_link_clicks));
  const clickToOrderFlat =
    clickToOrder !== "" && clickToOrderPrev !== "" && clickToOrderPrev !== 0 &&
    Math.abs((clickToOrder - clickToOrderPrev) / Math.abs(clickToOrderPrev)) <= 0.15;

  const postDropDecaySuppressed = inPostDropWindow && ctrDecayed && clickToOrderFlat;

  // Only a settled week may drive a Critical revenue-decline diagnosis, and only
  // when the decline is not explained by post-drop top-of-funnel decay.
  const salesDownConfirmed = salesDown && attributionSettled && !postDropDecaySuppressed;

  // Attributed comparisons require BOTH weeks settled. Blank, never zero:
  // "we cannot compare these yet" is not "no change" (non-negotiable #2).
  const attributedComparison = (() => {
    const current = metricOrBlank(weeklyRow?.net_sales_attributed);
    if (current === "" || !attributionSettled) {
      return { current, previous: "", wow: "", reason: attributionSettled ? "no_value" : "current_week_unsettled" };
    }

    const prevRow = previousShopify;
    const prevSettled = clean(prevRow?.attribution_settled).toUpperCase() === "TRUE";
    const previous = metricOrBlank(prevRow?.net_sales_attributed);

    if (!prevSettled || previous === "") {
      return { current, previous: "", wow: "", reason: "comparison_week_unsettled" };
    }

    return {
      current,
      previous,
      wow: previous === 0 ? "" : r4((current - previous) / Math.abs(previous)),
      reason: ""
    };
  })();

  const ordersDown =
    orders.wow !== "" && num(orders.wow) <= -0.1;

  const aovDown =
    aov.wow !== "" && num(aov.wow) <= -0.08;

  const cvrDown =
    shopifyCvrComp.wow !== "" && num(shopifyCvrComp.wow) <= -0.1;

  const merDown =
    merComp.wow !== "" && num(merComp.wow) <= -0.1;

  let ga4MainProblem = "";
  let metaMainProblem = "";
  let shopifyMainProblem = "";
  let mainDriver = "";
  let finalDiagnosis = "";
  let biggestRisk = "";
  let biggestOpportunity = "";
  const actionCandidates = [];

  // ── Shopify diagnosis ────────────────────────────────────────────────

  if (num(weeklyRow.sold_sku_oos_rate) >= 0.2) {
    shopifyMainProblem =
      "Inventory risk: a high share of sold SKUs are currently out of stock.";
    actionCandidates.push("Prioritize restock/substitutes for sold-out winning SKUs.");
  } else if (num(weeklyRow.refund_rate) >= 0.2 || num(weeklyRow.item_return_rate) >= 0.2) {
    shopifyMainProblem =
      "Revenue quality risk: refunds/returns are materially pressuring net sales.";
    actionCandidates.push("Review high-return products/SKUs and identify fit, quality, or expectation issues.");
  } else if (restockPriorityCount > 0) {
    shopifyMainProblem =
      "Restock risk: winning products/SKUs need inventory attention.";
    actionCandidates.push("Protect fast sellers from discounting and prepare restock/reallocation.");
  } else if (deadStockCount > 0) {
    shopifyMainProblem =
      "Dead stock exists and needs clearance or merchandising action.";
    actionCandidates.push("Build clearance/bundle plan for dead-stock SKUs.");
  } else {
    shopifyMainProblem =
      "No major Shopify inventory/returns issue detected from current thresholds.";
  }

  // ── GA4 funnel diagnosis ─────────────────────────────────────────────

  if (!hasGa4) {
    ga4MainProblem = "GA4 row missing for this week.";
    actionCandidates.push("Sync GA4 for this week before presenting funnel diagnosis.");
  } else if (ga4Sessions <= 0) {
    ga4MainProblem = "GA4 sessions are zero or missing.";
    actionCandidates.push("Check GA4 tracking and data collection.");
  } else if (ga4ProductViewRate > 0 && ga4ProductViewRate < 0.3) {
    ga4MainProblem =
      "Low product-view rate: traffic is not reaching PDPs efficiently.";
    actionCandidates.push("Audit landing pages, collections, navigation, and ad landing URLs.");
  } else if (ga4AtcRate > 0 && ga4AtcRate < GA4_LOW_ATC_RATE) {
    ga4MainProblem =
      "Low add-to-cart rate: PDP/product/price/offer may be weak.";
    actionCandidates.push("Audit PDP offer, price, size availability, product photos, and above-the-fold clarity.");
  } else if (ga4CheckoutStartRate > 0 && ga4CheckoutStartRate < 0.35) {
    ga4MainProblem =
      "Low checkout-start rate after add-to-cart: cart/shipping/offer friction may exist.";
    actionCandidates.push("Audit cart page, shipping fees, delivery promise, and checkout CTA clarity.");
  } else if (ga4CheckoutCompletionRate > 0 && ga4CheckoutCompletionRate < 0.35) {
    ga4MainProblem =
      "Low checkout completion: payment, trust, checkout UX, or delivery friction may exist.";
    actionCandidates.push("Audit checkout payment success, COD/prepaid behavior, trust signals, and delivery promise.");
  } else {
    ga4MainProblem =
      "GA4 funnel does not show an obvious major break from current thresholds.";
  }

  // ── Meta acquisition diagnosis ───────────────────────────────────────

  if (!hasMeta) {
    metaMainProblem = "Meta row missing for this week.";
    actionCandidates.push("Sync Meta for this week before presenting paid-media diagnosis.");
  } else if (metaSpend <= 0) {
    metaMainProblem = "Meta spend is zero or missing.";
    actionCandidates.push("Confirm whether paid ads were intentionally off this week.");
  } else if (metaRoas > 0 && metaRoas < 1.5) {
    metaMainProblem =
      "Meta ROAS is weak: paid acquisition efficiency is under pressure.";
    actionCandidates.push("Review top-spend ads/campaigns by ROAS, CPA, hook rate, and landing page view rate.");
  } else if (metaCtrLink > 0 && metaCtrLink < 0.008) {
    metaMainProblem =
      "Meta link CTR is weak: creative hook/offer may be underperforming.";
    actionCandidates.push("Refresh hooks, first frame, offer angle, and product proof in top-spend ads.");
  } else if (metaLpvRate > 0 && metaLpvRate < 0.5) {
    metaMainProblem =
      "Meta click-to-LPV rate is weak: click quality, tracking, or landing speed may be an issue.";
    actionCandidates.push("Check landing speed, destination URLs, UTMs, and click-to-session tracking gap.");
  } else if (metaFrequency > 0 && metaFrequency >= 3.5 && metaCtrLink < 0.012) {
    metaMainProblem =
      "Frequency is high while link CTR is soft: possible creative fatigue.";
    actionCandidates.push("Rotate creatives and reduce spend on fatigued ads/adsets.");
  } else {
    metaMainProblem =
      "Meta does not show an obvious acquisition break from current thresholds.";
  }

  // ── Main driver and final diagnosis ──────────────────────────────────

  if (salesDown && !hasGa4) {
    mainDriver = "Sales dropped, but GA4 is missing so traffic/funnel cause cannot be isolated.";
  } else if (salesDown && !hasMeta) {
    mainDriver = "Sales dropped, but Meta is missing so paid acquisition cause cannot be isolated.";
  } else if (salesDownConfirmed && ordersDown && cvrDown) {
    mainDriver = "Orders and conversion rate dropped. The main issue is likely onsite conversion/funnel quality.";
  } else if (salesDownConfirmed && ordersDown && hasGa4 && ga4Sessions > 0 && !cvrDown) {
    mainDriver = "Orders dropped while conversion did not materially drop. Traffic volume or traffic mix is likely the main driver.";
  } else if (salesDownConfirmed && aovDown) {
    mainDriver = "Net sales dropped with AOV pressure. Product mix, discounts, or lower-value orders likely contributed.";
  } else if (num(weeklyRow.sold_sku_oos_rate) >= 0.2) {
    mainDriver = "Inventory availability is likely constraining sales capture.";
  } else if (hasMeta && merDown && metaRoas < 2) {
    mainDriver = "Paid efficiency weakened. Meta appears to be a likely driver.";
  } else {
    mainDriver = "No single dominant driver detected. Review Shopify, GA4, and Meta sections together.";
  }

  if (num(weeklyRow.sold_sku_oos_rate) >= 0.2) {
    finalDiagnosis =
      "Inventory constraint is the highest-confidence issue: sold SKUs have meaningful OOS risk, which can block conversion even if traffic and demand exist.";
  } else if (num(weeklyRow.refund_rate) >= 0.2 || num(weeklyRow.item_return_rate) >= 0.2) {
    finalDiagnosis =
      "Returns/refunds are materially pressuring revenue quality. Diagnose high-return products/SKUs before scaling spend.";
  } else if (hasMeta && hasGa4 && metaSpend > 0 && metaRoas < 1.5) {
    finalDiagnosis =
      "Paid acquisition efficiency is the likely issue: Meta spend exists but ROAS is weak. Inspect top-spend ads and campaign efficiency.";
  } else if (hasGa4 && ga4Sessions > 0 && ga4AtcRate > 0 && ga4AtcRate < GA4_LOW_ATC_RATE) {
    finalDiagnosis =
      "Onsite product/PDP conversion is the likely issue: sessions exist but add-to-cart rate is weak.";
  } else if (hasGa4 && ga4CheckoutCompletionRate > 0 && ga4CheckoutCompletionRate < 0.35) {
    finalDiagnosis =
      "Checkout completion is the likely issue: users start checkout but do not complete purchases at a healthy rate.";
  } else if (restockPriorityCount > 0) {
    finalDiagnosis =
      "Main Shopify issue is restock risk on winning products/SKUs. Revenue may be protected by inventory action.";
  } else {
    finalDiagnosis =
      "No single dominant issue detected. Use product/SKU diagnostics and top Meta ads to decide the next action.";
  }

  biggestRisk =
    combinedDiagnosis.find((d) => d.severity === "Critical")?.diagnosis_label ||
    (num(weeklyRow.refund_rate) >= 0.2
      ? "High refund pressure"
      : hasMeta && metaRoas < 1.5
        ? "Weak paid acquisition efficiency"
        : "No critical risk detected");

  biggestOpportunity =
    weeklyRow.top_product_by_units
      ? `Scale/protect winner: ${weeklyRow.top_product_by_units}`
      : weeklyRow.top_product_by_revenue
        ? `Revenue driver: ${weeklyRow.top_product_by_revenue}`
        : "No clear product opportunity detected.";

  for (const d of combinedDiagnosis.slice(0, 3)) {
    if (d.recommended_action) actionCandidates.push(d.recommended_action);
  }

  const uniqueActions = [...new Set(actionCandidates.filter(Boolean))].slice(0, 3);

  return {
    week_start: boundaries.week_start,
    week_end: boundaries.week_end,
    synced_at: syncedAt,

    report_status:
      hasGa4 && hasMeta
        ? "Complete: Shopify + GA4 + Meta"
        : hasGa4
          ? "Partial: Shopify + GA4"
          : hasMeta
            ? "Partial: Shopify + Meta"
            : "Shopify only",

    executive_summary:
      `Net sales ${r2(shopifyNetSales)} ${weeklyRow.currency}; orders ${shopifyOrders}; ` +
      `AOV ${r2(shopifyAov)}; MER ${mer === "" ? "N/A" : r4(mer)}; ` +
      `Shopify CVR ${shopifyCvr === "" ? "N/A" : r4(shopifyCvr)}.`,

    main_driver: mainDriver,
    biggest_risk: biggestRisk,
    biggest_opportunity: biggestOpportunity,

    top_action_1: uniqueActions[0] || "Review Shopify, GA4, and Meta validation checks before presenting.",
    top_action_2: uniqueActions[1] || "Inspect top product/SKU and top Meta ad performance.",
    top_action_3: uniqueActions[2] || "Choose one primary action for next week and track it.",

    shopify_gross_sales: weeklyRow.gross_sales,
    shopify_net_sales: weeklyRow.net_sales,
    shopify_total_collected: "",
    shopify_orders: weeklyRow.orders,
    shopify_units_sold: weeklyRow.net_items_sold,
    shopify_aov: weeklyRow.aov,
    shopify_items_per_order: weeklyRow.net_items_per_order,
    shopify_discounts: weeklyRow.discounts,
    shopify_discount_rate: weeklyRow.discount_rate,
    shopify_sales_reversals: weeklyRow.sales_reversals,
    shopify_sales_reversal_rate: weeklyRow.sales_reversal_rate,
    shopify_net_sales_attributed: metricOrBlank(weeklyRow.net_sales_attributed),
    attribution_settled: clean(weeklyRow.attribution_settled),
    attribution_age_days: metricOrBlank(weeklyRow.attribution_age_days),

    // Blank whenever either week is unsettled, with the reason stated. A
    // rendered comparison must never look identical whether it was computed
    // against a settled week or a 6-day-old one.
    net_sales_attributed_previous_week: attributedComparison.previous,
    net_sales_attributed_wow_pct: attributedComparison.wow,
    attributed_comparison_blocked_reason: attributedComparison.reason,

    // §7: the weekly review header states drop position, always. Carried on the
    // report row rather than looked up, so the surface never has to join.
    drop_id: clean(weeklyRow?.drop_id),
    days_since_drop: metricOrBlank(weeklyRow?.days_since_drop),
    drop_week_label: clean(weeklyRow?.drop_week_label),
    drop_lift: metricOrBlank(weeklyRow?.drop_lift),
    // TRUE when the post-drop rule withheld a Critical, so the surface can say
    // why a decline is not flagged rather than silently not flagging it.
    post_drop_decay_suppressed: postDropDecaySuppressed ? "TRUE" : "FALSE",
    shopify_shipping_revenue: weeklyRow.shipping_revenue,
    shopify_active_skus: weeklyRow.active_skus,
    shopify_sold_skus: weeklyRow.sold_skus,
    shopify_stockout_sold_skus: weeklyRow.stockout_sold_skus,
    shopify_sold_sku_oos_rate: weeklyRow.sold_sku_oos_rate,
    shopify_ending_inventory_units: weeklyRow.ending_inventory_units,
    shopify_sell_through_rate: weeklyRow.weekly_sell_through_rate,
    shopify_restock_priority_count: restockPriorityCount,
    shopify_dead_stock_count: deadStockCount,
    shopify_slow_mover_count: slowMoverCount,
    shopify_main_problem_trigger: shopifyMainProblem,

    ga4_sessions: sourceValueOrBlank(ga4.sessions),
    ga4_users: sourceValueOrBlank(ga4.users),
    ga4_engaged_sessions: sourceValueOrBlank(ga4.engaged_sessions),
    ga4_engagement_rate: sourceValueOrBlank(ga4.engagement_rate),
    ga4_product_views: sourceValueOrBlank(ga4.view_item_events),
    ga4_add_to_carts: sourceValueOrBlank(ga4.add_to_cart_events),
    ga4_begin_checkouts: sourceValueOrBlank(ga4.begin_checkout_events),
    ga4_purchases: sourceValueOrBlank(ga4.purchase_events),
    ga4_product_view_rate: sourceValueOrBlank(ga4.product_view_rate),
    ga4_atc_rate: sourceValueOrBlank(ga4.atc_rate),
    ga4_checkout_start_rate: sourceValueOrBlank(ga4.checkout_start_rate),
    ga4_checkout_completion_rate: sourceValueOrBlank(ga4.checkout_completion_rate),
    ga4_shopify_cvr: r4(shopifyCvr),
    ga4_main_funnel_problem: ga4MainProblem,

    meta_spend: meta.spend || "",
    meta_impressions: meta.impressions || "",
    meta_reach: meta.reach || "",
    meta_frequency: meta.frequency || "",
    meta_cpm: meta.cpm || "",
    meta_ctr: meta.ctr_link || "",
    meta_cpc: meta.cpc_link || "",
    meta_link_clicks: meta.link_clicks || "",
    meta_landing_page_views: meta.landing_page_views || "",
    meta_purchases: meta.purchases || "",
    meta_purchase_value: meta.purchase_value || "",
    meta_cpa: meta.cpa || "",
    meta_roas: meta.roas || "",
    meta_main_problem: metaMainProblem,

    mer: r4(mer),
    blended_cac: r2(blendedCac),
    // Estimated from the reversal VALUE share, so it carries that basis.
    delivered_orders_estimated: deliveredOrders,
    delivered_cac_estimated: deliveredCac === "" ? "" : r2(deliveredCac),
    reversal_share_of_gross: reversalShare,
    reversal_share_basis: reversalBasis,
    delivered_orders_basis: deliveredOrdersBasis,
    paid_spend_basis: paidSpendBasis,
    paid_spend_note: paidSpendNote,
    reversal_wasted_ad_spend: wastedAdSpend,
    spend_as_pct_of_revenue: r4(spendPctRevenue),

    net_sales_previous_week: netSales.previous,
    net_sales_wow_pct: netSales.wow,
    net_sales_4w_avg: netSales.avg4,
    net_sales_vs_4w_avg_pct: netSales.vs4,

    orders_previous_week: orders.previous,
    orders_wow_pct: orders.wow,
    orders_4w_avg: orders.avg4,
    orders_vs_4w_avg_pct: orders.vs4,

    units_previous_week: units.previous,
    units_wow_pct: units.wow,
    units_4w_avg: units.avg4,
    units_vs_4w_avg_pct: units.vs4,

    aov_previous_week: aov.previous,
    aov_wow_pct: aov.wow,
    aov_4w_avg: aov.avg4,
    aov_vs_4w_avg_pct: aov.vs4,

    shopify_cvr_previous_week: shopifyCvrComp.previous,
    shopify_cvr_wow_pct: shopifyCvrComp.wow,
    shopify_cvr_4w_avg: shopifyCvrComp.avg4,
    shopify_cvr_vs_4w_avg_pct: shopifyCvrComp.vs4,

    mer_previous_week: merComp.previous,
    mer_wow_pct: merComp.wow,
    mer_4w_avg: merComp.avg4,
    mer_vs_4w_avg_pct: merComp.vs4,

    final_diagnosis: finalDiagnosis
  };
}

function buildActions({
  boundaries,
  syncedAt,
  reportRow,
  weeklyRow,
  ga4Row,
  metaRow,
  productRows,
  skuRows,
  productDiagnosis,
  skuDiagnosis,
  metaAdRows,
  ga4ProductRows
}) {
  const actions = [];
  const seen = new Set();

  function addAction({
    source,
    severity,
    issue,
    evidence,
    cause,
    fix,
    owner,
    expected_impact,
    next_week_check
  }) {
    const key = [
      source,
      severity,
      issue,
      evidence,
      fix,
      owner
    ].map(clean).join("|");

    if (seen.has(key)) return;
    seen.add(key);

    actions.push({
      action_id: "",
      week_start: boundaries.week_start,
      created_at: syncedAt,
      source: source || "Report",
      severity: severity || "Action",
      issue: issue || "",
      evidence: evidence || "",
      cause: cause || "",
      fix: fix || "",
      owner: owner || "",
      expected_impact: expected_impact || "",
      next_week_check: next_week_check || "",
      status: "Open"
    });
  }

  function severityScore(s) {
    return severityRank(s);
  }

  const shopify = weeklyRow || {};
  const ga4 = ga4Row || {};
  const meta = metaRow || {};
  const report = reportRow || {};

  const shopifyNetSales = num(shopify.net_sales);
  const shopifyOrders = num(shopify.orders);
  const soldSkuOosRate = num(shopify.sold_sku_oos_rate);
  const refundRate = num(shopify.sales_reversal_rate ?? shopify.refund_rate);
  const itemReturnRate = num(shopify.item_return_rate);

  const ga4Sessions = num(ga4.sessions);
  const ga4ProductViewRate = num(ga4.product_view_rate);
  const ga4AtcRate = num(ga4.atc_rate);
  const ga4CheckoutStartRate = num(ga4.checkout_start_rate);
  const ga4CheckoutCompletionRate = num(ga4.checkout_completion_rate);

  const metaSpend = num(meta.spend);
  const metaRoas = num(meta.roas);
  const metaCtrLink = num(meta.ctr_link);
  const metaCpm = num(meta.cpm);
  const metaCpcLink = num(meta.cpc_link);
  const metaLpvRate = num(meta.lpv_rate_from_link_click);
  const metaFrequency = num(meta.frequency);

  // ─────────────────────────────────────────────
  // 1. Shopify diagnosis actions: inventory/merchandising
  // ─────────────────────────────────────────────

  const combinedDiagnosis = [...(skuDiagnosis || []), ...(productDiagnosis || [])]
    .sort((a, b) => severityScore(a.severity) - severityScore(b.severity))
    .slice(0, 12);

  for (const d of combinedDiagnosis) {
    let owner = "Ecommerce";
    let expected = "Improve weekly performance.";
    const label = clean(d.diagnosis_label);

    if (
      ["STOCKOUT_WINNER", "CRITICAL_DAYS_COVER", "LOW_DAYS_COVER", "RESTOCK_PRIORITY", "FAST_SELLER_LOW_STOCK"].includes(label)
    ) {
      owner = "Operations";
      expected = "Recover or protect revenue by making proven-demand SKUs available.";
    } else if (["DEAD_SKU", "DEAD_STOCK", "SLOW_SKU", "SLOW_MOVER"].includes(label)) {
      owner = "Ecommerce / Merchandising";
      expected = "Improve stock efficiency and reduce capital trapped in slow stock.";
    }

    addAction({
      source: "Shopify",
      severity: d.severity,
      issue: label,
      evidence: d.evidence,
      cause: d.cause_guess,
      fix: d.recommended_action,
      owner,
      expected_impact: expected,
      next_week_check: d.next_week_check
    });
  }

  // ─────────────────────────────────────────────
  // 2. Inventory-level action
  // ─────────────────────────────────────────────

  if (soldSkuOosRate >= 0.2) {
    const topOosWinners = (skuRows || [])
      .filter((r) => num(r.units_sold) > 0 && clean(r.is_oos) === "TRUE")
      .sort((a, b) => num(b.units_sold) - num(a.units_sold))
      .slice(0, 5)
      .map((r) => `${clean(r.sku)} (${num(r.units_sold)} sold)`)
      .join(", ");

    addAction({
      source: "Shopify",
      severity: "Critical",
      issue: "Sold SKUs are going out of stock",
      evidence: `${r4(soldSkuOosRate)} of sold SKUs are currently out of stock. Top affected SKUs: ${topOosWinners || "N/A"}.`,
      cause: "Demand exists but inventory availability may block next week's conversion.",
      fix: "Restock the proven-demand SKUs, push substitutes, and avoid sending paid traffic to unavailable variants.",
      owner: "Operations",
      expected_impact: "Protect sales capture and reduce lost conversion from unavailable variants.",
      next_week_check: "Sold SKU OOS rate below 10%; top sold SKUs have enough days of cover."
    });
  }

  // ─────────────────────────────────────────────
  // 3. Returns/refunds action
  // ─────────────────────────────────────────────

  if (refundRate >= 0.15 || itemReturnRate >= 0.15) {
    const topReturnedSkus = (skuRows || [])
      .filter((r) => num(r.returned_items) > 0)
      .sort((a, b) => num(b.returned_items) - num(a.returned_items))
      .slice(0, 5)
      .map((r) => `${clean(r.sku)} (${num(r.returned_items)} returned)`)
      .join(", ");

    addAction({
      source: "Shopify",
      severity: refundRate >= 0.25 || itemReturnRate >= 0.25 ? "Critical" : "Action",
      issue: "Returns/refunds are pressuring revenue quality",
      evidence: `Refund rate ${r4(refundRate)}, item return rate ${r4(itemReturnRate)}. Top returned SKUs: ${topReturnedSkus || "N/A"}.`,
      cause: "Possible fit, size expectation, product quality, product page mismatch, or fulfillment issue.",
      fix: "Review the top returned SKUs, inspect customer complaints/reasons, and adjust PDP copy, size guidance, quality control, or fulfillment process.",
      owner: "Operations / Ecommerce",
      expected_impact: "Reduce revenue leakage and protect net sales quality.",
      next_week_check: "Refund rate and item return rate decrease; top returned SKUs no longer dominate returns."
    });
  }

  // ─────────────────────────────────────────────
  // 4. GA4 funnel actions
  // ─────────────────────────────────────────────

  if (!ga4Row) {
    addAction({
      source: "GA4",
      severity: "Critical",
      issue: "GA4 data missing",
      evidence: "GA4Weekly row is missing for this week.",
      cause: "GA4 sync did not run or failed.",
      fix: "Run GA4 sync for the report week before presenting funnel diagnosis.",
      owner: "Ecommerce",
      expected_impact: "Enables funnel diagnosis and prevents presenting incomplete conclusions.",
      next_week_check: "GA4Weekly row exists for the latest completed week."
    });
  } else if (ga4Sessions > 0 && ga4ProductViewRate > 0 && ga4ProductViewRate < 0.3) {
    addAction({
      source: "GA4",
      severity: "Action",
      issue: "Low product-view rate",
      evidence: `Product-view rate is ${r4(ga4ProductViewRate)} from ${ga4Sessions} sessions.`,
      cause: "Traffic may be landing on weak pages, collections may not push users into PDPs, or navigation/product discovery may be weak.",
      fix: "Audit ad landing URLs, homepage/collection layout, above-the-fold product entry points, and product discovery path.",
      owner: "Ecommerce / Website",
      expected_impact: "Move more sessions into product consideration.",
      next_week_check: "Product-view rate improves and product views increase without traffic-quality loss."
    });
  } else if (ga4AtcRate > 0 && ga4AtcRate < GA4_LOW_ATC_RATE) {
    const weakProducts = (ga4ProductRows || [])
      .filter((r) => num(r.item_views) >= 20 && num(r.view_to_cart_rate) > 0 && num(r.view_to_cart_rate) < 0.05)
      .sort((a, b) => num(b.item_views) - num(a.item_views))
      .slice(0, 5)
      .map((r) => `${clean(r.item_name)} (${num(r.item_views)} views, ATC ${r4(num(r.view_to_cart_rate))})`)
      .join("; ");

    addAction({
      source: "GA4",
      severity: "Action",
      issue: "Low add-to-cart rate",
      evidence: `ATC rate is ${r4(ga4AtcRate)}. Weak viewed products: ${weakProducts || "Check GA4ProductWeekly top viewed products."}`,
      cause: "PDP/product/price/offer/size availability may be weak.",
      fix: "Audit top-viewed low-ATC products: first image, price, size availability, delivery promise, above-the-fold CTA, and product description.",
      owner: "Ecommerce",
      expected_impact: "Improve product-to-cart conversion.",
      next_week_check: "ATC rate improves and top-viewed products produce more add-to-carts."
    });
  } else if (ga4CheckoutStartRate > 0 && ga4CheckoutStartRate < 0.35) {
    addAction({
      source: "GA4",
      severity: "Action",
      issue: "Cart to checkout-start friction",
      evidence: `Checkout-start rate is ${r4(ga4CheckoutStartRate)} from add-to-cart to begin checkout.`,
      cause: "Cart page, shipping cost visibility, discount expectation, delivery promise, or checkout CTA may be causing drop-off.",
      fix: "Audit cart page: shipping fee clarity, delivery promise, discount code behavior, trust signals, and checkout CTA visibility.",
      owner: "Ecommerce / Website",
      expected_impact: "Increase checkout starts from existing carts.",
      next_week_check: "Checkout-start rate improves while ATC volume remains stable or grows."
    });
  } else if (ga4CheckoutCompletionRate > 0 && ga4CheckoutCompletionRate < 0.35) {
    addAction({
      source: "GA4",
      severity: "Critical",
      issue: "Checkout completion is weak",
      evidence: `Checkout completion rate is ${r4(ga4CheckoutCompletionRate)}.`,
      cause: "Payment issues, trust issues, checkout UX, delivery friction, or COD/prepaid friction.",
      fix: "Inspect checkout errors, payment success, COD/prepaid options, form friction, delivery promise, and abandoned checkout patterns.",
      owner: "Ecommerce / Website",
      expected_impact: "Recover orders from users already showing high intent.",
      next_week_check: "Checkout completion rate improves and Shopify orders rise relative to begin_checkouts."
    });
  }

  // ─────────────────────────────────────────────
  // 5. Meta paid acquisition actions
  // ─────────────────────────────────────────────

  if (!metaRow) {
    addAction({
      source: "Meta",
      severity: "Critical",
      issue: "Meta data missing",
      evidence: "MetaWeekly row is missing for this week.",
      cause: "Meta sync did not run or failed.",
      fix: "Run Meta sync for the report week before presenting paid acquisition diagnosis.",
      owner: "Media Buying",
      expected_impact: "Enables spend/creative/traffic diagnosis.",
      next_week_check: "MetaWeekly row exists for the latest completed week."
    });
  } else if (metaSpend > 0 && metaRoas > 0 && metaRoas < 1.5) {
    const worstSpendAds = (metaAdRows || [])
      .filter((r) => num(r.spend) > 0)
      .sort((a, b) => {
        const aBad = num(a.spend) * (num(a.roas) < 1.5 ? 1 : 0);
        const bBad = num(b.spend) * (num(b.roas) < 1.5 ? 1 : 0);
        return bBad - aBad;
      })
      .slice(0, 5)
      .map((r) => `${clean(r.ad_name)} (spend ${r.spend}, ROAS ${r.roas})`)
      .join("; ");

    addAction({
      source: "Meta",
      severity: "Critical",
      issue: "Meta ROAS is weak",
      evidence: `Meta spend ${r2(metaSpend)}, ROAS ${r4(metaRoas)}. Weak spend ads: ${worstSpendAds || "Check MetaAdWeekly by spend and ROAS."}`,
      cause: "Paid traffic may be inefficient due to creative, targeting, offer, landing page, or product-market mismatch.",
      fix: "Review top-spend low-ROAS ads. Reduce waste, refresh creative angles, and shift budget to proven ads/products.",
      owner: "Media Buying",
      expected_impact: "Improve paid efficiency and protect MER.",
      next_week_check: "Meta ROAS and MER improve; spend shifts away from low-return ads."
    });
  } else if (metaCtrLink > 0 && metaCtrLink < 0.008) {
    addAction({
      source: "Meta",
      severity: "Action",
      issue: "Meta link CTR is weak",
      evidence: `Link CTR is ${r4(metaCtrLink)} with CPM ${r2(metaCpm)} and CPC link ${r2(metaCpcLink)}.`,
      cause: "Creative hook, first frame, product angle, or offer is not earning enough clicks.",
      fix: "Create new hooks and first-frame variants for the top products. Prioritize clearer product proof, stronger offer, and faster visual opening.",
      owner: "Creative / Media Buying",
      expected_impact: "Improve traffic efficiency and reduce CPC.",
      next_week_check: "CTR link improves and CPC link decreases without ROAS deterioration."
    });
  } else if (metaLpvRate > 0 && metaLpvRate < 0.5) {
    addAction({
      source: "Meta",
      severity: "Action",
      issue: "Meta click-to-landing-page-view rate is weak",
      evidence: `LPV/link-click rate is ${r4(metaLpvRate)}.`,
      cause: "Landing page load speed, accidental clicks, low-quality placements, tracking gap, or destination mismatch.",
      fix: "Check page speed, destination URLs, UTMs, placement breakdown, and click-to-session gap.",
      owner: "Media Buying / Website",
      expected_impact: "Improve traffic quality and reduce wasted clicks.",
      next_week_check: "LPV/link-click rate improves and GA4 sessions align better with Meta LPVs."
    });
  } else if (metaFrequency >= 3.5 && metaCtrLink < 0.012) {
    addAction({
      source: "Meta",
      severity: "Watch",
      issue: "Possible creative fatigue",
      evidence: `Frequency ${r4(metaFrequency)} and link CTR ${r4(metaCtrLink)}.`,
      cause: "Audience may be seeing the same ads too often while response weakens.",
      fix: "Refresh creatives, rotate hooks, and monitor frequency by campaign/adset.",
      owner: "Creative / Media Buying",
      expected_impact: "Protect CTR and reduce creative fatigue.",
      next_week_check: "Frequency stabilizes and CTR link does not continue falling."
    });
  }

  // ─────────────────────────────────────────────
  // 6. Creative/ad-level actions
  // ─────────────────────────────────────────────

  const highSpendLowRoasAds = (metaAdRows || [])
    .filter((r) => num(r.spend) >= 500 && num(r.roas) > 0 && num(r.roas) < 1.5)
    .sort((a, b) => num(b.spend) - num(a.spend))
    .slice(0, 5);

  for (const ad of highSpendLowRoasAds) {
    addAction({
      source: "MetaAd",
      severity: "Action",
      issue: "High-spend ad has weak ROAS",
      evidence: `${clean(ad.ad_name)} spent ${r2(ad.spend)} with ROAS ${r4(ad.roas)}, purchases ${num(ad.purchases)}.`,
      cause: "Creative, audience, landing page, or offer is not converting enough paid spend.",
      fix: "Review the ad before scaling. Either refresh the angle/creative, move spend to winners, or test a stronger landing/product match.",
      owner: "Media Buying / Creative",
      expected_impact: "Reduce wasted spend and improve campaign efficiency.",
      next_week_check: "Ad-level ROAS improves above 1.5 or spend is reallocated."
    });
  }

function looksLikeNonVideoAd(row) {
  const name = `${clean(row.ad_name)} ${clean(row.campaign_name)} ${clean(row.adset_name)}`.toLowerCase();

  return (
    name.includes("catalog") ||
    name.includes("catalogue") ||
    name.includes("carousel") ||
    name.includes("dynamic") ||
    name.includes("advantage+") ||
    name.includes("asc") ||
    name.includes("collection")
  );
}

function hasMeaningfulVideoSignals(row) {
  return (
    num(row.video_plays_3s) >= 100 &&
    num(row.video_p25_watched) > 0 &&
    num(row.video_p50_watched) > 0
  );
}

const lowHookAds = (metaAdRows || [])
  .filter((r) =>
    num(r.spend) >= 300 &&
    num(r.hook_rate_3s) > 0 &&
    num(r.hook_rate_3s) < 0.15 &&
    hasMeaningfulVideoSignals(r) &&
    !looksLikeNonVideoAd(r)
  )
  .sort((a, b) => num(b.spend) - num(a.spend))
  .slice(0, 3);

  for (const ad of lowHookAds) {
    addAction({
      source: "Creative",
      severity: "Action",
      issue: "Video hook is weak",
      evidence: `${clean(ad.ad_name)} hook rate ${r4(ad.hook_rate_3s)}, spend ${r2(ad.spend)}.`,
      cause: "The first 1–3 seconds may not stop the scroll.",
      fix: "Create new first-frame/opening variants: stronger product shot, movement, benefit, social proof, or pattern interrupt.",
      owner: "Creative",
      expected_impact: "Improve thumbstop and reduce wasted impressions.",
      next_week_check: "Hook rate improves and CTR link does not fall."
    });
  }

const goodHookPoorHoldAds = (metaAdRows || [])
  .filter((r) =>
    num(r.hook_rate_3s) >= 0.2 &&
    num(r.hold_rate_p50) > 0 &&
    num(r.hold_rate_p50) < 0.25 &&
    hasMeaningfulVideoSignals(r) &&
    !looksLikeNonVideoAd(r)
  )
  .sort((a, b) => num(b.spend) - num(a.spend))
  .slice(0, 3);

  for (const ad of goodHookPoorHoldAds) {
    addAction({
      source: "Creative",
      severity: "Watch",
      issue: "Video opens well but loses viewers",
      evidence: `${clean(ad.ad_name)} hook rate ${r4(ad.hook_rate_3s)} but hold rate P50 ${r4(ad.hold_rate_p50)}.`,
      cause: "Opening catches attention, but the body of the video may not sustain interest.",
      fix: "Keep the opening but test a tighter middle: faster product proof, clearer offer, fewer dead seconds.",
      owner: "Creative",
      expected_impact: "Improve creative quality and downstream clicks/conversions.",
      next_week_check: "Hold rate P50 improves while CTR link and ROAS remain stable or improve."
    });
  }

  // ─────────────────────────────────────────────
  // 7. Final ordering and IDs
  // ─────────────────────────────────────────────

  return actions
    .sort((a, b) => severityScore(a.severity) - severityScore(b.severity))
    .slice(0, 30)
    .map((a, i) => ({
      ...a,
      action_id: `${boundaries.week_start}-${String(i + 1).padStart(3, "0")}`
    }));
}

function upsertObjects(existingObjects, newObjects, keyFn) {
  const map = new Map();

  for (const obj of existingObjects || []) {
    if (!hasAnyValue(obj)) continue;

    const k = keyFn(obj);
    if (k) map.set(k, obj);
  }

  for (const obj of newObjects || []) {
    if (!hasAnyValue(obj)) continue;

    const k = keyFn(obj);
    if (k) map.set(k, obj);
  }

  return [...map.values()].sort((a, b) =>
    clean(a.week_start || a.snapshot_at || a.created_at).localeCompare(
      clean(b.week_start || b.snapshot_at || b.created_at)
    )
  );
}

function hasAnyValue(obj) {
  return Object.values(obj || {}).some((v) => clean(v) !== "");
}

function hasWeekStart(obj) {
  return clean(obj?.week_start) !== "";
}

function replaceObjectsForWeek(existingObjects, weekStart, newObjects, keepFn = null) {
  const cleanExisting = (existingObjects || []).filter((obj) => {
    if (!hasAnyValue(obj)) return false;
    if (!hasWeekStart(obj)) return false;

    const sameWeek = clean(obj.week_start) === weekStart;

    if (sameWeek) {
      return keepFn ? keepFn(obj) : false;
    }

    return true;
  });

  const cleanNew = (newObjects || []).filter((obj) => {
    if (!hasAnyValue(obj)) return false;
    if (!hasWeekStart(obj)) return false;
    return true;
  });

  return [...cleanExisting, ...cleanNew].sort((a, b) =>
    `${clean(a.week_start)}|${clean(a.severity)}|${clean(a.product_title)}|${clean(a.sku)}`.localeCompare(
      `${clean(b.week_start)}|${clean(b.severity)}|${clean(b.product_title)}|${clean(b.sku)}`
    )
  );
}

function buildRewritePayload(tab, headers, objects) {
  const cleanObjects = (objects || []).filter(hasAnyValue);
  const bodyRows = objectsToRows(headers, cleanObjects);
  const values = [headers, ...bodyRows];

  return {
    range: `${tab}!A1:${colLetter(headers.length)}${values.length}`,
    values
  };
}

function summarizeOrderForDebug(order) {
  let lineGross = 0;
  let lineNet = 0;
  let lineDiscounts = 0;
  let units = 0;
  let lineCount = 0;

  for (const edge of order.lineItems?.edges || []) {
    const line = edge.node;
    const f = lineFinancials(line);

    lineGross += f.gross;
    lineNet += f.net;
    lineDiscounts += f.discounts;
    units += f.currentQty;
    lineCount += 1;
  }

  return {
    name: order.name,
    id: shortGid(order.id),
    createdAt: order.createdAt,
    processedAt: order.processedAt || "",
    sourceName: order.sourceName || "",
    displayFinancialStatus: order.displayFinancialStatus || "",
    displayFulfillmentStatus: order.displayFulfillmentStatus || "",
    cancelledAt: order.cancelledAt || "",
    cancelReason: order.cancelReason || "",
    test: order.test ? "TRUE" : "FALSE",
    counted_by_current_worker_filter: validOrder(order) ? "TRUE" : "FALSE",

    order_currentSubtotalPrice: r2(money(order.currentSubtotalPriceSet)),
    order_currentTotalPrice: r2(money(order.currentTotalPriceSet)),
    order_currentTotalDiscounts: r2(money(order.currentTotalDiscountsSet)),
    order_currentShippingPrice: r2(money(order.currentShippingPriceSet)),
    order_currentTax: r2(money(order.currentTotalTaxSet)),
    order_totalRefunded: r2(money(order.totalRefundedSet)),

    worker_line_gross: r2(lineGross),
    worker_line_net: r2(lineNet),
    worker_line_discounts: r2(lineDiscounts),

    lineCount,
    units
  };
}

function countBy(rows, key) {
  const out = {};

  for (const row of rows) {
    const value = clean(row[key]) || "blank";
    out[value] = (out[value] || 0) + 1;
  }

  return out;
}

function sumDebugRows(rows) {
  return rows.reduce(
    (acc, o) => {
      acc.orders += 1;
      acc.order_currentSubtotalPrice += num(o.order_currentSubtotalPrice);
      acc.order_currentTotalPrice += num(o.order_currentTotalPrice);
      acc.order_currentTotalDiscounts += num(o.order_currentTotalDiscounts);
      acc.order_currentShippingPrice += num(o.order_currentShippingPrice);
      acc.order_currentTax += num(o.order_currentTax);
      acc.order_totalRefunded += num(o.order_totalRefunded);
      acc.worker_line_gross += num(o.worker_line_gross);
      acc.worker_line_net += num(o.worker_line_net);
      acc.worker_line_discounts += num(o.worker_line_discounts);
      acc.units += num(o.units);
      return acc;
    },
    {
      orders: 0,
      order_currentSubtotalPrice: 0,
      order_currentTotalPrice: 0,
      order_currentTotalDiscounts: 0,
      order_currentShippingPrice: 0,
      order_currentTax: 0,
      order_totalRefunded: 0,
      worker_line_gross: 0,
      worker_line_net: 0,
      worker_line_discounts: 0,
      units: 0
    }
  );
}

function roundDebugTotals(totals) {
  return {
    orders: totals.orders,
    order_currentSubtotalPrice: r2(totals.order_currentSubtotalPrice),
    order_currentTotalPrice: r2(totals.order_currentTotalPrice),
    order_currentTotalDiscounts: r2(totals.order_currentTotalDiscounts),
    order_currentShippingPrice: r2(totals.order_currentShippingPrice),
    order_currentTax: r2(totals.order_currentTax),
    order_totalRefunded: r2(totals.order_totalRefunded),
    worker_line_gross: r2(totals.worker_line_gross),
    worker_line_net: r2(totals.worker_line_net),
    worker_line_discounts: r2(totals.worker_line_discounts),
    units: totals.units
  };
}

async function debugShopifyOrders(env, weekStart) {
  if (!weekStart) {
    throw new Error("Missing week_start. Example: /debug-shopify-orders?week_start=2026-05-03");
  }

  const config = await getConfig(env);

  if (config.weekStartDay !== "SUNDAY") {
    throw new Error(`Config week_start_day must be SUNDAY. Current value: ${config.weekStartDay}`);
  }

  assertCompletedWeek(weekStart, config.timezone);

  const boundaries = weekBoundaries(weekStart, config.timezone);

  const orders = await fetchOrdersInRange(
    config.shopDomain,
    env.SHOPIFY_OFFLINE_TOKEN,
    boundaries.start_iso,
    boundaries.end_iso
  );

  const debugRows = orders.map(summarizeOrderForDebug);
  const countedRows = debugRows.filter((o) => o.counted_by_current_worker_filter === "TRUE");
  const notCountedRows = debugRows.filter((o) => o.counted_by_current_worker_filter !== "TRUE");

  return {
    ok: true,
    instruction:
      "Compare counted_orders_after_current_worker_filter and grouped statuses against Shopify Admin. Do not continue backfill until this matches Shopify.",
    week_start: boundaries.week_start,
    week_end: boundaries.week_end,
    timezone: config.timezone,
    start_iso_used_by_worker: boundaries.start_iso,
    end_iso_used_by_worker_exclusive: boundaries.end_iso,

    raw_orders_returned_by_shopify_api: orders.length,
    counted_orders_after_current_worker_filter: countedRows.length,
    not_counted_orders_after_current_worker_filter: notCountedRows.length,

    counted_totals: roundDebugTotals(sumDebugRows(countedRows)),
    raw_totals_before_filter: roundDebugTotals(sumDebugRows(debugRows)),

    byFinancialStatus_counted: countBy(countedRows, "displayFinancialStatus"),
    byFulfillmentStatus_counted: countBy(countedRows, "displayFulfillmentStatus"),
    bySourceName_counted: countBy(countedRows, "sourceName"),

    byFinancialStatus_raw: countBy(debugRows, "displayFinancialStatus"),
    byFulfillmentStatus_raw: countBy(debugRows, "displayFulfillmentStatus"),
    bySourceName_raw: countBy(debugRows, "sourceName"),

    counted_orders: countedRows
  };
}

function collectRefundAdjustmentsFromOrders(orders, startIso, endIso) {
  const totals = {
    refund_count: 0,
    refund_order_ids: new Set(),
same_week_order_refund_shipping_subtotal: 0,
older_order_refund_shipping_subtotal: 0,
    refund_line_quantity: 0,
    refund_line_subtotal: 0,
    refund_line_tax: 0,
    refund_shipping_subtotal: 0,
    refund_shipping_tax: 0
  };

  const productAdjustments = new Map();
  const skuAdjustments = new Map();

function addAdjustment(map, key, meta, qty, subtotal) {
  if (!key) return;

  const agg = getAgg(map, key);

  agg.meta = agg.meta || meta;

  // Do NOT reduce units_sold here.
  // units_sold should stay as gross units ordered in this report week.
  // Returns/refunds are tracked separately.
  agg.net_sales -= subtotal;
  agg.refunds += subtotal;
  agg.returned_items += qty;
}

  for (const order of orders) {
    if (order.test) continue;

    for (const refund of order.refunds || []) {
      const refundDate = refund.processedAt || refund.createdAt;

      if (!isIsoInRange(refundDate, startIso, endIso)) continue;

      totals.refund_count += 1;
      totals.refund_order_ids.add(order.id);

      for (const edge of refund.refundLineItems?.edges || []) {
        const item = edge.node;
        const line = item.lineItem || {};
        const meta = lineMeta(line);

        const qty = num(item.quantity);
        const subtotal = money(item.subtotalSet);
        const tax = money(item.totalTaxSet);

        totals.refund_line_quantity += qty;
        totals.refund_line_subtotal += subtotal;
        totals.refund_line_tax += tax;

        addAdjustment(productAdjustments, meta.product_id, meta, qty, subtotal);
        addAdjustment(skuAdjustments, meta.variant_id, meta, qty, subtotal);
      }

      for (const edge of refund.refundShippingLines?.edges || []) {
        const ship = edge.node;

const shipSubtotal = money(ship.subtotalAmountSet);
const shipTax = money(ship.taxAmountSet);

totals.refund_shipping_subtotal += shipSubtotal;
totals.refund_shipping_tax += shipTax;

// Shopify shipping charges appear to adjust only shipping refunds for orders created in this same report week.
if (isIsoInRange(order.createdAt, startIso, endIso)) {
  totals.same_week_order_refund_shipping_subtotal += shipSubtotal;
} else {
  totals.older_order_refund_shipping_subtotal += shipSubtotal;
}
      }
    }
  }

  return {
    totals,
    productAdjustments,
    skuAdjustments
  };
}

function applyRefundAdjustmentsToAggregate(aggregate, refundAdjustments) {
  const t = refundAdjustments.totals;

aggregate.weekly.refunds = r2(t.refund_line_subtotal);

aggregate.weekly.returned_items = num(t.refund_line_quantity);
aggregate.weekly.returned_orders = t.refund_order_ids ? t.refund_order_ids.size : 0;

aggregate.weekly.net_sales = r2(
  num(aggregate.weekly.gross_sales) -
  num(aggregate.weekly.discounts) -
  num(t.refund_line_subtotal)
);

aggregate.weekly.net_items_sold =
  num(aggregate.weekly.total_quantity_ordered) - num(t.refund_line_quantity);

// Keep legacy field aligned with Shopify net items sold.
aggregate.weekly.units_sold = aggregate.weekly.net_items_sold;

// Shopify shipping charges reconciliation.
// Do NOT subtract all refund shipping from older orders, or shipping becomes too low.
aggregate.weekly.shipping_refunded = r2(t.refund_shipping_subtotal);

// Shopify Sales report shipping charges reconcile as:
// raw shipping from orders created this week
// minus shipping refunds processed this week for older orders.
aggregate.weekly.shipping_revenue = r2(
  num(aggregate.weekly.shipping_revenue) -
  num(t.older_order_refund_shipping_subtotal)
);

aggregate.weekly.total_sales = r2(
  num(aggregate.weekly.net_sales) +
  num(aggregate.weekly.shipping_revenue) +
  num(aggregate.weekly.taxes)
);

  for (const [key, adj] of refundAdjustments.productAdjustments.entries()) {
  const target = getAgg(aggregate.productAgg, key);

  target.meta = target.meta || adj.meta;

  // Do not reduce gross units_sold here.
  // units_sold = units ordered from orders created in this report week.
  target.net_sales += adj.net_sales;
  target.refunds += adj.refunds;
  target.returned_items += adj.returned_items;
}

for (const [key, adj] of refundAdjustments.skuAdjustments.entries()) {
  const target = getAgg(aggregate.skuAgg, key);

  target.meta = target.meta || adj.meta;

  // Do not reduce gross units_sold here.
  // returned_items is tracked separately.
  target.net_sales += adj.net_sales;
  target.refunds += adj.refunds;
  target.returned_items += adj.returned_items;
}
  return aggregate;
}

function summarizeSalesAgreementsForDebug(orders, startIso, endIso) {
  const byLineType = {};
  const byActionType = {};
  const byReason = {};
  const rows = [];

  function add(map, key, amount) {
    const k = clean(key) || "blank";
    map[k] = r2(num(map[k]) + num(amount));
  }

  for (const order of orders) {
    if (order.test) continue;

    for (const agreementEdge of order.agreements?.edges || []) {
      const agreement = agreementEdge.node;

      if (!isIsoInRange(agreement.happenedAt, startIso, endIso)) continue;

      for (const saleEdge of agreement.sales?.edges || []) {
        const sale = saleEdge.node;

        const amount = money(sale.totalAmount);
        const discountBeforeTax = money(sale.totalDiscountAmountBeforeTaxes);
        const discountAfterTax = money(sale.totalDiscountAmountAfterTaxes);
        const tax = money(sale.totalTaxAmount);

        add(byLineType, sale.lineType, amount);
        add(byActionType, sale.actionType, amount);
        add(byReason, agreement.reason, amount);

        rows.push({
          order_name: order.name,
          order_id: shortGid(order.id),
          order_createdAt: order.createdAt,
          order_updatedAt: order.updatedAt,
          financial_status: order.displayFinancialStatus || "",
          fulfillment_status: order.displayFulfillmentStatus || "",

          agreement_id: shortGid(agreement.id),
          agreement_happenedAt: agreement.happenedAt,
          agreement_reason: agreement.reason,

          sale_id: shortGid(sale.id),
          actionType: sale.actionType,
          lineType: sale.lineType,
          quantity: sale.quantity ?? "",
          totalAmount: r2(amount),
          totalDiscountBeforeTax: r2(discountBeforeTax),
          totalDiscountAfterTax: r2(discountAfterTax),
          totalTax: r2(tax)
        });
      }
    }
  }

  const shippingRows = rows.filter((r) => r.lineType === "SHIPPING");

  return {
    totals: {
      byLineType,
      byActionType,
      byReason,
      shipping_totalAmount: r2(
        shippingRows.reduce((s, r) => s + num(r.totalAmount), 0)
      ),
      shipping_discount_before_tax: r2(
        shippingRows.reduce((s, r) => s + num(r.totalDiscountBeforeTax), 0)
      ),
      shipping_tax: r2(
        shippingRows.reduce((s, r) => s + num(r.totalTax), 0)
      ),
      shipping_row_count: shippingRows.length,
      all_sale_row_count: rows.length
    },
    shippingRows,
    rows
  };
}





function summarizeShippingDiscountApplicationsForDebug(orders, targetShipping = 0) {
  let rawShippingTotal = 0;
  let shippingLineSummaryTotal = 0;
  let finalShippingTotal = 0;

  let zeroRawShippingOrderCount = 0;
  let zeroRawShippingOrderValue = 0;

  let paidShippingOrderCount = 0;
  let paidShippingOrderValue = 0;

  const byRawShippingAmount = {};
  const byShippingTitle = {};
  const byFinancialStatus = {};
  const byFulfillmentStatus = {};
  const bySourceName = {};

  const paidShippingRows = [];
  const zeroShippingRows = [];

  function addGroup(map, key, shipping, orderValue, count = 1) {
    const k = clean(key) || "blank";

    if (!map[k]) {
      map[k] = {
        orders: 0,
        orderValue: 0,
        rawShipping: 0,
        shippingLineSummary: 0
      };
    }

    map[k].orders += count;
    map[k].orderValue += num(orderValue);
    map[k].rawShipping += num(shipping.raw);
    map[k].shippingLineSummary += num(shipping.summary);
  }

  for (const order of orders) {
    if (order.test) continue;

    const rawShipping = orderRawShipping(order);
    const shippingLineSummary = orderShippingLineSummaryAmount(order);
    const summaryShippingNum = num(shippingLineSummary);

    // IMPORTANT: for now, final = raw. shippingLine is diagnostic only.
    const finalShipping = rawShipping;

    const orderValue = money(order.currentSubtotalPriceSet);
    const orderTotal = money(order.currentTotalPriceSet);
    const shippingTitle = clean(order.shippingLine?.title || "NO_SHIPPING_LINE");

    rawShippingTotal += rawShipping;
    shippingLineSummaryTotal += summaryShippingNum;
    finalShippingTotal += finalShipping;

    const shippingPack = {
      raw: rawShipping,
      summary: summaryShippingNum
    };

    addGroup(byRawShippingAmount, String(rawShipping), shippingPack, orderValue);
    addGroup(byShippingTitle, shippingTitle, shippingPack, orderValue);
    addGroup(byFinancialStatus, order.displayFinancialStatus || "blank", shippingPack, orderValue);
    addGroup(byFulfillmentStatus, order.displayFulfillmentStatus || "blank", shippingPack, orderValue);
    addGroup(bySourceName, order.sourceName || "blank", shippingPack, orderValue);

    const row = {
      name: order.name,
      createdAt: order.createdAt,
      sourceName: order.sourceName || "",
      financial_status: order.displayFinancialStatus || "",
      fulfillment_status: order.displayFulfillmentStatus || "",

      orderValue: r2(orderValue),
      orderTotal: r2(orderTotal),

      shippingTitle,
      rawShipping: r2(rawShipping),
      shippingLineSummary: shippingLineSummary === "" ? "" : r2(shippingLineSummary),
      rawMinusShippingLineSummary: shippingLineSummary === "" ? "" : r2(rawShipping - summaryShippingNum),

      currentSubtotal: r2(money(order.currentSubtotalPriceSet)),
      currentTotal: r2(money(order.currentTotalPriceSet)),
      currentTax: r2(money(order.currentTotalTaxSet)),
      currentDiscounts: r2(money(order.currentTotalDiscountsSet))
    };

    if (rawShipping === 0) {
      zeroRawShippingOrderCount += 1;
      zeroRawShippingOrderValue += orderValue;
      zeroShippingRows.push(row);
    } else {
      paidShippingOrderCount += 1;
      paidShippingOrderValue += orderValue;
      paidShippingRows.push(row);
    }
  }

  function roundGroupMap(map) {
    const out = {};

    for (const [key, value] of Object.entries(map)) {
      out[key] = {
        orders: value.orders,
        orderValue: r2(value.orderValue),
        rawShipping: r2(value.rawShipping),
        shippingLineSummary: r2(value.shippingLineSummary)
      };
    }

    return out;
  }

  const target = num(targetShipping);
  const gapVsTarget = target ? rawShippingTotal - target : "";

  return {
    targetShopifyShipping: target,

    rawShippingTotal: r2(rawShippingTotal),
    shippingLineSummaryTotal: r2(shippingLineSummaryTotal),

    // For now final = raw, because shippingLineSummary made it worse.
    finalShippingTotal: r2(finalShippingTotal),
    differenceVsTarget: target ? r2(finalShippingTotal - target) : "",

    gapToExplain: gapVsTarget === "" ? "" : r2(gapVsTarget),

    zeroRawShippingOrderCount,
    zeroRawShippingOrderValue: r2(zeroRawShippingOrderValue),

    paidShippingOrderCount,
    paidShippingOrderValue: r2(paidShippingOrderValue),

    byRawShippingAmount: roundGroupMap(byRawShippingAmount),
    byShippingTitle: roundGroupMap(byShippingTitle),
    byFinancialStatus: roundGroupMap(byFinancialStatus),
    byFulfillmentStatus: roundGroupMap(byFulfillmentStatus),
    bySourceName: roundGroupMap(bySourceName),

    paidShippingRows,
    zeroShippingRows
  };
}

