function summarizeRefundShippingOnlyForDebug(refundOrders, startIso, endIso, targetGap = 0) {
  let refundShippingAllProcessedThisWeek = 0;
  let refundShippingForOrdersCreatedThisWeek = 0;
  let refundShippingForOlderOrders = 0;

  let refundShippingOrderCount = 0;
  const refundShippingOrderIds = new Set();

  const rows = [];

  for (const order of refundOrders) {
    if (order.test) continue;

    for (const refund of order.refunds || []) {
      const refundDate = refund.processedAt || refund.createdAt;

      if (!isIsoInRange(refundDate, startIso, endIso)) continue;

      let refundShippingForThisRefund = 0;

      for (const edge of refund.refundShippingLines?.edges || []) {
        const ship = edge.node;
        const amount = money(ship.subtotalAmountSet);

        if (!amount) continue;

        refundShippingForThisRefund += amount;
      }

      if (!refundShippingForThisRefund) continue;

      const orderCreatedThisWeek = isIsoInRange(order.createdAt, startIso, endIso);

      refundShippingAllProcessedThisWeek += refundShippingForThisRefund;

      if (orderCreatedThisWeek) {
        refundShippingForOrdersCreatedThisWeek += refundShippingForThisRefund;
      } else {
        refundShippingForOlderOrders += refundShippingForThisRefund;
      }

      refundShippingOrderIds.add(order.id);

      rows.push({
        order_name: order.name,
        order_id: shortGid(order.id),
        order_createdAt: order.createdAt,
        order_created_this_week: orderCreatedThisWeek ? "TRUE" : "FALSE",
        order_financial_status: order.displayFinancialStatus || "",
        order_fulfillment_status: order.displayFulfillmentStatus || "",

        refund_id: shortGid(refund.id),
        refund_createdAt: refund.createdAt,
        refund_processedAt: refund.processedAt,

        refund_shipping_amount: r2(refundShippingForThisRefund)
      });
    }
  }

  refundShippingOrderCount = refundShippingOrderIds.size;

  const target = num(targetGap);

  return {
    targetGapToExplain: target,

    refundShippingAllProcessedThisWeek: r2(refundShippingAllProcessedThisWeek),
    refundShippingForOrdersCreatedThisWeek: r2(refundShippingForOrdersCreatedThisWeek),
    refundShippingForOlderOrders: r2(refundShippingForOlderOrders),

    refundShippingOrderCount,

    differenceVsTarget_allProcessed: target
      ? r2(refundShippingAllProcessedThisWeek - target)
      : "",

    differenceVsTarget_createdThisWeek: target
      ? r2(refundShippingForOrdersCreatedThisWeek - target)
      : "",

    differenceVsTarget_olderOrders: target
      ? r2(refundShippingForOlderOrders - target)
      : "",

    rows
  };
}

