function summarizeFulfillmentDefinitionForDebug(weeklyOrders, refundOrders, startIso, endIso, targetFulfilled = 0) {
  const refundQtyByOrderId = new Map();
  const refundSubtotalByOrderId = new Map();
  const refundProcessedThisWeekByOrderId = new Set();

  for (const order of refundOrders) {
    if (order.test) continue;

    let qty = 0;
    let subtotal = 0;
    let hasRefundThisWeek = false;

    for (const refund of order.refunds || []) {
      const refundDate = refund.processedAt || refund.createdAt;
      if (!isIsoInRange(refundDate, startIso, endIso)) continue;

      hasRefundThisWeek = true;

      for (const edge of refund.refundLineItems?.edges || []) {
        const item = edge.node;
        qty += num(item.quantity);
        subtotal += money(item.subtotalSet);
      }
    }

    if (hasRefundThisWeek) {
      refundProcessedThisWeekByOrderId.add(order.id);
      refundQtyByOrderId.set(order.id, qty);
      refundSubtotalByOrderId.set(order.id, subtotal);
    }
  }

  const rows = [];

  const scenarios = {
    fulfilled_raw: 0,
    fulfilled_not_voided_not_refunded: 0,
    fulfilled_paid_or_pending_or_partially_refunded: 0,
    fulfilled_paid_or_pending_only: 0,
    fulfilled_excluding_any_refund_processed_this_week: 0,
    fulfilled_excluding_refund_line_qty_this_week: 0,
    fulfilled_excluding_current_qty_zero: 0
  };

  for (const order of weeklyOrders) {
    if (order.test) continue;

    const financial = clean(order.displayFinancialStatus);
    const fulfillment = clean(order.displayFulfillmentStatus);

    let orderedQty = 0;
    let currentQty = 0;

    for (const edge of order.lineItems?.edges || []) {
      const line = edge.node;
      orderedQty += num(line.quantity);
      currentQty += num(line.currentQuantity ?? line.quantity);
    }

    const fulfilled = fulfillment === "FULFILLED";
    const hasRefundProcessedThisWeek = refundProcessedThisWeekByOrderId.has(order.id);
    const refundQtyThisWeek = num(refundQtyByOrderId.get(order.id));
    const refundSubtotalThisWeek = num(refundSubtotalByOrderId.get(order.id));

    const notVoidedNotRefunded =
      financial !== "VOIDED" &&
      financial !== "REFUNDED" &&
      !order.cancelledAt;

    const paidPendingOrPartial =
      ["PAID", "PENDING", "PARTIALLY_REFUNDED"].includes(financial) &&
      !order.cancelledAt;

    const paidOrPendingOnly =
      ["PAID", "PENDING"].includes(financial) &&
      !order.cancelledAt;

    if (fulfilled) scenarios.fulfilled_raw += 1;

    if (fulfilled && notVoidedNotRefunded) {
      scenarios.fulfilled_not_voided_not_refunded += 1;
    }

    if (fulfilled && paidPendingOrPartial) {
      scenarios.fulfilled_paid_or_pending_or_partially_refunded += 1;
    }

    if (fulfilled && paidOrPendingOnly) {
      scenarios.fulfilled_paid_or_pending_only += 1;
    }

    if (fulfilled && notVoidedNotRefunded && !hasRefundProcessedThisWeek) {
      scenarios.fulfilled_excluding_any_refund_processed_this_week += 1;
    }

    if (fulfilled && notVoidedNotRefunded && refundQtyThisWeek === 0) {
      scenarios.fulfilled_excluding_refund_line_qty_this_week += 1;
    }

    if (fulfilled && notVoidedNotRefunded && currentQty > 0) {
      scenarios.fulfilled_excluding_current_qty_zero += 1;
    }

    rows.push({
      name: order.name,
      id: shortGid(order.id),
      createdAt: order.createdAt,
      financial_status: financial,
      fulfillment_status: fulfillment,
      cancelledAt: order.cancelledAt || "",

      orderedQty,
      currentQty,

      hasRefundProcessedThisWeek: hasRefundProcessedThisWeek ? "TRUE" : "FALSE",
      refundQtyThisWeek,
      refundSubtotalThisWeek: r2(refundSubtotalThisWeek),

      counted_current_sheet_rule:
        fulfilled && notVoidedNotRefunded ? "TRUE" : "FALSE",

      counted_paid_or_pending_only:
        fulfilled && paidOrPendingOnly ? "TRUE" : "FALSE",

      counted_excluding_refund_processed_this_week:
        fulfilled && notVoidedNotRefunded && !hasRefundProcessedThisWeek ? "TRUE" : "FALSE",

      counted_excluding_refund_line_qty_this_week:
        fulfilled && notVoidedNotRefunded && refundQtyThisWeek === 0 ? "TRUE" : "FALSE",

      counted_excluding_current_qty_zero:
        fulfilled && notVoidedNotRefunded && currentQty > 0 ? "TRUE" : "FALSE"
    });
  }

  const target = num(targetFulfilled);

  return {
    targetFulfilledOrders: target,
    currentSheetFulfilledOrders: scenarios.fulfilled_not_voided_not_refunded,
    gapCurrentVsTarget: target ? scenarios.fulfilled_not_voided_not_refunded - target : "",

    scenarios,

    differencesVsTarget: {
      fulfilled_raw: target ? scenarios.fulfilled_raw - target : "",
      fulfilled_not_voided_not_refunded: target ? scenarios.fulfilled_not_voided_not_refunded - target : "",
      fulfilled_paid_or_pending_or_partially_refunded: target ? scenarios.fulfilled_paid_or_pending_or_partially_refunded - target : "",
      fulfilled_paid_or_pending_only: target ? scenarios.fulfilled_paid_or_pending_only - target : "",
      fulfilled_excluding_any_refund_processed_this_week: target ? scenarios.fulfilled_excluding_any_refund_processed_this_week - target : "",
      fulfilled_excluding_refund_line_qty_this_week: target ? scenarios.fulfilled_excluding_refund_line_qty_this_week - target : "",
      fulfilled_excluding_current_qty_zero: target ? scenarios.fulfilled_excluding_current_qty_zero - target : ""
    },

    rows_current_sheet_counted: rows.filter((r) => r.counted_current_sheet_rule === "TRUE"),
    rows_with_refund_processed_this_week: rows.filter((r) => r.hasRefundProcessedThisWeek === "TRUE"),
    rows
  };
}

