async function fetchOrdersUpdatedInRangeWithFulfillments(shop, token, startIso, endIso) {
  const query = `
    query GetOrdersUpdatedWithFulfillments($cursor: String, $queryStr: String!) {
      orders(first: 100, after: $cursor, query: $queryStr, sortKey: UPDATED_AT, reverse: false) {
        edges {
          cursor
          node {
            id
            name
            createdAt
            updatedAt
            cancelledAt
            test
            sourceName
            displayFinancialStatus
            displayFulfillmentStatus

            fulfillments(first: 100) {
              id
              name
              status
              createdAt
              updatedAt
              deliveredAt
              totalQuantity
            }
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  `;

  const queryStr = `updated_at:>='${startIso}' AND updated_at:<'${endIso}'`;

  const all = [];
  let cursor = null;

  while (true) {
    const data = await shopifyGraphQL(shop, token, query, { cursor, queryStr });
    const conn = data.orders;

    for (const edge of conn.edges || []) {
      all.push(edge.node);
    }

    if (!conn.pageInfo?.hasNextPage) break;

    cursor = conn.pageInfo.endCursor;
    if (!cursor) break;
  }

  return all;
}

function summarizeFulfillmentEventsForDebug(createdOrders, updatedOrders, startIso, endIso, targetFulfilled = 0) {
  const createdOrderIds = new Set(createdOrders.filter((o) => !o.test).map((o) => o.id));

  const rows = [];
  const fulfilledOrderIdsByFulfillmentCreatedAt = new Set();
  const fulfilledOrderIdsByFulfillmentUpdatedAt = new Set();
  const fulfilledOrderIdsByDeliveredAt = new Set();

  const fulfilledCreatedThisWeekButOrderOlder = new Set();
  const orderCreatedThisWeekButFulfilledOutsideWeek = new Set();

  const byFulfillmentStatus = {};
  const byFinancialStatus = {};

  function addGroup(map, key) {
    const k = clean(key) || "blank";
    map[k] = num(map[k]) + 1;
  }

  for (const order of updatedOrders) {
    if (order.test) continue;

    const orderCreatedThisWeek = createdOrderIds.has(order.id);
    const financial = clean(order.displayFinancialStatus);
    const currentFulfillmentStatus = clean(order.displayFulfillmentStatus);

    for (const f of order.fulfillments || []) {
      const fulfillmentCreatedThisWeek = isIsoInRange(f.createdAt, startIso, endIso);
      const fulfillmentUpdatedThisWeek = isIsoInRange(f.updatedAt, startIso, endIso);
      const deliveredThisWeek = isIsoInRange(f.deliveredAt, startIso, endIso);

      const fulfillmentStatus = clean(f.status);

      if (fulfillmentCreatedThisWeek) {
        fulfilledOrderIdsByFulfillmentCreatedAt.add(order.id);
        addGroup(byFulfillmentStatus, fulfillmentStatus);
        addGroup(byFinancialStatus, financial);

        if (!orderCreatedThisWeek) {
          fulfilledCreatedThisWeekButOrderOlder.add(order.id);
        }
      }

      if (fulfillmentUpdatedThisWeek) {
        fulfilledOrderIdsByFulfillmentUpdatedAt.add(order.id);
      }

      if (deliveredThisWeek) {
        fulfilledOrderIdsByDeliveredAt.add(order.id);
      }

      if (
        orderCreatedThisWeek &&
        currentFulfillmentStatus === "FULFILLED" &&
        !fulfillmentCreatedThisWeek
      ) {
        orderCreatedThisWeekButFulfilledOutsideWeek.add(order.id);
      }

      rows.push({
        order_name: order.name,
        order_id: shortGid(order.id),
        order_createdAt: order.createdAt,
        order_updatedAt: order.updatedAt,
        order_created_this_week: orderCreatedThisWeek ? "TRUE" : "FALSE",
        financial_status: financial,
        current_order_fulfillment_status: currentFulfillmentStatus,

        fulfillment_id: shortGid(f.id),
        fulfillment_name: f.name || "",
        fulfillment_status: fulfillmentStatus,
        fulfillment_createdAt: f.createdAt,
        fulfillment_updatedAt: f.updatedAt,
        fulfillment_deliveredAt: f.deliveredAt || "",
        fulfillment_totalQuantity: num(f.totalQuantity),

        fulfillment_created_this_week: fulfillmentCreatedThisWeek ? "TRUE" : "FALSE",
        fulfillment_updated_this_week: fulfillmentUpdatedThisWeek ? "TRUE" : "FALSE",
        delivered_this_week: deliveredThisWeek ? "TRUE" : "FALSE"
      });
    }
  }

  const target = num(targetFulfilled);

  const scenarios = {
    unique_orders_with_fulfillment_created_this_week: fulfilledOrderIdsByFulfillmentCreatedAt.size,
    unique_orders_with_fulfillment_updated_this_week: fulfilledOrderIdsByFulfillmentUpdatedAt.size,
    unique_orders_delivered_this_week: fulfilledOrderIdsByDeliveredAt.size,
    older_orders_fulfilled_this_week: fulfilledCreatedThisWeekButOrderOlder.size,
    created_this_week_but_fulfilled_outside_week: orderCreatedThisWeekButFulfilledOutsideWeek.size
  };

  return {
    targetFulfilledOrders: target,
    scenarios,
    differencesVsTarget: {
      unique_orders_with_fulfillment_created_this_week: target ? scenarios.unique_orders_with_fulfillment_created_this_week - target : "",
      unique_orders_with_fulfillment_updated_this_week: target ? scenarios.unique_orders_with_fulfillment_updated_this_week - target : "",
      unique_orders_delivered_this_week: target ? scenarios.unique_orders_delivered_this_week - target : ""
    },
    byFulfillmentStatus,
    byFinancialStatus,
    fulfillmentRowsCreatedThisWeek: rows.filter((r) => r.fulfillment_created_this_week === "TRUE"),
    rows
  };
}

function summarizeFulfilledCurrentRowsForDebug(weeklyOrders, targetFulfilled = 0) {
  const rows = [];

  const buckets = {
    byFinancialStatus: {},
    byFulfillmentStatus: {},
    byFullyPaid: {},
    byClosed: {},
    byCancelled: {},
    byReturnStatus: {},
    byCurrentSubtotalZero: {},
    byCurrentTotalZero: {},
    byCurrentQtyZero: {},
    bySourceName: {}
  };

  function addBucket(map, key) {
    const k = clean(key) || "blank";
    map[k] = num(map[k]) + 1;
  }

  for (const order of weeklyOrders) {
    if (order.test) continue;

    const financial = clean(order.displayFinancialStatus);
    const fulfillment = clean(order.displayFulfillmentStatus);

    const isCommercialOrder =
      financial !== "VOIDED" &&
      financial !== "REFUNDED" &&
      !order.cancelledAt;

    const countedCurrentRule =
      fulfillment === "FULFILLED" &&
      isCommercialOrder;

    if (!countedCurrentRule) continue;

    let orderedQty = 0;
    let currentQty = 0;

    for (const edge of order.lineItems?.edges || []) {
      const line = edge.node;
      orderedQty += num(line.quantity);
      currentQty += num(line.currentQuantity ?? line.quantity);
    }

    const currentSubtotal = money(order.currentSubtotalPriceSet);
    const currentTotal = money(order.currentTotalPriceSet);

    const row = {
      name: order.name,
      id: shortGid(order.id),
      createdAt: order.createdAt,
      processedAt: order.processedAt || "",
      closedAt: order.closedAt || "",
      cancelledAt: order.cancelledAt || "",
      cancelReason: order.cancelReason || "",
      sourceName: order.sourceName || "",

      financial_status: financial,
      fulfillment_status: fulfillment,
      fullyPaid: order.fullyPaid === true ? "TRUE" : order.fullyPaid === false ? "FALSE" : "",
      returnStatus: order.returnStatus || "",

      orderedQty,
      currentQty,

      currentSubtotal: r2(currentSubtotal),
      currentTotal: r2(currentTotal),
      currentShipping: r2(orderRawShipping(order)),
      currentDiscounts: r2(money(order.currentTotalDiscountsSet)),

      currentSubtotalZero: currentSubtotal === 0 ? "TRUE" : "FALSE",
      currentTotalZero: currentTotal === 0 ? "TRUE" : "FALSE",
      currentQtyZero: currentQty === 0 ? "TRUE" : "FALSE"
    };

    rows.push(row);

    addBucket(buckets.byFinancialStatus, financial);
    addBucket(buckets.byFulfillmentStatus, fulfillment);
    addBucket(buckets.byFullyPaid, row.fullyPaid);
    addBucket(buckets.byClosed, row.closedAt ? "closed" : "not_closed");
    addBucket(buckets.byCancelled, row.cancelledAt ? "cancelled" : "not_cancelled");
    addBucket(buckets.byReturnStatus, row.returnStatus);
    addBucket(buckets.byCurrentSubtotalZero, row.currentSubtotalZero);
    addBucket(buckets.byCurrentTotalZero, row.currentTotalZero);
    addBucket(buckets.byCurrentQtyZero, row.currentQtyZero);
    addBucket(buckets.bySourceName, row.sourceName);
  }

  const target = num(targetFulfilled);

  return {
    targetFulfilledOrders: target,
    currentRuleCount: rows.length,
    gapCurrentVsTarget: target ? rows.length - target : "",

    buckets,

    candidateScenarioCounts: {
      exclude_not_fully_paid: rows.filter((r) => r.fullyPaid === "TRUE").length,
      exclude_closed: rows.filter((r) => !r.closedAt).length,
      exclude_subtotal_zero: rows.filter((r) => r.currentSubtotalZero !== "TRUE").length,
      exclude_total_zero: rows.filter((r) => r.currentTotalZero !== "TRUE").length,
      exclude_current_qty_zero: rows.filter((r) => r.currentQtyZero !== "TRUE").length,
      only_paid: rows.filter((r) => r.financial_status === "PAID").length,
      paid_or_pending_and_fully_paid_true: rows.filter((r) =>
        ["PAID", "PENDING"].includes(r.financial_status) &&
        r.fullyPaid === "TRUE"
      ).length
    },

    rows
  };
}

