async function fetchOrdersProcessedInRange(shop, token, startIso, endIso) {
  const query = `
    query GetOrdersProcessed($cursor: String, $queryStr: String!) {
      orders(first: 100, after: $cursor, query: $queryStr, sortKey: PROCESSED_AT, reverse: false) {
        edges {
          cursor
          node {
            id
            name
            createdAt
            processedAt
            cancelledAt
            closedAt
            cancelReason
            test
            sourceName
            currencyCode
            displayFinancialStatus
            displayFulfillmentStatus
            fullyPaid
            returnStatus
            currentSubtotalPriceSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            currentTotalPriceSet {
              shopMoney {
                amount
                currencyCode
              }
            }
            currentShippingPriceSet {
              shopMoney {
                amount
                currencyCode
              }
            }
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  `;

  const queryStr = `processed_at:>='${startIso}' AND processed_at:<'${endIso}'`;
  const all = [];
  let cursor = null;

  while (true) {
    const data = await shopifyGraphQL(shop, token, query, { cursor, queryStr });
    const conn = data.orders;

    for (const edge of conn.edges || []) {
      all.push(edge.node);
    }

    if (!conn.pageInfo?.hasNextPage) break;

    cursor = conn.pageInfo.endCursor;
    if (!cursor) break;
  }

  return all;
}

function summarizeFulfilledDateBasisForDebug(ordersCreatedRange, ordersProcessedRange, startIso, endIso, targetFulfilled = 0) {
  const byId = new Map();

  for (const order of ordersCreatedRange) {
    if (!order.test) byId.set(order.id, order);
  }

  for (const order of ordersProcessedRange) {
    if (!order.test) byId.set(order.id, order);
  }

  const rows = [...byId.values()];

  function isCommercialFulfilled(order) {
    const financial = clean(order.displayFinancialStatus);
    const fulfillment = clean(order.displayFulfillmentStatus);

    return (
      fulfillment === "FULFILLED" &&
      financial !== "VOIDED" &&
      financial !== "REFUNDED" &&
      !order.cancelledAt
    );
  }

  const createdFulfilled = rows.filter((o) =>
    isCommercialFulfilled(o) &&
    isIsoInRange(o.createdAt, startIso, endIso)
  );

  const processedFulfilled = rows.filter((o) =>
    isCommercialFulfilled(o) &&
    isIsoInRange(o.processedAt, startIso, endIso)
  );

  const createdAndProcessedFulfilled = rows.filter((o) =>
    isCommercialFulfilled(o) &&
    isIsoInRange(o.createdAt, startIso, endIso) &&
    isIsoInRange(o.processedAt, startIso, endIso)
  );

  const createdInWeekProcessedOutside = rows.filter((o) =>
    isCommercialFulfilled(o) &&
    isIsoInRange(o.createdAt, startIso, endIso) &&
    !isIsoInRange(o.processedAt, startIso, endIso)
  );

  const processedInWeekCreatedOutside = rows.filter((o) =>
    isCommercialFulfilled(o) &&
    !isIsoInRange(o.createdAt, startIso, endIso) &&
    isIsoInRange(o.processedAt, startIso, endIso)
  );

  function miniRows(list) {
    return list.map((o) => ({
      name: o.name,
      id: shortGid(o.id),
      createdAt: o.createdAt,
      processedAt: o.processedAt || "",
      financial_status: o.displayFinancialStatus || "",
      fulfillment_status: o.displayFulfillmentStatus || "",
      subtotal: r2(money(o.currentSubtotalPriceSet)),
      total: r2(money(o.currentTotalPriceSet)),
      shipping: r2(orderRawShipping(o))
    }));
  }

  const target = num(targetFulfilled);

  return {
    targetFulfilledOrders: target,

    scenarios: {
      fulfilled_createdAt_basis: createdFulfilled.length,
      fulfilled_processedAt_basis: processedFulfilled.length,
      fulfilled_createdAndProcessed_basis: createdAndProcessedFulfilled.length,
      createdInWeekProcessedOutside: createdInWeekProcessedOutside.length,
      processedInWeekCreatedOutside: processedInWeekCreatedOutside.length
    },

    differencesVsTarget: {
      fulfilled_createdAt_basis: target ? createdFulfilled.length - target : "",
      fulfilled_processedAt_basis: target ? processedFulfilled.length - target : "",
      fulfilled_createdAndProcessed_basis: target ? createdAndProcessedFulfilled.length - target : ""
    },

    createdInWeekProcessedOutsideRows: miniRows(createdInWeekProcessedOutside),
    processedInWeekCreatedOutsideRows: miniRows(processedInWeekCreatedOutside)
  };
}


function ga4DateRange(boundaries) {
  return {
    startDate: boundaries.week_start,
    endDate: boundaries.week_end
  };
}

// Landmine #3, fixed.
//
// These two functions existed but were never called: `syncMetaWeek` built empty
// Maps, so every row wrote `status: ""`, and `paidSupportSummary` tested
// `!/inactive|paused|archived|deleted/i.test(status)` — which an empty string
// never matches. Every ad with spend counted as active, so every "active ads"
// figure in Product Intelligence was wrong.
//
// Why they were never wired in is visible in the old code: one Graph call PER ID.
// At 67 ads and 6 campaigns that is 73 subrequests, fatal on the 50-call free
// plan the project used to run on. Meta's `ids=` parameter fetches up to 50
// objects in one call, so the real cost is 2 calls for the ads and 1 for the
// campaigns — 3, not 73.
//
// `effective_status` is fetched alongside `status` and is the one that answers
// "is this actually running": an ACTIVE ad inside a PAUSED ad set has
// `status: ACTIVE` and `effective_status: ADSET_PAUSED`. Reading `status` alone
// would have replaced one wrong answer with a subtler one.
const META_STATUS_CHUNK = 50;

// `effective_status` is authoritative over `status`: an ACTIVE ad inside a PAUSED
// ad set reports `status: ACTIVE`, `effective_status: ADSET_PAUSED`, and is not
// running. Fall back to `status` only for rows written before effective_status
// was collected, so historical weeks degrade rather than break.
function adEffectiveStatus(row) {
  return clean(row?.effective_status) || clean(row?.status);
}

// Meta's delivery states are an open vocabulary — ADSET_PAUSED, CAMPAIGN_PAUSED,
// IN_PROCESS, WITH_ISSUES, PENDING_REVIEW and more have appeared over time. So
// this allowlists what counts as running rather than blocklisting what does not:
// an unrecognised state must not become "active" by default, which is the exact
// shape of the bug being fixed here.
const META_DELIVERABLE_STATUSES = new Set(["ACTIVE", "IN_PROCESS", "PENDING_REVIEW", "LIMITED"]);

function adIsDeliverable(row) {
  return META_DELIVERABLE_STATUSES.has(adEffectiveStatus(row).toUpperCase());
}

const META_THUMBNAIL_PX = 1080;

// What Meta says an ad looks like. Absent fields stay null so the upsert keeps the
// creative already stored rather than blanking it.
function adCreativeFields(status, checkedAt) {
  const creative = status && status.creative ? status.creative : null;
  if (!creative) return {};
  const kind = clean(creative.video_id) ? "video" : clean(creative.object_type).toLowerCase() === "share" ? "image" : clean(creative.object_type).toLowerCase() || "unknown";
  return {
    creative_id: clean(creative.id) || null,
    thumbnail_url: clean(creative.thumbnail_url) || null,
    creative_image_url: clean(creative.image_url) || null,
    creative_kind: kind || null,
    creative_checked_at: checkedAt
  };
}

async function fetchMetaObjectStatuses(env, ids, fields, extraParams = {}) {
  const out = new Map();
  const unique = [...new Set((ids || []).filter(Boolean))];

  for (let i = 0; i < unique.length; i += META_STATUS_CHUNK) {
    const chunk = unique.slice(i, i + META_STATUS_CHUNK);
    try {
      // Path is empty: `/{version}/?ids=a,b,c` is the batch-by-id form.
      const data = await metaFetch("", { ids: chunk.join(","), fields, ...extraParams }, env);
      for (const id of chunk) {
        if (data && data[id]) out.set(id, data[id]);
      }
    } catch (_) {
      // One bad id fails its whole chunk. Those ids stay absent from the map and
      // are reported as unknown rather than being assumed active — a deleted ad
      // is exactly the kind of id that 400s, and exactly the kind that must not
      // be counted as running.
    }
  }

  return out;
}

async function fetchMetaCampaignStatuses(env, campaignIds) {
  return fetchMetaObjectStatuses(env, campaignIds, "id,name,status,effective_status,objective,buying_type");
}

async function fetchMetaAdStatuses(env, adIds) {
  return fetchMetaObjectStatuses(env, adIds, "id,name,status,effective_status");
}

async function fetchGA4BaseWeekly(env, propertyId, boundaries) {
  const body = {
    dateRanges: [ga4DateRange(boundaries)],
    metrics: [
      { name: "sessions" },
      { name: "totalUsers" },
      { name: "newUsers" },
      { name: "engagedSessions" },
      { name: "engagementRate" },
      { name: "totalRevenue" },
      { name: "purchaseRevenue" }
    ],
    limit: 1
  };

  const data = await ga4RunReport(env, propertyId, body);
  const row = data.rows?.[0] || {};
  const headers = {
    metricHeaders: data.metricHeaders || [],
    dimensionHeaders: data.dimensionHeaders || []
  };

  return {
    sessions: ga4MetricValue(row, headers, "sessions"),
    users: ga4MetricValue(row, headers, "totalUsers"),
    new_users: ga4MetricValue(row, headers, "newUsers"),
    engaged_sessions: ga4MetricValue(row, headers, "engagedSessions"),
    engagement_rate: ga4MetricValue(row, headers, "engagementRate"),
    total_revenue: ga4MetricValue(row, headers, "totalRevenue"),
    purchase_revenue: ga4MetricValue(row, headers, "purchaseRevenue")
  };
}

async function fetchGA4EventCounts(env, propertyId, boundaries) {
  const wanted = new Set([
    "view_item",
    "add_to_cart",
    "begin_checkout",
    "purchase"
  ]);

  const body = {
    dateRanges: [ga4DateRange(boundaries)],
    dimensions: [{ name: "eventName" }],
    metrics: [{ name: "eventCount" }],
    dimensionFilter: {
      filter: {
        fieldName: "eventName",
        inListFilter: {
          values: [...wanted]
        }
      }
    },
    limit: 20
  };

  const data = await ga4RunReport(env, propertyId, body);

  const headers = {
    metricHeaders: data.metricHeaders || [],
    dimensionHeaders: data.dimensionHeaders || []
  };

  const out = {
    view_item: 0,
    add_to_cart: 0,
    begin_checkout: 0,
    purchase: 0
  };

  for (const row of data.rows || []) {
    const eventName = ga4DimensionValue(row, headers, "eventName");
    const eventCount = ga4MetricValue(row, headers, "eventCount");

    if (wanted.has(eventName)) {
      out[eventName] = eventCount;
    }
  }

  return out;
}

async function fetchGA4ItemTotals(env, propertyId, boundaries) {
  const body = {
    dateRanges: [ga4DateRange(boundaries)],
    metrics: [
      { name: "itemsViewed" },
      { name: "itemsAddedToCart" },
      { name: "itemsCheckedOut" },
      { name: "itemsPurchased" }
    ],
    limit: 1
  };

  const data = await ga4RunReport(env, propertyId, body);
  const row = data.rows?.[0] || {};
  const headers = {
    metricHeaders: data.metricHeaders || [],
    dimensionHeaders: data.dimensionHeaders || []
  };

  return {
    item_views: ga4MetricValue(row, headers, "itemsViewed"),
    items_added_to_cart: ga4MetricValue(row, headers, "itemsAddedToCart"),
    items_checked_out: ga4MetricValue(row, headers, "itemsCheckedOut"),
    items_purchased: ga4MetricValue(row, headers, "itemsPurchased")
  };
}

async function fetchGA4Weekly(env, propertyId, boundaries) {
  const [base, events, itemTotals] = await Promise.all([
    fetchGA4BaseWeekly(env, propertyId, boundaries),
    fetchGA4EventCounts(env, propertyId, boundaries),
    fetchGA4ItemTotals(env, propertyId, boundaries)
  ]);

  return {
    ...base,
    view_item_events: events.view_item,
    add_to_cart_events: events.add_to_cart,
    begin_checkout_events: events.begin_checkout,
    purchase_events: events.purchase,
    ...itemTotals
  };
}


async function fetchGA4ProductWeekly(env, propertyId, boundaries) {
  const body = {
    dateRanges: [ga4DateRange(boundaries)],
    dimensions: [
      { name: "itemId" },
      { name: "itemName" },
      { name: "itemBrand" },
      { name: "itemCategory" },
      { name: "itemVariant" }
    ],
    metrics: [
      { name: "itemsViewed" },
      { name: "itemsAddedToCart" },
      { name: "itemsCheckedOut" },
      { name: "itemsPurchased" },
      { name: "itemRevenue" }
    ],
    orderBys: [
      {
        metric: { metricName: "itemsViewed" },
        desc: true
      }
    ],
    limit: 1000
  };

  let offset = 0;
  const allRows = [];
  let data;

  do {
    data = await ga4RunReport(env, propertyId, { ...body, offset });
    allRows.push(...(data.rows || []));
    offset += (data.rows || []).length;
  } while ((data.rows || []).length && num(data.rowCount) > allRows.length);

  const headers = {
    metricHeaders: data.metricHeaders || [],
    dimensionHeaders: data.dimensionHeaders || []
  };

  return allRows.map((row) => {
    const itemViews = ga4MetricValue(row, headers, "itemsViewed");
    const addToCarts = ga4MetricValue(row, headers, "itemsAddedToCart");
    const beginCheckouts = ga4MetricValue(row, headers, "itemsCheckedOut");
    const purchases = ga4MetricValue(row, headers, "itemsPurchased");

    return {
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      property_id: propertyId,

      item_id: ga4DimensionValue(row, headers, "itemId"),
      item_name: ga4DimensionValue(row, headers, "itemName"),
      item_brand: ga4DimensionValue(row, headers, "itemBrand"),
      item_category: ga4DimensionValue(row, headers, "itemCategory"),
      item_variant: ga4DimensionValue(row, headers, "itemVariant"),

      item_views: itemViews,
      add_to_carts: addToCarts,
      begin_checkouts: beginCheckouts,
      purchases,
      item_revenue: r2(ga4MetricValue(row, headers, "itemRevenue")),

      view_to_cart_rate: r4(div(addToCarts, itemViews)),
      cart_to_checkout_rate: r4(div(beginCheckouts, addToCarts)),
      checkout_to_purchase_rate: r4(div(purchases, beginCheckouts)),
      view_to_purchase_rate: r4(div(purchases, itemViews))
    };
  });
}

async function syncMetaWeek(env, options = {}) {
  const startedAt = new Date().toISOString();
  const runId = crypto.randomUUID();

  let weekStart = options.week_start || "";
  let weekEnd = "";

  try {
    const tabData = await readAllTabs(env);
    const config = parseConfig(tabData.Config, env);

    if (!config.metaAdAccountId) {
      throw new Error("Missing meta_ad_account_id in Config tab or META_AD_ACCOUNT_ID env var.");
    }

    weekStart = weekStart || latestCompletedSundayWeekStart(config.timezone);

    assertCompletedWeek(weekStart, config.timezone);

    const boundaries = weekBoundaries(weekStart, config.timezone);
    weekEnd = boundaries.week_end;
    const syncedAt = new Date().toISOString();

    const existingMetaWeekly = objectsFromTab(tabData, "MetaWeekly", HEADERS.MetaWeekly);
    const existingMetaCampaign = objectsFromTab(tabData, "MetaCampaignWeekly", HEADERS.MetaCampaignWeekly);
    const existingMetaAd = objectsFromTab(tabData, "MetaAdWeekly", HEADERS.MetaAdWeekly);
    const existingShopifyWeekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly);

    const shopifyWeek = existingShopifyWeekly.find((r) => clean(r.week_start) === boundaries.week_start) || null;
    const shopifyNetSales = shopifyWeek ? num(shopifyWeek.net_sales) : "";

    const [accountRows, campaignRowsRaw, adRowsRaw] = await Promise.all([
      fetchMetaInsights(env, config.metaAdAccountId, {
        level: "account",
        since: boundaries.week_start,
        until: boundaries.week_end
      }),
      fetchMetaInsights(env, config.metaAdAccountId, {
        level: "campaign",
        since: boundaries.week_start,
        until: boundaries.week_end
      }),
      fetchMetaInsights(env, config.metaAdAccountId, {
        level: "ad",
        since: boundaries.week_start,
        until: boundaries.week_end
      })
    ]);

    // +3 subrequests: 1 chunk of campaigns, 2 of ads at the current 67-ad scale.
    const [campaignStatuses, adStatuses] = await Promise.all([
      fetchMetaCampaignStatuses(env, campaignRowsRaw.map((r) => clean(r.campaign_id))),
      fetchMetaAdStatuses(env, adRowsRaw.map((r) => clean(r.ad_id)))
    ]);

    const account = accountRows[0] || {};
    const accountMetrics = metaBaseMetrics(account);

    const weeklyRow = {
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      synced_at: syncedAt,
      ad_account_id: metaActId(config.metaAdAccountId),
      currency: account.account_currency || config.currency,

      // dividing against ShopifyWeekly's net_sales — a row that does not exist
      // yet, because meta_sync runs BEFORE shopify_sync in the Workflow. Both
      // wrote blank on every first sync of a week.
      //
      // Reordering the steps would only hide it. A metric that spans two sources
      // does not belong in a single-source sync function: ReportWeekly derives
      // both at rebuild time, once every source has landed, and always has.
      // `shopify_net_sales` went with them: a denormalised copy of another
      // source's field, with no consumer, blank on every first sync.
      ...accountMetrics
    };

    const campaignRows = campaignRowsRaw.filter(metaHasActivity).map((r) => {
      const status = campaignStatuses.get(r.campaign_id) || {};

      return {
        week_start: boundaries.week_start,
        week_end: boundaries.week_end,
        synced_at: syncedAt,

        campaign_id: r.campaign_id || "",
        campaign_name: r.campaign_name || "",
        objective: status.objective || r.objective || "",
        buying_type: status.buying_type || r.buying_type || "",
        status: status.status || "",
        effective_status: status.effective_status || "",

        ...metaBaseMetrics(r)
      };
    });

const adRows = adRowsRaw.filter(metaHasActivity).map((r) => {
      const status = adStatuses.get(r.ad_id) || {};

      return {
        week_start: boundaries.week_start,
        week_end: boundaries.week_end,
        synced_at: syncedAt,

        campaign_id: r.campaign_id || "",
        campaign_name: r.campaign_name || "",
        adset_id: r.adset_id || "",
        adset_name: r.adset_name || "",
        ad_id: r.ad_id || "",
        ad_name: r.ad_name || "",
        status: status.status || "",
        effective_status: status.effective_status || "",

        ...metaBaseMetrics(r),
        ...metaAdVideoMetrics(r)
      };
    });

    const finalMetaWeekly = upsertObjects(
      existingMetaWeekly,
      [weeklyRow],
      (r) => clean(r.week_start)
    );

    const finalMetaCampaign = replaceObjectsForWeek(
      existingMetaCampaign,
      boundaries.week_start,
      campaignRows
    );

    const finalMetaAd = replaceObjectsForWeek(
      existingMetaAd,
      boundaries.week_start,
      adRows
    );

    // allowEmpty: MetaWeekly is a single upserted row and can never be empty.
    // The campaign and ad tabs are replaceObjectsForWeek targets — a week with
    // no spend legitimately returns zero rows.
    const tabsToRewrite = [
      { tab: "MetaWeekly", headers: HEADERS.MetaWeekly, objects: finalMetaWeekly, allowEmpty: false },
      { tab: "MetaCampaignWeekly", headers: HEADERS.MetaCampaignWeekly, objects: finalMetaCampaign, allowEmpty: true },
      { tab: "MetaAdWeekly", headers: HEADERS.MetaAdWeekly, objects: finalMetaAd, allowEmpty: true }
    ];

    const snapshot = await snapshotTabsBeforeRewrite(env, {
      source: "meta",
      weekStart: boundaries.week_start,
      runId,
      endpoint: options.endpoint || "/sync-meta-week",
      tabData,
      tabs: tabsToRewrite.map(({ tab }) => tab)
    });

    const rewrite = await rewriteTabs(env, {
      source: "meta",
      tabData,
      tabsToRewrite
    });

    let creativeMetadataRefresh = { stored_ids: [], errors: [] };
    try {
      creativeMetadataRefresh = await refreshMetaCreativeMetadata(env, {
        week: { week_start: boundaries.week_start },
        creative: { ads: adRows }
      }, {
        missing_only: true,
        max_ads: 100,
        batch_size: 5
      });
    } catch (err) {
      creativeMetadataRefresh = {
        stored_ids: [],
        errors: [truncateOperationalError(err)]
      };
    }

    const finishedAt = new Date().toISOString();

    const syncLog = await recordSyncSuccess(env, {
      syncKey: `meta_week_${boundaries.week_start}_${runId}`,
      runId,
      endpoint: options.endpoint || "/sync-meta-week",
      startedAt,
      finishedAt,
      weekStart: boundaries.week_start,
      weekEnd: boundaries.week_end,
      rowsWritten: 1 + campaignRows.length + adRows.length
    });

    return {
      ok: true,
      mode: options.week_start ? "specific_completed_week" : "latest_completed_week",
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      sync_log: syncLog,
      ad_account_id: metaActId(config.metaAdAccountId),
      meta_weekly_rows: 1,
      meta_campaign_rows: campaignRows.length,
      meta_ad_rows: adRows.length,
      spend: weeklyRow.spend,
      impressions: weeklyRow.impressions,
      link_clicks: weeklyRow.link_clicks,
      landing_page_views: weeklyRow.landing_page_views,
      purchases: weeklyRow.purchases,
      purchase_value: weeklyRow.purchase_value,
      shopify_net_sales_note: "removed from MetaWeekly (P1.8); ReportWeekly derives it after every source lands",

      snapshot,
      rewrite,
      creative_metadata_rows: creativeMetadataRefresh.stored_ids.length,
      creative_metadata_errors: creativeMetadataRefresh.errors,
      started_at: startedAt,
      finished_at: finishedAt
    };
  } catch (err) {
    const finishedAt = new Date().toISOString();

    try {
      await appendSheetRows(
        env,
        "SyncMeta",
        objectsToRows(HEADERS.SyncMeta, [
          {
            sync_key: `meta_week_${weekStart || "unknown"}_${runId}`,
            run_id: runId,
            endpoint: options.endpoint || "/sync-meta-week",
            status: "error",
            started_at: startedAt,
            finished_at: finishedAt,
            week_start: weekStart || "",
            week_end: weekEnd || "",
            rows_written: 0,
            error_message: String(err.message || err)
          }
        ])
      );
    } catch (_) {}

    throw err;
  }
}

async function syncGA4Week(env, options = {}) {
  const startedAt = new Date().toISOString();
  const runId = crypto.randomUUID();

  let weekStart = options.week_start || "";
  let weekEnd = "";

  try {
    const tabData = await readAllTabs(env);
    const config = parseConfig(tabData.Config, env);

    if (!config.ga4PropertyId) {
      throw new Error("Missing ga4_property_id in Config tab or GA4_PROPERTY_ID env var.");
    }

    weekStart = weekStart || latestCompletedSundayWeekStart(config.timezone);

    assertCompletedWeek(weekStart, config.timezone);

    const boundaries = weekBoundaries(weekStart, config.timezone);
    weekEnd = boundaries.week_end;
    const syncedAt = new Date().toISOString();

    const existingGA4Weekly = objectsFromTab(tabData, "GA4Weekly", HEADERS.GA4Weekly);
    const existingGA4Product = objectsFromTab(tabData, "GA4ProductWeekly", HEADERS.GA4ProductWeekly);
    const existingWeekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly);

    const shopifyWeek = existingWeekly.find((r) => clean(r.week_start) === boundaries.week_start) || null;
    const shopifyOrders = shopifyWeek ? num(shopifyWeek.orders) : "";

    const ga4Weekly = await fetchGA4Weekly(env, config.ga4PropertyId, boundaries);
    const ga4ProductRowsRaw = await fetchGA4ProductWeekly(env, config.ga4PropertyId, boundaries);

    const weeklyRow = {
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      synced_at: syncedAt,
      property_id: config.ga4PropertyId,

      sessions: ga4Weekly.sessions,
      users: ga4Weekly.users,
      new_users: ga4Weekly.new_users,
      engaged_sessions: ga4Weekly.engaged_sessions,
      engagement_rate: r4(ga4Weekly.engagement_rate),

      view_item_events: ga4Weekly.view_item_events,
      add_to_cart_events: ga4Weekly.add_to_cart_events,
      begin_checkout_events: ga4Weekly.begin_checkout_events,
      purchase_events: ga4Weekly.purchase_events,

      item_views: ga4Weekly.item_views,
      items_added_to_cart: ga4Weekly.items_added_to_cart,
      items_checked_out: ga4Weekly.items_checked_out,
      items_purchased: ga4Weekly.items_purchased,

      total_revenue: r2(ga4Weekly.total_revenue),
      purchase_revenue: r2(ga4Weekly.purchase_revenue),

      product_view_rate: r4(div(ga4Weekly.view_item_events, ga4Weekly.sessions)),
      atc_rate: r4(div(ga4Weekly.add_to_cart_events, ga4Weekly.view_item_events)),
      checkout_start_rate: r4(div(ga4Weekly.begin_checkout_events, ga4Weekly.add_to_cart_events)),
      checkout_completion_rate: r4(div(ga4Weekly.purchase_events, ga4Weekly.begin_checkout_events)),
      session_purchase_rate: r4(div(ga4Weekly.purchase_events, ga4Weekly.sessions)),

      shopify_orders: shopifyOrders,
      ga4_purchases_vs_shopify_orders_gap:
        shopifyOrders === "" ? "" : num(ga4Weekly.purchase_events) - num(shopifyOrders)
    };

    const productRows = ga4ProductRowsRaw.map((r) => ({
      ...r,
      synced_at: syncedAt
    }));

    const finalGA4Weekly = upsertObjects(
      existingGA4Weekly,
      [weeklyRow],
      (r) => clean(r.week_start)
    );

    const finalGA4Product = replaceObjectsForWeek(
      existingGA4Product,
      boundaries.week_start,
      productRows
    );

    // allowEmpty: GA4Weekly is a single upserted row. GA4ProductWeekly is a
    // replaceObjectsForWeek target and can legitimately return zero rows.
    const tabsToRewrite = [
      { tab: "GA4Weekly", headers: HEADERS.GA4Weekly, objects: finalGA4Weekly, allowEmpty: false },
      { tab: "GA4ProductWeekly", headers: HEADERS.GA4ProductWeekly, objects: finalGA4Product, allowEmpty: true }
    ];

    const snapshot = await snapshotTabsBeforeRewrite(env, {
      source: "ga4",
      weekStart: boundaries.week_start,
      runId,
      endpoint: options.endpoint || "/sync-ga4-week",
      tabData,
      tabs: tabsToRewrite.map(({ tab }) => tab)
    });

    const rewrite = await rewriteTabs(env, {
      source: "ga4",
      tabData,
      tabsToRewrite
    });

    const finishedAt = new Date().toISOString();

    const syncLog = await recordSyncSuccess(env, {
      syncKey: `ga4_week_${boundaries.week_start}_${runId}`,
      runId,
      endpoint: options.endpoint || "/sync-ga4-week",
      startedAt,
      finishedAt,
      weekStart: boundaries.week_start,
      weekEnd: boundaries.week_end,
      rowsWritten: 1 + productRows.length
    });

    return {
      ok: true,
      mode: options.week_start ? "specific_completed_week" : "latest_completed_week",
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      sync_log: syncLog,
      property_id: config.ga4PropertyId,
      ga4_weekly_rows: 1,
      ga4_product_rows: productRows.length,
      sessions: weeklyRow.sessions,
      view_item_events: weeklyRow.view_item_events,
      add_to_cart_events: weeklyRow.add_to_cart_events,
      begin_checkout_events: weeklyRow.begin_checkout_events,
      purchase_events: weeklyRow.purchase_events,
      shopify_orders: weeklyRow.shopify_orders,
      ga4_purchases_vs_shopify_orders_gap: weeklyRow.ga4_purchases_vs_shopify_orders_gap,
      snapshot,
      rewrite,
      started_at: startedAt,
      finished_at: finishedAt
    };
  } catch (err) {
    const finishedAt = new Date().toISOString();

    try {
      await appendSheetRows(
        env,
        "SyncMeta",
        objectsToRows(HEADERS.SyncMeta, [
          {
            sync_key: `ga4_week_${weekStart || "unknown"}_${runId}`,
            run_id: runId,
            endpoint: options.endpoint || "/sync-ga4-week",
            status: "error",
            started_at: startedAt,
            finished_at: finishedAt,
            week_start: weekStart || "",
            week_end: weekEnd || "",
            rows_written: 0,
            error_message: String(err.message || err)
          }
        ])
      );
    } catch (_) {}

    throw err;
  }
}


async function syncShopifyAll(env, options = {}) {
  const startedAt = new Date().toISOString();
  const runId = crypto.randomUUID();

  let weekStart = options.week_start || "";
  let weekEnd = "";

  try {
    const tabData = await readAllTabs(env);
    const config = parseConfig(tabData.Config, env);

    if (config.weekStartDay !== "SUNDAY") {
      throw new Error(`Config week_start_day must be SUNDAY. Current value: ${config.weekStartDay}`);
    }

    weekStart = weekStart || latestCompletedSundayWeekStart(config.timezone);
    assertCompletedWeek(weekStart, config.timezone);

    const boundaries = weekBoundaries(weekStart, config.timezone);
    weekEnd = boundaries.week_end;

    const rollingStartIso = new Date(boundaries.end_utc_ms - 30 * DAY_MS).toISOString();

const weeklyOrders = await fetchOrdersInRange(
  config.shopDomain,
  env.SHOPIFY_OFFLINE_TOKEN,
  boundaries.start_iso,
  boundaries.end_iso
);

const rollingOrders = await fetchOrdersInRange(
  config.shopDomain,
  env.SHOPIFY_OFFLINE_TOKEN,
  rollingStartIso,
  boundaries.end_iso
);

const variants = await fetchAllVariants(
  config.shopDomain,
  env.SHOPIFY_OFFLINE_TOKEN
);

const updatedOrdersWithRefunds = await fetchOrdersUpdatedInRangeWithRefunds(
  config.shopDomain,
  env.SHOPIFY_OFFLINE_TOKEN,
  boundaries.start_iso,
  boundaries.end_iso
);


    const syncedAt = new Date().toISOString();

// Exclusions applied to every Orders API path, matching the WHERE clause the
// ShopifyQL aggregate now carries. Both bases or neither.
const weeklyPartition = partitionExcludedOrders(weeklyOrders);
const rollingPartition = partitionExcludedOrders(rollingOrders);
const refundPartition = partitionExcludedOrders(updatedOrdersWithRefunds);
const excludedOrders = summarizeExcludedOrders(weeklyPartition.excluded);

if (excludedOrders.count) {
  console.log(
    JSON.stringify({
      event: "orders_excluded",
      week_start: boundaries.week_start,
      count: excludedOrders.count,
      by_rule: excludedOrders.by_rule,
      order_names: excludedOrders.order_names,
      gross_sales: excludedOrders.gross_sales
    })
  );
}

let aggregate = aggregateOrders(
  weeklyPartition.kept,
  rollingPartition.kept,
  boundaries.end_utc_ms
);
const salesAnalytics = await fetchSalesAnalyticsForWeek(
  config.shopDomain,
  env.SHOPIFY_OFFLINE_TOKEN,
  boundaries
);

// Second aggregate, unfiltered, purely to measure what the exclusion removed.
// Costs +1 subrequest per Shopify sync. Worth it: the Orders API cannot state
// the value, because these orders are usually cancelled and their current*
// money fields are zeroed. This gives the impact on the same basis the weekly
// financial fields are written from, so the numbers are comparable.
let excludedImpact = { available: false, reason: "not_measured" };

if (excludedOrders.count) {
  try {
    const unfiltered = await fetchSalesAnalyticsForWeek(
      config.shopDomain,
      env.SHOPIFY_OFFLINE_TOKEN,
      boundaries,
      { includeExcluded: true }
    );

    excludedImpact = {
      available: true,
      basis: "shopifyql",
      gross_sales: r2(unfiltered.gross_sales - salesAnalytics.gross_sales),
      discounts: r2(unfiltered.discounts - salesAnalytics.discounts),
      reversals: r2(unfiltered.refunds - salesAnalytics.refunds),
      net_sales: r2(unfiltered.net_sales - salesAnalytics.net_sales),
      orders: unfiltered.orders - salesAnalytics.orders
    };
  } catch (err) {
    // Never fail a sync to measure a diagnostic.
    excludedImpact = { available: false, reason: truncateOperationalError(err) };
  }
}

excludedOrders.impact = excludedImpact;

const refundAdjustments = collectRefundAdjustmentsFromOrders(
  refundPartition.kept,
  boundaries.start_iso,
  boundaries.end_iso
);

aggregate = applyRefundAdjustmentsToAggregate(aggregate, refundAdjustments);
// ShopifyQL is the source of truth for weekly top-level financials.
// Orders API remains the source for product/SKU/inventory diagnostics.
aggregate.weekly.gross_sales = salesAnalytics.gross_sales;
aggregate.weekly.discounts = salesAnalytics.discounts;
aggregate.weekly.refunds = salesAnalytics.refunds;
aggregate.weekly.net_sales = salesAnalytics.net_sales;
aggregate.weekly.shipping_revenue = salesAnalytics.shipping_revenue;
aggregate.weekly.taxes = salesAnalytics.taxes;
aggregate.weekly.total_sales = salesAnalytics.total_sales;
aggregate.weekly.orders = salesAnalytics.orders;

    // Recomputed on every sync and every backfill, never written once: a week's
    // attributed figure is a view of current knowledge. Recent weeks are
    // OVERSTATED because their own cohort's reversals have not arrived yet —
    // measured at 25-45% on week 2026-08-23 — which is what attribution_settled
    // exists to flag.
    const attribution = await computeReversalAttribution(
      config.shopDomain,
      env.SHOPIFY_OFFLINE_TOKEN,
      boundaries
    );

    if (!attribution.available) {
      console.error(
        JSON.stringify({
          event: "reversal_attribution_unavailable",
          week_start: boundaries.week_start,
          reason: attribution.reason
        })
      );
    }

    const dropCalendar = await loadDropCalendar(env);
    const dropPosition = dropPositionForWeek(dropCalendar, boundaries);

    // Known ad ids come from MetaAdWeekly, already in tabData — no extra fetch.
    const knownAdIds = new Set(
      objectsFromTab(tabData, "MetaAdWeekly", HEADERS.MetaAdWeekly)
        .map((r) => clean(r.ad_id))
        .filter(Boolean)
    );
    // Platform-scoped from the start. Adding TikTok is then one more key, not a
    // change to how matching behaves.
    const attributionCapture = summarizeAttributionCapture(weeklyPartition.kept, { meta: knownAdIds });
    const delivery = summarizeDelivery(weeklyPartition.kept);
    const freight = summarizeFreight(weeklyPartition.kept, config);
    const skuDelivery = summarizeSkuDelivery(weeklyPartition.kept);

    // P1.16. One extra ShopifyQL query covering every drop window at once, then
    // bucketed in memory — not one query per drop.
    let dropWeeklyRows = [];
    if (dropCalendar.length) {
      try {
        const earliest = dropCalendar
          .map((d) => clean(d.drop_date))
          .filter(Boolean)
          .sort()[0];
        const dailySeries = await fetchDailySalesSeries(
          config.shopDomain,
          env.SHOPIFY_OFFLINE_TOKEN,
          earliest,
          boundaries.week_end
        );
        dropWeeklyRows = buildDropRelativeWeeks(
          dailySeries,
          dropCalendar,
          boundaries.week_end
        ).map((r) => ({ ...r, synced_at: syncedAt }));
      } catch (err) {
        // Additive layer: never fail a sync for it.
        console.error(
          JSON.stringify({ event: "drop_relative_weeks_failed", error: truncateOperationalError(err) })
        );
      }
    }

    if (attributionCapture.health === "degraded") {
      console.error(
        JSON.stringify({
          event: "attribution_capture_degraded",
          week_start: boundaries.week_start,
          unattributed_share: attributionCapture.unattributed_share
        })
      );
    }

    const rows = buildRows({
      config,
      boundaries,
      syncedAt,
      variants,
      aggregate,
      attribution,
      dropPosition,
      attributionCapture,
      delivery,
      skuDelivery,
      freight
    });

    const diagnoses = buildDiagnoses({
      boundaries,
      syncedAt,
      productRows: rows.productRows,
      skuRows: rows.skuRows
    });

    const existingWeekly = objectsFromTab(tabData, "ShopifyWeekly", HEADERS.ShopifyWeekly);
const existingProduct = objectsFromTab(tabData, "ShopifyProductWeekly", HEADERS.ShopifyProductWeekly);
const existingSku = objectsFromTab(tabData, "ShopifySkuWeekly", HEADERS.ShopifySkuWeekly);
const existingSnapshot = objectsFromTab(tabData, "ShopifyInventorySnapshot", HEADERS.ShopifyInventorySnapshot);
const existingProdDiag = objectsFromTab(tabData, "ShopifyProductDiagnosis", HEADERS.ShopifyProductDiagnosis);
const existingSkuDiag = objectsFromTab(tabData, "ShopifySkuDiagnosis", HEADERS.ShopifySkuDiagnosis);

const existingGA4Weekly = objectsFromTab(tabData, "GA4Weekly", HEADERS.GA4Weekly);
const existingMetaWeekly = objectsFromTab(tabData, "MetaWeekly", HEADERS.MetaWeekly);

const existingReport = objectsFromTab(tabData, "ReportWeekly", HEADERS.ReportWeekly);
const existingActions = objectsFromTab(tabData, "ReportActions", HEADERS.ReportActions);
const existingSyncMeta = objectsFromTab(tabData, "SyncMeta", HEADERS.SyncMeta);

    const finalWeekly = upsertObjects(existingWeekly, [rows.weeklyRow], (r) => clean(r.week_start));

    const finalProduct = replaceObjectsForWeek(
      existingProduct,
      boundaries.week_start,
      rows.productRows
    );

    const finalSku = replaceObjectsForWeek(
      existingSku,
      boundaries.week_start,
      rows.skuRows
    );

    const finalSnapshot = replaceObjectsForWeek(
      existingSnapshot,
      boundaries.week_start,
      rows.snapshotRows
    );

    const finalProdDiag = replaceObjectsForWeek(
      existingProdDiag,
      boundaries.week_start,
      diagnoses.productDiagnosis
    );

    const finalSkuDiag = replaceObjectsForWeek(
      existingSkuDiag,
      boundaries.week_start,
      diagnoses.skuDiagnosis
    );

const weeklyHistoryMap = new Map(finalWeekly.map((r) => [clean(r.week_start), r]));
const reportHistoryMap = new Map(existingReport.map((r) => [clean(r.week_start), r]));

const ga4Row =
  existingGA4Weekly.find((r) => clean(r.week_start) === boundaries.week_start) || null;

const metaRow =
  existingMetaWeekly.find((r) => clean(r.week_start) === boundaries.week_start) || null;

const reportRow = buildReportWeekly(
  boundaries,
  syncedAt,
  rows.weeklyRow,
  ga4Row,
  metaRow,
  weeklyHistoryMap,
  new Map(existingGA4Weekly.map((r) => [clean(r.week_start), r])),
  reportHistoryMap,
  diagnoses.productDiagnosis,
  diagnoses.skuDiagnosis
);

    const finalReport = upsertObjects(existingReport, [reportRow], (r) => clean(r.week_start));

const actionRows = buildActions({
  boundaries,
  syncedAt,
  reportRow,
  weeklyRow: rows.weeklyRow,
  ga4Row,
  metaRow,
  productRows: rows.productRows,
  skuRows: rows.skuRows,
  productDiagnosis: diagnoses.productDiagnosis,
  skuDiagnosis: diagnoses.skuDiagnosis,
  metaAdRows: objectsFromTab(tabData, "MetaAdWeekly", HEADERS.MetaAdWeekly)
    .filter((r) => clean(r.week_start) === boundaries.week_start),
  ga4ProductRows: objectsFromTab(tabData, "GA4ProductWeekly", HEADERS.GA4ProductWeekly)
    .filter((r) => clean(r.week_start) === boundaries.week_start)
});

const finalActions = replaceObjectsForWeek(
  existingActions,
  boundaries.week_start,
  actionRows
);

    const finishedAt = new Date().toISOString();

    const syncMetaRow = {
      sync_key: `shopify_all_${boundaries.week_start}_${runId}`,
      run_id: runId,
      endpoint: options.endpoint || "/sync-shopify-all",
      status: "success",
      started_at: startedAt,
      finished_at: finishedAt,
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      excluded_orders: excludedOrders.count,
      rows_written:
        1 +
        rows.productRows.length +
        rows.skuRows.length +
        rows.snapshotRows.length +
        diagnoses.productDiagnosis.length +
        diagnoses.skuDiagnosis.length +
        1 +
        actionRows.length,
      error_message: ""
    };

    const finalSyncMeta = [...existingSyncMeta, syncMetaRow].slice(-500);

    // allowEmpty is false only where the content is unconditional: ShopifyWeekly
    // and ReportWeekly are single upserted rows, SyncMeta always appends this
    // run's row. Everything else is a replaceObjectsForWeek target — a clean
    // week legitimately yields zero diagnosis rows and zero actions.
    const tabsToRewrite = [
      { tab: "ShopifyWeekly", headers: HEADERS.ShopifyWeekly, objects: finalWeekly, allowEmpty: false },
      { tab: "ShopifyProductWeekly", headers: HEADERS.ShopifyProductWeekly, objects: finalProduct, allowEmpty: true },
      { tab: "ShopifySkuWeekly", headers: HEADERS.ShopifySkuWeekly, objects: finalSku, allowEmpty: true },
      { tab: "ShopifyInventorySnapshot", headers: HEADERS.ShopifyInventorySnapshot, objects: finalSnapshot, allowEmpty: true },
      { tab: "ShopifyProductDiagnosis", headers: HEADERS.ShopifyProductDiagnosis, objects: finalProdDiag, allowEmpty: true },
      { tab: "ShopifySkuDiagnosis", headers: HEADERS.ShopifySkuDiagnosis, objects: finalSkuDiag, allowEmpty: true },
      { tab: "ReportWeekly", headers: HEADERS.ReportWeekly, objects: finalReport, allowEmpty: false },
      { tab: "ReportActions", headers: HEADERS.ReportActions, objects: finalActions, allowEmpty: true },
      { tab: "SyncMeta", headers: HEADERS.SyncMeta, objects: finalSyncMeta, allowEmpty: false },
      // Fully recomputed each sync from the daily series, so a failed fetch
      // leaves the previous content rather than blanking it.
      {
        tab: "DropWeekly",
        headers: HEADERS.DropWeekly,
        objects: dropWeeklyRows.length
          ? dropWeeklyRows
          : objectsFromTab(tabData, "DropWeekly", HEADERS.DropWeekly),
        allowEmpty: true
      }
    ];

    const snapshot = await snapshotTabsBeforeRewrite(env, {
      source: "shopify",
      weekStart: boundaries.week_start,
      runId,
      endpoint: options.endpoint || "/sync-shopify-all",
      tabData,
      tabs: tabsToRewrite.map(({ tab }) => tab)
    });

    const rewrite = await rewriteTabs(env, {
      source: "shopify",
      tabData,
      tabsToRewrite
    });

    return {
      ok: true,
      mode: options.week_start ? "specific_completed_week" : "latest_completed_week",
      week_start: boundaries.week_start,
      week_end: boundaries.week_end,
      previous_week_start: addDays(boundaries.week_start, -7),
      previous_4w_average_rule:
        "Previous 4 completed weeks EXCLUDING this report week. Blank until all 4 previous weeks exist.",
      previous_4w_weeks_used: [-7, -14, -21, -28].map((d) =>
        addDays(boundaries.week_start, d)
      ),
      shopify_order_count_raw: weeklyOrders.length,
      excluded_orders: excludedOrders,
      cogs: rows.cogs,
      delivery: delivery,
      drop_weekly_rows: dropWeeklyRows.length,
      attribution_capture: attributionCapture,
      reversal_attribution: attribution,
      drop_position: dropPosition,
      snapshot,
      rewrite,
      write_debug: rewrite.write_debug,
      rolling_order_count_raw: rollingOrders.length,
      variant_count_raw: variants.length,
      updated_orders_with_refunds_count_raw: updatedOrdersWithRefunds.length,
refund_line_quantity: refundAdjustments.totals.refund_line_quantity,
refund_line_subtotal: r2(refundAdjustments.totals.refund_line_subtotal),
refund_shipping_subtotal: r2(refundAdjustments.totals.refund_shipping_subtotal),
      shopify_weekly_rows: 1,
      product_rows: rows.productRows.length,
      sku_rows: rows.skuRows.length,
      inventory_snapshot_rows: rows.snapshotRows.length,
      product_diagnosis_rows: diagnoses.productDiagnosis.length,
      sku_diagnosis_rows: diagnoses.skuDiagnosis.length,
      report_weekly_updated: true,
      report_actions_rows: actionRows.length,
      started_at: startedAt,
      finished_at: finishedAt,
      note:
  "Shopify layer synced and ReportWeekly rebuilt from ShopifyWeekly + GA4Weekly + MetaWeekly where available."
 };
  } catch (err) {
    const finishedAt = new Date().toISOString();

    try {
      await appendSheetRows(
        env,
        "SyncMeta",
        objectsToRows(HEADERS.SyncMeta, [
          {
            sync_key: `shopify_all_${weekStart || "unknown"}_${runId}`,
            run_id: runId,
            endpoint: options.endpoint || "/sync-shopify-all",
            status: "error",
            started_at: startedAt,
            finished_at: finishedAt,
            week_start: weekStart || "",
            week_end: weekEnd || "",
            rows_written: 0,
            error_message: String(err.message || err)
          }
        ])
      );
    } catch (_) {}

    throw err;
  }
}

function buildBackfillPlan(startWeek, endWeek, baseUrl) {
  if (!startWeek || !endWeek) {
    throw new Error(
      "Backfill plan requires start_week and end_week, both Sundays. Example: /sync-shopify-backfill-plan?start_week=2026-05-03&end_week=2026-05-24"
    );
  }

  if (!isSunday(startWeek) || !isSunday(endWeek)) {
    throw new Error("start_week and end_week must both be Sundays.");
  }

  if (dateOnlyToUtcMs(startWeek) > dateOnlyToUtcMs(endWeek)) {
    throw new Error("start_week must be before or equal to end_week.");
  }

  const urls = [];
  let current = startWeek;

  while (dateOnlyToUtcMs(current) <= dateOnlyToUtcMs(endWeek)) {
    urls.push(`${baseUrl}/sync-shopify-all?week_start=${current}`);
    current = addDays(current, 7);
  }

  return urls;
}

async function syncBackfill(env, startWeek, endWeek) {
  const config = await getConfig(env);

  if (!startWeek || !endWeek) {
    throw new Error(
      "Backfill requires start_week and end_week, both Sundays. Example: /sync-shopify-backfill?start_week=2026-05-03&end_week=2026-05-24"
    );
  }

  if (!isSunday(startWeek) || !isSunday(endWeek)) {
    throw new Error("start_week and end_week must both be Sundays.");
  }

  assertCompletedWeek(endWeek, config.timezone);

  if (dateOnlyToUtcMs(startWeek) > dateOnlyToUtcMs(endWeek)) {
    throw new Error("start_week must be before or equal to end_week.");
  }

  const weeks = [];
  let current = startWeek;

  while (dateOnlyToUtcMs(current) <= dateOnlyToUtcMs(endWeek)) {
    weeks.push(current);
    current = addDays(current, 7);
  }

  if (weeks.length > 1) {
    throw new Error(
      "For the Free Worker subrequest limit, do not run multi-week backfill in one request. Use /sync-shopify-backfill-plan and click each weekly URL one by one."
    );
  }

  const result = await syncShopifyAll(env, {
    week_start: weeks[0],
    endpoint: "/sync-shopify-backfill"
  });

  return {
    ok: true,
    weeks_synced: 1,
    previous_4w_average_rule:
      "Each week compares against the previous 4 completed weeks only. If fewer than 4 previous weeks exist, 4W avg fields remain blank.",
    results: [
      {
        week_start: result.week_start,
        week_end: result.week_end,
        ok: result.ok,
        orders: result.shopify_order_count_raw,
        sku_rows: result.sku_rows
      }
    ]
  };
}

function isoMs(value) {
  const ms = new Date(value || "").getTime();
  return Number.isFinite(ms) ? ms : 0;
}

function isIsoInRange(value, startIso, endIso) {
  const ms = isoMs(value);
  return ms >= isoMs(startIso) && ms < isoMs(endIso);
}

function summarizeRefundsForDebug(orders, startIso, endIso) {
  const refundRows = [];
  const refundLineRows = [];

  for (const order of orders) {
    for (const refund of order.refunds || []) {
      const refundDate = refund.processedAt || refund.createdAt;

      if (!isIsoInRange(refundDate, startIso, endIso)) continue;

      let lineQuantity = 0;
      let lineSubtotal = 0;
      let lineTax = 0;
      let shippingSubtotal = 0;
      let shippingTax = 0;
      let successfulTransactionAmount = 0;
      let allTransactionAmount = 0;

      for (const edge of refund.refundLineItems?.edges || []) {
        const item = edge.node;
        const lineItem = item.lineItem || {};

        const qty = num(item.quantity);
        const subtotal = money(item.subtotalSet);
        const tax = money(item.totalTaxSet);

        lineQuantity += qty;
        lineSubtotal += subtotal;
        lineTax += tax;

        refundLineRows.push({
          order_name: order.name,
          order_id: shortGid(order.id),
          order_createdAt: order.createdAt,
          order_updatedAt: order.updatedAt,
          order_financial_status: order.displayFinancialStatus,
          order_fulfillment_status: order.displayFulfillmentStatus,

          refund_id: shortGid(refund.id),
          refund_createdAt: refund.createdAt,
          refund_processedAt: refund.processedAt,
          refund_updatedAt: refund.updatedAt,

          line_item_title: lineItem.title || lineItem.name || "",
          sku: lineItem.sku || lineItem.variant?.sku || "",
          variant_id: shortGid(lineItem.variant?.id || ""),
          product_id: shortGid(lineItem.product?.id || ""),
          product_title: lineItem.product?.title || "",

          refund_quantity: qty,
          refund_price: r2(money(item.priceSet)),
          refund_subtotal: r2(subtotal),
          refund_tax: r2(tax),
          restocked: item.restocked ? "TRUE" : "FALSE",
          restockType: item.restockType || "",

          original_line_quantity: num(lineItem.quantity),
          current_line_quantity: num(lineItem.currentQuantity),
          original_unit_price: r2(money(lineItem.originalUnitPriceSet)),
          original_line_total: r2(money(lineItem.originalTotalSet)),
          discounted_line_total: r2(money(lineItem.discountedTotalSet)),
          line_discount: r2(money(lineItem.totalDiscountSet))
        });
      }

      for (const edge of refund.refundShippingLines?.edges || []) {
        const ship = edge.node;
        shippingSubtotal += money(ship.subtotalAmountSet);
        shippingTax += money(ship.taxAmountSet);
      }

      for (const edge of refund.transactions?.edges || []) {
        const tx = edge.node;
        const amount = money(tx.amountSet);
        allTransactionAmount += amount;

        if (String(tx.status || "").toUpperCase() === "SUCCESS") {
          successfulTransactionAmount += amount;
        }
      }

      refundRows.push({
        order_name: order.name,
        order_id: shortGid(order.id),
        order_createdAt: order.createdAt,
        order_updatedAt: order.updatedAt,
        order_financial_status: order.displayFinancialStatus,
        order_fulfillment_status: order.displayFulfillmentStatus,

        refund_id: shortGid(refund.id),
        refund_createdAt: refund.createdAt,
        refund_processedAt: refund.processedAt,
        refund_updatedAt: refund.updatedAt,
        refund_note: refund.note || "",

        refund_line_quantity: lineQuantity,
        refund_line_subtotal: r2(lineSubtotal),
        refund_line_tax: r2(lineTax),
        refund_shipping_subtotal: r2(shippingSubtotal),
        refund_shipping_tax: r2(shippingTax),
        refund_totalRefundedSet: r2(money(refund.totalRefundedSet)),
        refund_successful_transaction_amount: r2(successfulTransactionAmount),
        refund_all_transaction_amount: r2(allTransactionAmount)
      });
    }
  }

  const totals = refundRows.reduce(
    (acc, r) => {
      acc.refund_count += 1;
      acc.refund_line_quantity += num(r.refund_line_quantity);
      acc.refund_line_subtotal += num(r.refund_line_subtotal);
      acc.refund_line_tax += num(r.refund_line_tax);
      acc.refund_shipping_subtotal += num(r.refund_shipping_subtotal);
      acc.refund_shipping_tax += num(r.refund_shipping_tax);
      acc.refund_totalRefundedSet += num(r.refund_totalRefundedSet);
      acc.refund_successful_transaction_amount += num(r.refund_successful_transaction_amount);
      acc.refund_all_transaction_amount += num(r.refund_all_transaction_amount);
      return acc;
    },
    {
      refund_count: 0,
      refund_line_quantity: 0,
      refund_line_subtotal: 0,
      refund_line_tax: 0,
      refund_shipping_subtotal: 0,
      refund_shipping_tax: 0,
      refund_totalRefundedSet: 0,
      refund_successful_transaction_amount: 0,
      refund_all_transaction_amount: 0
    }
  );

  return {
    totals: {
      refund_count: totals.refund_count,
      refund_line_quantity: totals.refund_line_quantity,
      refund_line_subtotal: r2(totals.refund_line_subtotal),
      refund_line_tax: r2(totals.refund_line_tax),
      refund_shipping_subtotal: r2(totals.refund_shipping_subtotal),
      refund_shipping_tax: r2(totals.refund_shipping_tax),
      refund_totalRefundedSet: r2(totals.refund_totalRefundedSet),
      refund_successful_transaction_amount: r2(totals.refund_successful_transaction_amount),
      refund_all_transaction_amount: r2(totals.refund_all_transaction_amount)
    },
    refundRows,
    refundLineRows
  };
}

