const GROWTH_EXCLUSION_METRICS = Object.freeze(["exclusion_orders_removed", "exclusion_value_removed", "exclusion_units_removed"]);

// Customer segments are definitional, so their rows come from code, not a table.
const GROWTH_CUSTOMER_SEGMENTS = Object.freeze([
  "new", "returning", "vip", "lapsed", "one_time", "discount_dependent", "repeat_refuser"
]);

// Price bands on merchandise after discounts, rule price_band.v1: roughly one tee,
// one hoodie or jeans or two tees, a bundle, a large basket. A band change is a new
// rule version, never an edit.
const GROWTH_PRICE_BANDS = Object.freeze([
  { id: "under 1,000", max: 1000 },
  { id: "1,000–1,999", max: 2000 },
  { id: "2,000–2,999", max: 3000 },
  { id: "3,000+", max: Infinity }
]);

function orderPriceBand(subtotal) {
  if (subtotal === null || subtotal === undefined || subtotal === "") return "unknown";
  const v = Number(subtotal);
  return (GROWTH_PRICE_BANDS.find((b) => v < b.max) || GROWTH_PRICE_BANDS[GROWTH_PRICE_BANDS.length - 1]).id;
}

